--
-- Name: add(jsonb, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.add(body jsonb, by_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE w text := lower(coalesce(body->>'who', ''));
BEGIN
  IF w ~ '^[0-9a-f]{64}$' THEN w := auth.account_of(w);
  ELSIF w !~ '^[enw]-[0-9a-f]{16,64}$' THEN RETURN access.err(400, 'a pubkey (hex) or an account id'); END IF;
  PERFORM access.approve(w, 'admin', NULL, by_);
  RETURN access.r(200, jsonb_build_object('who', w, 'creator', true), NULL);
END $_$;


--
-- Name: admin_add(jsonb, text, text[]); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.admin_add(body jsonb, by_ text, roots text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  pk text := lower(coalesce(body->>'pubkey', ''));
  note_ text := verse.clean_text(body->'note', 120);
BEGIN
  IF NOT access.admin_may(by_, roots) THEN RETURN access.err(403, 'only a root admin (admins.conf) changes the admins'); END IF;
  IF pk !~ '^[0-9a-f]{64}$' THEN RETURN access.err(400, 'a pubkey (64 hex)'); END IF;
  IF pk = ANY (roots) THEN RETURN access.err(409, 'that key is a root admin already'); END IF;
  INSERT INTO access.admin_keys VALUES (pk, note_, by_, projects.now_ms()) ON CONFLICT (pubkey) DO NOTHING;
  IF FOUND THEN INSERT INTO access.admin_audit (at_ms, by, action, pubkey, note) VALUES (projects.now_ms(), by_, 'add', pk, note_); END IF;
  RETURN access.r(200, jsonb_build_object('pubkey', pk, 'admin', true), format(E'admin %s\n', pk));
END $_$;


--
-- Name: admin_lines(); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.admin_lines() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT string_agg(l, E'\n' ORDER BY o, k) || E'\n' FROM (
    SELECT 0 o, 0::bigint k, format('F|%s|%s', n, CASE WHEN access.flag(n) THEN 1 ELSE 0 END) l FROM unnest(ARRAY['realm_invites']) n
    UNION ALL
    SELECT 1, -i.id, format('I|%s|%s|%s|%s|%s|%s|%s', i.id, i.uses, i.used, i.expires_ms,
      CASE WHEN i.revoked_ms IS NOT NULL THEN 'revoked' WHEN i.used >= i.uses THEN 'used' WHEN i.expires_ms <= projects.now_ms() THEN 'expired' ELSE 'live' END,
      access.line(i.note), projects.chi(i.expires_ms)) FROM access.invites i
    UNION ALL
    SELECT 2, CASE WHEN r.state = 'waiting' THEN r.id ELSE 1000000000000 - r.id END,
      format('R|%s|%s|%s|%s|%s|%s|%s', r.id, auth.bech32('npub', r.pubkey), access.line(r.note), access.line(r.contact), r.state, r.at_ms, projects.chi(r.at_ms)) FROM access.requests r
    UNION ALL
    SELECT 3, -c.at_ms, format('C|%s|%s|%s|%s', access.line(c.who), c.how, c.at_ms, projects.chi(c.at_ms)) FROM access.creators c
  ) x
$$;


--
-- Name: admin_list(text[]); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.admin_list(roots text[]) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT coalesce((SELECT string_agg(format(E'A|%s|%s|root\n', auth.bech32('npub', r), r), '' ORDER BY o)
                   FROM unnest(roots) WITH ORDINALITY AS t(r, o) WHERE r ~ '^[0-9a-f]{64}$'), '')
      || coalesce((SELECT string_agg(format(E'A|%s|%s|db|%s|%s|%s\n', auth.bech32('npub', k.pubkey), k.pubkey,
                                            CASE WHEN k.added_by ~ '^[0-9a-f]{64}$' THEN auth.bech32('npub', k.added_by) ELSE access.line(k.added_by) END,
                                            k.added_ms, access.line(k.note)), '' ORDER BY k.added_ms, k.pubkey)
                   FROM access.admin_keys k WHERE NOT k.pubkey = ANY (roots)), '') $_$;


--
-- Name: admin_may(text, text[]); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.admin_may(by_ text, roots text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT coalesce(by_ ~ '^[0-9a-f]{64}$' AND by_ = ANY (roots), false) $_$;


--
-- Name: admin_remove(text, text, text[]); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.admin_remove(pk_ text, by_ text, roots text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE pk text := lower(coalesce(pk_, ''));
BEGIN
  IF NOT access.admin_may(by_, roots) THEN RETURN access.err(403, 'only a root admin (admins.conf) changes the admins'); END IF;
  IF pk = ANY (roots) THEN RETURN access.err(409, 'a root admin is in admins.conf: only a deploy removes it'); END IF;
  DELETE FROM access.admin_keys WHERE pubkey = pk;
  IF NOT FOUND THEN RETURN access.err(404, 'not a database admin'); END IF;
  INSERT INTO access.admin_audit (at_ms, by, action, pubkey) VALUES (projects.now_ms(), by_, 'remove', pk);
  RETURN access.r(200, jsonb_build_object('pubkey', pk, 'admin', false), format(E'removed %s\n', pk));
END $$;


--
-- Name: approve(text, text, bigint, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.approve(who_ text, how_ text, ref_ bigint, by_ text) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH x AS (INSERT INTO access.creators (who, how, ref, by, at_ms) VALUES (who_, how_, ref_, by_, projects.now_ms())
             ON CONFLICT (who) DO NOTHING RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM x)
$$;


--
-- Name: ask(jsonb, text, integer); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.ask(body jsonb, pk text, cap integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  acct text := auth.account_of(pk);
  note_ text := verse.clean_text(body->'note', 280);
  contact_ text := lower(verse.clean_text(body->'contact', 200));
BEGIN
  IF acct IS NULL THEN RETURN access.err(401, 'log in first'); END IF;
  IF EXISTS (SELECT 1 FROM access.creators WHERE who = acct) THEN RETURN access.r(200, '{"creator": true}', E'creator 1\n'); END IF;
  IF note_ = '' THEN RETURN access.err(400, 'say what you''d make'); END IF;
  IF contact_ <> '' AND contact_ !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RETURN access.err(400, 'that email doesn''t look right'); END IF;
  UPDATE access.requests SET note = note_, contact = CASE WHEN body ? 'contact' THEN contact_ ELSE contact END, pubkey = pk, at_ms = projects.now_ms()
    WHERE who = acct AND state = 'waiting';
  IF NOT FOUND THEN
    IF (SELECT count(*) FROM access.requests WHERE state = 'waiting') >= cap THEN RETURN access.err(429, 'slow down'); END IF;
    INSERT INTO access.requests (who, pubkey, note, contact, at_ms) VALUES (acct, pk, note_, contact_, projects.now_ms());
  END IF;
  RETURN access.r(200, '{"state": "waiting"}', E'asked waiting\n');
END $_$;


--
-- Name: decide(bigint, boolean, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.decide(id_ bigint, yes boolean, by_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE acct text;
BEGIN
  SELECT who INTO acct FROM access.requests WHERE id = id_;
  IF acct IS NULL THEN RETURN access.err(404, 'no such request'); END IF;
  UPDATE access.requests SET state = CASE WHEN yes THEN 'approved' ELSE 'declined' END, decided_ms = projects.now_ms(), decided_by = by_
    WHERE id = id_ AND state = 'waiting';
  IF NOT FOUND THEN RETURN access.err(409, 'already decided'); END IF;
  IF yes THEN PERFORM access.approve(acct, 'request', id_, by_); END IF;
  RETURN access.r(200, jsonb_build_object('id', id_, 'state', CASE WHEN yes THEN 'approved' ELSE 'declined' END), NULL);
END $$;


--
-- Name: err(integer, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.err(status integer, why text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT access.r(status, jsonb_build_object('error', why), why)
$$;


--
-- Name: flag(text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.flag(want text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT on_ FROM access.flags WHERE name = want), false)
$$;


--
-- Name: gate(text, text, boolean); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.gate(k text, pk text, admin boolean) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN NOT access.flag('realm_invites') OR admin OR access.is_creator(k, pk) THEN 200 ELSE 403 END
$$;


--
-- Name: grandfather(text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.grandfather(by_ text) RETURNS jsonb
    LANGUAGE sql
    AS $$
  WITH owners AS (
    SELECT DISTINCT coalesce(w.owner_account, p.account, w.owner_player) AS who
    FROM verse.made_realms m JOIN verse.worlds w ON w.id = m.world LEFT JOIN verse.players p ON p.id = w.owner_player
  ), x AS (
    INSERT INTO access.creators (who, how, by, at_ms) SELECT who, 'grandfather', by_, projects.now_ms() FROM owners WHERE who IS NOT NULL
    ON CONFLICT (who) DO NOTHING RETURNING 1
  )
  SELECT access.r(200, jsonb_build_object('approved', (SELECT count(*) FROM x)), NULL)
$$;


--
-- Name: is_creator(text, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.is_creator(k text, pk text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM access.creators c WHERE c.who IN (
    verse.player_of(k),
    (SELECT p.account FROM verse.players p WHERE p.id = verse.player_of(k)),
    auth.account_of(pk)))
$$;


--
-- Name: is_db_admin(text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.is_db_admin(pk text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM access.admin_keys WHERE pubkey = lower(coalesce(pk, ''))) $$;


--
-- Name: line(text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.line(v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT regexp_replace(coalesce(v, ''), '[|\x00-\x1f\x7f]+', ' ', 'g')
$$;


--
-- Name: mint(jsonb, text, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.mint(body jsonb, by_ text, site text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  uses_ int := 1; days int := 14;
  code text := left(projects.token(), 32);
  id_ bigint;
BEGIN
  IF body ? 'uses' THEN
    IF jsonb_typeof(body->'uses') <> 'number' OR (body->>'uses')::numeric NOT BETWEEN 1 AND 1000 OR (body->>'uses')::numeric % 1 <> 0 THEN RETURN access.err(400, 'uses: 1 to 1000'); END IF;
    uses_ := (body->>'uses')::int;
  END IF;
  IF body ? 'days' THEN
    IF jsonb_typeof(body->'days') <> 'number' OR (body->>'days')::numeric NOT BETWEEN 1 AND 90 OR (body->>'days')::numeric % 1 <> 0 THEN RETURN access.err(400, 'days: 1 to 90'); END IF;
    days := (body->>'days')::int;
  END IF;
  INSERT INTO access.invites (code_sha256, uses, note, by, made_ms, expires_ms)
    VALUES (projects.sha(code), uses_, verse.clean_text(body->'note', 120), by_, projects.now_ms(), projects.now_ms() + days * 86400000::bigint)
    RETURNING id INTO id_;
  RETURN access.r(200, jsonb_build_object('id', id_, 'code', code, 'uses', uses_, 'days', days, 'link', site || '/invite#code=' || code), NULL);
END $$;


--
-- Name: r(integer, jsonb, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.r(status integer, body jsonb, lines text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('status', status, 'body', body, 'lines', lines)
$$;


--
-- Name: redeem(jsonb, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.redeem(body jsonb, pk text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  acct text := auth.account_of(pk);
  code text := CASE WHEN jsonb_typeof(body->'code') = 'string' THEN lower(btrim(body->>'code')) ELSE '' END;
  inv bigint;
BEGIN
  IF acct IS NULL THEN RETURN access.err(401, 'log in first'); END IF;
  IF code !~ '^[0-9a-f]{32}$' THEN RETURN access.err(404, 'that code isn''t good'); END IF;
  IF EXISTS (SELECT 1 FROM access.creators WHERE who = acct) THEN
    RETURN access.r(200, '{"creator": true}', E'creator 1\n');
  END IF;
  UPDATE access.invites SET used = used + 1
    WHERE code_sha256 = projects.sha(code) AND revoked_ms IS NULL AND expires_ms > projects.now_ms() AND used < uses
    RETURNING id INTO inv;
  IF inv IS NULL THEN RETURN access.err(404, 'that code isn''t good'); END IF;
  INSERT INTO access.redemptions VALUES (inv, acct, projects.now_ms());
  PERFORM access.approve(acct, 'invite', inv, NULL);
  RETURN access.r(200, '{"creator": true}', E'creator 1\n');
END $_$;


--
-- Name: remove(text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.remove(w text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM access.creators WHERE who = w;
  IF NOT FOUND THEN RETURN access.err(404, 'not a creator'); END IF;
  RETURN access.r(200, jsonb_build_object('who', w, 'creator', false), NULL);
END $$;


--
-- Name: revoke(bigint); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.revoke(id_ bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE access.invites SET revoked_ms = coalesce(revoked_ms, projects.now_ms()) WHERE id = id_;
  IF NOT FOUND THEN RETURN access.err(404, 'no such invite'); END IF;
  RETURN access.r(200, jsonb_build_object('id', id_, 'state', 'revoked'), NULL);
END $$;


--
-- Name: set_flag(jsonb, text); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.set_flag(body jsonb, by_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE n text := body->>'name';
BEGIN
  IF n IS NULL OR n <> 'realm_invites' OR jsonb_typeof(body->'on') <> 'boolean' THEN RETURN access.err(400, 'name and on'); END IF;
  INSERT INTO access.flags VALUES (n, (body->>'on')::boolean, by_, projects.now_ms())
    ON CONFLICT (name) DO UPDATE SET on_ = excluded.on_, set_by = excluded.set_by, set_ms = excluded.set_ms;
  RETURN access.r(200, jsonb_build_object('name', n, 'on', (body->>'on')::boolean), NULL);
END $$;


--
-- Name: state(text, text, boolean); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.state(k text, pk text, admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT format(E'invites %s\nmake %s\nin %s\ncreator %s\nasked %s\n',
    CASE WHEN access.flag('realm_invites') THEN 1 ELSE 0 END,
    CASE WHEN access.gate(k, pk, admin) = 200 THEN 1 ELSE 0 END,
    CASE WHEN auth.account_of(pk) IS NULL THEN 0 ELSE 1 END,
    CASE WHEN admin OR access.is_creator(k, pk) THEN 1 ELSE 0 END,
    coalesce((SELECT r.state FROM access.requests r WHERE r.who = auth.account_of(pk) ORDER BY r.id DESC LIMIT 1), 'none'))
$$;


--
-- Name: bot_agent(text); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.bot_agent(ua text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(left(regexp_replace(lower(coalesce(m[1], m[2], m[3])), '[^a-z0-9-]', '', 'g'), 32),
                  CASE WHEN coalesce(ua, '') ~* '\+https?://' THEN 'bot' END)
  FROM (SELECT regexp_match(coalesce(ua, ''),
    '(headlesschrome|headless|phantomjs|puppeteer|playwright|selenium|webdriver|lighthouse|'
    'facebookexternalhit|facebot|meta-externalagent|twitterbot|slackbot|discordbot|linkedinbot|'
    'telegrambot|googlebot|google-inspectiontool|adsbot|bingbot|applebot|yandexbot|'
    'baiduspider|duckduckbot|petalbot|bytespider|gptbot|claudebot|ccbot|crawler|spider|'
    'python-requests|python-urllib|curl/|wget/|go-http-client|okhttp|\ybot\y)'
    '|\y([a-z0-9_-]*(?:bot|crawl|spider|scraper|fetcher))/'
    '|compatible; *([a-z0-9_ .-]*(?:bot|crawl|spider|scan|scraper|fetcher|preview))', 'i') AS m) x
$$;


--
-- Name: clean_props(jsonb); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.clean_props(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  out jsonb := '{}';
  k text; v jsonb; n int := 0;
  consent boolean := jsonb_typeof(p) = 'object' AND p->'consent' = 'true'::jsonb;
BEGIN
  IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RETURN out; END IF;
  FOR k, v IN SELECT key, value FROM jsonb_each(p) LOOP
    EXIT WHEN n >= 16;
    CONTINUE WHEN k !~ '^[A-Za-z][A-Za-z0-9_]{0,23}$';
    IF k = 'text' THEN
      IF consent AND jsonb_typeof(v) = 'string' THEN out := out || jsonb_build_object(k, left(v #>> '{}', 500)); n := n + 1; END IF;
      CONTINUE;
    END IF;
    CASE jsonb_typeof(v)
      WHEN 'boolean', 'null' THEN out := out || jsonb_build_object(k, v);
      WHEN 'number' THEN
        out := out || jsonb_build_object(k, CASE WHEN v::text ~ '[.eE]' THEN to_jsonb(round((v::text)::numeric, 3)) ELSE v END);
      WHEN 'string' THEN out := out || jsonb_build_object(k, left(v #>> '{}', 80));
      ELSE CONTINUE;
    END CASE;
    n := n + 1;
  END LOOP;
  RETURN out;
END $_$;


--
-- Name: email_sha256(text); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.email_sha256(email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT encode(sha256(convert_to(lower(btrim(coalesce(email, ''))), 'UTF8')), 'hex') $$;


--
-- Name: health(bigint); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.health(now_ms bigint) RETURNS TABLE(surface text, last_ms bigint, last_ev text, hour bigint, day bigint, missing text[])
    LANGUAGE sql STABLE
    AS $$
  WITH recent AS (
    SELECT page, ev, ms FROM analytics.events WHERE space = 'web' AND ms >= now_ms - 30 * 86400000::bigint
  ), surfaces AS (
    SELECT DISTINCT c.surface FROM analytics.contract c
    UNION SELECT DISTINCT page FROM recent WHERE ms >= now_ms - 86400000 AND page <> ''
  )
  SELECT s.surface,
    (SELECT max(r.ms) FROM recent r WHERE r.page = s.surface),
    (SELECT r.ev FROM recent r WHERE r.page = s.surface ORDER BY r.ms DESC LIMIT 1),
    (SELECT count(*) FROM recent r WHERE r.page = s.surface AND r.ms >= now_ms - 3600000),
    (SELECT count(*) FROM recent r WHERE r.page = s.surface AND r.ms >= now_ms - 86400000),
    coalesce((SELECT array_agg(c.ev ORDER BY c.ev) FROM analytics.contract c WHERE c.surface = s.surface
      AND NOT EXISTS (SELECT 1 FROM recent r WHERE r.page = c.surface AND r.ev = c.ev AND r.ms >= now_ms - 86400000)), '{}')
  FROM surfaces s
$$;


--
-- Name: ingest(jsonb, jsonb); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.ingest(batch jsonb, ctx jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
  s text := batch->>'sid';
  now_ms bigint := (ctx->>'ms')::bigint;
  auto text := coalesce(nullif(ctx->>'auto', ''), CASE WHEN batch->>'auto' ~ '^[a-z][a-z0-9-]{0,31}$' THEN batch->>'auto' END);
  agent text := coalesce(nullif(ctx->>'agent', ''), analytics.bot_agent(ctx->>'ua'));
  k text := ctx->>'key';
  pl verse.players;
  acct_npub text;
  sess_npub text;
  site_npub text;
  was_team boolean;
  team_ boolean;
  npub_ text := nullif(ctx->>'npub', '');
  have int;
  kept int;
BEGIN
  IF jsonb_typeof(batch) IS DISTINCT FROM 'object' OR s IS NULL OR s !~ '^[A-Za-z0-9_:-]{8,80}$'
     OR jsonb_typeof(batch->'events') IS DISTINCT FROM 'array' THEN
    RETURN -1;
  END IF;
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO pl FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
    SELECT a.npub INTO acct_npub FROM verse.accounts a WHERE a.id = pl.account;
  END IF;
  IF ctx->>'site' ~ '^[0-9a-f]{64}$' THEN site_npub := ctx->>'site'; END IF;   -- a logged-in session's key (analytics.c)
  SELECT x.events, x.npub, x.team INTO have, sess_npub, was_team FROM analytics.sessions x WHERE x.sid = s;
  npub_ := coalesce(npub_, sess_npub, acct_npub);
  have := coalesce(have, 0);
  was_team := coalesce(was_team, false);
  team_ := auto IS NULL AND (was_team OR coalesce(ctx->>'team', '') = '1'
    OR EXISTS (SELECT 1 FROM analytics.team t WHERE t.kind = 'npub' AND t.value IN (npub_, acct_npub, site_npub))
    OR (pl.id IS NOT NULL AND EXISTS (SELECT 1 FROM analytics.team t WHERE t.kind = 'player' AND t.value = pl.id))
    OR EXISTS (SELECT 1 FROM analytics.playtesters j WHERE j.sid = s AND j.auto = 'team')   -- joined as the team before this batch
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(batch->'events') e JOIN analytics.team_devices v ON v.pid = e->'p'->>'pid'
               WHERE jsonb_typeof(e) = 'object' AND jsonb_typeof(e->'p') = 'object'));
  team_ := coalesce(team_, false);
  IF team_ THEN auto := 'team'; END IF;
  WITH raw AS (
    SELECT e, ord FROM jsonb_array_elements(batch->'events') WITH ORDINALITY AS a(e, ord) WHERE ord <= 50
  ), clean AS (
    SELECT ord, e->>'ev' AS ev,
           CASE WHEN jsonb_typeof(e->'page') = 'string' THEN left(e->>'page', 32) ELSE '' END AS page,
           CASE WHEN jsonb_typeof(e->'ct') = 'number' THEN floor((e->>'ct')::numeric)::bigint END AS ct,
           analytics.clean_props(e->'p') AS p
    FROM raw WHERE jsonb_typeof(e) = 'object' AND e->>'ev' ~ '^[a-z][a-z0-9-]{0,31}$'
  ), capped AS (
    SELECT * FROM clean ORDER BY ord LIMIT greatest(0, 5000 - have)
  )
  INSERT INTO analytics.events (ms, sid, acct, npub, ev, page, ct, p, auto, space, host)
  SELECT now_ms, s, pl.account, npub_, ev, page, ct,
         CASE WHEN ev = 'session-start' AND agent IS NOT NULL THEN p || jsonb_build_object('agent', agent) ELSE p END,
         auto, 'web', nullif(ctx->>'host', '')
  FROM capped ORDER BY ord;
  GET DIAGNOSTICS kept = ROW_COUNT;
  INSERT INTO analytics.sessions AS x (sid, first_ms, last_ms, host, ip, ua, agent, region, subdivision, city, latlong, rtt_ms, tls, device, npub, events, player, team)
  VALUES (s, now_ms, now_ms, nullif(ctx->>'host', ''), nullif(ctx->>'ip', ''), left(nullif(ctx->>'ua', ''), 400), agent,
          nullif(ctx->>'region', ''), nullif(ctx->>'subdivision', ''), nullif(ctx->>'city', ''), nullif(ctx->>'latlong', ''),
          CASE WHEN ctx->>'rtt' ~ '^[0-9]{1,9}$' THEN (ctx->>'rtt')::int END, nullif(ctx->>'tls', ''), nullif(ctx->>'device', ''),
          npub_, kept, pl.id, team_)
  ON CONFLICT (sid) DO UPDATE SET last_ms = greatest(x.last_ms, EXCLUDED.last_ms), events = x.events + EXCLUDED.events,
    npub = coalesce(x.npub, EXCLUDED.npub), ip = coalesce(x.ip, EXCLUDED.ip), ua = coalesce(x.ua, EXCLUDED.ua),
    agent = coalesce(x.agent, EXCLUDED.agent), region = coalesce(x.region, EXCLUDED.region),
    subdivision = coalesce(x.subdivision, EXCLUDED.subdivision), city = coalesce(x.city, EXCLUDED.city),
    latlong = coalesce(x.latlong, EXCLUDED.latlong), rtt_ms = coalesce(x.rtt_ms, EXCLUDED.rtt_ms),
    tls = coalesce(x.tls, EXCLUDED.tls), device = coalesce(x.device, EXCLUDED.device),
    player = coalesce(x.player, EXCLUDED.player), team = x.team OR EXCLUDED.team;
  -- newly team, or a pid of this batch not yet known: spread it
  IF team_ AND (NOT was_team OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(batch->'events') e
       WHERE jsonb_typeof(e) = 'object' AND e->>'ev' IN ('session-start', 'page-view') AND jsonb_typeof(e->'p') = 'object'
         AND e->'p'->>'pid' ~ '^[A-Za-z0-9_-]{6,64}$'
         AND NOT EXISTS (SELECT 1 FROM analytics.team_devices v WHERE v.pid = e->'p'->>'pid'))) THEN
    PERFORM analytics.team_tag();
  END IF;
  RETURN kept;
END $_$;


--
-- Name: team_after_events(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.team_after_events() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF EXISTS (SELECT 1 FROM new_rows n WHERE n.auto IS NULL AND (
       EXISTS (SELECT 1 FROM analytics.team t WHERE (t.kind = 'npub' AND t.value = n.npub)
                 OR (t.kind = 'player' AND t.value ~ '^[a-z]+-[0-9a-f]{16}$' AND n.sid LIKE t.value || '-%'))
       OR EXISTS (SELECT 1 FROM analytics.sessions x WHERE x.sid = n.sid AND x.team)
       OR EXISTS (SELECT 1 FROM analytics.playtesters j WHERE j.sid = n.sid AND j.auto = 'team')
       OR (n.ev IN ('session-start', 'page-view') AND EXISTS (SELECT 1 FROM analytics.team_devices v WHERE v.pid = n.p->>'pid')))) THEN
    PERFORM analytics.team_tag();
  END IF;
  RETURN NULL;
END $_$;


--
-- Name: team_after_playtesters(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.team_after_playtesters() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM new_rows n WHERE n.auto IS NULL AND analytics.team_playtester(n.email, n.player, n.space)) THEN
    PERFORM analytics.team_tag();
  END IF;
  RETURN NULL;
END $$;


--
-- Name: team_playtester(text, text, text); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.team_playtester(email text, player text, space text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM analytics.team t WHERE
    (t.kind = 'email_sha256' AND t.value = analytics.email_sha256(email))
    OR (t.kind = 'player' AND player IS NOT NULL AND (t.value = player OR t.value = space || '-' || player)))
$$;


--
-- Name: team_set(jsonb); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.team_set(cfg jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE n int;
BEGIN
  DELETE FROM analytics.team;
  INSERT INTO analytics.team (kind, value)
  SELECT DISTINCT k, lower(v) FROM (
    SELECT 'npub' AS k, jsonb_array_elements_text(coalesce(cfg->'npub', '[]')) AS v
    UNION ALL SELECT 'player', jsonb_array_elements_text(coalesce(cfg->'player', '[]'))
    UNION ALL SELECT 'email_sha256', jsonb_array_elements_text(coalesce(cfg->'email_sha256', '[]'))) x
  WHERE (k = 'npub' AND v ~* '^[0-9a-f]{64}$') OR (k = 'email_sha256' AND v ~* '^[0-9a-f]{64}$')
     OR (k = 'player' AND v ~ '^[a-z][a-z0-9-]{3,63}$');
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $_$;


--
-- Name: team_tag(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.team_tag() RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  devices int := 0; d int; s int; rounds int := 0;
  sessions_n int; events_n int; playtesters_n int; answers_n int;
  now_ms bigint := floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS team_sids (sid text PRIMARY KEY) ON COMMIT DROP;
  DELETE FROM team_sids;
  -- the seeds: sessions already team, an admin's key, a team player or email
  INSERT INTO team_sids SELECT sid FROM analytics.sessions WHERE team ON CONFLICT DO NOTHING;
  INSERT INTO team_sids SELECT x.sid FROM analytics.sessions x JOIN analytics.team t
    ON (t.kind = 'npub' AND t.value = x.npub) OR (t.kind = 'player' AND t.value = x.player) ON CONFLICT DO NOTHING;
  INSERT INTO team_sids SELECT DISTINCT e.sid FROM analytics.events e JOIN analytics.team t ON t.kind = 'npub' AND t.value = e.npub
    ON CONFLICT DO NOTHING;
  INSERT INTO team_sids SELECT DISTINCT p.sid FROM analytics.playtesters p
    WHERE p.sid IS NOT NULL AND p.sid <> '' AND analytics.team_playtester(p.email, p.player, p.space) ON CONFLICT DO NOTHING;
  -- the old playtest's sessions are kiki-<player hex>-<8 hex>
  INSERT INTO team_sids SELECT DISTINCT e.sid FROM analytics.events e JOIN analytics.team t
    ON t.kind = 'player' AND t.value ~ '^[a-z]+-[0-9a-f]{16}$' AND e.sid LIKE t.value || '-%' ON CONFLICT DO NOTHING;
  -- devices <-> sessions, to a fixed point
  LOOP
    rounds := rounds + 1;
    INSERT INTO analytics.team_devices (pid, ms, sid)
    SELECT DISTINCT ON (e.p->>'pid') e.p->>'pid', now_ms, e.sid FROM analytics.events e JOIN team_sids USING (sid)
    WHERE e.ev IN ('session-start', 'page-view') AND e.p->>'pid' ~ '^[A-Za-z0-9_-]{6,64}$'
      AND (e.auto IS NULL OR e.auto = 'team')   -- not from an automated run's own events
    ORDER BY e.p->>'pid', e.ms
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS d = ROW_COUNT;
    devices := devices + d;
    INSERT INTO team_sids SELECT DISTINCT e.sid FROM analytics.events e JOIN analytics.team_devices v ON v.pid = e.p->>'pid'
    WHERE e.ev IN ('session-start', 'page-view') ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS s = ROW_COUNT;
    EXIT WHEN (d = 0 AND s = 0) OR rounds >= 20;
  END LOOP;
  -- the backfill; automation keeps its own mark
  UPDATE analytics.sessions x SET team = true FROM team_sids t WHERE x.sid = t.sid AND NOT x.team;
  GET DIAGNOSTICS sessions_n = ROW_COUNT;
  UPDATE analytics.events e SET auto = 'team' FROM team_sids t WHERE e.sid = t.sid AND e.auto IS NULL;
  GET DIAGNOSTICS events_n = ROW_COUNT;
  UPDATE analytics.playtesters p SET auto = 'team'
  WHERE p.auto IS NULL AND (p.sid IN (SELECT sid FROM team_sids) OR analytics.team_playtester(p.email, p.player, p.space));
  GET DIAGNOSTICS playtesters_n = ROW_COUNT;
  UPDATE analytics.survey_answers a SET auto = 'team' FROM team_sids t WHERE a.sid = t.sid AND a.auto IS NULL;
  GET DIAGNOSTICS answers_n = ROW_COUNT;
  RETURN jsonb_build_object('sessions', sessions_n, 'events', events_n, 'devices', devices,
                            'playtesters', playtesters_n, 'answers', answers_n);
END $_$;


--
-- Name: access_session(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.access_session(at_sha text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT s.token_sha256 FROM auth.refresh r JOIN auth.sessions s ON s.id = r.session
   WHERE r.access_sha256 = at_sha AND r.access_until > now()
$$;


--
-- Name: account_for_key(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.account_for_key(pk text, label_ text, OUT acct text, OUT made boolean) RETURNS record
    LANGUAGE plpgsql
    AS $_$
DECLARE old text;
BEGIN
  made := false;
  IF coalesce(pk, '') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'auth: not a key' USING ERRCODE = 'invalid_parameter_value'; END IF;
  SELECT account INTO acct FROM auth.nostr_keys WHERE pubkey = pk;
  IF acct IS NOT NULL THEN
    UPDATE auth.nostr_keys SET last_used_at = now() WHERE pubkey = pk;
    RETURN;
  END IF;
  old := (SELECT a.id FROM verse.accounts a WHERE a.id = 'n-' || pk);
  -- An old account already adopted by another key keeps its one owner: this key starts fresh.
  IF old IS NOT NULL AND EXISTS (SELECT 1 FROM auth.accounts WHERE verse_account = old) THEN old := NULL; END IF;
  acct := auth.new_person(old);
  INSERT INTO auth.nostr_keys (account, pubkey, label, last_used_at) VALUES (acct, pk, nullif(left(label_, 80), ''), now());
  UPDATE auth.accounts SET team = auth.is_team(acct) WHERE id = acct;
  made := true;
END $_$;


--
-- Name: account_named(text[], text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.account_named(lookups text[], pk text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT e.account FROM auth.emails e WHERE e.lookup = ANY(lookups) LIMIT 1),
                  (SELECT k.account FROM auth.nostr_keys k WHERE k.pubkey = pk))
$$;


--
-- Name: account_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.account_of(pk text) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT CASE
    WHEN pk ~ '^acct_[a-z2-7]{26}$' THEN (SELECT a.verse_account FROM auth.accounts a WHERE a.id = pk AND a.deleted_at IS NULL)
    WHEN coalesce(pk, '') !~ '^[0-9a-f]{64}$' THEN NULL
    ELSE coalesce((SELECT a.verse_account FROM auth.nostr_keys k JOIN auth.accounts a ON a.id = k.account WHERE k.pubkey = pk),
                  'n-' || pk) END
$_$;


--
-- Name: agent_facts(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.agent_facts(acct text) RETURNS TABLE(grant_id text, owner text, scopes integer, per_day bigint, per_payment bigint, hosts text[], expires_ms bigint, revoked_ms bigint, suspended boolean, now_ms bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT g.id, g.owner, g.scopes, g.sats_per_day, g.sats_per_payment, g.hosts,
         (extract(epoch FROM g.expires_at) * 1000)::bigint,
         coalesce((extract(epoch FROM g.revoked_at) * 1000)::bigint, 0),
         g.suspended_at IS NOT NULL OR a.frozen_at IS NOT NULL OR a.deleted_at IS NOT NULL
           OR o.frozen_at IS NOT NULL OR o.deleted_at IS NOT NULL,
         (extract(epoch FROM now()) * 1000)::bigint
    FROM auth.agent_grants g JOIN auth.accounts a ON a.id = g.agent JOIN auth.accounts o ON o.id = g.owner
   WHERE g.agent = acct
$$;


--
-- Name: agents_of(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.agents_of(owner_ text, one text) RETURNS TABLE(account text, name text, grant_id text, scopes integer, per_day bigint, per_payment bigint, hosts text, created_ms bigint, expires_ms bigint, revoked_ms bigint, suspended boolean, spent bigint, last_used_ms bigint, now_ms bigint, record text, keys text)
    LANGUAGE sql STABLE
    AS $$
  SELECT a.id, coalesce(a.display_name, ''), g.id, g.scopes, g.sats_per_day, g.sats_per_payment, array_to_string(g.hosts, ' '),
         (extract(epoch FROM g.approved_at) * 1000)::bigint, (extract(epoch FROM g.expires_at) * 1000)::bigint,
         coalesce((extract(epoch FROM g.revoked_at) * 1000)::bigint, 0),
         g.suspended_at IS NOT NULL OR a.frozen_at IS NOT NULL OR o.frozen_at IS NOT NULL,
         auth.spent_24h(g.id), coalesce((extract(epoch FROM g.last_used_at) * 1000)::bigint, 0),
         (extract(epoch FROM now()) * 1000)::bigint, encode(g.record, 'hex'),
         coalesce((SELECT string_agg(k, E'\n' ORDER BY k) FROM (
             SELECT concat_ws(' ', ak.id, 1, (extract(epoch FROM ak.created_at) * 1000)::bigint,
                              coalesce((extract(epoch FROM ak.last_used_at) * 1000)::bigint, 0),
                              coalesce((extract(epoch FROM ak.revoked_at) * 1000)::bigint, 0)) k
               FROM auth.agent_keys ak WHERE ak.agent = a.id
             UNION ALL
             SELECT concat_ws(' ', nk.pubkey, 0, (extract(epoch FROM nk.created_at) * 1000)::bigint,
                              coalesce((extract(epoch FROM nk.last_used_at) * 1000)::bigint, 0), 0)
               FROM auth.nostr_keys nk WHERE nk.account = a.id) s), '')
    FROM auth.accounts a JOIN auth.agent_grants g ON g.agent = a.id JOIN auth.accounts o ON o.id = a.owner
   WHERE a.owner = owner_ AND a.kind = 'agent' AND a.deleted_at IS NULL AND g.revoked_at IS NULL AND (one IS NULL OR a.id = one)
   ORDER BY g.approved_at DESC
   LIMIT 32
$$;


--
-- Name: agents_sweep(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.agents_sweep() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE n int; m int;
BEGIN
  DELETE FROM auth.agent_requests WHERE expires_at < now() - interval '1 day';
  GET DIAGNOSTICS n = ROW_COUNT;
  DELETE FROM auth.agent_spends WHERE at < now() - interval '7 days';
  GET DIAGNOSTICS m = ROW_COUNT;
  RETURN n + m;
END $$;


--
-- Name: app_pair(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.app_pair(sid text, family_ text, rt_sha text, at_sha text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.refresh (token_sha256, family, session, access_sha256, access_until)
  VALUES (rt_sha, family_, sid, at_sha, now() + interval '1 hour')
$$;


--
-- Name: app_refresh(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.app_refresh(rt_sha text, new_rt text, new_at text, OUT state text, OUT account text, OUT family text) RETURNS record
    LANGUAGE sql
    AS $$
  SELECT r.state, r.account, r.family FROM auth.app_refresh(rt_sha, new_rt, new_at, NULL::bigint) r
$$;


--
-- Name: app_refresh(text, text, text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.app_refresh(rt_sha text, new_rt text, new_at text, proved bigint, OUT state text, OUT account text, OUT family text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE r auth.refresh; dev bigint; live boolean;
BEGIN
  SELECT * INTO r FROM auth.refresh WHERE token_sha256 = rt_sha FOR UPDATE;
  IF r.token_sha256 IS NULL THEN state := 'unknown'; RETURN; END IF;
  SELECT s.account, s.device INTO account, dev FROM auth.sessions s WHERE s.id = r.session;
  family := r.family;
  IF dev IS NOT NULL THEN
    SELECT d.revoked_at IS NULL INTO live FROM auth.devices d WHERE d.id = dev;
    IF proved IS DISTINCT FROM dev OR NOT coalesce(live, false) THEN state := 'proof'; RETURN; END IF;
  END IF;
  IF r.spent_at IS NOT NULL THEN
    DELETE FROM auth.sessions s WHERE s.id IN (SELECT x.session FROM auth.refresh x WHERE x.family = r.family);
    state := 'reused'; RETURN;
  END IF;
  IF r.created_at < now() - interval '90 days' THEN
    DELETE FROM auth.sessions s WHERE s.id = r.session;
    state := 'idle'; RETURN;
  END IF;
  UPDATE auth.refresh SET spent_at = now() WHERE token_sha256 = rt_sha;
  INSERT INTO auth.refresh (token_sha256, family, session, access_sha256, access_until)
  VALUES (new_rt, r.family, r.session, new_at, now() + interval '1 hour');
  UPDATE auth.sessions SET last_seen_at = now() WHERE id = r.session;
  IF dev IS NOT NULL THEN UPDATE auth.devices SET last_seen_at = now() WHERE id = dev; END IF;
  state := 'ok';
END $$;


--
-- Name: attach_guest(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.attach_guest(vacct text, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  rec verse.players;
  own text;
BEGIN
  IF coalesce(k, '') !~ '^[A-Za-z0-9_-]{20,128}$' OR vacct IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO rec FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  IF rec.id IS NULL THEN RETURN NULL; END IF;
  IF rec.account IS NOT NULL AND rec.account <> vacct AND rec.account NOT LIKE 'g-%' THEN RETURN NULL; END IF;
  own := CASE WHEN rec.account LIKE 'g-%' THEN rec.account END;
  UPDATE verse.players SET account = vacct WHERE id = rec.id OR (own IS NOT NULL AND account = own);
  UPDATE verse.worlds SET owner_account = vacct
   WHERE (owner_player = rec.id AND (owner_account IS NULL OR owner_account = own)) OR (own IS NOT NULL AND owner_account = own);
  IF own IS NOT NULL THEN
    UPDATE verse.progress g SET account = vacct
     WHERE g.account = own AND NOT EXISTS (SELECT 1 FROM verse.progress x WHERE x.account = vacct AND x.slot = g.slot);
    DELETE FROM verse.progress WHERE account = own;
  END IF;
  RETURN jsonb_build_object('key', k, 'id', rec.id, 'account', vacct);
END $_$;


--
-- Name: audit_age(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.audit_age() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.audit SET account = NULL WHERE at < now() - interval '2 years' AND account IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: audit_day(date); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.audit_day(day date) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg(jsonb_build_object('id', id, 'at', at, 'account', account, 'actor', actor, 'action', action,
                                                'result', result, 'detail', detail)::text, E'\n' ORDER BY id) || E'\n', '')
    FROM auth.audit WHERE (at AT TIME ZONE 'America/Chicago')::date = day
$$;


--
-- Name: audit_forget(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.audit_forget(acct text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'auth'
    AS $_$
DECLARE n int;
BEGIN
  IF coalesce(acct, '') !~ '^acct_[a-z2-7]{26}$' THEN RETURN 0; END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.accounts WHERE id = acct AND deleted_at IS NOT NULL) THEN RETURN 0; END IF;
  UPDATE auth.audit SET account = NULL WHERE account = acct;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $_$;


--
-- Name: audit_frozen(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.audit_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_user <> (SELECT pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = TG_RELID) THEN
    RAISE EXCEPTION 'auth.audit is append-only (docs/auth/data-and-backups.md)' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: audit_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.audit_of(acct text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('at', at, 'action', action, 'result', result, 'detail', detail) ORDER BY id), '[]'::jsonb)
    FROM auth.audit WHERE account = acct
$$;


--
-- Name: bech32(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.bech32(hrp text, hex text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  cs constant text := 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
  g constant int[] := ARRAY[996825010, 642813549, 513874426, 1027748829, 705979059];
  b bytea := decode(hex, 'hex');
  v int[] := '{}';
  acc int := 0; bits int := 0; chk int := 1; top int; x int; out text := '';
BEGIN
  FOR i IN 0 .. length(b) - 1 LOOP
    acc := ((acc << 8) | get_byte(b, i)) & 4095; bits := bits + 8;
    WHILE bits >= 5 LOOP bits := bits - 5; v := v || ((acc >> bits) & 31); END LOOP;
  END LOOP;
  IF bits > 0 THEN v := v || ((acc << (5 - bits)) & 31); END IF;
  -- the checksum over the expanded hrp, the data and six zeros
  FOREACH x IN ARRAY (SELECT array_agg(ascii(substr(hrp, i, 1)) >> 5 ORDER BY i) FROM generate_series(1, length(hrp)) i) || 0
      || (SELECT array_agg(ascii(substr(hrp, i, 1)) & 31 ORDER BY i) FROM generate_series(1, length(hrp)) i) || v || ARRAY[0, 0, 0, 0, 0, 0] LOOP
    top := chk >> 25; chk := ((chk & 33554431) << 5) # x;
    FOR k IN 0 .. 4 LOOP IF (top >> k) & 1 = 1 THEN chk := chk # g[k + 1]; END IF; END LOOP;
  END LOOP;
  chk := chk # 1;
  FOREACH x IN ARRAY v LOOP out := out || substr(cs, x + 1, 1); END LOOP;
  FOR k IN 0 .. 5 LOOP out := out || substr(cs, ((chk >> (5 * (5 - k))) & 31) + 1, 1); END LOOP;
  RETURN hrp || '1' || out;
END $$;


--
-- Name: bucket_lock(text, text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.bucket_lock(name_ text, key_ text, full_ms bigint, OUT fill_ms bigint, OUT at_ms bigint, OUT now_ms bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  now_ms := projects.now_ms();
  INSERT INTO auth.limit_buckets (name, key, fill_ms, at_ms) VALUES (name_, key_, full_ms, now_ms) ON CONFLICT DO NOTHING;
  SELECT b.fill_ms, b.at_ms INTO fill_ms, at_ms FROM auth.limit_buckets b WHERE b.name = name_ AND b.key = key_ FOR UPDATE;
  IF random() < 0.01 THEN DELETE FROM auth.limit_buckets b WHERE b.at_ms < now_ms - 86400000; END IF;
END $$;


--
-- Name: bucket_put(text, text, bigint, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.bucket_put(name_ text, key_ text, fill_ms_ bigint, at_ms_ bigint) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.limit_buckets SET fill_ms = fill_ms_, at_ms = at_ms_ WHERE name = name_ AND key = key_ $$;


--
-- Name: caller_key(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.caller_key(pk text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  acct text := auth.account_of(pk);
  k text;
BEGIN
  IF acct IS NULL THEN RETURN NULL; END IF;
  k := 'c' || projects.sha((SELECT secret FROM auth.caller_secret) || ':' || acct);
  IF NOT EXISTS (SELECT 1 FROM verse.players WHERE key_sha256 = projects.sha(k)) THEN
    INSERT INTO verse.accounts (id, npub, created_ms)
      VALUES (acct, CASE WHEN acct = 'n-' || pk THEN pk END, verse.now_ms()) ON CONFLICT DO NOTHING;
    INSERT INTO verse.players (id, key_sha256, account, created_ms)
      VALUES ('p-' || left(projects.sha('caller:' || acct), 16), projects.sha(k), acct, verse.now_ms()) ON CONFLICT DO NOTHING;
  END IF;
  RETURN k;
END $$;


--
-- Name: code_new(text, bytea, bytea); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.code_new(acct text, hash bytea, salt_ bytea) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE id_ bigint;
BEGIN
  INSERT INTO auth.recovery (account, code_scrypt, salt) VALUES (acct, hash, salt_) RETURNING id INTO id_;
  UPDATE auth.recovery SET spent_at = now() WHERE account = acct AND spent_at IS NULL AND id <> id_;
  RETURN id_;
END $$;


--
-- Name: code_spend(bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.code_spend(id_ bigint) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH u AS (UPDATE auth.recovery SET spent_at = now() WHERE id = id_ AND spent_at IS NULL RETURNING 1) SELECT EXISTS (SELECT 1 FROM u)
$$;


--
-- Name: credit_limit_facts(text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.credit_limit_facts(pk text, default_sat bigint, OUT account text, OUT daily_sat bigint, OUT pending_sat bigint, OUT pending_ms bigint, OUT now_ms bigint, OUT wallet_sat bigint, OUT credit_msat bigint, OUT l2_age_ms bigint) RETURNS SETOF record
    LANGUAGE sql STABLE
    AS $$
  SELECT a.id, coalesce(l.daily_sat, default_sat), coalesce(l.pending_sat, 0), coalesce((extract(epoch FROM l.pending_at) * 1000)::bigint, 0),
         (extract(epoch FROM now()) * 1000)::bigint,
         (SELECT w.spent FROM auth.wallet_spent(a.id, '') w), auth.credit_spent(a.id),
         coalesce(((extract(epoch FROM now()) - extract(epoch FROM (SELECT max(s.l2_at) FROM auth.sessions s WHERE s.account = a.id))) * 1000)::bigint, -1)
    FROM auth.nostr_keys k JOIN auth.accounts a ON a.id = k.account AND a.kind = 'person' AND a.deleted_at IS NULL
    LEFT JOIN auth.wallet_limits l ON l.account = a.id
   WHERE k.pubkey = pk
$$;


--
-- Name: credit_spent(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.credit_spent(acct text) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(sum(c.msat), 0)::bigint FROM auth.credit_spends c WHERE c.account = acct AND c.hour > now() - interval '25 hours'
$$;


--
-- Name: delete_ask(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.delete_ask(acct text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE at_ timestamptz;
BEGIN
  UPDATE auth.accounts SET delete_asked_at = coalesce(delete_asked_at, now()),
                           purge_at = coalesce(purge_at, now() + interval '30 days'),
                           frozen_at = coalesce(frozen_at, now()), frozen_why = coalesce(frozen_why, 'delete')
   WHERE id = acct AND kind = 'person' AND deleted_at IS NULL AND merged_into IS NULL
   RETURNING purge_at INTO at_;
  IF at_ IS NULL THEN RETURN NULL; END IF;
  PERFORM auth.sessions_end_all(acct);
  RETURN (extract(epoch FROM at_) * 1000)::bigint;
END $$;


--
-- Name: delete_cancel(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.delete_cancel(acct text) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH u AS (UPDATE auth.accounts SET delete_asked_at = NULL, purge_at = NULL,
                                      frozen_at = CASE WHEN frozen_why = 'delete' THEN NULL ELSE frozen_at END,
                                      frozen_why = CASE WHEN frozen_why = 'delete' THEN NULL ELSE frozen_why END
              WHERE id = acct AND delete_asked_at IS NOT NULL AND deleted_at IS NULL RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM u)
$$;


--
-- Name: device_link(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_link(acct text, code text, OUT status integer, OUT machine text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE d auth.device_logins; held text;
BEGIN
  SELECT * INTO d FROM auth.device_logins x WHERE x.code_sha256 = projects.sha(coalesce(code, '')) FOR UPDATE;
  IF d.id IS NULL THEN status := 404; RETURN; END IF;
  machine := d.machine;
  IF d.account IS NOT NULL THEN status := 409; RETURN; END IF;
  IF d.expires_ms <= projects.now_ms() THEN status := 410; RETURN; END IF;
  SELECT k.account INTO held FROM auth.nostr_keys k WHERE k.pubkey = d.pubkey;
  IF held IS NOT NULL AND held <> acct THEN status := 409; RETURN; END IF;
  UPDATE auth.device_logins SET account = acct, approved_ms = projects.now_ms(), approved_by = acct WHERE id = d.id;
  IF held IS NULL THEN
    INSERT INTO auth.nostr_keys (account, pubkey, label) VALUES (acct, d.pubkey, left('cli:' || d.machine, 80));
  END IF;
  status := 200;
END $$;


--
-- Name: device_look(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_look(body jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE d auth.device_logins;
BEGIN
  SELECT * INTO d FROM auth.device_logins x WHERE x.code_sha256 = projects.sha(coalesce(body->>'code', ''));
  IF d.id IS NULL THEN RETURN access.err(404, 'that code isn''t good'); END IF;
  RETURN access.r(200, jsonb_build_object('machine', d.machine,
      'state', CASE WHEN d.account IS NOT NULL THEN 'approved' WHEN d.expires_ms <= projects.now_ms() THEN 'expired' ELSE 'waiting' END), NULL);
END $$;


--
-- Name: device_look(text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_look(acct text, dev bigint, OUT found boolean, OUT mine boolean, OUT removed boolean) RETURNS record
    LANGUAGE sql STABLE
    AS $$
  SELECT count(*) > 0, coalesce(bool_or(d.account = acct), false), coalesce(bool_or(d.revoked_at IS NOT NULL), false) FROM auth.devices d WHERE d.id = dev
$$;


--
-- Name: device_machine(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_machine(m text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(left(btrim(access.line(m)), 64), '')
$$;


--
-- Name: device_moved(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_moved() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.account IS DISTINCT FROM OLD.account THEN NEW.revoked_at := coalesce(NEW.revoked_at, now()); END IF;
  RETURN NEW;
END $$;


--
-- Name: device_poll(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_poll(pk text, id_ text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE d auth.device_logins;
BEGIN
  SELECT * INTO d FROM auth.device_logins x WHERE x.id = id_ AND x.pubkey = pk;
  IF d.id IS NULL THEN RETURN access.err(404, 'no such request'); END IF;
  IF d.account IS NOT NULL THEN
    RETURN access.r(200, jsonb_build_object('state', 'approved', 'account', d.account), format(E'state approved\naccount %s\n', d.account));
  END IF;
  IF d.expires_ms <= projects.now_ms() THEN RETURN access.r(200, jsonb_build_object('state', 'expired'), E'state expired\n'); END IF;
  RETURN access.r(200, jsonb_build_object('state', 'waiting'), E'state waiting\n');
END $$;


--
-- Name: device_proof_once(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_proof_once(sha text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  DELETE FROM auth.device_proofs WHERE expires_at < now();
  INSERT INTO auth.device_proofs (message_sha256, expires_at) VALUES (sha, now() + interval '11 minutes') ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n = 1;
END $$;


--
-- Name: device_push_forget(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_push_forget() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.revoked_at IS NOT NULL THEN NEW.push_service := NULL; NEW.push_token := NULL; NEW.push_at := NULL; END IF;
  RETURN NEW;
END $$;


--
-- Name: device_push_gone(bigint, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_push_gone(dev bigint, token_ text) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.devices SET push_service = NULL, push_token = NULL, push_at = NULL WHERE id = dev AND push_token = token_
$$;


--
-- Name: device_push_off(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_push_off(acct text, sid text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.devices d SET push_service = NULL, push_token = NULL, push_at = NULL
    FROM auth.sessions s
   WHERE s.id = sid AND s.account = acct AND d.id = s.device AND d.account = acct AND d.push_token IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n > 0;
END $$;


--
-- Name: device_push_set(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_push_set(acct text, sid text, service_ text, token_ text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE dev bigint;
BEGIN
  SELECT d.id INTO dev FROM auth.sessions s JOIN auth.devices d ON d.id = s.device
   WHERE s.id = sid AND s.account = acct AND s.client = 'app' AND d.account = acct AND d.revoked_at IS NULL FOR UPDATE OF d;
  IF dev IS NULL THEN RETURN NULL; END IF;
  UPDATE auth.devices SET push_service = NULL, push_token = NULL, push_at = NULL
   WHERE push_service = service_ AND push_token = token_ AND id <> dev;
  UPDATE auth.devices SET push_service = service_, push_token = token_, push_at = now() WHERE id = dev;
  RETURN dev;
END $$;


--
-- Name: device_remove(text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_remove(acct text, dev bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.devices SET revoked_at = now() WHERE id = dev AND account = acct AND revoked_at IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;
  DELETE FROM auth.sessions WHERE device = dev;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: device_start(text, jsonb, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.device_start(pk text, body jsonb, ttl_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  m text := auth.device_machine(body->>'machine');
  code text := left(projects.sha(projects.token()), 32);
  id_ text := left(projects.sha(projects.token()), 16);
  now_ bigint := projects.now_ms();
BEGIN
  IF coalesce(pk, '') !~ '^[0-9a-f]{64}$' THEN RETURN access.err(401, 'sign it with the new key'); END IF;
  IF jsonb_typeof(body->'machine') IS DISTINCT FROM 'string' OR m IS NULL THEN RETURN access.err(400, 'name the machine'); END IF;
  IF (SELECT count(*) FROM auth.device_logins d WHERE d.pubkey = pk AND d.account IS NULL AND d.expires_ms > now_) >= 5 THEN
    RETURN access.err(429, 'five requests are open: approve one or wait ten minutes');
  END IF;
  INSERT INTO auth.device_logins (id, code_sha256, pubkey, machine, made_ms, expires_ms)
    VALUES (id_, projects.sha(code), pk, m, now_, now_ + ttl_ms);
  RETURN access.r(200, jsonb_build_object('id', id_, 'code', code, 'expires_ms', now_ + ttl_ms),
                  format(E'id %s\ncode %s\nexpires_ms %s\n', id_, code, now_ + ttl_ms));
END $_$;


--
-- Name: devices_of(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.devices_of(acct text, this_sid text) RETURNS TABLE(id bigint, name text, platform text, store text, created_ms bigint, last_seen_ms bigint, sessions integer, this boolean)
    LANGUAGE sql STABLE
    AS $$
  SELECT d.id, coalesce(d.name, CASE d.platform WHEN 'ios' THEN 'iPhone' WHEN 'mac' THEN 'Mac' WHEN 'android' THEN 'Android' ELSE 'Browser' END),
         d.platform, d.store,
         (extract(epoch FROM d.created_at) * 1000)::bigint,
         (extract(epoch FROM coalesce(d.last_seen_at, d.created_at)) * 1000)::bigint,
         (SELECT count(*) FROM auth.sessions s WHERE s.device = d.id)::int,
         EXISTS (SELECT 1 FROM auth.sessions s WHERE s.device = d.id AND s.id = this_sid)
    FROM auth.devices d WHERE d.account = acct AND d.revoked_at IS NULL
   ORDER BY coalesce(d.last_seen_at, d.created_at) DESC, d.id DESC
$$;


--
-- Name: email_account(text, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.email_account(lookup_ text, team_ boolean, OUT acct text, OUT email_id bigint, OUT made boolean) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  made := false;
  SELECT e.account, e.id INTO acct, email_id FROM auth.emails e WHERE e.lookup = lookup_;
  IF acct IS NOT NULL THEN
    UPDATE auth.emails SET last_used_at = now(), verified_at = coalesce(verified_at, now()) WHERE id = email_id;
    IF team_ THEN UPDATE auth.accounts SET team = true WHERE id = acct; END IF;
    RETURN;
  END IF;
  acct := auth.new_person(NULL);
  UPDATE auth.accounts SET team = team_ WHERE id = acct;
  INSERT INTO auth.emails (account, lookup, sealed, verified_at, is_primary, last_used_at)
  VALUES (acct, lookup_, '', now(), true, now()) RETURNING id INTO email_id;
  made := true;
END $$;


--
-- Name: email_attach(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.email_attach(acct text, lookup_ text, OUT state text, OUT email_id bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE other text;
BEGIN
  SELECT e.account, e.id INTO other, email_id FROM auth.emails e WHERE e.lookup = lookup_;
  IF other = acct THEN state := 'already'; RETURN; END IF;
  IF other IS NOT NULL THEN state := 'theirs'; email_id := NULL; RETURN; END IF;
  INSERT INTO auth.emails (account, lookup, sealed, verified_at, is_primary)
  VALUES (acct, lookup_, '', now(), NOT EXISTS (SELECT 1 FROM auth.emails WHERE account = acct)) RETURNING id INTO email_id;
  state := 'ok';
END $$;


--
-- Name: email_code(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.email_code(browser_sha text, code text, OUT state text, OUT id text, OUT sealed text, OUT lookup text, OUT purpose text, OUT account text, OUT client text, OUT tries_left integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE p auth.pending;
BEGIN
  SELECT * INTO p FROM auth.pending x WHERE x.kind = 'email' AND x.browser_sha256 = browser_sha AND x.done_at IS NULL
   ORDER BY x.created_at DESC LIMIT 1 FOR UPDATE;
  IF p.id IS NULL THEN state := 'none'; RETURN; END IF;
  IF p.expires_at <= now() OR p.tries >= 5 THEN state := 'dead'; RETURN; END IF;
  IF projects.sha(coalesce(code, '') || p.id) <> p.code_sha256 THEN
    UPDATE auth.pending SET tries = tries + 1 WHERE auth.pending.id = p.id;
    state := CASE WHEN p.tries + 1 >= 5 THEN 'dead' ELSE 'wrong' END;
    tries_left := 5 - (p.tries + 1);
    RETURN;
  END IF;
  UPDATE auth.pending SET done_at = now() WHERE auth.pending.id = p.id;
  state := 'ok'; id := p.id; sealed := p.target_sealed; lookup := p.target_lookup; purpose := p.purpose;
  account := p.account; client := p.client;
END $$;


--
-- Name: email_link(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.email_link(link_sha text, browser_sha text, OUT state text, OUT id text, OUT sealed text, OUT lookup text, OUT purpose text, OUT account text, OUT client text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE p auth.pending;
BEGIN
  SELECT * INTO p FROM auth.pending x WHERE x.kind = 'email' AND x.link_sha256 = link_sha FOR UPDATE;
  IF p.id IS NULL OR p.done_at IS NOT NULL THEN state := 'none'; RETURN; END IF;
  IF p.expires_at <= now() OR p.tries >= 5 THEN state := 'dead'; RETURN; END IF;
  IF p.browser_sha256 IS DISTINCT FROM browser_sha THEN state := 'elsewhere'; RETURN; END IF;
  UPDATE auth.pending SET done_at = now() WHERE auth.pending.id = p.id;
  state := 'ok'; id := p.id; sealed := p.target_sealed; lookup := p.target_lookup; purpose := p.purpose;
  account := p.account; client := p.client;
END $$;


--
-- Name: email_seal(bigint, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.email_seal(email_id bigint, sealed_ text) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.emails SET sealed = sealed_ WHERE id = email_id
$$;


--
-- Name: email_start(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.email_start(id_ text, lookup_ text, sealed_ text, code_sha text, link_sha text, browser_sha text, client_ text, purpose_ text, acct text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM auth.pending WHERE kind = 'email' AND target_lookup = lookup_ AND done_at IS NULL;
  DELETE FROM auth.pending WHERE expires_at < now() - interval '1 day';
  INSERT INTO auth.pending (id, kind, purpose, code_sha256, link_sha256, target_lookup, target_sealed, account, browser_sha256, client, expires_at)
  VALUES (id_, 'email', purpose_, code_sha, link_sha, lookup_, sealed_, acct, browser_sha, client_, now() + interval '10 minutes');
END $$;


--
-- Name: export_audit(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.export_audit(acct text) RETURNS SETOF text
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('type', 'audit', 'account', x.account, 'at', x.at, 'action', x.action, 'result', x.result, 'detail', x.detail)::text
    FROM auth.audit x
   WHERE x.account = acct OR x.account IN (SELECT m.merged FROM auth.merges m WHERE m.survivor = acct)
   ORDER BY x.id
$$;


--
-- Name: export_rows(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.export_rows(acct text) RETURNS SETOF text
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  r record;
  a text;
  vals text[];
  line text;
BEGIN
  FOR a IN SELECT acct UNION ALL SELECT m.merged FROM auth.merges m WHERE m.survivor = acct LOOP
    FOR r IN SELECT l.* FROM auth.life_columns l WHERE l.export AND to_regclass(l.tbl) IS NOT NULL ORDER BY l.tbl, l.col LOOP
      vals := auth.life_values(a, r.holds);
      IF vals IS NULL OR cardinality(vals) = 0 THEN CONTINUE; END IF;
      FOR line IN EXECUTE format(
          'SELECT jsonb_build_object(''type'', ''row'', ''account'', $3, ''table'', $2, ''column'', $4, ''row'', to_jsonb(t) - $5)::text '
          'FROM %s t WHERE %I::text = ANY($1) LIMIT 50000', r.tbl, r.col)
        USING vals, r.tbl, a, r.col, r.omit LOOP
        RETURN NEXT line;
      END LOOP;
    END LOOP;
  END LOOP;
END $_$;


--
-- Name: freeze(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth."freeze"(acct text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.accounts SET frozen_at = coalesce(frozen_at, now()), frozen_why = 'freeze'
   WHERE id = acct AND deleted_at IS NULL AND merged_into IS NULL;
  UPDATE auth.recovery_requests SET cancelled_at = now(), cancelled_via = 'freeze'   -- as 0148's: a freeze stops a recovery
   WHERE account = acct AND cancelled_at IS NULL AND done_at IS NULL;
  n := auth.sessions_end_all(acct);
  RETURN n;
END $$;


--
-- Name: freeze_by_link(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.freeze_by_link(sha text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE acct text;
BEGIN
  UPDATE auth.freeze_links SET used_at = now() WHERE token_sha256 = sha AND used_at IS NULL AND expires_at > now() RETURNING account INTO acct;
  IF acct IS NOT NULL THEN PERFORM auth.freeze(acct); END IF;
  RETURN acct;
END $$;


--
-- Name: freeze_link(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.freeze_link(acct text, sha text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.freeze_links (token_sha256, account, expires_at) VALUES (sha, acct, now() + interval '14 days')
$$;


--
-- Name: grant_matches_agent(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.grant_matches_agent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM auth.accounts WHERE id = NEW.agent AND kind = 'agent' AND owner = NEW.owner) THEN
    RAISE EXCEPTION 'auth: a grant''s agent is an agent of its owner' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: has_strong(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.has_strong(acct text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM auth.nostr_keys k WHERE k.account = acct AND coalesce(k.label, '') <> 'agent')
      OR EXISTS (SELECT 1 FROM auth.passkeys p WHERE p.account = acct)
$$;


--
-- Name: is_team(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.is_team(acct text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM auth.nostr_keys k JOIN analytics.team t ON t.kind = 'npub' AND t.value = k.pubkey WHERE k.account = acct)
$$;


--
-- Name: keep_a_way_in(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.keep_a_way_in() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM auth.accounts a WHERE a.id = OLD.account AND a.deleted_at IS NULL AND a.merged_into IS NULL)
     AND auth.login_ways(OLD.account) = 0 THEN
    RAISE EXCEPTION 'Add another way to log in first' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: key_link(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.key_link(acct text, pk text, label_ text) RETURNS bigint
    LANGUAGE sql
    AS $$
  INSERT INTO auth.nostr_keys (account, pubkey, label, last_used_at) VALUES (acct, pk, nullif(left(label_, 80), ''), now()) RETURNING id
$$;


--
-- Name: key_owner(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.key_owner(pk text, acct text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT CASE WHEN account = acct THEN 1 ELSE 2 END FROM auth.nostr_keys WHERE pubkey = pk), 0)
$$;


--
-- Name: life_delete(regclass, text, text[], integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.life_delete(tbl regclass, col text, vals text[], depth integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE
  fk record;
  keys text[];
  n bigint := 0;
  m bigint;
BEGIN
  IF vals IS NULL OR cardinality(vals) = 0 THEN RETURN 0; END IF;
  IF depth > 8 THEN RAISE EXCEPTION 'auth.life_delete: too deep at %', tbl; END IF;
  FOR fk IN
    SELECT c.conrelid::regclass AS dep, da.attname::text AS depcol, ra.attname::text AS refcol
      FROM pg_constraint c
      JOIN pg_attribute da ON da.attrelid = c.conrelid AND da.attnum = c.conkey[1]
      JOIN pg_attribute ra ON ra.attrelid = c.confrelid AND ra.attnum = c.confkey[1]
     WHERE c.contype = 'f' AND c.confrelid = tbl AND cardinality(c.conkey) = 1 AND c.confdeltype <> 'c'
       AND c.conrelid <> tbl
  LOOP
    EXECUTE format('SELECT array_agg(%I::text) FROM %s WHERE %I::text = ANY($1)', fk.refcol, tbl, col) INTO keys USING vals;
    n := n + auth.life_delete(fk.dep, fk.depcol, keys, depth + 1);
  END LOOP;
  EXECUTE format('DELETE FROM %s WHERE %I::text = ANY($1)', tbl, col) USING vals;
  GET DIAGNOSTICS m = ROW_COUNT;
  RETURN n + m;
END $_$;


--
-- Name: life_move(regclass, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.life_move(tbl regclass, col text, from_ text, to_ text, OUT moved bigint, OUT kept bigint) RETURNS record
    LANGUAGE plpgsql
    AS $_$
DECLARE
  k record;
  clash text := '';
  others text;
BEGIN
  FOR k IN
    SELECT i.indkey::int2[] AS cols FROM pg_index i
     WHERE i.indrelid = tbl AND i.indisunique
       AND (SELECT attnum FROM pg_attribute WHERE attrelid = tbl AND attname = col) = ANY(i.indkey::int2[])
  LOOP
    SELECT string_agg(format('x.%1$I IS NOT DISTINCT FROM t.%1$I', a.attname), ' AND ') INTO others
      FROM pg_attribute a WHERE a.attrelid = tbl AND a.attnum = ANY(k.cols) AND a.attname <> col;
    clash := clash || format(' OR EXISTS (SELECT 1 FROM %s x WHERE x.%I::text = $2%s)', tbl, col,
                             CASE WHEN others IS NULL THEN '' ELSE ' AND ' || others END);
  END LOOP;
  EXECUTE format('UPDATE %s t SET %I = $2 WHERE t.%I::text = $1 AND NOT (false%s)', tbl, col, col, clash) USING from_, to_;
  GET DIAGNOSTICS moved = ROW_COUNT;
  EXECUTE format('SELECT count(*) FROM %s WHERE %I::text = $1', tbl, col) INTO kept USING from_;
END $_$;


--
-- Name: life_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.life_of(acct text) RETURNS TABLE(kind text, frozen_ms bigint, frozen_why text, delete_asked_ms bigint, purge_ms bigint, now_ms bigint, strong integer, emails integer, keys integer, agents integer, agents_paused integer, credit_msat bigint, worlds integer, saves integer, merged_from integer, deleted boolean, merged_into text)
    LANGUAGE sql STABLE
    AS $$
  SELECT a.kind,
         coalesce((extract(epoch FROM a.frozen_at) * 1000)::bigint, 0), coalesce(a.frozen_why, ''),
         coalesce((extract(epoch FROM a.delete_asked_at) * 1000)::bigint, 0),
         coalesce((extract(epoch FROM a.purge_at) * 1000)::bigint, 0),
         (extract(epoch FROM now()) * 1000)::bigint,
         auth.strong_ways(a.id),
         (SELECT count(*) FROM auth.emails e WHERE e.account = a.id)::int,
         (SELECT count(*) FROM auth.nostr_keys k WHERE k.account = a.id)::int,
         (SELECT count(*) FROM auth.accounts g WHERE g.owner = a.id AND g.deleted_at IS NULL)::int,
         (SELECT count(*) FROM auth.agent_grants g WHERE g.owner = a.id AND g.revoked_at IS NULL AND g.suspended_at IS NOT NULL)::int,
         coalesce((SELECT sum(c.msat) FROM inference.credit c JOIN auth.nostr_keys k ON k.pubkey = c.pubkey WHERE k.account = a.id AND c.msat > 0), 0)::bigint,
         (SELECT count(*) FROM verse.worlds w WHERE w.owner_account = a.verse_account)::int,
         (SELECT count(*) FROM verse.progress g WHERE g.account = a.verse_account)::int,
         (SELECT count(*) FROM auth.merges m WHERE m.survivor = a.id)::int,
         a.deleted_at IS NOT NULL, coalesce(a.merged_into, '')
    FROM auth.accounts a WHERE a.id = acct
$$;


--
-- Name: life_sweep(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.life_sweep() RETURNS integer
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM auth.merge_asks WHERE expires_at < now() - interval '1 day' RETURNING 1) SELECT count(*)::int FROM d
$$;


--
-- Name: life_unlisted(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.life_unlisted() RETURNS TABLE(tbl text, col text, points_at text)
    LANGUAGE sql STABLE
    AS $$
  SELECT c.conrelid::regclass::text, a.attname::text, c.confrelid::regclass::text
    FROM pg_constraint c
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
   WHERE c.contype = 'f' AND c.confrelid IN ('auth.accounts'::regclass, 'verse.accounts'::regclass)
     AND NOT (c.conrelid = 'auth.accounts'::regclass AND a.attname = 'merged_into')
     AND NOT EXISTS (SELECT 1 FROM auth.life_columns l WHERE to_regclass(l.tbl) = c.conrelid AND l.col = a.attname)
$$;


--
-- Name: life_values(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.life_values(acct text, holds_ text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE holds_
    WHEN 'account' THEN ARRAY[acct]
    WHEN 'verse' THEN (SELECT array_agg(a.verse_account) FROM auth.accounts a WHERE a.id = acct)
    WHEN 'player' THEN (SELECT array_agg(p.id) FROM verse.players p JOIN auth.accounts a ON a.verse_account = p.account WHERE a.id = acct)
    WHEN 'pubkey' THEN (SELECT array_agg(k.pubkey) FROM auth.nostr_keys k WHERE k.account = acct)
    WHEN 'world' THEN (SELECT array_agg(w.id) FROM verse.worlds w JOIN auth.accounts a ON a.verse_account = w.owner_account WHERE a.id = acct)
  END
$$;


--
-- Name: limit_hit(text, text, bigint, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.limit_hit(name_ text, key_ text, window_ms bigint, count_it boolean, OUT started_ms bigint, OUT n integer, OUT now_ms bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  now_ms := projects.now_ms();
  INSERT INTO auth.limit_counts AS c (name, key, started_ms, n) VALUES (name_, key_, now_ms, CASE WHEN count_it THEN 1 ELSE 0 END)
  ON CONFLICT (name, key) DO UPDATE SET
    started_ms = CASE WHEN c.started_ms <= now_ms - window_ms THEN now_ms ELSE c.started_ms END,
    n = CASE WHEN c.started_ms <= now_ms - window_ms THEN 0 ELSE c.n END + CASE WHEN count_it THEN 1 ELSE 0 END
  RETURNING c.started_ms, c.n INTO started_ms, n;
END $$;


--
-- Name: limit_sweep(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.limit_sweep() RETURNS integer
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM auth.limit_counts WHERE started_ms < projects.now_ms() - 8 * 86400000::bigint RETURNING 1) SELECT count(*)::int FROM d
$$;


--
-- Name: log(text, text, text, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.log(acct text, actor_ text, action_ text, result_ text, detail_ jsonb) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.audit (account, actor, action, result, detail) VALUES (acct, actor_, action_, result_, coalesce(detail_, '{}'))
$$;


--
-- Name: login_ways(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.login_ways(acct text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT (SELECT count(*) FROM auth.emails WHERE account = acct)::int
       + (SELECT count(*) FROM auth.nostr_keys WHERE account = acct)::int
       + (SELECT count(*) FROM auth.passkeys WHERE account = acct)::int
       + (SELECT count(*) FROM auth.recovery WHERE account = acct AND spent_at IS NULL)::int
$$;


--
-- Name: me_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.me_of(acct text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('account', a.id, 'kind', a.kind, 'team', a.team,
           'emails', coalesce((SELECT jsonb_agg(jsonb_build_object('id', e.id, 'sealed', e.sealed, 'primary', e.is_primary) ORDER BY e.id)
                               FROM auth.emails e WHERE e.account = a.id), '[]'::jsonb),
           'keys', coalesce((SELECT jsonb_agg(jsonb_build_object('id', k.id, 'pubkey', k.pubkey, 'label', k.label) ORDER BY k.id)
                             FROM auth.nostr_keys k WHERE k.account = a.id), '[]'::jsonb),
           'passkeys', (SELECT count(*) FROM auth.passkeys p WHERE p.account = a.id))
    FROM auth.accounts a WHERE a.id = acct
$$;


--
-- Name: merge(text, text, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.merge(survivor_ text, other_ text, money_ boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  s auth.accounts;
  o auth.accounts;
  r record;
  from_v text;
  to_v text;
  mv bigint; kp bigint;
  moved jsonb := '{}';
  kept jsonb := '{}';
BEGIN
  IF survivor_ = other_ THEN RETURN NULL; END IF;
  -- Both rows locked, in id order, so two merges can't cross.
  PERFORM 1 FROM auth.accounts WHERE id IN (survivor_, other_) ORDER BY id FOR UPDATE;
  SELECT * INTO s FROM auth.accounts WHERE id = survivor_;
  SELECT * INTO o FROM auth.accounts WHERE id = other_;
  IF s.id IS NULL OR o.id IS NULL OR s.kind <> 'person' OR o.kind <> 'person'
     OR s.deleted_at IS NOT NULL OR o.deleted_at IS NOT NULL OR s.merged_into IS NOT NULL OR o.merged_into IS NOT NULL
     OR s.delete_asked_at IS NOT NULL OR o.delete_asked_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  PERFORM auth.sessions_end_all(other_);
  FOR r IN SELECT l.* FROM auth.life_columns l WHERE l.on_merge IN ('move', 'end') AND to_regclass(l.tbl) IS NOT NULL ORDER BY l.holds, l.tbl, l.col LOOP
    IF r.holds = 'account' THEN from_v := other_; to_v := survivor_;
    ELSIF r.holds = 'verse' THEN from_v := o.verse_account; to_v := s.verse_account;
    ELSE CONTINUE; END IF;
    IF r.on_merge = 'end' THEN
      EXECUTE format('DELETE FROM %s WHERE %I::text = $1', r.tbl, r.col) USING from_v;
      CONTINUE;
    END IF;
    SELECT x.moved, x.kept INTO mv, kp FROM auth.life_move(r.tbl::regclass, r.col, from_v, to_v) x;
    IF mv > 0 THEN moved := moved || jsonb_build_object(r.tbl || '.' || r.col, mv); END IF;
    IF kp > 0 THEN kept := kept || jsonb_build_object(r.tbl || '.' || r.col, kp); END IF;
  END LOOP;
  -- A realm's admins name game accounts too.
  UPDATE verse.realm_rights SET admins = array_replace(admins, o.verse_account, s.verse_account) WHERE o.verse_account = ANY(admins);
  -- Freezes join: a frozen side keeps the survivor frozen. Recovery waiting on the other ends.
  UPDATE auth.accounts SET frozen_at = coalesce(s.frozen_at, o.frozen_at), frozen_why = coalesce(s.frozen_why, o.frozen_why),
                           team = s.team OR o.team
   WHERE id = survivor_;
  UPDATE auth.recovery_requests SET cancelled_at = now() WHERE account = other_ AND cancelled_at IS NULL AND done_at IS NULL;
  UPDATE auth.accounts SET merged_into = survivor_, deleted_at = now(), frozen_at = NULL, frozen_why = NULL WHERE id = other_;
  INSERT INTO auth.merges (survivor, merged, moved, kept, money) VALUES (survivor_, other_, moved, kept, money_);
  RETURN jsonb_build_object('moved', moved, 'kept', kept);
END $_$;


--
-- Name: merge_ask(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.merge_ask(id_ text, survivor_ text, session_ text) RETURNS void
    LANGUAGE sql
    AS $$
  DELETE FROM auth.merge_asks WHERE survivor = survivor_ AND done_at IS NULL;
  INSERT INTO auth.merge_asks (id, survivor, session, expires_at) VALUES (id_, survivor_, session_, now() + interval '10 minutes');
$$;


--
-- Name: merge_done(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.merge_done(id_ text) RETURNS void
    LANGUAGE sql
    AS $$ UPDATE auth.merge_asks SET done_at = now() WHERE id = id_ $$;


--
-- Name: merge_preview(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.merge_preview(other_ text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('emails', l.emails, 'keys', l.keys, 'agents', l.agents, 'worlds', l.worlds, 'saves', l.saves,
                            'credit_msat', l.credit_msat, 'strong', l.strong, 'kind', l.kind,
                            'frozen', l.frozen_ms > 0, 'deleting', l.delete_asked_ms > 0, 'gone', l.deleted)
    FROM auth.life_of(other_) l
$$;


--
-- Name: merge_proved(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.merge_proved(survivor_ text, other_ text, via text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE a auth.merge_asks;
BEGIN
  SELECT * INTO a FROM auth.merge_asks WHERE survivor = survivor_ AND done_at IS NULL AND expires_at > now()
   ORDER BY expires_at DESC LIMIT 1 FOR UPDATE;
  IF a.id IS NULL THEN RETURN 'none'; END IF;
  IF other_ = survivor_ THEN RETURN 'self'; END IF;
  UPDATE auth.merge_asks SET other = other_, proved_via = via, proved_at = now() WHERE id = a.id;
  RETURN 'ok';
END $$;


--
-- Name: merge_ready(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.merge_ready(survivor_ text, session_ text) RETURNS TABLE(id text, other text, proved_via text, proof_age_ms bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT a.id, a.other, a.proved_via, (extract(epoch FROM now() - a.proved_at) * 1000)::bigint
    FROM auth.merge_asks a
   WHERE a.survivor = survivor_ AND a.session = session_ AND a.done_at IS NULL AND a.expires_at > now() AND a.other IS NOT NULL
   ORDER BY a.expires_at DESC LIMIT 1
$$;


--
-- Name: methods_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.methods_of(acct text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
  SELECT array_remove(ARRAY[
    CASE WHEN EXISTS (SELECT 1 FROM auth.nostr_keys WHERE account = acct) THEN 'nostr' END,
    CASE WHEN EXISTS (SELECT 1 FROM auth.passkeys WHERE account = acct) THEN 'passkey' END,
    CASE WHEN EXISTS (SELECT 1 FROM auth.recovery WHERE account = acct AND spent_at IS NULL) THEN 'recovery_code' END], NULL)
$$;


--
-- Name: new_account_id(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.new_account_id() RETURNS text
    LANGUAGE sql
    AS $$ SELECT 'acct_' || auth.random_b32(26) $$;


--
-- Name: new_agent(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.new_agent(owner_ text, name_ text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE id_ text := auth.new_account_id();
BEGIN
  INSERT INTO verse.accounts (id, created_ms) VALUES (id_, verse.now_ms()) ON CONFLICT DO NOTHING;
  INSERT INTO auth.accounts (id, kind, owner, display_name, team, verse_account)
  SELECT id_, 'agent', a.id, left(name_, 80), a.team, id_ FROM auth.accounts a WHERE a.id = owner_ AND a.kind = 'person' AND a.deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'auth: no such owner' USING ERRCODE = 'check_violation'; END IF;
  RETURN id_;
END $$;


--
-- Name: new_person(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.new_person(verse_acct text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE id_ text := auth.new_account_id();
BEGIN
  INSERT INTO verse.accounts (id, created_ms) VALUES (coalesce(verse_acct, id_), verse.now_ms()) ON CONFLICT DO NOTHING;
  INSERT INTO auth.accounts (id, kind, verse_account) VALUES (id_, 'person', coalesce(verse_acct, id_));
  RETURN id_;
END $$;


--
-- Name: nip98_once(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.nip98_once(event_id text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO auth.nip98_seen (event_id, expires_at) VALUES (event_id, now() + interval '11 minutes') ON CONFLICT DO NOTHING;
  RETURN FOUND;
END $$;


--
-- Name: nostr_challenge(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.nostr_challenge(id_ text, challenge_sha text, client_ text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.pending (id, kind, link_sha256, client, expires_at) VALUES (id_, 'nostr', challenge_sha, client_, now() + interval '5 minutes')
$$;


--
-- Name: nostr_spend(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.nostr_spend(challenge_sha text, event_id text, OUT state text, OUT client text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE p auth.pending;
BEGIN
  DELETE FROM auth.nip98_seen WHERE expires_at < now();
  INSERT INTO auth.nip98_seen (event_id, expires_at) VALUES (event_id, now() + interval '11 minutes') ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN state := 'replay'; RETURN; END IF;
  UPDATE auth.pending x SET done_at = now() WHERE x.kind = 'nostr' AND x.link_sha256 = challenge_sha AND x.done_at IS NULL AND x.expires_at > now()
  RETURNING * INTO p;
  IF p.id IS NULL THEN state := 'none'; RETURN; END IF;
  state := 'ok'; client := p.client;
END $$;


--
-- Name: notice_add(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.notice_add(acct text, what_ text, words_ text) RETURNS bigint
    LANGUAGE sql
    AS $$
  INSERT INTO auth.notices (account, what, words) VALUES (acct, what_, left(words_, 400)) RETURNING id
$$;


--
-- Name: notice_sent(bigint, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.notice_sent(id_ bigint, sent_ jsonb) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.notices SET sent = sent_ WHERE id = id_
$$;


--
-- Name: notices_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.notices_of(acct text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('at_ms', (extract(epoch FROM n.at) * 1000)::bigint, 'what', n.what, 'words', n.words, 'sent', n.sent)
                            ORDER BY n.id DESC), '[]'::jsonb)
    FROM (SELECT * FROM auth.notices WHERE account = acct ORDER BY id DESC LIMIT 50) n
$$;


--
-- Name: notices_sweep(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.notices_sweep() RETURNS integer
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM auth.notices WHERE at < now() - interval '90 days' RETURNING 1) SELECT count(*)::int FROM d
$$;


--
-- Name: owner_is_person(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.owner_is_person() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.owner IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auth.accounts WHERE id = NEW.owner AND kind = 'person') THEN
    RAISE EXCEPTION 'auth: an agent''s owner must be a person' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: passkey_add(text, text, text, text, integer, bigint, boolean, boolean, text, text[], text, text, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_add(acct text, cred text, handle text, cose_hex text, alg_ integer, count_ bigint, be boolean, bs boolean, aaguid_ text, transports_ text[], name_ text, salt_hex text, prf_ boolean, rp text) RETURNS bigint
    LANGUAGE sql
    AS $$
  INSERT INTO auth.passkeys (account, credential_id, user_handle, public_key, alg, sign_count, backup_eligible, backed_up,
                             aaguid, transports, name, prf_salt, prf, rp_id, last_used_at)
  VALUES (acct, cred, handle, decode(cose_hex, 'hex'), alg_, count_, be, bs, nullif(aaguid_, ''), transports_, name_,
          decode(salt_hex, 'hex'), prf_, rp, now())
  RETURNING id
$$;


--
-- Name: passkey_challenge(text, text, text, text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_challenge(id_ text, challenge_sha text, purpose_ text, client_ text, acct text, sid text, browser_sha text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.pending (id, kind, purpose, link_sha256, client, account, session, browser_sha256, expires_at)
  VALUES (id_, 'passkey', purpose_, challenge_sha, client_, acct, sid, browser_sha, now() + interval '5 minutes')
$$;


--
-- Name: passkey_clone(bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_clone(id_ bigint) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.passkeys SET clone_at = now() WHERE id = id_
$$;


--
-- Name: passkey_find(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_find(cred text, rp text) RETURNS TABLE(id bigint, account text, user_handle text, cose_hex text, sign_count bigint, backup_eligible boolean, frozen boolean)
    LANGUAGE sql STABLE
    AS $$
  SELECT p.id, p.account, p.user_handle, encode(p.public_key, 'hex'), p.sign_count, p.backup_eligible, a.frozen_at IS NOT NULL
    FROM auth.passkeys p JOIN auth.accounts a ON a.id = p.account
   WHERE p.credential_id = cred AND coalesce(p.rp_id, rp) = rp AND a.deleted_at IS NULL AND a.merged_into IS NULL
$$;


--
-- Name: passkey_handle(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_handle(acct text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT user_handle FROM auth.passkeys WHERE account = acct ORDER BY id LIMIT 1
$$;


--
-- Name: passkey_offered(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_offered(acct text) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.accounts SET passkey_offered_at = coalesce(passkey_offered_at, now()) WHERE id = acct
$$;


--
-- Name: passkey_owner(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_owner(cred text, acct text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT CASE WHEN account = acct THEN 1 ELSE 2 END FROM auth.passkeys WHERE credential_id = cred), 0)
$$;


--
-- Name: passkey_rename(text, bigint, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_rename(acct text, id_ bigint, name_ text) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH u AS (UPDATE auth.passkeys SET name = name_ WHERE id = id_ AND account = acct RETURNING 1) SELECT EXISTS (SELECT 1 FROM u)
$$;


--
-- Name: passkey_spend(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_spend(challenge_sha text) RETURNS TABLE(purpose text, client text, account text, session text, browser_sha256 text, made_ms bigint, now_ms bigint)
    LANGUAGE sql
    AS $$
  UPDATE auth.pending p SET done_at = now()
   WHERE p.link_sha256 = challenge_sha AND p.kind = 'passkey' AND p.done_at IS NULL
  RETURNING p.purpose, p.client, p.account, p.session, p.browser_sha256,
            (extract(epoch FROM p.created_at) * 1000)::bigint, (extract(epoch FROM now()) * 1000)::bigint
$$;


--
-- Name: passkey_used(bigint, bigint, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkey_used(id_ bigint, count_ bigint, bs boolean) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.passkeys SET sign_count = count_, backed_up = bs, last_used_at = now() WHERE id = id_
$$;


--
-- Name: passkeys_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.passkeys_of(acct text) RETURNS TABLE(id bigint, name text, added_ms bigint, used_ms bigint, synced boolean, clone boolean, prf boolean, transports text)
    LANGUAGE sql STABLE
    AS $$
  SELECT p.id, coalesce(p.name, 'Passkey'), (extract(epoch FROM p.created_at) * 1000)::bigint,
         coalesce((extract(epoch FROM p.last_used_at) * 1000)::bigint, 0), p.backed_up, p.clone_at IS NOT NULL, p.prf,
         coalesce(array_to_string(p.transports, ','), '')
    FROM auth.passkeys p WHERE p.account = acct ORDER BY p.id
$$;


--
-- Name: phone_approve(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.phone_approve(challenge_sha text, pk text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE p auth.pending;
BEGIN
  SELECT * INTO p FROM auth.pending x WHERE x.kind = 'phone' AND x.link_sha256 = challenge_sha FOR UPDATE;
  IF p.id IS NULL OR p.expires_at <= now() OR p.done_at IS NOT NULL THEN RETURN 'none'; END IF;
  IF p.approved_pubkey IS NOT NULL THEN RETURN 'already'; END IF;
  UPDATE auth.pending SET approved_pubkey = pk WHERE id = p.id;
  RETURN 'ok';
END $$;


--
-- Name: phone_poll(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.phone_poll(poll_sha text, browser_sha text, OUT state text, OUT pubkey text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE p auth.pending;
BEGIN
  SELECT * INTO p FROM auth.pending x WHERE x.kind = 'phone' AND x.poll_sha256 = poll_sha AND x.browser_sha256 = browser_sha FOR UPDATE;
  IF p.id IS NULL OR p.done_at IS NOT NULL THEN state := 'none'; RETURN; END IF;
  IF p.approved_pubkey IS NULL THEN state := CASE WHEN p.expires_at <= now() THEN 'expired' ELSE 'waiting' END; RETURN; END IF;
  UPDATE auth.pending SET done_at = now() WHERE id = p.id;
  state := 'ok'; pubkey := p.approved_pubkey;
END $$;


--
-- Name: phone_start(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.phone_start(id_ text, challenge_sha text, poll_sha text, browser_sha text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.pending (id, kind, link_sha256, poll_sha256, browser_sha256, expires_at)
  VALUES (id_, 'phone', challenge_sha, poll_sha, browser_sha, now() + interval '5 minutes')
$$;


--
-- Name: proof_challenge(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.proof_challenge(id_ text, challenge_sha text, acct text, purpose_ text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.pending (id, kind, purpose, link_sha256, account, expires_at)
  VALUES (id_, 'nostr', purpose_, challenge_sha, acct, now() + interval '5 minutes')
$$;


--
-- Name: proof_spend(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.proof_spend(challenge_sha text, acct text, purpose_ text, event_id text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE pid text;
BEGIN
  SELECT p.id INTO pid FROM auth.pending p
   WHERE p.link_sha256 = challenge_sha AND p.account = acct AND p.purpose = purpose_ AND p.kind = 'nostr'
     AND p.done_at IS NULL AND p.expires_at > now() FOR UPDATE;
  IF pid IS NULL THEN RETURN 'none'; END IF;
  IF NOT auth.nip98_once(event_id) THEN RETURN 'replay'; END IF;
  UPDATE auth.pending SET done_at = now() WHERE id = pid;
  RETURN 'ok';
END $$;


--
-- Name: purge(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.purge(acct text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  r record;
  vals text[];
  m bigint;
  counts jsonb := '{}';
  agent text;
  vacct text;
BEGIN
  SELECT verse_account INTO vacct FROM auth.accounts WHERE id = acct AND deleted_at IS NULL FOR UPDATE;
  IF vacct IS NULL THEN RETURN NULL; END IF;
  FOR agent IN SELECT id FROM auth.accounts WHERE owner = acct AND deleted_at IS NULL LOOP
    counts := counts || jsonb_build_object('agent:' || agent, auth.purge(agent));
  END LOOP;
  PERFORM auth.sessions_end_all(acct);
  -- A tombstone from here on: no session, and keep_a_way_in (0142) lets its last way in go.
  UPDATE auth.accounts SET deleted_at = now(), display_name = NULL, team = false WHERE id = acct;
  -- Values first (the keys, players and realms), then the rows: deleting the keys' rows last.
  FOR r IN SELECT l.* FROM auth.life_columns l
            WHERE l.on_purge <> 'keep' AND l.tbl <> 'auth.accounts' AND to_regclass(l.tbl) IS NOT NULL
            ORDER BY CASE l.holds WHEN 'world' THEN 0 WHEN 'player' THEN 1 WHEN 'pubkey' THEN 2 WHEN 'verse' THEN 3 ELSE 4 END,
                     CASE WHEN l.tbl = 'auth.nostr_keys' THEN 1 ELSE 0 END, l.tbl, l.col LOOP
    vals := auth.life_values(acct, r.holds);
    IF vals IS NULL OR cardinality(vals) = 0 THEN CONTINUE; END IF;
    IF r.on_purge = 'delete' THEN
      m := auth.life_delete(r.tbl::regclass, r.col, vals, 0);
    ELSE
      EXECUTE format('UPDATE %s SET %I = ''deleted'' WHERE %I::text = ANY($1)', r.tbl, r.col, r.col) USING vals;
      GET DIAGNOSTICS m = ROW_COUNT;
    END IF;
    IF m > 0 THEN counts := counts || jsonb_build_object(r.tbl || '.' || r.col, m); END IF;
  END LOOP;
  UPDATE verse.accounts SET npub = NULL, name = NULL WHERE id = vacct;
  counts := counts || jsonb_build_object('audit_forgotten', auth.audit_forget(acct));
  RETURN counts;
END $_$;


--
-- Name: purge_due(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.purge_due() RETURNS text[]
    LANGUAGE plpgsql
    AS $$
DECLARE acct text; done text[] := '{}';
BEGIN
  FOR acct IN SELECT id FROM auth.accounts WHERE purge_at IS NOT NULL AND purge_at <= now() AND deleted_at IS NULL AND kind = 'person'
               ORDER BY purge_at LIMIT 100 LOOP
    PERFORM auth.purge(acct);
    done := done || acct;
  END LOOP;
  RETURN done;
END $$;


--
-- Name: push_targets(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.push_targets(acct text) RETURNS TABLE(device bigint, platform text, service text, token text)
    LANGUAGE sql STABLE
    AS $$
  SELECT d.id, d.platform, d.push_service, d.push_token
    FROM auth.devices d
   WHERE d.account = acct AND d.revoked_at IS NULL AND d.push_token IS NOT NULL
     AND EXISTS (SELECT 1 FROM auth.sessions s WHERE s.device = d.id)
   ORDER BY d.id
$$;


--
-- Name: random_b32(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.random_b32(n integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  bits bytea := sha256(convert_to(gen_random_uuid()::text || gen_random_uuid()::text || clock_timestamp()::text, 'UTF8'));
  alphabet text := 'abcdefghijklmnopqrstuvwxyz234567';
  out text := '';
  i int;
  v int;
BEGIN
  FOR i IN 0..n - 1 LOOP
    -- five bits starting at bit 5i
    v := ((get_byte(bits, (5 * i) / 8) << 8) | get_byte(bits, (5 * i) / 8 + 1)) >> (11 - (5 * i) % 8) & 31;
    out := out || substr(alphabet, v + 1, 1);
  END LOOP;
  RETURN out;
END $$;


--
-- Name: recovery_ask(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.recovery_ask(acct text, sid text, cancel_sha text, OUT id bigint, OUT asked_ms bigint, OUT ready_ms bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO auth.recovery_requests AS r (account, asked_at, ready_at, asked_session, cancel_sha256)
  VALUES (acct, now(), now() + interval '72 hours', sid, cancel_sha)
  RETURNING r.id, (extract(epoch FROM r.asked_at) * 1000)::bigint, (extract(epoch FROM r.ready_at) * 1000)::bigint INTO id, asked_ms, ready_ms;
END $$;


--
-- Name: recovery_cancel(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.recovery_cancel(acct text, via text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.recovery_requests SET cancelled_at = now(), cancelled_via = via
   WHERE account = acct AND cancelled_at IS NULL AND done_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: recovery_cancel_by_link(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.recovery_cancel_by_link(sha text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE acct text;
BEGIN
  UPDATE auth.recovery_requests SET cancelled_at = now(), cancelled_via = 'link'
   WHERE cancel_sha256 = sha AND cancelled_at IS NULL AND done_at IS NULL RETURNING account INTO acct;
  RETURN acct;
END $$;


--
-- Name: recovery_finish(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.recovery_finish(acct text, sid text, pk text, label_ text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE rid bigint; kid bigint;
BEGIN
  SELECT r.id INTO rid FROM auth.recovery_requests r
   WHERE r.account = acct AND r.cancelled_at IS NULL AND r.done_at IS NULL AND r.ready_at <= now()
     AND r.asked_at <= now() - interval '72 hours' FOR UPDATE;
  IF rid IS NULL THEN RAISE EXCEPTION 'auth: recovery is not ready' USING ERRCODE = 'check_violation'; END IF;
  INSERT INTO auth.nostr_keys (account, pubkey, label, last_used_at) VALUES (acct, pk, nullif(left(label_, 80), ''), now()) RETURNING id INTO kid;
  DELETE FROM auth.nostr_keys WHERE account = acct AND id <> kid;
  DELETE FROM auth.passkeys WHERE account = acct;
  UPDATE auth.devices SET revoked_at = now() WHERE account = acct AND revoked_at IS NULL;
  UPDATE auth.recovery SET spent_at = now() WHERE account = acct AND spent_at IS NULL;
  DELETE FROM auth.sessions WHERE account = acct AND id <> sid;
  UPDATE auth.sessions SET level = 'L2', l2_at = now(), via_kind = 'nostr', via_id = kid WHERE id = sid;
  UPDATE auth.recovery_requests SET done_at = now(), done_key = kid WHERE id = rid;
  RETURN kid;
END $$;


--
-- Name: recovery_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.recovery_of(acct text) RETURNS TABLE(id bigint, asked_ms bigint, ready_ms bigint, cancelled_ms bigint, done_ms bigint, now_ms bigint, cancelled_via text)
    LANGUAGE sql STABLE
    AS $$
  SELECT r.id, (extract(epoch FROM r.asked_at) * 1000)::bigint, (extract(epoch FROM r.ready_at) * 1000)::bigint,
         coalesce((extract(epoch FROM r.cancelled_at) * 1000)::bigint, 0), coalesce((extract(epoch FROM r.done_at) * 1000)::bigint, 0),
         (extract(epoch FROM now()) * 1000)::bigint, r.cancelled_via
    FROM auth.recovery_requests r WHERE r.account = acct ORDER BY r.id DESC LIMIT 1
$$;


--
-- Name: refresh_look(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.refresh_look(rt_sha text) RETURNS TABLE(family text, session text, account text, device bigint, public_key text, revoked boolean, now_ms bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT r.family, s.id, s.account, s.device, coalesce(encode(d.public_key, 'hex'), ''), d.revoked_at IS NOT NULL,
         (extract(epoch FROM now()) * 1000)::bigint
    FROM auth.refresh r JOIN auth.sessions s ON s.id = r.session LEFT JOIN auth.devices d ON d.id = s.device
   WHERE r.token_sha256 = rt_sha
$$;


--
-- Name: session_bind(text, text, bytea, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_bind(sid text, acct text, key bytea, platform_ text, store_ text, name_ text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE dev bigint;
BEGIN
  PERFORM 1 FROM auth.sessions s WHERE s.id = sid AND s.account = acct AND s.client = 'app' AND s.device IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT d.id INTO dev FROM auth.devices d WHERE d.account = acct AND d.public_key = key AND d.revoked_at IS NULL;
  IF dev IS NULL THEN
    INSERT INTO auth.devices (account, public_key, platform, store, name, last_seen_at)
    VALUES (acct, key, platform_, store_, nullif(left(name_, 80), ''), now()) RETURNING id INTO dev;
  ELSE
    UPDATE auth.devices SET last_seen_at = now(), name = coalesce(nullif(left(name_, 80), ''), name) WHERE id = dev;
  END IF;
  UPDATE auth.sessions SET device = dev WHERE id = sid;
  RETURN dev;
END $$;


--
-- Name: session_device(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_device(acct text, sid text, OUT app boolean, OUT platform text) RETURNS record
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(bool_or(s.client = 'app'), false), coalesce(max(d.platform), '')
    FROM auth.sessions s LEFT JOIN auth.devices d ON d.id = s.device AND d.revoked_at IS NULL
   WHERE s.id = sid AND s.account = acct
$$;


--
-- Name: session_device_fixed(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_device_fixed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.device IS NOT NULL AND NEW.device IS DISTINCT FROM OLD.device THEN
    RAISE EXCEPTION 'auth.sessions: a session''s device key never changes' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: session_end(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_end(sid text) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM auth.sessions WHERE id = sid RETURNING 1) SELECT EXISTS (SELECT 1 FROM d)
$$;


--
-- Name: session_look(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_look(sha text) RETURNS TABLE(id text, account text, kind text, verse_account text, level text, via_kind text, client text, created_ms bigint, last_seen_ms bigint, rotated_ms bigint, l2_ms bigint, now_ms bigint, current boolean, good_epoch boolean, frozen boolean, team boolean, pubkey text, strong integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT s.id, s.account, a.kind, a.verse_account, s.level, s.via_kind, s.client,
         (extract(epoch FROM s.created_at) * 1000)::bigint, (extract(epoch FROM s.last_seen_at) * 1000)::bigint,
         (extract(epoch FROM s.rotated_at) * 1000)::bigint, (extract(epoch FROM s.l2_at) * 1000)::bigint,
         (extract(epoch FROM now()) * 1000)::bigint,
         s.token_sha256 = sha, s.epoch = a.session_epoch, a.frozen_at IS NOT NULL, a.team,
         coalesce((SELECT k.pubkey FROM auth.nostr_keys k WHERE s.via_kind = 'nostr' AND k.id = s.via_id),
                  (SELECT k.pubkey FROM auth.nostr_keys k WHERE k.account = a.id ORDER BY k.last_used_at DESC NULLS LAST, k.id DESC LIMIT 1)),
         auth.strong_ways(a.id)
    FROM auth.sessions s JOIN auth.accounts a ON a.id = s.account
   WHERE (s.token_sha256 = sha OR (s.prev_sha256 = sha AND s.prev_until > now())) AND a.deleted_at IS NULL
$$;


--
-- Name: session_new(text, text, text, bigint, text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_new(sha text, acct text, kind_ text, via bigint, level_ text, client_ text, name_ text, country_ text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE sid text := 'ses_' || left(projects.sha(projects.token()), 16);
BEGIN
  INSERT INTO auth.sessions (token_sha256, id, account, via_kind, via_id, client, level, l1_at, l2_at, epoch, name, country)
  SELECT sha, sid, a.id, kind_, via, client_, level_, now(), CASE WHEN level_ = 'L2' THEN now() END, a.session_epoch,
         nullif(left(name_, 80), ''), nullif(left(country_, 2), '')
    FROM auth.accounts a WHERE a.id = acct AND a.deleted_at IS NULL AND a.merged_into IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN sid;
END $$;


--
-- Name: session_raise(text, text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_raise(sid text, kind_ text, via bigint) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH u AS (UPDATE auth.sessions SET level = 'L2', l2_at = now(), via_kind = kind_, via_id = via WHERE id = sid RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM u)
$$;


--
-- Name: session_rotate(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_rotate(sid text, old_sha text, new_sha text) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH u AS (UPDATE auth.sessions SET prev_sha256 = old_sha, prev_until = now() + interval '60 seconds',
                                      token_sha256 = new_sha, rotated_at = now()
              WHERE id = sid AND token_sha256 = old_sha RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM u)
$$;


--
-- Name: session_seen(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.session_seen(sid text) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE auth.sessions SET last_seen_at = now() WHERE id = sid AND last_seen_at < now() - interval '1 minute'
$$;


--
-- Name: sessions_end_all(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.sessions_end_all(acct text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.accounts SET session_epoch = session_epoch + 1 WHERE id = acct;
  DELETE FROM auth.sessions WHERE account = acct;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: sessions_of(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.sessions_of(acct text, this_sid text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'name', coalesce(s.name, CASE s.client WHEN 'app' THEN 'App' ELSE 'Browser' END),
           'client', s.client, 'via', s.via_kind, 'level', s.level, 'country', s.country,
           'created_ms', (extract(epoch FROM s.created_at) * 1000)::bigint,
           'last_seen_ms', (extract(epoch FROM s.last_seen_at) * 1000)::bigint,
           'this', s.id = this_sid, 'device', s.device) ORDER BY s.last_seen_at DESC), '[]'::jsonb)
    FROM auth.sessions s WHERE s.account = acct
$$;


--
-- Name: spent_24h(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.spent_24h(grant_ text) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(sum(sats), 0)::bigint FROM auth.agent_spends WHERE grant_id = grant_ AND at > now() - interval '24 hours'
$$;


--
-- Name: strong_ways(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.strong_ways(acct text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT (SELECT count(*) FROM auth.nostr_keys WHERE account = acct)::int
       + (SELECT count(*) FROM auth.passkeys WHERE account = acct)::int
       + (SELECT count(*) FROM auth.recovery WHERE account = acct AND spent_at IS NULL)::int
$$;


--
-- Name: unfreeze(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.unfreeze(acct text) RETURNS boolean
    LANGUAGE sql
    AS $$
  WITH u AS (UPDATE auth.accounts SET frozen_at = NULL, frozen_why = NULL
              WHERE id = acct AND frozen_why = 'freeze' AND delete_asked_at IS NULL AND deleted_at IS NULL RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM u)
$$;


--
-- Name: unlink(text, text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.unlink(acct text, kind_ text, id_ bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  IF kind_ = 'email' THEN DELETE FROM auth.emails WHERE id = id_ AND account = acct;
  ELSIF kind_ = 'nostr' THEN DELETE FROM auth.nostr_keys WHERE id = id_ AND account = acct;
  ELSIF kind_ = 'passkey' THEN DELETE FROM auth.passkeys WHERE id = id_ AND account = acct;
  ELSE RETURN NULL; END IF;
  IF NOT FOUND THEN RETURN NULL; END IF;
  DELETE FROM auth.sessions WHERE account = acct AND via_kind = kind_ AND via_id = id_;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: viewer_lines(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.viewer_lines(pk text) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT CASE WHEN coalesce(pk, '') ~ '^[0-9a-f]{64}$' THEN
    'K|' || auth.bech32('npub', pk) || E'\n'
      || coalesce((SELECT string_agg('J|' || d.slug, E'\n' ORDER BY d.slug) FROM projects.docs d WHERE projects.member_of(d.slug, pk) IS NOT NULL), '') || E'\n'
      || 'H|' || pk || E'\n'
      || coalesce((SELECT string_agg(DISTINCT 'M|' || k.member, E'\n') FROM projects.member_keys k WHERE k.pubkey = pk), '') || E'\n'
  END
$_$;


--
-- Name: wallet_backup_drop(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_backup_drop(acct text) RETURNS integer
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM auth.wallet_backups WHERE account = acct RETURNING 1) SELECT count(*)::int FROM d
$$;


--
-- Name: wallet_backup_forward(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_backup_forward() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.epoch <> OLD.epoch + 1 THEN
    RAISE EXCEPTION 'auth.wallet_backups: an epoch goes up by one' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: wallet_backup_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_backup_of(acct text) RETURNS TABLE(vault text, epoch bigint, slots text, object_hex text, created_ms bigint, updated_ms bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT b.vault, b.epoch, b.slots, encode(b.object, 'hex'), (extract(epoch FROM b.created_at) * 1000)::bigint, (extract(epoch FROM b.updated_at) * 1000)::bigint
    FROM auth.wallet_backups b WHERE b.account = acct
$$;


--
-- Name: wallet_backup_put(text, bigint, text, text, bytea); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_backup_put(acct text, after bigint, vault_ text, slots_ text, object_ bytea) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE cur bigint;
BEGIN
  PERFORM 1 FROM auth.accounts a WHERE a.id = acct FOR UPDATE;
  SELECT b.epoch INTO cur FROM auth.wallet_backups b WHERE b.account = acct;
  IF coalesce(cur, 0) <> after THEN RETURN NULL; END IF;
  IF cur IS NULL THEN
    INSERT INTO auth.wallet_backups (account, vault, epoch, slots, object) VALUES (acct, vault_, 1, slots_, object_);
    RETURN 1;
  END IF;
  UPDATE auth.wallet_backups SET vault = vault_, epoch = cur + 1, slots = slots_, object = object_, updated_at = now() WHERE account = acct;
  RETURN cur + 1;
END $$;


--
-- Name: wallet_limit_by_link(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_limit_by_link(sha text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT l.account FROM auth.wallet_limits l WHERE l.cancel_sha256 = sha AND l.pending_at > now()
$$;


--
-- Name: wallet_limit_cancel(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_limit_cancel(acct text) RETURNS bigint
    LANGUAGE sql
    AS $$
  WITH old AS (SELECT l.pending_sat FROM auth.wallet_limits l WHERE l.account = acct AND l.pending_at > now() FOR UPDATE),
       u AS (UPDATE auth.wallet_limits l SET pending_sat = NULL, pending_asked_at = NULL, pending_at = NULL, cancel_sha256 = NULL, updated_at = now()
              WHERE l.account = acct AND EXISTS (SELECT 1 FROM old) RETURNING 1)
  SELECT (SELECT pending_sat FROM old) FROM (SELECT count(*) FROM u) done
$$;


--
-- Name: wallet_limit_lower(text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_limit_lower(acct text, sat bigint) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.wallet_limits (account, daily_sat) VALUES (acct, sat)
  ON CONFLICT (account) DO UPDATE SET daily_sat = EXCLUDED.daily_sat, pending_sat = NULL, pending_asked_at = NULL, pending_at = NULL, cancel_sha256 = NULL, updated_at = now()
$$;


--
-- Name: wallet_limit_of(text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_limit_of(acct text, default_sat bigint, OUT daily_sat bigint, OUT pending_sat bigint, OUT pending_asked_ms bigint, OUT pending_ms bigint, OUT now_ms bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE auth.wallet_limits l SET daily_sat = l.pending_sat, pending_sat = NULL, pending_asked_at = NULL, pending_at = NULL, cancel_sha256 = NULL, updated_at = now()
   WHERE l.account = acct AND l.pending_at IS NOT NULL AND l.pending_at <= now();
  SELECT l.daily_sat, coalesce(l.pending_sat, 0), coalesce((extract(epoch FROM l.pending_asked_at) * 1000)::bigint, 0),
         coalesce((extract(epoch FROM l.pending_at) * 1000)::bigint, 0)
    INTO daily_sat, pending_sat, pending_asked_ms, pending_ms FROM auth.wallet_limits l WHERE l.account = acct;
  IF daily_sat IS NULL THEN daily_sat := default_sat; pending_sat := 0; pending_asked_ms := 0; pending_ms := 0; END IF;
  now_ms := (extract(epoch FROM now()) * 1000)::bigint;
END $$;


--
-- Name: wallet_limit_raise(text, bigint, bigint, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_limit_raise(acct text, current bigint, sat bigint, cancel text) RETURNS bigint
    LANGUAGE sql
    AS $$
  INSERT INTO auth.wallet_limits (account, daily_sat, pending_sat, pending_asked_at, pending_at, cancel_sha256)
  VALUES (acct, current, sat, now(), now() + interval '24 hours', cancel)
  ON CONFLICT (account) DO UPDATE SET pending_sat = EXCLUDED.pending_sat, pending_asked_at = now(), pending_at = now() + interval '24 hours',
                                      cancel_sha256 = EXCLUDED.cancel_sha256, updated_at = now()
  RETURNING (extract(epoch FROM pending_at) * 1000)::bigint
$$;


--
-- Name: wallet_spend_add(text, text, bigint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_spend_add(acct text, pid text, sats_ bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  INSERT INTO auth.wallet_spends (account, payment_id, sats) VALUES (acct, pid, sats_) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n = 1;
END $$;


--
-- Name: wallet_spend_void(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_spend_void(acct text, pid text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  UPDATE auth.wallet_spends SET voided_at = now() WHERE account = acct AND payment_id = pid AND voided_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n = 1;
END $$;


--
-- Name: wallet_spends_sweep(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_spends_sweep() RETURNS integer
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM auth.wallet_spends WHERE at < now() - interval '30 days' RETURNING 1),
       c AS (DELETE FROM auth.credit_spends WHERE hour < now() - interval '30 days' RETURNING 1)
  SELECT ((SELECT count(*) FROM d) + (SELECT count(*) FROM c))::int
$$;


--
-- Name: wallet_spent(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.wallet_spent(acct text, pid text, OUT spent bigint, OUT seen bigint) RETURNS record
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT sum(s.sats) FROM auth.wallet_spends s WHERE s.account = acct AND s.voided_at IS NULL AND s.at > now() - interval '24 hours'), 0)::bigint,
         coalesce((SELECT s.sats FROM auth.wallet_spends s WHERE s.account = acct AND s.payment_id = pid), 0)::bigint
$$;


--
-- Name: ways_of(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.ways_of(acct text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'emails', coalesce((SELECT jsonb_agg(jsonb_build_object('id', e.id, 'sealed', e.sealed,
                          'added_ms', (extract(epoch FROM e.created_at) * 1000)::bigint) ORDER BY e.id) FROM auth.emails e WHERE e.account = acct), '[]'),
    'keys', coalesce((SELECT jsonb_agg(jsonb_build_object('id', k.id, 'pubkey', k.pubkey, 'label', coalesce(k.label, ''),
                          'added_ms', (extract(epoch FROM k.created_at) * 1000)::bigint) ORDER BY k.id) FROM auth.nostr_keys k WHERE k.account = acct), '[]'),
    'passkeys', (SELECT count(*) FROM auth.passkeys WHERE account = acct),
    'recovery_code', EXISTS (SELECT 1 FROM auth.recovery WHERE account = acct AND spent_at IS NULL),
    'ways', auth.login_ways(acct), 'strong', auth.strong_ways(acct))
$$;


--
-- Name: api(text, jsonb, jsonb); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.api(op text, body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  pk text := nullif(who->>'pubkey', '');
  may boolean := coalesce((who->>'may')::boolean, false);
  b jsonb := CASE WHEN jsonb_typeof(body) = 'object' THEN body ELSE '{}' END;
  cid bigint := CASE WHEN coalesce(b->>'c', '') ~ '^[0-9]{1,18}$' THEN (b->>'c')::bigint END;
  res jsonb;
  at int;
BEGIN
  IF op IN ('tab', 'record') THEN
    IF pk IS NULL OR NOT may THEN RETURN chat.r(403, '{"error":"admins only"}'); END IF;
    IF cid IS NULL OR NOT EXISTS (SELECT 1 FROM chat.conversations WHERE id = cid AND owner = pk) THEN
      RETURN chat.r(404, '{"error":"no such conversation"}');
    END IF;
    IF op = 'record' THEN RETURN chat.r(200, to_jsonb(chat.record(cid))); END IF;
    IF coalesce(b->>'open', 'true') = 'false' THEN
      PERFORM chat.tab_close(pk, cid);
      RETURN chat.r(200, jsonb_build_object('c', cid, 'tab', NULL));
    END IF;
    at := chat.tab_open(pk, cid);
    RETURN chat.r(200, jsonb_build_object('c', cid, 'tab', at));
  END IF;
  res := chat.api_v1(op, body, who);
  IF op IN ('new', 'send') AND (res->>'status')::int = 200 AND coalesce(res->'body'->>'c', '') ~ '^[0-9]{1,18}$' THEN
    PERFORM chat.tab_open(pk, (res->'body'->>'c')::bigint);
  END IF;
  RETURN res;
END $_$;


--
-- Name: api_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.api_v1(op text, body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  pk text := nullif(who->>'pubkey', '');
  may boolean := coalesce((who->>'may')::boolean, false);
  runner boolean := coalesce((who->>'runner')::boolean, false);
  cap numeric := coalesce(nullif(who->>'cap_usd', '')::numeric, 10);
  now_ms bigint := chat.now_ms();
  b jsonb := CASE WHEN jsonb_typeof(body) = 'object' THEN body ELSE '{}' END;
  cid bigint := CASE WHEN coalesce(b->>'c', '') ~ '^[0-9]{1,18}$' THEN (b->>'c')::bigint END;
  m text := coalesce(b->>'model', '');
  t text;
  cv chat.conversations;
  tn chat.turns;
  cr chat.credentials;
  x jsonb;
  st text;
BEGIN
  IF op IN ('next', 'event', 'end') THEN
    IF NOT runner THEN RETURN chat.r(403, '{"error":"the runner only"}'); END IF;
  ELSIF pk IS NULL OR NOT may THEN
    RETURN chat.r(403, '{"error":"admins only"}');
  END IF;

  IF op = 'state' THEN
    RETURN chat.r(200, to_jsonb(coalesce(chat.lines(pk, cid, cap), '')));
  ELSIF op = 'new' THEN
    IF NOT chat.model_ok(m) THEN m := 'claude-opus-5-5'; END IF;
    INSERT INTO chat.conversations (owner, model, created_ms, updated_ms) VALUES (pk, m, now_ms, now_ms) RETURNING * INTO cv;
    RETURN chat.r(200, jsonb_build_object('c', cv.id));
  ELSIF op = 'model' THEN
    IF NOT chat.model_ok(m) THEN RETURN chat.r(400, '{"error":"that model is not offered"}'); END IF;
    UPDATE chat.conversations SET model = m WHERE id = cid AND owner = pk RETURNING * INTO cv;
    IF cv.id IS NULL THEN RETURN chat.r(404, '{"error":"no such conversation"}'); END IF;
    RETURN chat.r(200, jsonb_build_object('c', cv.id, 'model', m));
  ELSIF op = 'send' THEN
    t := btrim(coalesce(b->>'text', ''));
    IF t = '' OR length(t) > 8000 THEN RETURN chat.r(400, '{"error":"a message is 1 to 8000 characters"}'); END IF;
    IF m <> '' AND NOT chat.model_ok(m) THEN RETURN chat.r(400, '{"error":"that model is not offered"}'); END IF;
    IF cid IS NULL THEN
      INSERT INTO chat.conversations (owner, model, created_ms, updated_ms)
        VALUES (pk, CASE WHEN m = '' THEN 'claude-opus-5-5' ELSE m END, now_ms, now_ms) RETURNING * INTO cv;
    ELSE
      SELECT * INTO cv FROM chat.conversations WHERE id = cid AND owner = pk FOR UPDATE;
      IF cv.id IS NULL THEN RETURN chat.r(404, '{"error":"no such conversation"}'); END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM chat.turns WHERE conv = cv.id AND status IN ('queued', 'running')) THEN
      RETURN chat.r(409, '{"error":"the agent is still answering; wait or press STOP"}');
    END IF;
    SELECT * INTO cr FROM chat.credentials WHERE owner = pk;
    IF (cr.owner IS NULL OR cr.expired) AND chat.spent() >= cap THEN
      RETURN chat.r(429, jsonb_build_object('error', 'Today''s $' || to_char(cap, 'FM9990') || ' limit for /chat on the OpenAgents key is reached. Save your own key, or come back after midnight Chicago time.', 'cap', true));
    END IF;
    IF m <> '' THEN cv.model := m; END IF;
    UPDATE chat.conversations SET model = cv.model, updated_ms = now_ms, status = 'running',
      title = CASE WHEN title = '' THEN left(regexp_replace(t, '\s+', ' ', 'g'), 80) ELSE title END WHERE id = cv.id;
    INSERT INTO chat.turns (conv, owner, text, model, status, asked_ms) VALUES (cv.id, pk, t, cv.model, 'queued', now_ms) RETURNING * INTO tn;
    INSERT INTO chat.events (turn, at_ms, type, data) VALUES (tn.id, now_ms, 'user.message', jsonb_build_object('length', length(t)));
    RETURN chat.r(200, jsonb_build_object('c', cv.id, 'turn', tn.id, 'model', cv.model)) || '{"wake":true}';
  ELSIF op = 'stop' THEN
    SELECT * INTO tn FROM chat.turns WHERE conv = cid AND owner = pk AND status IN ('queued', 'running') ORDER BY id DESC LIMIT 1 FOR UPDATE;
    IF tn.id IS NULL THEN RETURN chat.r(409, '{"error":"nothing is running"}'); END IF;
    IF tn.status = 'queued' THEN
      UPDATE chat.turns SET status = 'stopped', stop = true, ended_ms = now_ms WHERE id = tn.id;
      UPDATE chat.conversations SET status = 'idle' WHERE id = tn.conv;
    ELSE
      UPDATE chat.turns SET stop = true WHERE id = tn.id;
    END IF;
    INSERT INTO chat.events (turn, at_ms, type, data) VALUES (tn.id, now_ms, 'user.interrupt', '{}');
    RETURN chat.r(200, jsonb_build_object('turn', tn.id));
  ELSIF op = 'key_set' THEN
    IF coalesce(b->>'kind', '') NOT IN ('api', 'oauth') OR coalesce(b->>'last4', '') !~ '^[A-Za-z0-9_-]{4}$'
       OR coalesce(b->>'sealed', '') !~ '^[A-Za-z0-9+/=]+$' OR length(b->>'sealed') NOT BETWEEN 40 AND 4000 THEN
      RETURN chat.r(400, '{"error":"not a sealed credential"}');
    END IF;
    INSERT INTO chat.credentials (owner, kind, last4, sealed, saved_ms) VALUES (pk, b->>'kind', b->>'last4', b->>'sealed', now_ms)
      ON CONFLICT (owner) DO UPDATE SET kind = excluded.kind, last4 = excluded.last4, sealed = excluded.sealed, expired = false, saved_ms = excluded.saved_ms;
    RETURN chat.r(200, jsonb_build_object('kind', b->>'kind', 'label', chat.cred_label(b->>'kind'), 'last4', b->>'last4'));
  ELSIF op = 'key_remove' THEN
    DELETE FROM chat.credentials WHERE owner = pk;
    RETURN chat.r(200, '{"removed":true}');

  -- the runner
  ELSIF op = 'next' THEN
    -- a turn the runner never ended fails after 20 minutes
    UPDATE chat.turns SET status = 'failed', error = 'the agent stopped answering', ended_ms = now_ms
      WHERE status = 'running' AND started_ms < now_ms - 1200000;
    SELECT * INTO tn FROM chat.turns WHERE status = 'queued' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;
    IF tn.id IS NULL THEN RETURN chat.r(200, '{"turn":null}'); END IF;
    SELECT * INTO cv FROM chat.conversations WHERE id = tn.conv;
    SELECT * INTO cr FROM chat.credentials WHERE owner = tn.owner AND NOT expired;
    IF cr.owner IS NULL AND chat.spent() >= cap THEN
      UPDATE chat.turns SET status = 'refused', ended_ms = now_ms,
        error = 'Today''s $' || to_char(cap, 'FM9990') || ' limit for /chat on the OpenAgents key is reached.' WHERE id = tn.id;
      UPDATE chat.conversations SET status = 'idle' WHERE id = tn.conv;
      INSERT INTO chat.events (turn, at_ms, type, data) VALUES (tn.id, now_ms, 'session.error', '{"error":"over the daily cap"}');
      RETURN chat.r(200, jsonb_build_object('turn', NULL, 'refused', tn.id));
    END IF;
    UPDATE chat.turns SET status = 'running', started_ms = now_ms, working = 'starting',
      credential = CASE WHEN cr.owner IS NULL THEN 'openagents' ELSE 'own' END WHERE id = tn.id;
    INSERT INTO chat.events (turn, at_ms, type, data) VALUES (tn.id, now_ms, 'session.status_running', '{}');
    RETURN chat.r(200, jsonb_build_object(
      'turn', jsonb_build_object('id', tn.id, 'conv', tn.conv, 'text', tn.text, 'model', tn.model, 'by', 'You', 'session', cv.session_id::text),
      'spent', chat.spent(), 'cap', CASE WHEN cr.owner IS NULL THEN cap ELSE 0 END,
      'credential', CASE WHEN cr.owner IS NULL THEN NULL ELSE jsonb_build_object('kind', cr.kind, 'owner', cr.owner, 'sealed', cr.sealed) END,
      'history', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'by', 'You', 'text', h.text, 'answer', h.answer) ORDER BY h.id), '[]')
                  FROM (SELECT * FROM chat.turns WHERE conv = tn.conv AND status = 'done' AND id < tn.id ORDER BY id DESC LIMIT 10) h)));
  END IF;

  -- event and end: a running turn
  SELECT * INTO tn FROM chat.turns WHERE id = CASE WHEN coalesce(b->>'turn', '') ~ '^[0-9]{1,18}$' THEN (b->>'turn')::bigint END AND status = 'running';
  IF tn.id IS NULL THEN RETURN chat.r(409, '{"error":"that turn is not running"}'); END IF;
  IF op = 'event' THEN
    IF jsonb_typeof(b->'events') <> 'array' OR jsonb_array_length(b->'events') > 50 THEN RETURN chat.r(400, '{"error":"events is a list of at most 50"}'); END IF;
    FOR x IN SELECT * FROM jsonb_array_elements(b->'events') LOOP
      IF x->>'type' = 'working' THEN
        UPDATE chat.turns SET working = left(coalesce(x->'data'->>'text', ''), 160) WHERE id = tn.id;
      ELSIF x->>'type' IN ('agent.message', 'agent.tool_use', 'session.error') THEN
        INSERT INTO chat.events (turn, at_ms, type, data) VALUES (tn.id, now_ms, x->>'type',
          CASE WHEN x->>'type' = 'agent.message' THEN jsonb_build_object('length', length(coalesce(x->'data'->>'text', '')))
               ELSE jsonb_build_object('name', left(coalesce(x->'data'->>'name', ''), 60), 'detail', left(coalesce(x->'data'->>'detail', ''), 300),
                                       'error', left(coalesce(x->'data'->>'error', ''), 300)) END);
      END IF;
    END LOOP;
    RETURN chat.r(200, jsonb_build_object('stop', (SELECT stop FROM chat.turns WHERE id = tn.id)));
  ELSIF op = 'end' THEN
    st := coalesce(b->>'status', 'failed');
    IF st NOT IN ('done', 'failed', 'stopped') THEN st := 'failed'; END IF;
    IF tn.stop AND st = 'done' THEN st := 'stopped'; END IF;
    UPDATE chat.turns SET status = st, ended_ms = now_ms, working = '',
      answer = left(coalesce(b->>'answer', ''), 60000), error = left(coalesce(b->>'error', ''), 2000),
      resumed = coalesce((b->>'resumed')::boolean, false),
      cost_usd = least(greatest(coalesce(nullif(b->>'cost_usd', '')::numeric, 0), 0), 100) WHERE id = tn.id;
    UPDATE chat.conversations SET status = 'idle', updated_ms = now_ms WHERE id = tn.conv;
    IF coalesce((b->>'credential_expired')::boolean, false) AND tn.credential = 'own' THEN
      UPDATE chat.credentials SET expired = true WHERE owner = tn.owner;
    END IF;
    INSERT INTO chat.events (turn, at_ms, type, data) VALUES (tn.id, now_ms, 'session.status_idle', jsonb_build_object('status', st));
    RETURN chat.r(200, jsonb_build_object('turn', tn.id, 'status', st));
  END IF;
  RETURN chat.r(404, '{"error":"not found"}');
END
$_$;


--
-- Name: chi(bigint); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chi(ms bigint) RETURNS text
    LANGUAGE sql STABLE
    AS $$ SELECT to_char(to_timestamp(ms / 1000.0) AT TIME ZONE 'America/Chicago', 'Mon DD HH24:MI') $$;


--
-- Name: cred_label(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.cred_label(kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE kind WHEN 'api' THEN 'Anthropic API key' WHEN 'oauth' THEN 'Claude subscription token (from claude setup-token)' ELSE '' END
$$;


--
-- Name: folder_ok(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.folder_ok(f text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT f IN ('openagents') $$;


--
-- Name: jn(text, bigint); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.jn(k text, v bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT to_json(k)::text || ':' || coalesce(v, 0)::text $$;


--
-- Name: jo(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.jo(k text, v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT CASE WHEN coalesce(v, '') = '' THEN '' ELSE ',' || chat.js(k, v) END $$;


--
-- Name: js(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.js(k text, v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT to_json(k)::text || ':' || to_json(coalesce(v, ''))::text $$;


--
-- Name: lines(text, bigint, numeric); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.lines(pk text, want bigint, cap numeric) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH me AS (SELECT * FROM chat.credentials WHERE owner = pk),
  newest AS (SELECT id FROM chat.conversations WHERE owner = pk ORDER BY updated_ms DESC LIMIT 60),
  cs AS (SELECT c.*, EXISTS (SELECT 1 FROM chat.turns t WHERE t.conv = c.id AND t.status IN ('queued', 'running')) AS busy
         FROM chat.conversations c WHERE c.owner = pk AND (c.tab IS NOT NULL OR c.id IN (SELECT id FROM newest))),
  shown AS (SELECT * FROM chat.conversations WHERE owner = pk AND id = coalesce(want, (SELECT id FROM cs ORDER BY updated_ms DESC LIMIT 1))),
  t AS (SELECT * FROM (SELECT * FROM chat.turns WHERE conv = (SELECT id FROM shown) ORDER BY id DESC LIMIT 40) x)
  SELECT string_agg(line, E'\n' ORDER BY o1, o2) || E'\n' FROM (
    SELECT 0 AS o1, 0::bigint AS o2, 'Z|' || to_char(chat.spent(), 'FM9990.00') || '|' || to_char(cap, 'FM9990.00') || '|'
         || coalesce((SELECT kind FROM me), '') || '|' || coalesce((SELECT last4 FROM me), '') || '|'
         || CASE WHEN coalesce((SELECT expired FROM me), false) THEN '1' ELSE '0' END || '|'
         || CASE WHEN EXISTS (SELECT 1 FROM t WHERE status IN ('queued', 'running')) THEN '1' ELSE '0' END || '|'
         || coalesce((SELECT id FROM shown), 0) || '|2' AS line
    UNION ALL SELECT 1, row_number() OVER (ORDER BY updated_ms DESC, id DESC), 'C|' || id || '|' || chat.v(left(title, 80)) || '|' || model || '|' || chat.chi(updated_ms) || '|'
         || CASE WHEN busy THEN '1' ELSE '0' END || '|' || chat.v(folder) || '|' || coalesce(tab::text, '') FROM cs
    UNION ALL SELECT 2, 0, 'S|' || id || '|' || chat.v(left(title, 80)) || '|' || model || '|'
         || CASE WHEN EXISTS (SELECT 1 FROM chat.turns x WHERE x.conv = shown.id AND x.started_ms IS NOT NULL) THEN '1' ELSE '0' END FROM shown
    UNION ALL SELECT 3, t.id * 100, 'U|' || t.id || '|' || t.status || '|' || chat.chi(t.asked_ms) || '|' || t.model || '|' || t.credential || '|'
         || chat.vv(left(t.text, 8000)) || '|' || chat.vv(left(t.answer, 24000)) || '|' || chat.v(left(t.error, 400)) || '|' || chat.v(left(t.working, 160)) || '|'
         || to_char(t.cost_usd, 'FM9990.0000') FROM t
    UNION ALL SELECT 3, e.turn * 100 + 1 + e.k, 'T|' || e.turn || '|' || chat.v(left(e.data->>'name', 40)) || '|' || chat.v(left(coalesce(e.data->>'detail', ''), 200))
      FROM (SELECT ev.*, row_number() OVER (PARTITION BY ev.turn ORDER BY ev.id DESC) AS k FROM chat.events ev
            WHERE ev.turn IN (SELECT id FROM t) AND ev.type = 'agent.tool_use') e WHERE e.k <= 12
  ) all_lines
$$;


--
-- Name: model_ok(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.model_ok(m text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT m IN ('claude-opus-5-5', 'claude-sonnet-5-5', 'claude-haiku-5-5',
                  'google/gemini-3.8-flash', 'google/gemini-4-argon', 'google/gemini-4-carbon') $$;


--
-- Name: now_ms(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.now_ms() RETURNS bigint
    LANGUAGE sql
    AS $$ SELECT floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint $$;


--
-- Name: r(integer, jsonb); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.r(status integer, body jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT jsonb_build_object('status', status, 'body', body) $$;


--
-- Name: record(bigint); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.record(cid bigint) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH cv AS (SELECT * FROM chat.conversations WHERE id = cid),
  t AS (SELECT * FROM chat.turns WHERE conv = cid),
  tools AS (SELECT ev.* FROM chat.events ev WHERE ev.turn IN (SELECT id FROM t) AND ev.type = 'agent.tool_use'),
  lines AS (
    SELECT 0::bigint AS o1, 0::bigint AS o2, 0 AS o3, '{' || chat.js('kind', 'session') || ',' || chat.js('schema', 'openagents.session.v1') || ','
        || chat.js('id', cv.session_id::text) || ',' || chat.js('engine', 'claude') || ',' || chat.js('cwd', cv.folder) || ','
        || chat.jn('started_us', cv.created_ms * 1000) || chat.jo('title', cv.title) || chat.jo('model', cv.model) || '}' AS line FROM cv
    UNION ALL SELECT t.id, 0, 0, '{' || chat.js('kind', 'user') || ',' || chat.js('text', t.text) || '}' FROM t
    UNION ALL SELECT e.turn, e.id, 0, '{' || chat.js('kind', 'tool') || ','
        || chat.js('label', coalesce(e.data->>'name', 'tool') || CASE WHEN coalesce(e.data->>'detail', '') = '' THEN '' ELSE '(' || (e.data->>'detail') || ')' END) || ','
        || chat.js('tool', chat.tool_kind(coalesce(e.data->>'name', ''))) || ',' || chat.js('name', coalesce(e.data->>'name', 'tool')) || ','
        || chat.js('id', 'chat-' || e.id) || chat.jo('detail', e.data->>'detail') || '}' FROM tools e
    UNION ALL SELECT e.turn, e.id, 1, '{' || chat.js('kind', 'result') || ',' || chat.js('text', '') || ',"error":false,' || chat.js('id', 'chat-' || e.id) || '}' FROM tools e
    UNION ALL SELECT t.id, 9223372036854775806, 0, '{' || chat.js('kind', 'reply') || ',' || chat.js('text', t.answer) || '}' FROM t WHERE t.answer <> ''
    UNION ALL SELECT t.id, 9223372036854775806, 1, '{' || chat.js('kind', 'notice') || ','
        || chat.js('notice', CASE WHEN t.status = 'refused' THEN 'limit' ELSE 'error' END) || ',' || chat.js('text', t.error) || '}'
      FROM t WHERE t.error <> '' AND t.status IN ('failed', 'refused')
    UNION ALL SELECT t.id, 9223372036854775807, 0, '{' || chat.js('kind', 'end') || ','
        || chat.js('ending', CASE t.status WHEN 'done' THEN 'finished' WHEN 'stopped' THEN 'stopped' ELSE 'failed' END) || ','
        || chat.jn('ms', greatest(coalesce(t.ended_ms - coalesce(t.started_ms, t.asked_ms), 0), 0)) || ','
        || chat.jn('steps', (SELECT count(*) FROM tools x WHERE x.turn = t.id)) || ','
        || chat.jn('cost_usd_e6', round(t.cost_usd * 1000000)::bigint) || '}'
      FROM t WHERE t.status IN ('done', 'failed', 'stopped', 'refused')
  )
  SELECT coalesce(string_agg(line, E'\n' ORDER BY o1, o2, o3) || E'\n', '') FROM lines
$$;


--
-- Name: spent(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.spent() RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(sum(cost_usd), 0) FROM chat.turns
  WHERE credential = 'openagents'
    AND asked_ms >= (extract(epoch FROM (date_trunc('day', now() AT TIME ZONE 'America/Chicago') AT TIME ZONE 'America/Chicago')) * 1000)::bigint
$$;


--
-- Name: tab_close(text, bigint); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.tab_close(pk text, cid bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE at int;
BEGIN
  SELECT tab INTO at FROM chat.conversations WHERE id = cid AND owner = pk FOR UPDATE;
  IF at IS NULL THEN RETURN; END IF;
  UPDATE chat.conversations SET tab = NULL WHERE id = cid AND owner = pk;
  UPDATE chat.conversations SET tab = tab - 1 WHERE owner = pk AND tab > at;
END $$;


--
-- Name: tab_open(text, bigint); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.tab_open(pk text, cid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE at int;
BEGIN
  SELECT tab INTO at FROM chat.conversations WHERE id = cid AND owner = pk FOR UPDATE;
  IF at IS NOT NULL THEN RETURN at; END IF;
  SELECT coalesce(max(tab), 0) + 1 INTO at FROM chat.conversations WHERE owner = pk AND tab IS NOT NULL;
  UPDATE chat.conversations SET tab = at WHERE id = cid AND owner = pk;
  RETURN at;
END $$;


--
-- Name: tool_kind(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.tool_kind(name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE name WHEN 'Read' THEN 'read' WHEN 'Grep' THEN 'search' WHEN 'Glob' THEN 'glob'
    WHEN 'WebSearch' THEN 'web' WHEN 'WebFetch' THEN 'fetch' WHEN 'Bash' THEN 'exec'
    WHEN 'Edit' THEN 'edit' WHEN 'Write' THEN 'write' WHEN 'TodoWrite' THEN 'todo' WHEN 'Task' THEN 'agent'
    ELSE CASE WHEN name LIKE 'mcp\_\_%' THEN 'mcp' ELSE 'tool' END END
$$;


--
-- Name: v(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.v(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT regexp_replace(coalesce(t, ''), '[|\r\n\t]', ' ', 'g') $$;


--
-- Name: vv(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.vv(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT replace(replace(replace(replace(replace(coalesce(t, ''), E'\\', E'\\\\'), '|', E'\\p'), E'\r', ''), E'\n', E'\\n'), E'\t', '  ') $$;


--
-- Name: admit(text, boolean, text, jsonb, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.admit(pubkey text, admin boolean, drop_ text, req jsonb, prefix text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  d drops.drops;
  name_ text; ext_ text; kind_ text; bytes_ bigint; id_ text; obj text;
  in_drop int; drop_bytes bigint;
BEGIN
  SELECT * INTO d FROM drops.drops WHERE id = drop_ AND owner = pubkey FOR UPDATE;
  IF d.id IS NULL THEN RETURN drops.r(404, '{"error":"not found"}'); END IF;
  IF NOT drops.may(pubkey, admin) THEN RETURN drops.r(403, '{"error":"this key may not drop files yet"}'); END IF;
  IF d.status <> 'open' THEN RETURN drops.r(409, '{"error":"this drop is closed"}'); END IF;
  name_ := req->>'name';
  IF jsonb_typeof(req->'name') <> 'string' OR length(name_) < 1 OR octet_length(name_) > 200 OR name_ ~ '[\x00-\x1f/\\]' THEN
    RETURN drops.r(400, '{"error":"a file needs a name"}');
  END IF;
  IF jsonb_typeof(req->'bytes') <> 'number' OR (req->>'bytes') !~ '^[0-9]{1,12}$' THEN RETURN drops.r(400, '{"error":"how big is it?"}'); END IF;
  bytes_ := (req->>'bytes')::bigint;
  ext_ := drops.ext(name_);
  kind_ := drops.kind(ext_);
  IF kind_ IS NULL THEN RETURN drops.r(415, jsonb_build_object('error', 'we don''t take ' || CASE WHEN ext_ = '' THEN 'files without an extension' ELSE '.' || ext_ || ' files' END)); END IF;
  IF bytes_ = 0 THEN RETURN drops.r(400, '{"error":"it is empty"}'); END IF;
  IF bytes_ > drops.file_limit() THEN RETURN drops.r(413, '{"error":"over 64 MB"}'); END IF;
  SELECT count(*), coalesce(sum(bytes), 0) INTO in_drop, drop_bytes FROM drops.files WHERE drop_id = d.id AND status <> 'refused';
  IF in_drop >= drops.files_limit() THEN RETURN drops.r(413, '{"error":"a drop holds 40 files"}'); END IF;
  IF drop_bytes + bytes_ > drops.drop_limit() THEN RETURN drops.r(413, '{"error":"a drop holds 512 MB"}'); END IF;
  IF drops.used(pubkey) + bytes_ > drops.owner_limit() THEN RETURN drops.r(413, '{"error":"you have 2 GB of drops already"}'); END IF;
  id_ := 'f-' || drops.hex16();
  obj := prefix || '/' || pubkey || '/' || d.id || '/' || id_ || '.' || ext_;
  INSERT INTO drops.files (id, drop_id, name, ext, kind, bytes, content_type, object, created_ms)
  VALUES (id_, d.id, name_, ext_, kind_, bytes_, drops.content_type(ext_), obj, drops.now_ms());
  RETURN drops.r(200, jsonb_build_object('file', id_)) || jsonb_build_object('object', obj, 'type', drops.content_type(ext_), 'bytes', bytes_);
END $_$;


--
-- Name: adopt(text, jsonb, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.adopt(signer text, req jsonb, sealed text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE s text := req->>'slug'; m text[];
BEGIN
  IF s IS NULL OR s = '' OR s <> drops.slug(s) THEN RETURN drops.r(400, '{"error":"a slug: lowercase words joined by dashes"}'); END IF;
  IF coalesce(btrim(req->>'name'), '') = '' THEN RETURN drops.r(400, '{"error":"the project''s name"}'); END IF;
  IF jsonb_typeof(req->'members') <> 'array' THEN RETURN drops.r(400, '{"error":"members: their hex keys"}'); END IF;
  SELECT array_agg(DISTINCT x) INTO m FROM jsonb_array_elements_text(req->'members') x;
  IF m IS NULL OR EXISTS (SELECT 1 FROM unnest(m) x WHERE x !~ '^[0-9a-f]{64}$') THEN
    RETURN drops.r(400, '{"error":"members: their hex keys"}');
  END IF;
  IF sealed !~ '^[0-9a-f]+$' OR signer !~ '^[0-9a-f]{64}$' THEN RETURN drops.r(400, '{"error":"not sealed"}'); END IF;
  IF EXISTS (SELECT 1 FROM drops.projects WHERE slug = s AND pubkey = signer) THEN
    RETURN drops.r(409, '{"error":"this project''s key is here already"}');
  END IF;
  INSERT INTO drops.homes (slug, pubkey, key_sealed, name, members, adopted_ms)
  VALUES (s, signer, sealed, drops.one_line(req->>'name', 120), m, drops.now_ms())
  ON CONFLICT (slug, pubkey) DO UPDATE SET key_sealed = EXCLUDED.key_sealed, name = EXCLUDED.name, members = EXCLUDED.members,
    adopted_ms = EXCLUDED.adopted_ms;
  RETURN drops.r(200, jsonb_build_object('slug', s, 'pubkey', signer, 'members', array_length(m, 1)));
END $_$;


--
-- Name: at(bytea, integer, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.at(b bytea, at integer, p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT length(b) >= at + length(p) / 2 AND substring(b FROM at + 1 FOR length(p) / 2) = decode(p, 'hex') $$;


--
-- Name: clean(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.clean(s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT regexp_replace(coalesce(s, ''), '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]', '', 'g') $$;


--
-- Name: content_type(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.content_type(ext text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE ext
    WHEN 'txt' THEN 'text/plain; charset=utf-8' WHEN 'md' THEN 'text/markdown; charset=utf-8'
    WHEN 'markdown' THEN 'text/markdown; charset=utf-8' WHEN 'csv' THEN 'text/csv; charset=utf-8'
    WHEN 'json' THEN 'application/json' WHEN 'pdf' THEN 'application/pdf' WHEN 'rtf' THEN 'application/rtf'
    WHEN 'docx' THEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    WHEN 'odt' THEN 'application/vnd.oasis.opendocument.text'
    WHEN 'png' THEN 'image/png' WHEN 'jpg' THEN 'image/jpeg' WHEN 'jpeg' THEN 'image/jpeg' WHEN 'gif' THEN 'image/gif'
    WHEN 'webp' THEN 'image/webp' WHEN 'avif' THEN 'image/avif' WHEN 'heic' THEN 'image/heic' WHEN 'svg' THEN 'text/plain; charset=utf-8'
    WHEN 'mp3' THEN 'audio/mpeg' WHEN 'wav' THEN 'audio/wav' WHEN 'm4a' THEN 'audio/mp4' WHEN 'aac' THEN 'audio/aac'
    WHEN 'ogg' THEN 'audio/ogg' WHEN 'opus' THEN 'audio/ogg' WHEN 'flac' THEN 'audio/flac' WHEN 'webm' THEN 'audio/webm'
    WHEN 'glb' THEN 'model/gltf-binary' WHEN 'gltf' THEN 'model/gltf+json' WHEN 'obj' THEN 'model/obj'
    WHEN 'mtl' THEN 'model/mtl' WHEN 'stl' THEN 'model/stl' WHEN 'usdz' THEN 'model/vnd.usdz+zip'
    WHEN 'mp4' THEN 'video/mp4' WHEN 'mov' THEN 'video/quicktime' WHEN 'zip' THEN 'application/zip'
    WHEN 'ktx2' THEN 'image/ktx2'
    ELSE 'application/octet-stream'
  END $$;


--
-- Name: cover(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.cover(slug_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '/' || f.dest FROM drops.projects p JOIN drops.drafts x ON x.drop_id = p.drop_id
  JOIN drops.files df ON df.drop_id = p.drop_id AND df.status = 'scanned' AND df.kind = 'image' AND df.name = x.draft#>>'{card,cover}'
  JOIN drops.publish_files(p.slug) f ON f.object = df.object
  WHERE p.slug = slug_ LIMIT 1 $$;


--
-- Name: discard(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.discard(pubkey text, drop_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE d drops.drops; gone jsonb;
BEGIN
  SELECT * INTO d FROM drops.drops WHERE id = drop_ AND owner = pubkey FOR UPDATE;
  IF d.id IS NULL THEN RETURN drops.r(404, '{"error":"not found"}'); END IF;
  IF d.status NOT IN ('open', 'approved') THEN RETURN drops.r(409, '{"error":"this drop is closed"}'); END IF;
  IF EXISTS (SELECT 1 FROM drops.files WHERE drop_id = d.id AND status IN ('waiting', 'uploading') AND created_ms > drops.now_ms() - 3600000) THEN
    RETURN drops.r(409, '{"error":"files are still uploading"}');
  END IF;
  SELECT coalesce(jsonb_agg(object), '[]') INTO gone FROM drops.files WHERE drop_id = d.id AND status <> 'refused';
  DELETE FROM drops.drafts WHERE drop_id = d.id;
  DELETE FROM drops.files WHERE drop_id = d.id;
  UPDATE drops.drops SET status = 'discarded' WHERE id = d.id;
  RETURN drops.r(200, '{"drop":"discarded"}') || jsonb_build_object('objects', gone);
END $$;


--
-- Name: draft_approve(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_approve(pubkey text, drop_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE d drops.drops; x drops.drafts;
BEGIN
  SELECT * INTO d FROM drops.drops WHERE id = drop_ AND owner = pubkey FOR UPDATE;
  IF d.id IS NULL THEN RETURN drops.r(404, '{"error":"not found"}'); END IF;
  IF d.status <> 'open' THEN RETURN drops.r(409, '{"error":"this drop is closed"}'); END IF;
  SELECT * INTO x FROM drops.drafts WHERE drop_id = d.id FOR UPDATE;
  IF x.status IS DISTINCT FROM 'ready' OR drops.draft_invalid(x.draft) IS NOT NULL THEN
    RETURN drops.r(409, '{"error":"no draft to publish"}');
  END IF;
  IF EXISTS (SELECT 1 FROM drops.files WHERE drop_id = d.id AND status IN ('waiting', 'uploading')) THEN
    RETURN drops.r(409, '{"error":"files are still uploading"}');
  END IF;
  UPDATE drops.drops SET status = 'approved' WHERE id = d.id;
  UPDATE drops.drafts SET approved_ms = drops.now_ms() WHERE drop_id = d.id RETURNING * INTO x;
  RETURN drops.r(200, drops.draft_json(x) || '{"drop":"approved"}');
END $$;


--
-- Name: draft_done(text, integer, text, text, integer); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_done(drop_ text, http integer, answer text, model_ text, took integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE body jsonb; txt text; d jsonb; why text; x drops.drafts; dr drops.drops; h record;
BEGIN
  SELECT * INTO dr FROM drops.drops WHERE id = drop_;
  IF http = 200 THEN
    BEGIN
      body := answer::jsonb;
      SELECT string_agg(p->>'text', '' ORDER BY i) INTO txt
      FROM jsonb_array_elements(body#>'{candidates,0,content,parts}') WITH ORDINALITY AS z(p, i)
      WHERE coalesce((p->>'thought')::bool, false) = false AND p ? 'text';
      d := txt::jsonb;
    EXCEPTION WHEN others THEN d := NULL;
    END;
    IF jsonb_typeof(d) = 'object' AND dr.project IS NOT NULL THEN
      SELECT * INTO h FROM drops.home(dr.project, dr.project_pubkey) LIMIT 1;
      d := (d - 'grow') || jsonb_build_object('grow', jsonb_build_object('project', dr.project, 'pubkey', dr.project_pubkey));
      d := jsonb_set(d, '{card}', CASE WHEN jsonb_typeof(d->'card') = 'object' THEN d->'card' ELSE '{}' END
                     || jsonb_build_object('name', coalesce(h.name, dr.project), 'slug', dr.project));
    END IF;
    why := CASE WHEN d IS NULL THEN 'the model''s answer was not a draft' ELSE drops.draft_invalid(d) END;
  ELSE
    why := 'the model did not answer (' || http || ')';
  END IF;
  IF why IS NULL THEN
    d := jsonb_set(d, '{card,slug}', to_jsonb(drops.slug(coalesce(nullif(d#>>'{card,slug}', ''), d#>>'{card,name}'))));
  END IF;
  UPDATE drops.drafts SET status = CASE WHEN why IS NULL THEN 'ready' ELSE 'failed' END, draft = CASE WHEN why IS NULL THEN d ELSE draft END,
    note = coalesce(why, ''), model = model_, done_ms = drops.now_ms(), took_ms = took
  WHERE drop_id = drop_ RETURNING * INTO x;
  RETURN drops.r(CASE WHEN why IS NULL THEN 200 ELSE 502 END, drops.draft_json(x));
END $$;


--
-- Name: draft_edit(text, text, jsonb); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_edit(pubkey text, drop_ text, req jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE d drops.drops; x drops.drafts; p text[]; v text; parent jsonb; target jsonb; nd jsonb; why text; n int;
BEGIN
  SELECT * INTO d FROM drops.drops WHERE id = drop_ AND owner = pubkey FOR UPDATE;
  IF d.id IS NULL THEN RETURN drops.r(404, '{"error":"not found"}'); END IF;
  IF d.status <> 'open' THEN RETURN drops.r(409, '{"error":"this drop is closed"}'); END IF;
  SELECT * INTO x FROM drops.drafts WHERE drop_id = d.id FOR UPDATE;
  IF x.status IS DISTINCT FROM 'ready' THEN RETURN drops.r(409, '{"error":"no draft to change"}'); END IF;
  IF jsonb_typeof(req->'path') <> 'array' OR jsonb_typeof(req->'value') <> 'string' THEN
    RETURN drops.r(400, '{"error":"a path and a value"}');
  END IF;
  SELECT array_agg(e ORDER BY i) INTO p FROM jsonb_array_elements_text(req->'path') WITH ORDINALITY AS z(e, i);
  v := req->>'value';
  n := coalesce(array_length(p, 1), 0);
  IF n < 2 OR n > 8 OR p[1] NOT IN ('card', 'mechanics', 'design', 'roadmap', 'assets', 'to_make', 'engine_needs') THEN
    RETURN drops.r(400, '{"error":"not a field of the draft"}');
  END IF;
  IF length(v) > drops.edit_max() THEN RETURN drops.r(400, '{"error":"too long"}'); END IF;
  v := btrim(v);
  target := x.draft #> p;
  parent := x.draft #> p[1:n - 1];
  IF target IS NULL AND jsonb_typeof(parent) = 'array' AND p[n] ~ '^[0-9]+$' AND p[n]::int = jsonb_array_length(parent)
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(parent) e WHERE jsonb_typeof(e) <> 'string') THEN
    IF v = '' THEN RETURN drops.r(400, '{"error":"nothing to add"}'); END IF;
    nd := jsonb_set(x.draft, p[1:n - 1], parent || to_jsonb(v));
  ELSIF jsonb_typeof(target) = 'boolean' THEN
    IF lower(v) NOT IN ('yes', 'no', 'true', 'false') THEN RETURN drops.r(400, '{"error":"yes or no"}'); END IF;
    nd := jsonb_set(x.draft, p, to_jsonb(lower(v) IN ('yes', 'true')));
  ELSIF jsonb_typeof(target) = 'string' THEN
    IF v = '' AND jsonb_typeof(parent) = 'array' THEN
      nd := x.draft #- p;
    ELSE
      IF p[n] = 'size' AND v NOT IN ('S', 'M', 'L') THEN RETURN drops.r(400, '{"error":"a size is S, M or L"}'); END IF;
      IF p[1:2] = ARRAY['card', 'slug'] THEN
        v := drops.slug(v);
        IF v = '' THEN RETURN drops.r(400, '{"error":"a slug needs a letter or a digit"}'); END IF;
      END IF;
      nd := jsonb_set(x.draft, p, to_jsonb(v));
    END IF;
  ELSE
    RETURN drops.r(400, '{"error":"not a field of the draft"}');
  END IF;
  why := drops.draft_invalid(nd);
  IF why IS NOT NULL THEN RETURN drops.r(400, jsonb_build_object('error', 'that would leave ' || why)); END IF;
  UPDATE drops.drafts SET original = coalesce(original, draft), draft = nd, edits = edits + 1, edited_ms = drops.now_ms()
  WHERE drop_id = d.id RETURNING * INTO x;
  RETURN drops.r(200, drops.draft_json(x));
END $_$;


--
-- Name: draft_get(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_get(pubkey text, drop_ text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN d.id IS NULL THEN drops.r(404, '{"error":"not found"}')
    WHEN x.drop_id IS NULL THEN drops.r(200, '{"status":"none"}')
    ELSE drops.r(200, drops.draft_json(x)) END
  FROM (SELECT 1) one LEFT JOIN drops.drops d ON d.id = drop_ AND d.owner = pubkey
  LEFT JOIN drops.drafts x ON x.drop_id = d.id $$;


--
-- Name: draft_invalid(jsonb); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_invalid(d jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE m jsonb; t jsonb;
BEGIN
  IF jsonb_typeof(d) <> 'object' THEN RETURN 'not an object'; END IF;
  IF d ? 'grow' THEN RETURN drops.grow_invalid(d); END IF;
  IF coalesce(d#>>'{card,name}', '') = '' THEN RETURN 'no name'; END IF;
  IF jsonb_typeof(d#>'{roadmap,milestones}') <> 'array' OR jsonb_array_length(d#>'{roadmap,milestones}') = 0 THEN RETURN 'no milestones'; END IF;
  FOR m IN SELECT * FROM jsonb_array_elements(d#>'{roadmap,milestones}') LOOP
    IF jsonb_typeof(m->'tasks') <> 'array' OR jsonb_array_length(m->'tasks') = 0 THEN RETURN 'a milestone without tasks'; END IF;
    FOR t IN SELECT * FROM jsonb_array_elements(m->'tasks') LOOP
      IF coalesce(t->>'title', '') = '' THEN RETURN 'a task without a title'; END IF;
      IF jsonb_typeof(t->'acceptance') <> 'array' OR jsonb_array_length(t->'acceptance') = 0 THEN RETURN 'a task without acceptance checks'; END IF;
    END LOOP;
  END LOOP;
  RETURN NULL;
END $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: drafts; Type: TABLE; Schema: drops; Owner: -
--

CREATE TABLE drops.drafts (
    drop_id text NOT NULL,
    status text NOT NULL,
    draft jsonb,
    note text DEFAULT ''::text NOT NULL,
    model text,
    started_ms bigint NOT NULL,
    done_ms bigint,
    took_ms integer,
    original jsonb,
    edits integer DEFAULT 0 NOT NULL,
    edited_ms bigint,
    approved_ms bigint,
    CONSTRAINT drafts_status_check CHECK ((status = ANY (ARRAY['reading'::text, 'ready'::text, 'failed'::text])))
);


--
-- Name: draft_json(drops.drafts); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_json(x drops.drafts) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('status', x.status, 'note', x.note, 'model', x.model, 'took_ms', x.took_ms, 'draft', x.draft,
    'edits', x.edits, 'approved', x.approved_ms IS NOT NULL) $$;


--
-- Name: draft_prompt(); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_prompt() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT
'You set up a new project on openagents.com from what its owner dropped: design notes, voice memos, concept art, '
'models, textures, sounds and documents. People and agents will build the project from what you write, so it must '
'be complete and faithful.

Write:
- card: the project''s name, a slug (lowercase words joined by dashes), one line about it, the owner as the drop '
'names them (else empty), the dropped image that best serves as the cover (its file name, else empty), and the art '
'direction in a few sentences.
- mechanics: every mechanic, feature, rule and look the drop describes, one item each, in the owner''s own words. '
'Miss none: a reader should find every idea from the drop here.
- design.markdown: the design document, in the owner''s words and order, as Markdown. Keep their phrasing; add '
'nothing they did not say. design.open_questions: what the drop leaves unclear or undecided, as questions to the owner.
- roadmap: one initiative and its milestones, in the order to build them, each with tasks. Every mechanic is built '
'by at least one task, and each task lists the mechanics it builds. Each task has a short body, a size (S, M or L) '
'and acceptance checks a reviewer could run: concrete steps and what they should see ("Open the realm on a phone, '
'press play: you stand in the cemetery at night, lit by moonlight"), never "works well".
- assets: each dropped file, its kind, its licence ("unknown: ask the owner" unless the drop says), and its use.
- to_make: the assets the design needs that the drop does not have yet.
- engine_needs: what the design needs from the Verse engine that it does not have today. Reuse an existing engine '
'task when it covers the need (reuses true, its slug); otherwise propose a new one (reuses false, a new verse- slug, '
'a body and acceptance checks). The tasks that wait on a need list it in needs as verse:<slug>.

' || drops.engine_has() || '

The Verse engine''s planned upgrades (slug: title. what):
' || (SELECT string_agg(slug || ': ' || title || '. ' || what, E'\n' ORDER BY slug) FROM drops.engine_tasks) $$;


--
-- Name: draft_request(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_request(drop_ text, bucket text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text', drops.draft_prompt()))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts',
      jsonb_build_array(jsonb_build_object('text', 'The drop: ' || (SELECT count(*) FROM drops.files WHERE drop_id = drop_ AND status = 'scanned')
        || ' files. Each readable one follows its name. Files listed without content are kept as assets.'))
      || coalesce((SELECT jsonb_agg(p ORDER BY at, k) FROM (
           SELECT f.created_ms AS at, 0 AS k, jsonb_build_object('text', 'File: ' || f.name || ' (' || f.kind || ', ' || f.bytes || ' bytes)'
             || CASE WHEN drops.readable_type(f.ext) IS NULL THEN ', not readable here' ELSE '' END) AS p
           FROM drops.files f WHERE f.drop_id = drop_ AND f.status = 'scanned'
           UNION ALL
           SELECT f.created_ms, 1, jsonb_build_object('fileData', jsonb_build_object('mimeType', drops.readable_type(f.ext),
             'fileUri', 'gs://' || bucket || '/' || f.object))
           FROM drops.files f WHERE f.drop_id = drop_ AND f.status = 'scanned' AND drops.readable_type(f.ext) IS NOT NULL) x), '[]'))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json', 'responseSchema', drops.draft_schema(),
      'temperature', 0.3, 'maxOutputTokens', 32768)) $$;


--
-- Name: draft_schema(); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_schema() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT '{
  "type": "OBJECT",
  "required": ["card", "mechanics", "design", "roadmap", "assets", "to_make", "engine_needs"],
  "properties": {
    "card": {"type": "OBJECT", "required": ["name", "slug", "line", "owner", "cover", "art_direction"], "properties": {
      "name": {"type": "STRING"}, "slug": {"type": "STRING"}, "line": {"type": "STRING"}, "owner": {"type": "STRING"},
      "cover": {"type": "STRING", "description": "the dropped file to use as the cover image, by its name, or empty"},
      "art_direction": {"type": "STRING"}}},
    "design": {"type": "OBJECT", "required": ["markdown", "open_questions"], "properties": {
      "markdown": {"type": "STRING"}, "open_questions": {"type": "ARRAY", "items": {"type": "STRING"}}}},
    "roadmap": {"type": "OBJECT", "required": ["initiative", "milestones"], "properties": {
      "initiative": {"type": "OBJECT", "required": ["slug", "title", "body"], "properties": {
        "slug": {"type": "STRING"}, "title": {"type": "STRING"}, "body": {"type": "STRING"}}},
      "milestones": {"type": "ARRAY", "items": {"type": "OBJECT", "required": ["slug", "title", "body", "tasks"], "properties": {
        "slug": {"type": "STRING"}, "title": {"type": "STRING"}, "body": {"type": "STRING"},
        "tasks": {"type": "ARRAY", "items": {"type": "OBJECT", "required": ["slug", "title", "body", "size", "acceptance", "mechanics", "needs"], "properties": {
          "slug": {"type": "STRING"}, "title": {"type": "STRING"}, "body": {"type": "STRING"},
          "size": {"type": "STRING", "enum": ["S", "M", "L"]},
          "acceptance": {"type": "ARRAY", "items": {"type": "STRING"}},
          "mechanics": {"type": "ARRAY", "items": {"type": "STRING"}, "description": "the design mechanics this task builds, in the owner''s words"},
          "needs": {"type": "ARRAY", "items": {"type": "STRING"}, "description": "engine needs this task waits on, as verse:<slug>"}}}}}}}}},
    "mechanics": {"type": "ARRAY", "items": {"type": "STRING"}, "description": "every mechanic the drop describes, one each, in the owner''s words"},
    "assets": {"type": "ARRAY", "items": {"type": "OBJECT", "required": ["file", "kind", "licence", "use"], "properties": {
      "file": {"type": "STRING"}, "kind": {"type": "STRING"}, "licence": {"type": "STRING"}, "use": {"type": "STRING"}}}},
    "to_make": {"type": "ARRAY", "items": {"type": "STRING"}},
    "engine_needs": {"type": "ARRAY", "items": {"type": "OBJECT", "required": ["slug", "title", "why", "reuses"], "properties": {
      "slug": {"type": "STRING"}, "title": {"type": "STRING"}, "why": {"type": "STRING"},
      "reuses": {"type": "BOOLEAN", "description": "true when slug is an existing Verse engine task"},
      "body": {"type": "STRING"}, "acceptance": {"type": "ARRAY", "items": {"type": "STRING"}}}}}
  }
}'::jsonb $$;


--
-- Name: draft_start(text, text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.draft_start(pubkey text, drop_ text, bucket text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE d drops.drops; cur drops.drafts;
BEGIN
  SELECT * INTO d FROM drops.drops WHERE id = drop_ AND owner = pubkey FOR UPDATE;
  IF d.id IS NULL THEN RETURN drops.r(404, '{"error":"not found"}'); END IF;
  IF d.project IS NOT NULL THEN RETURN drops.r(409, '{"error":"a drop on a project is read with its work"}'); END IF;
  IF d.status <> 'open' THEN RETURN drops.r(409, '{"error":"this drop is closed"}'); END IF;
  IF NOT EXISTS (SELECT 1 FROM drops.files WHERE drop_id = d.id AND status = 'scanned') THEN
    RETURN drops.r(409, '{"error":"nothing kept to read yet"}');
  END IF;
  SELECT * INTO cur FROM drops.drafts WHERE drop_id = d.id;
  IF cur.status = 'reading' AND cur.started_ms > drops.now_ms() - 300000 THEN RETURN drops.r(409, '{"error":"already reading"}'); END IF;
  INSERT INTO drops.drafts (drop_id, status, started_ms) VALUES (d.id, 'reading', drops.now_ms())
  ON CONFLICT (drop_id) DO UPDATE SET status = 'reading', note = '', started_ms = EXCLUDED.started_ms, done_ms = NULL,
    original = NULL, edits = 0, edited_ms = NULL;
  RETURN drops.r(200, '{}') || jsonb_build_object('request', drops.draft_request(d.id, bucket));
END $$;


