--
-- Name: publish_sealed(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.publish_sealed(slug_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT key_sealed FROM drops.projects WHERE slug = slug_ $$;


--
-- Name: publish_sent(text, integer, text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.publish_sent(slug_ text, seq_ integer, id text, ev text) RETURNS boolean
    LANGUAGE sql
    AS $_$
  UPDATE drops.project_items SET event_id = id, event = ev WHERE slug = slug_ AND seq = seq_ AND event_id IS NULL
    AND id ~ '^[0-9a-f]{64}$' RETURNING true $_$;


--
-- Name: publish_step(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.publish_step(slug_ text, step text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE p drops.projects;
BEGIN
  IF step = 'sent' THEN UPDATE drops.projects SET sent_ms = coalesce(sent_ms, drops.now_ms()) WHERE slug = slug_;
  ELSIF step = 'files' THEN UPDATE drops.projects SET files_ms = coalesce(files_ms, drops.now_ms()) WHERE slug = slug_;
  ELSIF step = 'listed' THEN
    UPDATE drops.projects SET published_ms = coalesce(published_ms, drops.now_ms()) WHERE slug = slug_;
  ELSIF step = 'done' THEN
    UPDATE drops.drops SET status = 'published' WHERE id = (SELECT drop_id FROM drops.projects WHERE slug = slug_);
  END IF;
  SELECT * INTO p FROM drops.projects WHERE slug = slug_;
  RETURN jsonb_build_object('sent', p.sent_ms IS NOT NULL, 'files', p.files_ms IS NOT NULL, 'listed', p.published_ms IS NOT NULL);
END $$;


--
-- Name: published_rows(); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.published_rows() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg(concat_ws('|', p.slug, drops.one_line(p.name, 120), drops.one_line(p.line, 400), 'open', 'public',
      (SELECT count(*) FROM drops.project_items i WHERE i.slug = p.slug AND i.item_kind = 'task'),
      (SELECT count(*) FROM drops.project_items i WHERE i.slug = p.slug AND i.item_kind = 'task'), 0, '',
      lpad((p.published_ms / 1000)::text, 10, '0'),
      to_char(to_timestamp(p.published_ms / 1000.0) AT TIME ZONE 'America/Chicago', 'MM-DD HH24:MI'),
      '/projects/' || p.slug, p.pubkey, p.owner) || E'\n', '' ORDER BY p.published_ms DESC), '')
  FROM drops.projects p WHERE p.published_ms IS NOT NULL AND p.visibility = 'public' $$;


--
-- Name: published_slugs(); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.published_slugs() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg(slug || E'\n', '' ORDER BY slug), '') FROM drops.projects WHERE published_ms IS NOT NULL $$;


--
-- Name: r(integer, jsonb); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.r(status integer, body jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT jsonb_build_object('status', status, 'body', body) $$;


--
-- Name: readable_type(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.readable_type(ext text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN ext IN ('txt', 'md', 'markdown', 'csv', 'json', 'svg', 'gltf', 'obj', 'mtl') THEN 'text/plain'
    WHEN ext = 'pdf' THEN 'application/pdf'
    WHEN ext = 'png' THEN 'image/png' WHEN ext IN ('jpg', 'jpeg') THEN 'image/jpeg' WHEN ext = 'webp' THEN 'image/webp'
    WHEN ext = 'heic' THEN 'image/heic'
    WHEN ext = 'mp3' THEN 'audio/mp3' WHEN ext = 'wav' THEN 'audio/wav' WHEN ext = 'aac' THEN 'audio/aac'
    WHEN ext = 'ogg' THEN 'audio/ogg' WHEN ext = 'flac' THEN 'audio/flac' WHEN ext = 'm4a' THEN 'audio/mp4'
    WHEN ext = 'mp4' THEN 'video/mp4' WHEN ext = 'mov' THEN 'video/quicktime'
  END $$;


--
-- Name: realm_done(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.realm_done(slug_ text, note text) RETURNS boolean
    LANGUAGE sql
    AS $$
  UPDATE drops.projects SET realm_ms = coalesce(realm_ms, drops.now_ms()), realm_note = nullif(drops.one_line(note, 1000), '')
  WHERE slug = slug_ RETURNING true $$;


--
-- Name: realm_md(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.realm_md(slug_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT replace(drops.realm_md_0110(slug_), 'first realm', 'first world') $$;


--
-- Name: realm_md_0110(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.realm_md_0110(slug_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '# ' || p.name || E': a first realm\n\n'
    || 'The 3D models dropped for [' || p.name || '](/projects/' || p.slug || E'), stood on an empty floor so the project has somewhere to walk on day one. '
    || E'You carry a lamp among them: W and S walk, A and D turn, a drag turns; on a phone a thumb drags to walk and turn.\n\n'
    || coalesce(E'## Standing here\n\n' || (SELECT string_agg('- ' || m.file || ' (' || m.licence || ')', E'\n') FROM drops.realm_models(p.slug) m) || E'\n\n', '')
    || coalesce(E'## Not placed\n\n' || p.realm_note || E'\n\n', '')
    || E'Without WebGPU (a current Chrome, Edge or Safari) the page shows only its name and a link here.\n'
  FROM drops.projects p WHERE p.slug = slug_ $$;


--
-- Name: realm_models(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.realm_models(slug_ text) RETURNS TABLE(object text, file text, mesh text, licence text)
    LANGUAGE sql STABLE
    AS $_$
  SELECT f.object, drops.one_line(f.name, 60),
         left(coalesce(nullif(trim(BOTH '-' FROM regexp_replace(regexp_replace(f.name, '\.[^.]*$', ''), '[^A-Za-z0-9_-]+', '-', 'g')), ''), 'model'), 31),
         coalesce(nullif(drops.one_line((SELECT a->>'licence' FROM jsonb_array_elements(coalesce(x.draft->'assets', '[]')) a
                                         WHERE a->>'file' = f.name LIMIT 1), 60), ''), 'licence unknown: ask the owner')
  FROM drops.projects p JOIN drops.files f ON f.drop_id = p.drop_id AND f.status = 'scanned' AND f.ext = 'glb'
  LEFT JOIN drops.drafts x ON x.drop_id = p.drop_id
  WHERE p.slug = slug_ ORDER BY f.created_ms, f.id LIMIT 24 $_$;


--
-- Name: realm_page(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.realm_page(slug_ text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT replace(replace(drops.realm_page_0110(slug_, origin), 'first realm', 'first world'), '"/realms/drop"', '"/worlds/drop"') $$;


--
-- Name: realm_page_0110(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.realm_page_0110(slug_ text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>' || drops.html(p.name) || ' · a first realm · OpenAgents</title>
<meta name="description" content="' || drops.html(p.line) || '">
' || drops.preview(slug_, p.name || ': a first realm', '/projects/' || p.slug || '/realm', origin) || '<meta name="theme-color" content="#000000">
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="alternate" type="text/markdown" href="/projects/' || p.slug || '/realm/index.md">
<script>if ("gpu" in navigator) document.documentElement.classList.add("gpu")</script>
<style>
html,body{margin:0;height:100%;background:#000;color:#ededed}
body{overflow:hidden;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:14px;line-height:1.5}
canvas{position:fixed;inset:0;width:100%;height:100%;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
canvas[data-cursor=pointer]{cursor:pointer}
main{position:relative;max-width:640px;margin:0 auto;padding:24px 16px}
html:not(.gpu) body{overflow:auto}
a{color:#ff8c1f}
.gpu main{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;padding:0}
</style>
</head>
<body>
<canvas id="coaxial" aria-hidden="true"></canvas>
<main>
<h1>' || drops.html(p.name) || '</h1>
<p><a href="/projects/' || p.slug || '/realm/index.md">A first realm</a></p>
</main>
<script type="module" data-realm-of="' || p.slug || '" data-name="' || drops.html(p.name) || '">
const me = document.querySelector("script[data-realm-of]"), slug = me.dataset.realmOf;
const t = await (await fetch("/realms/drop", { cache: "no-store" })).text();
const from = new DOMParser().parseFromString(t, "text/html").querySelector("script[data-app]");
const s = document.createElement("script");
for (const a of from.attributes) s.setAttribute(a.name, a.value);
s.dataset.realm = slug; s.dataset.slot = "project-" + slug;
s.dataset.assets = "pack:/projects/" + slug + "/realm/realm.pack";
s.dataset.text = me.dataset.name + "\n/projects/" + slug;
document.body.append(s);
</script>
</body>
</html>
' FROM drops.projects p WHERE p.slug = slug_ $$;


