CREATE FUNCTION drops.repo() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT '{
  "d": "openagents", "name": "OpenAgents", "description": "The OpenAgents monorepo: the apps, the protocol, Coax and the Grid.",
  "web": "https://github.com/OpenAgentsInc/openagents", "clone": "https://github.com/OpenAgentsInc/openagents.git",
  "euc": "0aa2d953dd48f0d402ea7c826bad90b2548524c2", "relay": "wss://relay.openagents.com"}'::jsonb $$;


--
-- Name: scan(text, bigint, text, bytea); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.scan(file_ text, size bigint, md5_ text, head bytea) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE f drops.files; why text;
BEGIN
  SELECT * INTO f FROM drops.files WHERE id = file_ FOR UPDATE;
  IF f.status <> 'uploading' THEN RETURN drops.r(200, jsonb_build_object('file', drops.file_json(f))); END IF;
  IF size < 0 THEN RETURN drops.r(409, '{"error":"the upload isn''t finished"}'); END IF;
  why := CASE WHEN size <> f.bytes THEN 'it arrived at a different size' ELSE drops.sniff(f.ext, head) END;
  UPDATE drops.files SET status = CASE WHEN why IS NULL THEN 'scanned' ELSE 'refused' END, note = coalesce(why, ''),
    md5 = md5_, session = NULL, done_ms = drops.now_ms() WHERE id = file_ RETURNING * INTO f;
  RETURN drops.r(200, jsonb_build_object('file', drops.file_json(f))) || jsonb_build_object('delete', why IS NOT NULL);
END $$;


--
-- Name: slug(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.slug(s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(trim(BOTH '-' FROM regexp_replace(lower(coalesce(s, '')), '[^a-z0-9]+', '-', 'g')), 48) $$;


--
-- Name: slug_taken(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.slug_taken(s text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT s IN ('coax', 'coder', 'dead-gears', 'openagents-desktop', 'planetary-villa', 'private', 'psionic', 'verse',
               'new', 'demo', 'api', 'published', 'list', 'index', 'mine', 'assets')
      OR EXISTS (SELECT 1 FROM projects.docs WHERE slug = s)
      OR EXISTS (SELECT 1 FROM drops.projects WHERE slug = s) $$;


--
-- Name: sniff(text, bytea); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.sniff(ext text, head bytea) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE ftyp bool := drops.at(head, 4, '66747970');   -- "ftyp" at 4: MP4, MOV, M4A, AVIF, HEIC
BEGIN
  IF length(head) = 0 THEN RETURN 'it is empty'; END IF;
  IF drops.at(head, 0, '4d5a') OR drops.at(head, 0, '7f454c46') OR drops.at(head, 0, '2321')
     OR drops.at(head, 0, 'feedface') OR drops.at(head, 0, 'feedfacf') OR drops.at(head, 0, 'cefaedfe')
     OR drops.at(head, 0, 'cffaedfe') OR drops.at(head, 0, 'cafebabe') OR drops.at(head, 0, '0061736d') THEN
    RETURN 'it is a program';
  END IF;
  RETURN CASE
    WHEN ext IN ('txt', 'md', 'markdown', 'csv', 'json', 'obj', 'mtl', 'gltf') THEN
      CASE WHEN drops.texty(head) THEN NULL ELSE 'it is not text' END
    WHEN ext = 'svg' THEN
      CASE WHEN drops.texty(head) AND position('\x3c737667'::bytea IN head) > 0 THEN NULL ELSE 'it is not an SVG' END
    WHEN ext = 'rtf' THEN CASE WHEN drops.at(head, 0, '7b5c727466') THEN NULL ELSE 'it is not RTF' END
    WHEN ext = 'pdf' THEN CASE WHEN drops.at(head, 0, '255044462d') THEN NULL ELSE 'it is not a PDF' END
    WHEN ext IN ('docx', 'odt', 'zip', 'usdz') THEN CASE WHEN drops.at(head, 0, '504b0304') THEN NULL ELSE 'it is not a zip' END
    WHEN ext = 'png' THEN CASE WHEN drops.at(head, 0, '89504e470d0a1a0a') THEN NULL ELSE 'it is not a PNG' END
    WHEN ext IN ('jpg', 'jpeg') THEN CASE WHEN drops.at(head, 0, 'ffd8ff') THEN NULL ELSE 'it is not a JPEG' END
    WHEN ext = 'gif' THEN CASE WHEN drops.at(head, 0, '474946383761') OR drops.at(head, 0, '474946383961') THEN NULL ELSE 'it is not a GIF' END
    WHEN ext = 'webp' THEN CASE WHEN drops.at(head, 0, '52494646') AND drops.at(head, 8, '57454250') THEN NULL ELSE 'it is not a WebP' END
    WHEN ext IN ('avif', 'heic', 'mp4', 'm4a') THEN CASE WHEN ftyp THEN NULL ELSE 'it is not an MP4 family file' END
    WHEN ext = 'mov' THEN CASE WHEN ftyp OR drops.at(head, 4, '6d6f6f76') OR drops.at(head, 4, '77696465') OR drops.at(head, 4, '6d646174')
                               THEN NULL ELSE 'it is not a QuickTime movie' END
    WHEN ext = 'wav' THEN CASE WHEN drops.at(head, 0, '52494646') AND drops.at(head, 8, '57415645') THEN NULL ELSE 'it is not a WAV' END
    WHEN ext = 'mp3' THEN CASE WHEN drops.at(head, 0, '494433') OR (get_byte(head, 0) = 255 AND length(head) > 1 AND get_byte(head, 1) >= 224)
                               THEN NULL ELSE 'it is not an MP3' END
    WHEN ext = 'aac' THEN CASE WHEN ftyp OR drops.at(head, 0, 'fff1') OR drops.at(head, 0, 'fff9') THEN NULL ELSE 'it is not AAC' END
    WHEN ext IN ('ogg', 'opus') THEN CASE WHEN drops.at(head, 0, '4f676753') THEN NULL ELSE 'it is not Ogg' END
    WHEN ext = 'flac' THEN CASE WHEN drops.at(head, 0, '664c6143') THEN NULL ELSE 'it is not FLAC' END
    WHEN ext = 'webm' THEN CASE WHEN drops.at(head, 0, '1a45dfa3') THEN NULL ELSE 'it is not WebM' END
    WHEN ext = 'glb' THEN CASE WHEN drops.at(head, 0, '676c5446') THEN NULL ELSE 'it is not a binary glTF' END
    WHEN ext = 'fbx' THEN CASE WHEN drops.at(head, 0, '4b617964617261204642582042696e617279') OR drops.texty(head) THEN NULL ELSE 'it is not FBX' END
    WHEN ext = 'ply' THEN CASE WHEN drops.at(head, 0, '706c79') THEN NULL ELSE 'it is not PLY' END
    WHEN ext = 'blend' THEN CASE WHEN drops.at(head, 0, '424c454e444552') THEN NULL ELSE 'it is not a Blender file' END
    WHEN ext = 'ktx2' THEN CASE WHEN drops.at(head, 0, 'ab4b5458203230bb0d0a1a0a') THEN NULL ELSE 'it is not KTX2' END
    WHEN ext = 'exr' THEN CASE WHEN drops.at(head, 0, '762f3101') THEN NULL ELSE 'it is not OpenEXR' END
    WHEN ext = 'hdr' THEN CASE WHEN drops.at(head, 0, '233f') THEN NULL ELSE 'it is not Radiance HDR' END
    WHEN ext IN ('stl', 'bin', 'tga') THEN NULL   -- no magic of their own; a program was refused above
    ELSE 'we don''t take this kind of file'
  END;
END $$;


--
-- Name: started(text, text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.started(file_ text, session_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE f drops.files;
BEGIN
  IF session_ IS NULL OR session_ = '' THEN
    UPDATE drops.files SET status = 'refused', note = 'storage was unavailable; drop it again', done_ms = drops.now_ms() WHERE id = file_;
    RETURN drops.r(503, '{"error":"storage was unavailable; drop it again"}');
  END IF;
  UPDATE drops.files SET status = 'uploading', session = session_ WHERE id = file_ RETURNING * INTO f;
  RETURN drops.r(200, jsonb_build_object('file', drops.file_json(f), 'upload', session_));
END $$;


--
-- Name: tag(text[]); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.tag(VARIADIC v text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT '[' || string_agg(drops.j(x), ',' ORDER BY k) || ']' FROM unnest(v) WITH ORDINALITY AS t(x, k) $$;


--
-- Name: texty(bytea); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.texty(b bytea) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE n int := length(b); k int := 0;
BEGIN
  IF position('\x00'::bytea IN b) > 0 THEN RETURN false; END IF;
  WHILE k < 4 AND n - k > 0 LOOP   -- a cut character at the end is no fault
    BEGIN
      PERFORM convert_from(substring(b FROM 1 FOR n - k), 'UTF8');
      RETURN true;
    EXCEPTION WHEN others THEN k := k + 1;
    END;
  END LOOP;
  RETURN n = 0;
END $$;


--
-- Name: used(text); Type: FUNCTION; Schema: drops; Owner: -
--

CREATE FUNCTION drops.used(pubkey text) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(sum(f.bytes), 0)::bigint FROM drops.files f JOIN drops.drops d ON d.id = f.drop_id
  WHERE d.owner = pubkey AND d.status = 'open' AND f.status <> 'refused' $$;


--
-- Name: begin(jsonb, text, bigint); Type: FUNCTION; Schema: email; Owner: -
--

CREATE FUNCTION email.begin(m jsonb, allow text, now_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  rcpt jsonb := CASE jsonb_typeof(m->'to') WHEN 'string' THEN jsonb_build_array(m->'to') WHEN 'array' THEN m->'to' ELSE NULL END;
  atts jsonb := coalesce(m->'attachments', '[]'::jsonb);
  k text := m->>'idempotency_key';
  h text;
  prior email.sends;
  bad text;
BEGIN
  IF rcpt IS NULL OR jsonb_array_length(rcpt) NOT BETWEEN 1 AND 50 THEN RETURN jsonb_build_object('state', 'refused', 'error', 'to: one to fifty addresses'); END IF;
  SELECT x INTO bad FROM jsonb_array_elements_text(rcpt) x WHERE x !~ '^[^@\s<>,"]+@[^@\s<>,"]+\.[^@\s<>,"]+$' LIMIT 1;
  IF FOUND THEN RETURN jsonb_build_object('state', 'refused', 'error', 'to: not an address'); END IF;
  IF allow <> '' THEN
    SELECT x INTO bad FROM jsonb_array_elements_text(rcpt) x
      WHERE lower(x) NOT IN (SELECT lower(trim(a)) FROM unnest(string_to_array(allow, ',')) a) LIMIT 1;
    IF FOUND THEN RETURN jsonb_build_object('state', 'refused', 'error', 'to: not on this service''s allowlist'); END IF;
  END IF;
  IF coalesce(m->>'subject', '') = '' OR length(m->>'subject') > 200 THEN RETURN jsonb_build_object('state', 'refused', 'error', 'subject: one to 200 characters'); END IF;
  IF coalesce(m->>'text', '') = '' THEN RETURN jsonb_build_object('state', 'refused', 'error', 'text: a plain-text body is required'); END IF;
  IF k IS NULL OR length(k) NOT BETWEEN 8 AND 256 THEN RETURN jsonb_build_object('state', 'refused', 'error', 'idempotency_key: 8 to 256 characters'); END IF;
  IF jsonb_typeof(atts) <> 'array' OR jsonb_array_length(atts) > 10
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(atts) a WHERE coalesce(a->>'filename', '') !~ '^[A-Za-z0-9._ -]{1,100}$'
                                                              OR coalesce(a->>'content', '') !~ '^[A-Za-z0-9+/]+=*$') THEN
    RETURN jsonb_build_object('state', 'refused', 'error', 'attachments: up to ten, each a filename and base64 content');
  END IF;
  h := encode(sha256(convert_to(k, 'UTF8')), 'hex');
  INSERT INTO email.sends (key_sha256, recipients, attachments, state, created_ms, updated_ms)
    VALUES (h, jsonb_array_length(rcpt), jsonb_array_length(atts), 'sending', now_ms, now_ms)
    ON CONFLICT (key_sha256) DO NOTHING;
  IF NOT FOUND THEN
    SELECT * INTO prior FROM email.sends WHERE key_sha256 = h FOR UPDATE;
    IF prior.state = 'sent' THEN RETURN jsonb_build_object('state', 'sent', 'id', prior.resend_id, 'key', h); END IF;
    IF prior.state = 'sending' AND prior.updated_ms > now_ms - 120000 THEN
      RETURN jsonb_build_object('state', 'refused', 'error', 'this message is being sent now');
    END IF;
    UPDATE email.sends SET state = 'sending', updated_ms = now_ms WHERE key_sha256 = h;   -- a failed or stalled send goes again (Resend dedupes the key too)
  END IF;
  RETURN jsonb_build_object('state', 'send', 'key', h, 'payload', jsonb_strip_nulls(jsonb_build_object(
    'from', 'OpenAgents <no-reply@openagents.com>',
    'to', rcpt,
    'subject', m->>'subject',
    'text', m->>'text',
    'html', m->>'html',
    'headers', jsonb_build_object('List-Unsubscribe', coalesce(m->>'unsubscribe', '<mailto:no-reply@openagents.com?subject=unsubscribe>')),
    'attachments', CASE WHEN jsonb_array_length(atts) > 0 THEN
      (SELECT jsonb_agg(jsonb_build_object('filename', a->>'filename', 'content', a->>'content')) FROM jsonb_array_elements(atts) a) END)));
END $_$;


--
-- Name: finish(text, boolean, integer, integer, text, bigint); Type: FUNCTION; Schema: email; Owner: -
--

CREATE FUNCTION email.finish(h text, ok boolean, tries integer, status integer, id text, now_ms bigint) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE email.sends SET state = CASE WHEN ok THEN 'sent' ELSE 'failed' END, attempts = attempts + tries,
                         http_status = status, resend_id = id, updated_ms = now_ms
   WHERE key_sha256 = h
$$;


