-- Name: no(); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.no() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT projects.r(404, '{"error":"not found"}') $$;


--
-- Name: now_ms(); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.now_ms() RETURNS bigint
    LANGUAGE sql
    AS $$ SELECT floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint $$;


--
-- Name: numbers(); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.numbers() RETURNS TABLE(label text, today bigint, week bigint)
    LANGUAGE sql STABLE
    AS $_$
  WITH b AS (SELECT (extract(epoch FROM (date_trunc('day', now() AT TIME ZONE 'America/Chicago') AT TIME ZONE 'America/Chicago')) * 1000)::bigint AS today,
                    (extract(epoch FROM ((date_trunc('day', now() AT TIME ZONE 'America/Chicago') - interval '6 days') AT TIME ZONE 'America/Chicago')) * 1000)::bigint AS week),
  s AS (SELECT sid, min(ms) AS first_ms, bool_or(auto IS NOT NULL OR (ev = 'session-start' AND p ? 'agent')) AS automated
        FROM analytics.events, b WHERE ms >= b.week AND space = 'web' GROUP BY sid),
  k AS (SELECT sid, first_ms >= (SELECT today FROM b) AS t FROM s WHERE NOT automated),
  e AS (SELECT x.sid, x.ev, x.p, k.t FROM analytics.events x JOIN k USING (sid) WHERE x.ms >= (SELECT week FROM b)),
  q AS (SELECT sid, bool_or(t) AS t, max(CASE WHEN p->>'step' ~ '^[0-9]{1,2}$' THEN (p->>'step')::int ELSE 0 END) AS step
        FROM e WHERE ev = 'quest' GROUP BY sid)
  SELECT 'Sessions', count(*) FILTER (WHERE t), count(*) FROM k
  UNION ALL SELECT 'Visitors', count(DISTINCT p->>'pid') FILTER (WHERE t), count(DISTINCT p->>'pid') FROM e WHERE ev = 'session-start'
  UNION ALL SELECT 'Entered the Haunted House', count(DISTINCT sid) FILTER (WHERE t), count(DISTINCT sid) FROM e
            WHERE ev = 'world-enter' AND p->>'world' = 'haunted-house'
  UNION ALL SELECT * FROM (SELECT 'Quest step ' || n || CASE WHEN n = 8 THEN ' (done)' ELSE '' END,
                                  count(q.sid) FILTER (WHERE q.t), count(q.sid)
                           FROM generate_series(1, 8) n LEFT JOIN q ON q.step >= n GROUP BY n ORDER BY n) f
$_$;


--
-- Name: patch_apply(jsonb, jsonb); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.patch_apply(doc jsonb, ops jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  o jsonb; p text[]; f text[]; parent text[]; last text; v jsonb; holder jsonb; n int := 0;
BEGIN
  IF jsonb_typeof(ops) <> 'array' OR jsonb_array_length(ops) = 0 OR jsonb_array_length(ops) > 50 THEN
    RETURN '{"error":"ops is a list of 1 to 50 operations"}';
  END IF;
  FOR o IN SELECT * FROM jsonb_array_elements(ops) LOOP
    n := n + 1;
    p := projects.pointer(o->>'path');
    IF p IS NULL OR cardinality(p) = 0 THEN RETURN jsonb_build_object('error', 'operation ' || n || ': path is a JSON pointer inside the document, like /days/0/milestones/1/text'); END IF;
    parent := p[1:cardinality(p) - 1]; last := p[cardinality(p)];
    holder := CASE WHEN cardinality(parent) = 0 THEN doc ELSE doc #> parent END;
    IF o->>'op' = 'move' THEN
      f := projects.pointer(o->>'from');
      IF f IS NULL OR doc #> f IS NULL THEN RETURN jsonb_build_object('error', 'operation ' || n || ': nothing at from'); END IF;
      v := doc #> f; doc := doc #- f;
      holder := CASE WHEN cardinality(parent) = 0 THEN doc ELSE doc #> parent END;
      o := jsonb_build_object('op', 'add', 'path', o->'path', 'value', v);
    END IF;
    IF o->>'op' = 'test' THEN
      IF doc #> p IS DISTINCT FROM o->'value' THEN RETURN jsonb_build_object('error', 'operation ' || n || ': test failed: the document is not what you read'); END IF;
    ELSIF o->>'op' = 'remove' THEN
      IF doc #> p IS NULL THEN RETURN jsonb_build_object('error', 'operation ' || n || ': nothing at path'); END IF;
      doc := doc #- p;
    ELSIF o->>'op' = 'replace' THEN
      IF doc #> p IS NULL OR NOT o ? 'value' THEN RETURN jsonb_build_object('error', 'operation ' || n || ': replace needs a value at an existing path'); END IF;
      doc := jsonb_set(doc, p, o->'value', false);
    ELSIF o->>'op' = 'add' THEN
      IF holder IS NULL OR NOT o ? 'value' THEN RETURN jsonb_build_object('error', 'operation ' || n || ': add needs a value and an existing parent'); END IF;
      IF jsonb_typeof(holder) = 'array' THEN
        IF last = '-' OR last = jsonb_array_length(holder)::text THEN
          doc := CASE WHEN cardinality(parent) = 0 THEN doc || jsonb_build_array(o->'value')
                 ELSE jsonb_set(doc, parent, holder || jsonb_build_array(o->'value'), false) END;
        ELSIF last ~ '^[0-9]{1,6}$' AND last::int < jsonb_array_length(holder) THEN
          doc := jsonb_insert(doc, p, o->'value', false);
        ELSE RETURN jsonb_build_object('error', 'operation ' || n || ': index out of range'); END IF;
      ELSIF jsonb_typeof(holder) = 'object' THEN
        doc := jsonb_set(doc, p, o->'value', true);
      ELSE RETURN jsonb_build_object('error', 'operation ' || n || ': the parent is not a list or an object'); END IF;
    ELSE
      RETURN jsonb_build_object('error', 'operation ' || n || ': op is add, remove, replace, move or test');
    END IF;
  END LOOP;
  RETURN jsonb_build_object('doc', doc);
END $_$;


--
-- Name: pointer(text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.pointer(p text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p IS NULL OR left(p, 1) <> '/' THEN NULL
    ELSE (SELECT array_agg(replace(replace(x, '~1', '/'), '~0', '~') ORDER BY o) FROM unnest(string_to_array(substr(p, 2), '/')) WITH ORDINALITY AS u(x, o)) END
$$;


--
-- Name: r(integer, jsonb); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.r(status integer, body jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT jsonb_build_object('status', status, 'body', body) $$;


--
-- Name: record_edit(text, bigint, jsonb, jsonb, text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.record_edit(want text, turn_id bigint, before jsonb, after jsonb, op text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO projects.events (slug, turn, at_ms, type, data)
  SELECT want, turn_id, projects.now_ms(), 'agent.edit', jsonb_build_object('op', op, 'line', l)
  FROM (SELECT l FROM jsonb_array_elements_text(projects.diff(before, after)) l
        UNION ALL SELECT 'no visible change' WHERE projects.diff(before, after) = '[]') z(l)
$$;


--
-- Name: role(text, text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.role(want text, pk text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM projects.docs d, jsonb_array_elements(d.doc->'members') m WHERE d.slug = want AND m->>'pubkey' = pk) THEN 'member'
    ELSE coalesce((SELECT a.role FROM projects.agents a JOIN projects.docs d USING (slug) WHERE a.slug = want AND a.pubkey = pk), '') END
$$;


--
-- Name: session(text, text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.session(want text, token text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT s.pubkey FROM projects.sessions s
  WHERE s.token_sha256 = projects.sha(coalesce(token, '')) AND s.slug = want AND s.expires_ms > projects.now_ms()
    AND projects.role(want, s.pubkey) = 'member'
$$;


--
-- Name: sha(text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.sha(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT encode(sha256(convert_to(t, 'UTF8')), 'hex') $$;


--
-- Name: spent(text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.spent(want text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(sum(cost_usd), 0) FROM projects.turns
  WHERE slug = want AND credential <> 'own'
    AND asked_ms >= (extract(epoch FROM (date_trunc('day', now() AT TIME ZONE 'America/Chicago') AT TIME ZONE 'America/Chicago')) * 1000)::bigint
$$;


--
-- Name: state(text, text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.state(want text, pk text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'slug', d.slug, 'version', d.version, 'updated_at', projects.chi(d.updated_ms), 'updated_by', projects.name_of(d.slug, d.updated_by),
    'you', jsonb_build_object('name', projects.name_of(want, pk), 'role', projects.role(want, pk)),
    'today', to_char(now() AT TIME ZONE 'America/Chicago', 'YYYY-MM-DD'),
    'doc', d.doc,
    'agents', (SELECT coalesce(jsonb_agg(jsonb_build_object('name', name, 'pubkey', pubkey, 'role', role) ORDER BY added_ms), '[]') FROM projects.agents WHERE slug = want),
    'activity', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', id, 'at', projects.chi(at_ms), 'by', by_name, 'kind', kind, 'text', text) ORDER BY at_ms DESC), '[]')
                 FROM (SELECT * FROM projects.activity WHERE slug = want ORDER BY at_ms DESC LIMIT 50) a),
    'messages', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', id, 'at', projects.chi(at_ms), 'from', from_name, 'text', text, 'reply_to', reply_to) ORDER BY at_ms), '[]')
                 FROM (SELECT * FROM projects.messages WHERE slug = want ORDER BY at_ms DESC LIMIT 50) m),
    'analytics', (SELECT jsonb_agg(jsonb_build_object('label', label, 'today', today, 'week', week)) FROM projects.numbers()))
  FROM projects.docs d WHERE d.slug = want
$$;


--
-- Name: talk_json(text, numeric); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.talk_json(want text, cap numeric) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('spent', projects.spent(want), 'cap', cap,
    'turns', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'kind', t.kind, 'status', t.status, 'at', projects.chi(t.asked_ms), 'by', t.by_name,
                'text', t.text, 'answer', t.answer, 'error', t.error, 'commit', t.commit_sha, 'files', t.files, 'cost_usd', t.cost_usd,
                'version_before', t.version_before, 'version_after', t.version_after, 'undo_of', t.undo_of, 'undone_by', t.undone_by,
                'events', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'type', e.type, 'data', e.data) ORDER BY e.id), '[]') FROM projects.events e WHERE e.turn = t.id))
              ORDER BY t.id), '[]') FROM (SELECT * FROM projects.turns WHERE slug = want ORDER BY id DESC LIMIT 20) t))
$$;


--
-- Name: talk_lines(text, numeric); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.talk_lines(want text, cap numeric) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH d AS (SELECT * FROM projects.docs WHERE slug = want),
  t AS (SELECT * FROM (SELECT * FROM projects.turns WHERE slug = want ORDER BY id DESC LIMIT 20) x)
  SELECT string_agg(line, E'\n' ORDER BY o1, o2) || E'\n' FROM (
    SELECT 0 AS o1, 0::bigint AS o2, 'Z|' || to_char(projects.spent(want), 'FM9990.00') || '|' || to_char(cap, 'FM9990.00') || '|'
         || CASE WHEN EXISTS (SELECT 1 FROM projects.turns WHERE slug = want AND status IN ('queued', 'running')) THEN '1' ELSE '0' END
         || '|' || (SELECT jsonb_array_length(doc->'members') FROM d) AS line
    UNION ALL SELECT 0, i, 'G|' || projects.v(g->>'id') || '|' || coalesce(projects.v((SELECT string_agg(m->>'name', ', ' ORDER BY o)
           FROM jsonb_array_elements(d.doc->'members') WITH ORDINALITY AS mm(m, o) JOIN projects.agreements a
             ON a.slug = want AND a.goal = g->>'id' AND a.goal_text = g->>'text' AND a.pubkey = m->>'pubkey')), '')
      FROM d, jsonb_array_elements(coalesce(d.doc->'goals', '[]')) WITH ORDINALITY AS z(g, i) WHERE g->>'status' = 'proposed'
    UNION ALL SELECT 1, t.id * 1000, 'U|' || t.id || '|' || t.kind || '|' || t.status || '|' || projects.chi(t.asked_ms) || '|' || projects.v(t.by_name) || '|'
         || projects.v(left(t.text, 1500)) || '|' || projects.v(left(t.answer, 3000)) || '|' || projects.v(t.error) || '|' || coalesce(left(t.commit_sha, 7), '') || '|'
         || jsonb_array_length(t.files) || '|' || CASE WHEN projects.undoable(t.kind, t.status, t.undone_by, t.commit_sha, t.version_after, (SELECT version FROM d)) THEN '1' ELSE '0' END || '|'
         || coalesce(t.undone_by::text, '') || '|' || projects.v(t.working) || '|' || coalesce(t.undo_of::text, '') || '|' || t.credential
      FROM t
    UNION ALL SELECT 1, e.turn * 1000 + 1 + row_number() OVER (PARTITION BY e.turn ORDER BY e.id),
         'E|' || e.turn || '|' || e.id || '|' || e.type || '|' || projects.v(left(projects.event_text(e.type, e.data), 300))
      FROM projects.events e WHERE e.turn IN (SELECT id FROM t) AND e.type IN ('agent.edit', 'agent.commit', 'session.error', 'user.interrupt')
  ) all_lines WHERE EXISTS (SELECT 1 FROM d)
$$;


--
-- Name: token(); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.token() RETURNS text
    LANGUAGE sql
    AS $$ SELECT replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '') $$;


--
-- Name: undoable(text, text, bigint, text, integer, integer); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.undoable(kind text, status text, undone_by bigint, commit_sha text, version_after integer, current integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT kind = 'ask' AND status IN ('done', 'failed', 'stopped') AND undone_by IS NULL
     AND (commit_sha IS NOT NULL OR version_after IS NOT NULL)
     AND (version_after IS NULL OR version_after = current)
$$;


--
-- Name: v(text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.v(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT regexp_replace(coalesce(t, ''), '[|\r\n\t]', ' ', 'g') $$;


--
-- Name: with_day(jsonb, text); Type: FUNCTION; Schema: projects; Owner: -
--

CREATE FUNCTION projects.with_day(doc jsonb, day text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(doc->'days', '[]')) d WHERE d->>'date' = day) THEN doc
    ELSE jsonb_set(doc, '{days}', (SELECT jsonb_agg(d ORDER BY d->>'date') FROM jsonb_array_elements(
           coalesce(doc->'days', '[]') || jsonb_build_array(jsonb_build_object('date', day, 'milestones', '[]'::jsonb))) d), true) END
$$;


--
-- Name: api(text, text[], jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.api(method text, parts text[], body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  n int := coalesce(array_length(parts, 1), 0);
  route jsonb;
BEGIN
  IF parts[1] IS DISTINCT FROM 'progress' OR n NOT IN (3, 4) THEN RETURN verse.api_0057(method, parts, body, who); END IF;
  IF n = 4 AND (parts[4] <> 'erase' OR method <> 'POST') THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
  route := verse.progress_route(parts, who);
  IF (route->>'status')::int <> 0 THEN RETURN route; END IF;
  IF n = 4 THEN
    UPDATE verse.progress SET cur = NULL, cur_at = NULL, prev = NULL, prev_at = NULL
    WHERE account = route->>'acct' AND slot = route->>'slot';
    RETURN verse.r(200, '{"erased":true}');
  END IF;
  IF method = 'POST' THEN
    IF NOT coalesce((who->>'good')::boolean, false) THEN RETURN verse.r(400, '{"error":"that is not a good progress save"}'); END IF;
    RETURN verse.api_0057(method, parts, body, who);
  END IF;
  RETURN verse.r(200, verse.progress_view(route->>'acct', route->>'slot'));
END $$;


--
-- Name: api_0004(text, text[], jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.api_0004(method text, parts text[], body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
#variable_conflict use_column
DECLARE
  safe text := '^[A-Za-z0-9_-]{1,64}$';
  k text := who->>'key';
  auto text := nullif(who->>'auto', '');
  site boolean := coalesce((who->>'site')::boolean, false);
  npub text := nullif(who->>'npub', '');
  now_s double precision := extract(epoch FROM clock_timestamp());
  n int := coalesce(array_length(parts, 1), 0);
  rec verse.players;
  acct text;
  acct_name text;
  world text := CASE WHEN n >= 2 THEN parts[2] END;
  mine boolean;
  pub verse.published;
  st verse.world_state;
  w verse.worlds;
  who_name text;
  given text;
  email text;
  out jsonb;
  ver int;
  p verse.progress;
  slot_ text;
  at double precision;
BEGIN
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO rec FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  END IF;
  -- A Nostr key that signed: its account, and the sent key linked to it when free.
  IF npub IS NOT NULL THEN
    INSERT INTO verse.accounts (id, npub, created_ms) VALUES ('n-' || npub, npub, verse.now_ms()) ON CONFLICT DO NOTHING;
    acct := 'n-' || npub;
    IF rec.id IS NOT NULL AND rec.account IS NULL THEN
      UPDATE verse.players SET account = acct WHERE id = rec.id;
      rec.account := acct;
    END IF;
  ELSE
    acct := rec.account;
  END IF;
  SELECT name INTO acct_name FROM verse.accounts WHERE id = acct;
  -- The name an edit log shows: the account's, else what a guest typed (a label only).
  given := CASE WHEN jsonb_typeof(body->'user') = 'object' THEN nullif(body->'user'->>'name', '') END;
  who_name := left(coalesce(acct_name, given, 'owner'), 40);
  IF world IS NOT NULL AND parts[1] IN ('world', 'log') AND world !~ safe THEN
    RETURN verse.r(404, '{"error":"unknown"}');
  END IF;
  mine := world IS NOT NULL AND (site OR verse.owns(rec, acct, world));

  -- ---- players and guests
  IF parts = ARRAY['player'] AND method = 'GET' THEN
    IF rec.id IS NULL THEN RETURN verse.r(404, '{"error":"unknown player key"}'); END IF;
    RETURN verse.r(200, jsonb_build_object('id', rec.id, 'account', rec.account,
      'worlds', coalesce((SELECT jsonb_agg(x.id ORDER BY x.id) FROM verse.worlds x WHERE verse.owns(rec, acct, x.id)), '[]')));
  END IF;
  IF parts = ARRAY['player'] AND method = 'POST' THEN
    IF rec.id IS NOT NULL THEN RETURN verse.r(200, jsonb_build_object('key', k, 'id', rec.id, 'account', rec.account)); END IF;
    RETURN verse.r(200, verse.mint(acct, auto));
  END IF;
  IF parts = ARRAY['join'] AND method = 'POST' THEN
    email := lower(btrim(coalesce(body->>'email', '')));
    IF length(email) > 120 OR email !~ '^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$' THEN
      RETURN verse.r(400, '{"error":"that is not an email address"}');
    END IF;
    INSERT INTO analytics.playtesters (id, at, email, player, sid, how, auto, space)
    VALUES (verse.hex(16), now_s, email, left(body->>'player', 32), left(body->>'sid', 80), left(body->>'how', 16), auto, 'web');
    INSERT INTO verse.accounts (id, email, created_ms)
    VALUES ('e-' || left(encode(sha256(convert_to(email, 'UTF8')), 'hex'), 24), email, verse.now_ms()) ON CONFLICT DO NOTHING;
    acct := 'e-' || left(encode(sha256(convert_to(email, 'UTF8')), 'hex'), 24);
    RETURN verse.r(200, jsonb_build_object('joined', true, 'player', verse.link(k, rec, acct, auto)));
  END IF;
  IF parts = ARRAY['worlds'] AND method = 'POST' THEN
    IF rec.id IS NULL AND acct IS NULL THEN
      RETURN verse.r(403, '{"error":"send a player key (POST /api/playtest/player) to make a world"}');
    END IF;
    world := 'w-' || verse.hex(12);
    INSERT INTO verse.worlds (id, owner_player, owner_account, created_ms) VALUES (world, rec.id, coalesce(acct, rec.account), verse.now_ms());
    RETURN verse.r(200, jsonb_build_object('id', world));
  END IF;

  -- ---- published worlds
  IF parts[1] = 'world' AND n = 2 AND method = 'GET' THEN
    SELECT * INTO pub FROM verse.published WHERE published.world = parts[2];
    IF pub.world IS NULL THEN RETURN verse.r(200, '{"doc":null,"version":0}'); END IF;
    RETURN verse.r(200, jsonb_build_object('doc', pub.doc, 'version', pub.version, 'publishedBy', pub.published_by, 'publishedAt', pub.published_at));
  END IF;
  IF parts[1] = 'world' AND n = 2 AND method = 'POST' THEN
    SELECT * INTO st FROM verse.world_state WHERE world_state.world = parts[2];
    IF NOT mine AND NOT ((rec.id IS NOT NULL OR acct IS NOT NULL) AND st.open_ms IS NOT NULL) THEN
      IF rec.id IS NULL AND acct IS NULL THEN RETURN verse.r(403, '{"error":"log in to publish","offer":true}'); END IF;
      RETURN verse.r(403, '{"error":"only its owner can publish this world","offer":true}');
    END IF;
    IF jsonb_typeof(body->'doc') IS DISTINCT FROM 'object' THEN RETURN verse.r(400, '{"error":"publish needs the world as {\"doc\"}"}'); END IF;
    PERFORM pg_advisory_xact_lock(7731004, hashtext(world));
    SELECT coalesce(max(version), 0) + 1 INTO ver FROM verse.published WHERE published.world = parts[2];
    INSERT INTO verse.published (world, doc, version, published_by, published_at) VALUES (world, body->'doc', ver, who_name, now_s)
    ON CONFLICT (world) DO UPDATE SET doc = EXCLUDED.doc, version = EXCLUDED.version, published_by = EXCLUDED.published_by, published_at = EXCLUDED.published_at;
    INSERT INTO verse.log (world, version, who, summary, at, state, by_account, by_player, doc)
    VALUES (world, ver, who_name, left(coalesce(body->>'summary', ''), 300), now_s, 'published', acct, rec.id, body->'doc');
    RETURN verse.r(200, jsonb_build_object('version', ver));
  END IF;
  IF parts[1] = 'world' AND n = 3 AND parts[3] = 'owner' AND method = 'GET' THEN
    SELECT * INTO w FROM verse.worlds WHERE id = world;
    SELECT * INTO st FROM verse.world_state WHERE world_state.world = parts[2];
    RETURN verse.r(200, jsonb_build_object('claimed', w.id IS NOT NULL, 'you', mine, 'site', site, 'open', st.open_ms IS NOT NULL,
      'name', left(coalesce((SELECT a.name FROM verse.accounts a WHERE a.id = coalesce(w.owner_account,
        (SELECT pl.account FROM verse.players pl WHERE pl.id = w.owner_player))), ''), 40)));
  END IF;
  IF parts[1] = 'world' AND n = 3 AND parts[3] = 'settings' AND method = 'GET' THEN
    SELECT * INTO st FROM verse.world_state WHERE world_state.world = parts[2];
    IF st.settings_ms IS NULL THEN RETURN verse.r(200, '{"settings":{}}'); END IF;
    RETURN verse.r(200, jsonb_build_object('settings', st.settings, 'at', st.settings_ms / 1000.0, 'by', st.settings_by));
  END IF;
  IF parts[1] = 'world' AND n = 3 AND parts[3] = 'settings' AND method = 'POST' THEN
    IF NOT mine THEN RETURN verse.r(403, '{"error":"only the world''s owner changes its settings"}'); END IF;
    IF jsonb_typeof(body->'view') IS DISTINCT FROM 'object' OR NOT (body->'view'->>'view' = ANY (ARRAY['third', 'first', 'top']))
       OR jsonb_typeof(coalesce(body->'view'->'allowToggle', 'false')) <> 'boolean' THEN
      RETURN verse.r(400, '{"error":"expected {\"view\": {\"view\": \"third\"|\"first\"|\"top\", \"allowToggle\": bool}}"}');
    END IF;
    INSERT INTO verse.world_state AS x (world, settings, settings_ms, settings_by)
    VALUES (world, jsonb_build_object('view', jsonb_build_object('view', body->'view'->>'view',
            'allowToggle', coalesce((body->'view'->>'allowToggle')::boolean, false))), verse.now_ms(), who_name)
    ON CONFLICT (world) DO UPDATE SET settings = x.settings || EXCLUDED.settings, settings_ms = EXCLUDED.settings_ms, settings_by = EXCLUDED.settings_by
    RETURNING * INTO st;
    RETURN verse.r(200, jsonb_build_object('settings', st.settings, 'at', st.settings_ms / 1000.0, 'by', st.settings_by));
  END IF;
  IF parts[1] = 'world' AND n = 3 AND parts[3] = 'open' AND method = 'POST' THEN
    IF NOT mine THEN RETURN verse.r(403, '{"error":"only the owner can open a world to publishing"}'); END IF;
    INSERT INTO verse.world_state AS x (world, open_ms)
    VALUES (world, CASE WHEN body->'open' = 'true'::jsonb THEN verse.now_ms() END)
    ON CONFLICT (world) DO UPDATE SET open_ms = EXCLUDED.open_ms;
    RETURN verse.r(200, jsonb_build_object('open', body->'open' = 'true'::jsonb));
  END IF;
  IF parts[1] = 'world' AND n = 3 AND parts[3] = 'reset' AND method = 'POST' THEN
    IF NOT mine THEN RETURN verse.r(403, '{"error":"only the owner can reset a world"}'); END IF;
    DELETE FROM verse.published WHERE published.world = parts[2] RETURNING * INTO pub;
    INSERT INTO verse.log (world, version, who, summary, at, state, by_account, by_player)
    VALUES (world, 0, who_name, 'Reset to the built-in world' || coalesce(' (was version ' || pub.version || ')', ''), now_s, 'reset', acct, rec.id);
    RETURN verse.r(200, jsonb_build_object('reset', true, 'was', coalesce(pub.version, 0)));
  END IF;
  IF parts[1] = 'log' AND n = 2 AND method = 'GET' THEN
    RETURN verse.r(200, coalesce((SELECT jsonb_agg(e ORDER BY id DESC) FROM (
      SELECT l.id, jsonb_build_object('version', l.version, 'who', l.who, 'summary', l.summary, 'at', l.at, 'amount', 0, 'unit', 'sats',
             'state', l.state) || CASE WHEN l.by_account IS NOT NULL OR l.by_player IS NOT NULL
             THEN jsonb_build_object('by', jsonb_build_object('account', l.by_account, 'player', l.by_player)) ELSE '{}' END AS e
      FROM verse.log l WHERE l.world = parts[2] ORDER BY l.id DESC LIMIT 200) q), '[]'));
  END IF;

  -- ---- progress saves (an account's)
  IF parts[1] = 'progress' AND n IN (3, 4) THEN
    IF parts[2] !~ safe OR parts[3] !~ safe OR (n = 4 AND (parts[4] <> 'erase' OR method <> 'POST')) THEN
      RETURN verse.r(404, '{"error":"unknown"}');
    END IF;
    IF acct IS NULL THEN RETURN verse.r(403, '{"error":"join with your email to keep your progress on the server"}'); END IF;
    slot_ := parts[2] || '/' || parts[3];
    IF n = 4 THEN
      DELETE FROM verse.progress WHERE account = acct AND progress.slot = slot_;
      RETURN verse.r(200, '{"erased":true}');
    END IF;
    IF method = 'POST' THEN
      IF NOT coalesce((who->>'good')::boolean, false) THEN RETURN verse.r(400, '{"error":"that is not a good progress save"}'); END IF;
      at := CASE WHEN jsonb_typeof(body->'at') = 'number' THEN (body->>'at')::double precision ELSE now_s * 1000 END;
      SELECT * INTO p FROM verse.progress WHERE account = acct AND progress.slot = slot_ FOR UPDATE;
      IF p.cur IS NOT NULL AND p.cur_at > at THEN
        RETURN verse.r(409, jsonb_build_object('current', jsonb_build_object('bytes', verse.b64(p.cur), 'at', p.cur_at),
          'previous', CASE WHEN p.prev IS NOT NULL THEN jsonb_build_object('bytes', verse.b64(p.prev), 'at', p.prev_at) END));
      END IF;
      INSERT INTO verse.progress AS x (account, slot, cur, cur_at) VALUES (acct, slot_, decode(who->>'bytes', 'base64'), at)
      ON CONFLICT (account, slot) DO UPDATE SET prev = x.cur, prev_at = x.cur_at, cur = EXCLUDED.cur, cur_at = EXCLUDED.cur_at;
    END IF;
    SELECT * INTO p FROM verse.progress WHERE account = acct AND progress.slot = slot_;
    RETURN verse.r(200, jsonb_build_object(
      'current', CASE WHEN p.cur IS NOT NULL THEN jsonb_build_object('bytes', verse.b64(p.cur), 'at', p.cur_at) END,
      'previous', CASE WHEN p.prev IS NOT NULL THEN jsonb_build_object('bytes', verse.b64(p.prev), 'at', p.prev_at) END));
  END IF;
  RETURN verse.r(404, '{"error":"unknown"}');
END $_$;


--
-- Name: api_0010(text, text[], jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.api_0010(method text, parts text[], body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
#variable_conflict use_column
DECLARE
  k text := who->>'key';
  site boolean := coalesce((who->>'site')::boolean, false);
  npub text := nullif(who->>'npub', '');
  now_s double precision := extract(epoch FROM clock_timestamp());
  n int := coalesce(array_length(parts, 1), 0);
  world text := CASE WHEN n >= 2 THEN parts[2] END;
  rec verse.players;
  acct text;
  b jsonb := CASE WHEN jsonb_typeof(body) = 'object' THEN body ELSE '{}' END;
  given text;
  who_name text;
  o verse.offers;
  price numeric;
  ver int;
  d jsonb;
BEGIN
  IF NOT (parts[1] IN ('change', 'log') AND n >= 2) THEN
    RETURN verse.api_0004(method, parts, body, who);
  END IF;
  IF world !~ '^[A-Za-z0-9_-]{1,64}$' THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;

  IF parts[1] = 'log' AND n = 2 AND method = 'GET' THEN
    RETURN verse.r(200, coalesce((SELECT jsonb_agg(e ORDER BY at DESC, o2 DESC) FROM (
      SELECT * FROM (
        SELECT l.at, l.id AS o2, jsonb_build_object('version', l.version, 'who', l.who, 'summary', l.summary, 'at', l.at, 'amount', 0,
               'unit', 'sats', 'state', l.state) || CASE WHEN l.by_account IS NOT NULL OR l.by_player IS NOT NULL
               THEN jsonb_build_object('by', jsonb_build_object('account', l.by_account, 'player', l.by_player)) ELSE '{}' END AS e
        FROM verse.log l WHERE l.world = parts[2]
        UNION ALL
        SELECT x.at, 0, verse.offer_json(x) FROM verse.offers x WHERE x.world = parts[2]) u
      ORDER BY at DESC, o2 DESC LIMIT 200) q), '[]'));
  END IF;
  IF parts[1] = 'log' THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;

  -- who asks: the player key, and the account a Nostr key or the key gives
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO rec FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  END IF;
  IF npub IS NOT NULL THEN
    INSERT INTO verse.accounts (id, npub, created_ms) VALUES ('n-' || npub, npub, verse.now_ms()) ON CONFLICT DO NOTHING;
    acct := 'n-' || npub;
  ELSE
    acct := rec.account;
  END IF;
  given := CASE WHEN jsonb_typeof(b->'user') = 'object' THEN nullif(btrim(b->'user'->>'name'), '') END;

  IF method <> 'POST' THEN RETURN verse.r(405, '{"error":"POST a change"}'); END IF;

  IF n = 2 THEN
    IF rec.id IS NULL AND acct IS NULL THEN RETURN verse.r(403, '{"error":"log in to offer a change"}'); END IF;
    d := b->'delta';
    IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR NOT EXISTS (
         SELECT 1 FROM unnest(ARRAY['added', 'changed', 'removed']) AS f(k)
         WHERE jsonb_typeof(d->f.k) = 'array' AND jsonb_array_length(d->f.k) > 0) THEN
      RETURN verse.r(400, '{"error":"there is no change to offer"}');
    END IF;
    IF b ? 'doc' AND jsonb_typeof(b->'doc') NOT IN ('object', 'null') THEN
      RETURN verse.r(400, '{"error":"the world with the change made must be a world record"}');
    END IF;
    IF b ? 'price' AND jsonb_typeof(b->'price') <> 'number' THEN
      RETURN verse.r(400, '{"error":"the price must be a whole number of sats"}');
    END IF;
    price := coalesce((b->>'price')::numeric, 0);
    IF price <> trunc(price) THEN RETURN verse.r(400, '{"error":"the price must be a whole number of sats"}'); END IF;
    IF price < 0 OR price > 1000000 THEN RETURN verse.r(400, '{"error":"the price must be between 0 and 1,000,000 sats"}'); END IF;
    who_name := left(coalesce((SELECT a.name FROM verse.accounts a WHERE a.id = acct), given, 'Guest'), 40);
    INSERT INTO verse.offers (world, id, who, summary, at, amount, state, delta, doc, by_account, by_player, guest)
    VALUES (world, verse.hex(12), who_name, left(coalesce(b->>'summary', ''), 300), now_s, price::int, 'waiting', d,
            CASE WHEN jsonb_typeof(b->'doc') = 'object' THEN b->'doc' END, acct, rec.id, acct IS NULL)
    RETURNING * INTO o;
    RETURN verse.r(200, jsonb_build_object('id', o.id, 'state', 'waiting'));
  END IF;

  IF n = 4 AND parts[3] ~ '^[A-Za-z0-9_-]{1,64}$' AND parts[4] IN ('accept', 'decline') THEN
    IF NOT (site OR verse.owns(rec, acct, world)) THEN
      RETURN verse.r(403, '{"error":"only the owner can accept or decline changes"}');
    END IF;
    PERFORM pg_advisory_xact_lock(7731004, hashtext(world));
    SELECT * INTO o FROM verse.offers x WHERE x.world = parts[2] AND x.id = parts[3] FOR UPDATE;
    IF o.id IS NULL THEN RETURN verse.r(404, '{"error":"no such change"}'); END IF;
    IF o.state <> 'waiting' THEN RETURN verse.r(409, jsonb_build_object('error', 'that change was already ' || o.state)); END IF;
    who_name := left(coalesce((SELECT a.name FROM verse.accounts a WHERE a.id = acct), CASE WHEN site THEN 'site owner' END, given, 'owner'), 40);
    IF parts[4] = 'decline' THEN
      UPDATE verse.offers x SET state = 'declined', decided_at = now_s, decided_by = who_name WHERE x.world = o.world AND x.id = o.id;
      RETURN verse.r(200, '{"state":"declined"}');
    END IF;
    d := CASE WHEN jsonb_typeof(b->'doc') = 'object' THEN b->'doc' ELSE o.doc END;
    IF d IS NULL THEN RETURN verse.r(400, '{"error":"accepting needs the world with the change made"}'); END IF;
    SELECT coalesce(max(version), 0) + 1 INTO ver FROM verse.published p WHERE p.world = o.world;
    INSERT INTO verse.published (world, doc, version, published_by, published_at) VALUES (o.world, d, ver, o.who, now_s)
    ON CONFLICT (world) DO UPDATE SET doc = EXCLUDED.doc, version = EXCLUDED.version, published_by = EXCLUDED.published_by,
      published_at = EXCLUDED.published_at, source = NULL;
    UPDATE verse.offers x SET state = 'accepted', decided_at = now_s, decided_by = who_name, version = ver, doc = d
    WHERE x.world = o.world AND x.id = o.id;
    RETURN verse.r(200, jsonb_build_object('state', 'accepted', 'version', ver));
  END IF;
  RETURN verse.r(404, '{"error":"unknown"}');
END $_$;


--
-- Name: api_0011(text, text[], jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.api_0011(method text, parts text[], body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
#variable_conflict use_column
DECLARE
  k text := who->>'key';
  npub text := nullif(who->>'npub', '');
  site boolean := coalesce((who->>'site')::boolean, false);
  now_s double precision := extract(epoch FROM clock_timestamp());
  n int := coalesce(array_length(parts, 1), 0);
  b jsonb := CASE WHEN jsonb_typeof(body) = 'object' THEN body ELSE '{}' END;
  rec verse.players;
  acct text;
  u text;
  uname text;
  pid text;
  w verse.worlds;
  p verse.planets;
  s jsonb;
  ps verse.planet_saves;
  after_n bigint;
BEGIN
  IF parts[1] NOT IN ('award', 'planets') OR n > 2 THEN RETURN verse.api_0010(method, parts, body, who); END IF;
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO rec FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  END IF;
  IF npub IS NOT NULL THEN
    INSERT INTO verse.accounts (id, npub, created_ms) VALUES ('n-' || npub, npub, verse.now_ms()) ON CONFLICT DO NOTHING;
    acct := 'n-' || npub;
  ELSE
    acct := rec.account;
  END IF;

  IF parts = ARRAY['award'] AND method = 'POST' THEN
    u := left(coalesce(b->>'user', ''), 64);
    INSERT INTO verse.awards (user_id, planet, at)
    VALUES (u, 'planet-' || right(regexp_replace(u, '[^A-Za-z0-9]', '', 'g'), 12) || right(to_hex(floor(now_s)::bigint), 4), now_s)
    ON CONFLICT DO NOTHING;
    RETURN verse.r(200, jsonb_build_object('planet', (SELECT planet FROM verse.awards WHERE user_id = u)));
  END IF;

  IF parts = ARRAY['planets'] AND method = 'GET' THEN
    after_n := CASE WHEN who->>'after' ~ '^[0-9]{1,15}$' THEN (who->>'after')::bigint ELSE 0 END;
    RETURN verse.r(200, jsonb_build_object(
      'planets', coalesce((SELECT jsonb_agg(verse.planet_json(x) ORDER BY x.n) FROM verse.planets x WHERE x.n > after_n), '[]'),
      'n', coalesce((SELECT max(x.n) FROM verse.planets x), 0)));
  END IF;

  IF parts = ARRAY['planets'] AND method = 'POST' THEN
    IF rec.id IS NULL AND acct IS NULL THEN
      RETURN verse.r(403, '{"error":"send a player key (POST /api/playtest/player) to make a planet"}');
    END IF;
    IF acct IS NOT NULL THEN
      u := acct;
      uname := coalesce((SELECT a.name FROM verse.accounts a WHERE a.id = acct),
                        CASE WHEN jsonb_typeof(b->'user') = 'object' THEN b->'user'->>'name' END);
    ELSE
      u := CASE WHEN jsonb_typeof(b->'user') = 'object' THEN left(b->'user'->>'id', 64) END;
      uname := CASE WHEN jsonb_typeof(b->'user') = 'object' THEN b->'user'->>'name' END;
    END IF;
    s := b->'settings';
    IF coalesce(u, '') !~ '^[A-Za-z0-9_-]{1,64}$' OR jsonb_typeof(s) IS DISTINCT FROM 'object' THEN
      RETURN verse.r(400, '{"error":"expected the user and the planet''s settings"}');
    END IF;
    INSERT INTO verse.awards (user_id, planet, at)
    VALUES (u, 'planet-' || right(regexp_replace(u, '[^A-Za-z0-9]', '', 'g'), 12) || right(to_hex(floor(now_s)::bigint), 4), now_s)
    ON CONFLICT DO NOTHING;
    SELECT planet INTO pid FROM verse.awards WHERE user_id = u;
    PERFORM pg_advisory_xact_lock(7731004, hashtext(pid));
    SELECT * INTO w FROM verse.worlds WHERE id = pid;
    IF w.id IS NOT NULL AND (w.owner_player IS NOT NULL OR w.owner_account IS NOT NULL) AND NOT (site OR verse.owns(rec, acct, pid)) THEN
      RETURN verse.r(403, '{"error":"this planet belongs to another player"}');
    END IF;
    IF w.id IS NULL THEN
      INSERT INTO verse.worlds (id, owner_player, owner_account, created_ms) VALUES (pid, rec.id, acct, verse.now_ms());
    ELSIF w.owner_player IS NULL AND w.owner_account IS NULL THEN
      UPDATE verse.worlds SET owner_player = rec.id, owner_account = acct WHERE id = pid;
    END IF;
    INSERT INTO verse.planets AS x (id, n, name, owner, owner_id, kind, art, cam, cycle, made, at)
    VALUES (pid, nextval('verse.planet_n'), left(coalesce(nullif(btrim(s->>'name'), ''), 'My planet'), 40),
            left(coalesce(nullif(btrim(uname), ''), 'Guest'), 40), u,
            verse.planet_pick(s->>'kind', ARRAY['forest', 'village', 'cemetery']),
            verse.planet_pick(s->>'art', ARRAY['Low poly', 'Painted', 'Pixel', 'Ink']),
            verse.planet_pick(s->>'cam', ARRAY['Third person', 'First person', 'Top down']),
            verse.planet_pick(s->>'cycle', ARRAY['Day/night cycle', 'Always day', 'Always night']), now_s, now_s)
    ON CONFLICT (id) DO UPDATE SET n = EXCLUDED.n, name = EXCLUDED.name, owner = EXCLUDED.owner, owner_id = EXCLUDED.owner_id,
      kind = EXCLUDED.kind, art = EXCLUDED.art, cam = EXCLUDED.cam, cycle = EXCLUDED.cycle, at = EXCLUDED.at, source = NULL
    RETURNING * INTO p;
    RETURN verse.r(200, verse.planet_json(p));
  END IF;

  IF parts = ARRAY['planets', 'mine'] THEN
    IF rec.id IS NOT NULL OR acct IS NOT NULL THEN
      SELECT * INTO p FROM verse.planets x WHERE verse.owns(rec, acct, x.id) ORDER BY x.n DESC LIMIT 1;
    END IF;
    IF method = 'GET' THEN
      IF p.id IS NULL THEN RETURN verse.r(200, '{"planet":null,"invited":false,"saved":null}'); END IF;
      SELECT * INTO ps FROM verse.planet_saves x WHERE x.planet = p.id;
      RETURN verse.r(200, jsonb_build_object('planet', verse.planet_json(p), 'invited', ps.invited IS NOT NULL, 'saved', ps.saved));
    END IF;
    IF p.id IS NULL THEN RETURN verse.r(404, '{"error":"make a planet first"}'); END IF;
    IF b ? 'doc' AND jsonb_typeof(b->'doc') NOT IN ('object', 'null') THEN
      RETURN verse.r(400, '{"error":"the planet must be a world record"}');
    END IF;
    INSERT INTO verse.planet_saves AS x (planet) VALUES (p.id) ON CONFLICT DO NOTHING;
    UPDATE verse.planet_saves x SET
      saved = CASE WHEN NOT b ? 'doc' THEN x.saved WHEN jsonb_typeof(b->'doc') = 'object' AND b->'doc' <> '{}'
                   THEN jsonb_build_object('doc', b->'doc', 'at', now_s) END,
      invited = CASE WHEN coalesce(b->'invited' = 'true'::jsonb, false) THEN coalesce(x.invited, now_s) ELSE x.invited END,
      source = NULL
    WHERE x.planet = p.id RETURNING * INTO ps;
    RETURN verse.r(200, jsonb_build_object('id', p.id, 'invited', ps.invited IS NOT NULL, 'at', ps.saved->'at'));
  END IF;

  IF parts[1] = 'planets' AND n = 2 AND method = 'GET' THEN
    SELECT * INTO p FROM verse.planets x WHERE x.id = parts[2];
    IF p.id IS NULL THEN RETURN verse.r(404, '{"error":"no such planet"}'); END IF;
    RETURN verse.r(200, verse.planet_json(p));
  END IF;
  RETURN verse.r(404, '{"error":"unknown"}');
END $_$;


--
-- Name: api_0015(text, text[], jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.api_0015(method text, parts text[], body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
#variable_conflict use_column
DECLARE
  k text := who->>'key';
  auto text := nullif(who->>'auto', '');
  signer text := nullif(who->>'npub', '');
  b jsonb := CASE WHEN jsonb_typeof(body) = 'object' THEN body ELSE '{}' END;
  now_s double precision := extract(epoch FROM clock_timestamp());
  rec verse.players;
  acct text;
  own text;
  email text;
  out jsonb;
  sid_ text;
  planet_ text;
  worlds_n int := 0;
  saves_n int := 0;
  sessions_n int := 0;
BEGIN
  IF NOT (method = 'POST' AND parts IN (ARRAY['join'], ARRAY['signin'])) THEN RETURN verse.api_0011(method, parts, body, who); END IF;
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO rec FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  END IF;
  IF signer IS NOT NULL THEN
    INSERT INTO verse.accounts (id, npub, created_ms) VALUES ('n-' || signer, signer, verse.now_ms()) ON CONFLICT DO NOTHING;
  END IF;

  IF parts = ARRAY['join'] THEN
    email := lower(btrim(coalesce(b->>'email', '')));
    IF length(email) > 120 OR email !~ '^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$' THEN
      RETURN verse.r(400, '{"error":"that is not an email address"}');
    END IF;
    INSERT INTO analytics.playtesters (id, at, email, player, sid, how, auto, space)
    VALUES (verse.hex(16), now_s, email, left(b->>'player', 32), left(b->>'sid', 80), left(b->>'how', 16), auto, 'web');
    IF rec.id IS NOT NULL AND rec.account IS NOT NULL THEN
      RETURN verse.r(200, jsonb_build_object('joined', true, 'player', jsonb_build_object('key', k, 'id', rec.id, 'account', rec.account)));
    END IF;
    IF signer IS NOT NULL THEN
      acct := 'n-' || signer;
    ELSE
      acct := 'g-' || verse.hex(24);
      INSERT INTO verse.accounts (id, created_ms) VALUES (acct, verse.now_ms());
    END IF;
    RETURN verse.r(200, jsonb_build_object('joined', true, 'player', verse.link(k, rec, acct, auto)));
  END IF;

  IF signer IS NULL THEN RETURN verse.r(401, '{"error":"sign in with a NIP-98 signed request"}'); END IF;
  acct := 'n-' || signer;
  IF rec.id IS NULL THEN
    out := verse.mint(acct, auto);
  ELSIF rec.account IS NULL OR rec.account = acct OR rec.account LIKE 'g-%' THEN
    own := CASE WHEN rec.account LIKE 'g-%' THEN rec.account END;
    UPDATE verse.players SET account = acct WHERE id = rec.id OR (own IS NOT NULL AND account = own);
    UPDATE verse.worlds SET owner_account = acct
    WHERE (owner_player = rec.id AND (owner_account IS NULL OR owner_account = own)) OR (own IS NOT NULL AND owner_account = own);
    GET DIAGNOSTICS worlds_n = ROW_COUNT;
    IF NOT EXISTS (SELECT 1 FROM verse.awards WHERE user_id = acct) THEN
      SELECT a.planet INTO planet_ FROM verse.awards a JOIN verse.worlds w ON w.id = a.planet
      WHERE w.owner_account = acct ORDER BY a.at DESC LIMIT 1;
      IF planet_ IS NOT NULL THEN
        UPDATE verse.awards SET user_id = acct WHERE planet = planet_ AND user_id <> acct;
        UPDATE verse.planets SET owner_id = acct WHERE id = planet_;
      END IF;
    END IF;
    IF own IS NOT NULL THEN
      INSERT INTO verse.progress AS x (account, slot, cur, cur_at, prev, prev_at)
      SELECT acct, g.slot, g.cur, g.cur_at, g.prev, g.prev_at FROM verse.progress g WHERE g.account = own
      ON CONFLICT (account, slot) DO UPDATE SET
        cur = CASE WHEN EXCLUDED.cur_at > x.cur_at THEN EXCLUDED.cur ELSE x.cur END,
        cur_at = greatest(EXCLUDED.cur_at, x.cur_at),
        prev = CASE WHEN EXCLUDED.cur_at > x.cur_at THEN x.cur ELSE coalesce(x.prev, EXCLUDED.cur) END,
        prev_at = CASE WHEN EXCLUDED.cur_at > x.cur_at THEN x.cur_at ELSE coalesce(x.prev_at, EXCLUDED.cur_at) END;
      GET DIAGNOSTICS saves_n = ROW_COUNT;
      DELETE FROM verse.progress WHERE account = own;
    END IF;
    out := jsonb_build_object('key', k, 'id', rec.id, 'account', acct);
  ELSE
    out := verse.mint(acct, auto);
  END IF;

  sid_ := CASE WHEN b->>'sid' ~ '^[A-Za-z0-9_:-]{8,80}$' THEN b->>'sid' END;
  UPDATE analytics.sessions SET npub = signer, player = coalesce(player, out->>'id')
  WHERE npub IS NULL AND ((rec.id IS NOT NULL AND player = rec.id) OR (sid = sid_ AND (player IS NULL OR player = rec.id)));
  GET DIAGNOSTICS sessions_n = ROW_COUNT;
  RETURN verse.r(200, jsonb_build_object('signedIn', true, 'npub', signer, 'player', out,
    'moved', jsonb_build_object('worlds', worlds_n, 'saves', saves_n, 'sessions', sessions_n)));
END $_$;


--
-- Name: api_0057(text, text[], jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.api_0057(method text, parts text[], body jsonb, who jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  b jsonb := CASE WHEN jsonb_typeof(body) = 'object' THEN body ELSE '{}' END;
  me text;
  cid text := parts[2];
  c verse.courses;
  hs jsonb;
  realm_ text;
  ms_ int;
  now_ bigint := verse.now_ms();
BEGIN
  IF parts[1] IS DISTINCT FROM 'course' THEN RETURN verse.api_0015(method, parts, body, who); END IF;
  IF cid IS NULL OR cid !~ '^[a-z0-9]{8,16}$' OR array_length(parts, 1) > 3 OR (array_length(parts, 1) = 3 AND parts[3] <> 'time') THEN
    RETURN verse.r(404, '{"error":"unknown"}');
  END IF;
  me := verse.player_of(who->>'key');
  SELECT * INTO c FROM verse.courses WHERE id = cid;
  IF method = 'GET' THEN
    IF array_length(parts, 1) <> 2 THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
    IF c.id IS NULL THEN RETURN verse.r(404, '{"error":"no such course"}'); END IF;
    RETURN verse.r(200, verse.course_view(cid, me));
  END IF;
  IF me IS NULL THEN RETURN verse.r(403, '{"error":"a player key is needed"}'); END IF;

  IF array_length(parts, 1) = 2 THEN
    hs := verse.course_hoops(b->'hoops');
    IF hs IS NULL THEN RETURN verse.r(400, '{"error":"hoops: 3 to 12 of [x, y, z, yaw]"}'); END IF;
    IF c.id IS NULL THEN
      realm_ := CASE WHEN b->>'realm' ~ '^[a-z0-9-]{1,40}$' THEN b->>'realm' ELSE 'fairy-forest' END;
      IF (SELECT count(*) FROM verse.courses WHERE owner = me AND made_ms > now_ - 86400000) >= 30 THEN
        RETURN verse.r(429, '{"error":"that is enough courses for today"}');
      END IF;
      INSERT INTO verse.courses (id, realm, owner, hoops, made_ms, changed_ms) VALUES (cid, realm_, me, hs, now_, now_);
    ELSIF c.owner <> me THEN
      RETURN verse.r(403, '{"error":"that course is someone else''s"}');
    ELSIF c.hoops IS DISTINCT FROM hs THEN
      UPDATE verse.courses SET hoops = hs, changed_ms = now_ WHERE id = cid;
      DELETE FROM verse.course_times WHERE course = cid;
    END IF;
    RETURN verse.r(200, verse.course_view(cid, me));
  END IF;

  -- a time
  IF c.id IS NULL THEN RETURN verse.r(404, '{"error":"no such course"}'); END IF;
  IF jsonb_typeof(b->'ms') <> 'number' THEN RETURN verse.r(400, '{"error":"ms: the run in milliseconds"}'); END IF;
  ms_ := round((b->>'ms')::numeric);
  IF ms_ < 1000 OR ms_ > 3600000 THEN RETURN verse.r(400, '{"error":"ms: 1 s to an hour"}'); END IF;
  IF EXISTS (SELECT 1 FROM verse.course_times WHERE course = cid AND player = me AND at_ms > now_ - 2000) THEN
    RETURN verse.r(429, '{"error":"one run at a time"}');
  END IF;
  INSERT INTO verse.course_times (course, player, ms, at_ms) VALUES (cid, me, ms_, now_)
    ON CONFLICT (course, player) DO UPDATE SET ms = least(verse.course_times.ms, EXCLUDED.ms), at_ms = EXCLUDED.at_ms,
      runs = verse.course_times.runs + 1;
  RETURN verse.r(200, verse.course_view(cid, me));
END
$_$;


--
-- Name: ask_add(text, jsonb, integer, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_add(s text, body jsonb, cap integer, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  said text := btrim(regexp_replace(CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'words', 400) ELSE '' END, '[[:cntrl:]]+', ' ', 'g'));
  x jsonb;
  aid bigint;
  st int;
BEGIN
  x := verse.edit_revise_ask(s, jsonb_build_object('prompt', said), cap, k, site_admin);
  st := (x->>'status')::int;
  IF st IN (400, 401, 403, 404, 429) THEN RETURN x; END IF;
  IF said = '' THEN RETURN '{"status":400,"error":"say what you want"}'; END IF;
  INSERT INTO verse.realm_asks (slug, ms, player, words, state, plan)
  VALUES (s, verse.now_ms(), (verse.builder_player(k)).id, said, CASE WHEN st = 200 THEN 'asking' ELSE 'waiting' END, CASE WHEN st = 200 THEN (x->>'id')::bigint END)
  RETURNING id INTO aid;
  IF st <> 200 THEN
    RETURN jsonb_build_object('status', 200, 'ask', aid, 'lines', 'ask ' || aid || E' waiting\n' || verse.edit_rows(s));
  END IF;
  RETURN x || jsonb_build_object('ask', aid);
END $$;


--
-- Name: ask_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  out jsonb := verse.ask_answer_0078(asked, http, response, model, taken);
  a verse.realm_asks;
  d jsonb;
  extra text;
BEGIN
  SELECT * INTO a FROM verse.realm_asks WHERE id = (out->>'ask')::bigint;
  IF a.id IS NULL OR a.state <> 'applied' OR NOT verse.edit_made(a.slug) THEN RETURN out; END IF;
  BEGIN d := verse.builder_said(response)::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
  IF jsonb_typeof(d) <> 'object' THEN RETURN out; END IF;
  INSERT INTO verse.realm_asks (slug, ms, player, words, state)
  SELECT a.slug, verse.now_ms(), a.player, w #>> '{}', 'waiting' FROM jsonb_array_elements(verse.builder_wanted(NULL, d->'asked')) WITH ORDINALITY AS t(w, o) ORDER BY o;
  RETURN out;
END $$;


--
-- Name: ask_answer_0078(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_answer_0078(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  a verse.realm_asks;
  before jsonb;
  res jsonb;
  d jsonb;
  st text;
BEGIN
  SELECT * INTO a FROM verse.realm_asks WHERE id = (asked->>'ask')::bigint FOR UPDATE;
  IF a.id IS NULL THEN   -- deleted while the model thought: its answer changes nothing
    RETURN jsonb_build_object('status', 200, 'lines', E'ask 0 gone\n' || verse.edit_rows((SELECT slug FROM verse.realm_plans WHERE id = (asked->>'id')::bigint)));
  END IF;
  before := verse.ask_state(a.slug);
  res := verse.fork_revise_answer(asked, http, response, model, taken);
  d := verse.ask_diff(before, verse.ask_state(a.slug));
  -- a hand-built realm's answer names every row; the ones it didn't change keep what they held
  IF NOT coalesce((before->>'made')::boolean, false) THEN
    UPDATE verse.realm_edit SET
      switched = (switched - ARRAY(SELECT kk FROM jsonb_object_keys(before->'rows') kk WHERE NOT coalesce(d->'after', '{}') ? kk))
              || coalesce((SELECT jsonb_object_agg(kk, v->'raw') FROM jsonb_each(before->'rows') x(kk, v)
                           WHERE NOT coalesce(d->'after', '{}') ? kk AND jsonb_typeof(v->'raw') = 'boolean'), '{}')
    WHERE slug = a.slug;
  END IF;
  st := CASE WHEN (res->>'status')::int = 200 AND verse.ask_changed(d) THEN 'applied' ELSE 'waiting' END;
  UPDATE verse.realm_asks SET state = st, did = CASE WHEN st = 'applied' THEN d ELSE '{}' END WHERE id = a.id;
  RETURN jsonb_build_object('status', 200, 'ask', a.id, 'state', st,
    'lines', 'ask ' || a.id || ' ' || st || E'\n' || coalesce(res->>'lines', verse.edit_rows(a.slug)));
END $$;


--
-- Name: ask_changed(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_changed(d jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(d->'after', '{}') <> '{}' OR d ? 'ground' OR d ? 'time' OR d ? 'palette' $$;


--
-- Name: ask_delete(text, bigint, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_delete(s text, aid bigint, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.ask_delete_0110(s, aid, k, site_admin)) $$;


--
-- Name: ask_delete_0110(text, bigint, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_delete_0110(s text, aid bigint, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  a verse.realm_asks;
  n int;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  SELECT * INTO a FROM verse.realm_asks WHERE id = aid AND slug = s FOR UPDATE;
  IF a.id IS NULL THEN RETURN '{"status":404,"error":"no such ask"}'; END IF;
  IF a.commit_hash IS NOT NULL AND a.kind = 'ask' THEN
    UPDATE verse.realm_asks SET state = 'removing' WHERE id = aid;
    RETURN jsonb_build_object('status', 200, 'ask', aid, 'state', 'removing');
  END IF;
  n := verse.ask_revert(s, a.did);
  DELETE FROM verse.realm_asks WHERE id = aid;
  RETURN jsonb_build_object('status', 200, 'deleted', aid, 'reverted', n);
END $$;


--
-- Name: ask_diff(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_diff(b jsonb, a jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.ask_diff_0078(b, a)
    || CASE WHEN b->>'palette' IS DISTINCT FROM a->>'palette' THEN jsonb_build_object('palette', jsonb_build_array(b->'palette', a->'palette')) ELSE '{}' END $$;


--
-- Name: ask_diff_0078(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_diff_0078(b jsonb, a jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('before', coalesce(jsonb_object_agg(k, b->'rows'->k), '{}'), 'after', coalesce(jsonb_object_agg(k, a->'rows'->k), '{}'))
    || CASE WHEN b->>'ground' IS DISTINCT FROM a->>'ground' THEN jsonb_build_object('ground', jsonb_build_array(b->'ground', a->'ground')) ELSE '{}' END
    || CASE WHEN b->>'time' IS DISTINCT FROM a->>'time' THEN jsonb_build_object('time', jsonb_build_array(b->'time', a->'time')) ELSE '{}' END
  FROM (SELECT k FROM (SELECT jsonb_object_keys(coalesce(b->'rows', '{}')) k UNION SELECT jsonb_object_keys(coalesce(a->'rows', '{}'))) u
        WHERE CASE WHEN coalesce((a->>'made')::boolean, false) THEN b->'rows'->k IS DISTINCT FROM a->'rows'->k
                   ELSE b->'rows'->k->'on' IS DISTINCT FROM a->'rows'->k->'on' END) x $$;


--
-- Name: ask_doc_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_doc_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  pid bigint := (asked->>'id')::bigint;
  s text := (SELECT slug FROM verse.realm_plans WHERE id = pid);
  who text := (SELECT player FROM verse.realm_plans WHERE id = pid);
  nm text := coalesce(nullif(asked->>'doc', ''), 'document');
  before jsonb := verse.ask_state(s);
  now_st jsonb;
  res jsonb;
  dd jsonb;
  said jsonb;
  it jsonb;
  w text;
  f text;
  keys text[];
  claimed text[] := '{}';
  did jsonb;
  st text;
  applied int := 0;
  waiting int := 0;
  rest text[];
BEGIN
  res := verse.fork_revise_answer(asked - 'doc', http, response, model, taken);
  IF (res->>'status')::int <> 200 THEN RETURN res; END IF;
  now_st := verse.ask_state(s);
  dd := verse.ask_diff(before, now_st);
  -- a hand-built realm's answer names every row; the ones it didn't change keep what they held (as 0078's)
  IF NOT coalesce((before->>'made')::boolean, false) THEN
    UPDATE verse.realm_edit SET
      switched = (switched - ARRAY(SELECT kk FROM jsonb_object_keys(before->'rows') kk WHERE NOT coalesce(dd->'after', '{}') ? kk))
              || coalesce((SELECT jsonb_object_agg(kk, v->'raw') FROM jsonb_each(before->'rows') x(kk, v)
                           WHERE NOT coalesce(dd->'after', '{}') ? kk AND jsonb_typeof(v->'raw') = 'boolean'), '{}')
    WHERE slug = s;
  END IF;
  BEGIN said := verse.builder_said(response)::jsonb; EXCEPTION WHEN others THEN said := NULL; END;
  FOR it IN SELECT e FROM jsonb_array_elements(CASE WHEN jsonb_typeof(said->'asked') = 'array' THEN said->'asked' ELSE '[]' END) WITH ORDINALITY t(e, o)
            WHERE jsonb_typeof(e) = 'object' ORDER BY o LIMIT 40 LOOP
    w := verse.builder_line(it->'thing', 200);
    CONTINUE WHEN w = '';
    f := coalesce(verse.builder_line(it->'feature', 60), 'none');
    keys := ARRAY(SELECT kk FROM jsonb_object_keys(coalesce(dd->'after', '{}')) kk
                  WHERE f <> 'none' AND NOT kk = ANY (claimed)
                    AND (kk = f OR verse.ask_doc_row(dd, kk)->>'feature' = f
                         OR (verse.ask_doc_row(dd, kk)->>'feature' = 'row' AND verse.ask_doc_row(dd, kk)->>'variant' = f)));
    claimed := claimed || keys;
    did := jsonb_build_object('before', coalesce((SELECT jsonb_object_agg(kk, dd->'before'->kk) FROM unnest(keys) kk), '{}'),
                              'after', coalesce((SELECT jsonb_object_agg(kk, dd->'after'->kk) FROM unnest(keys) kk), '{}'));
    IF f = 'setup' THEN did := did || (dd - 'before' - 'after'); dd := dd - 'ground' - 'time' - 'palette'; END IF;
    st := CASE WHEN verse.ask_changed(did) OR (f NOT IN ('none', 'setup') AND verse.ask_doc_there(now_st, f)) THEN 'applied' ELSE 'waiting' END;
    INSERT INTO verse.realm_asks (slug, ms, player, words, state, plan, did)
    VALUES (s, verse.now_ms(), who, w, st, pid, CASE WHEN st = 'applied' AND verse.ask_changed(did) THEN did ELSE '{}' END);
    IF st = 'applied' THEN applied := applied + 1; ELSE waiting := waiting + 1; END IF;
  END LOOP;
  -- what it changed that no line claimed: one more line holds it, so DELETE can take it back too
  rest := ARRAY(SELECT kk FROM jsonb_object_keys(coalesce(dd->'after', '{}')) kk WHERE NOT kk = ANY (claimed));
  did := jsonb_build_object('before', coalesce((SELECT jsonb_object_agg(kk, dd->'before'->kk) FROM unnest(rest) kk), '{}'),
                            'after', coalesce((SELECT jsonb_object_agg(kk, dd->'after'->kk) FROM unnest(rest) kk), '{}')) || (dd - 'before' - 'after');
  IF verse.ask_changed(did) THEN
    INSERT INTO verse.realm_asks (slug, ms, player, words, state, plan, did)
    VALUES (s, verse.now_ms(), who, left('The rest of ' || nm, 400), 'applied', pid, did);
    applied := applied + 1;
  END IF;
  -- nothing named and nothing changed: the document itself waits, never dropped
  IF applied + waiting = 0 THEN
    INSERT INTO verse.realm_asks (slug, ms, player, words, state, plan) VALUES (s, verse.now_ms(), who, left('What ' || nm || ' asks for', 400), 'waiting', pid);
    waiting := 1;
  END IF;
  RETURN jsonb_build_object('status', 200, 'applied', applied, 'waiting', waiting,
    'lines', 'doc ' || (applied + waiting) || ' ' || applied || ' applied ' || waiting || E' waiting\n' || coalesce(res->>'lines', verse.edit_rows(s)));
END $$;


--
-- Name: ask_doc_ask(text, jsonb, integer, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_doc_ask(s text, d jsonb, cap integer, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  nm text := coalesce(nullif(verse.builder_line(d->'name', 80), ''), 'document');
  x jsonb := verse.edit_revise_ask(s, jsonb_build_object('prompt', 'the design document ' || nm), cap, k, site_admin);
  made boolean := verse.edit_made(s) AND (verse.fork_of(s)).slug IS NULL;
  t text;
  sch jsonb;
  ids jsonb;
  parts jsonb;
BEGIN
  IF (x->>'status')::int <> 200 OR NOT x ? 'request' THEN RETURN x; END IF;
  IF coalesce(d->>'text', '') = '' AND coalesce(d->>'pdf', '') = '' THEN RETURN '{"status":400,"error":"that document has no words in it"}'; END IF;
  t := split_part(x #>> '{request,contents,0,parts,0,text}', E'\nThey now say: ', 1)
    || E'\nThey dropped their design document "' || nm || '". In "asked", list every feature or change it asks for, in its order, '
    || 'each in a few of its own words (at most 40 of them), with the feature that makes it'
    || CASE WHEN made THEN ', setup for how it looks (its ground, time of day or colours),' ELSE '' END
    || ' or none when nothing here does. Then answer the board with every one a feature makes on, and keep everything else as it is.';
  IF coalesce(d->>'text', '') <> '' THEN t := t || E'\nThe document:\n' || left(d->>'text', 60000); END IF;
  parts := jsonb_build_array(jsonb_build_object('text', t));
  IF coalesce(d->>'pdf', '') <> '' THEN
    parts := parts || jsonb_build_array(jsonb_build_object('inlineData', jsonb_build_object('mimeType', 'application/pdf', 'data', d->>'pdf')));
  END IF;
  x := jsonb_set(x, '{request,contents,0,parts}', parts);
  sch := x #> '{request,generationConfig,responseSchema}';
  ids := CASE WHEN made THEN to_jsonb(verse.builder_order() || ARRAY['setup', 'none'])
              ELSE coalesce(sch #> '{properties,features,items,properties,id,enum}', '[]') || '["none"]' END;
  sch := jsonb_set(sch, '{properties,asked}', jsonb_build_object('type', 'array', 'items', jsonb_build_object('type', 'object',
    'required', jsonb_build_array('thing', 'feature'), 'propertyOrdering', jsonb_build_array('thing', 'feature'),
    'properties', jsonb_build_object('thing', jsonb_build_object('type', 'string'), 'feature', jsonb_build_object('type', 'string', 'enum', ids)))));
  sch := jsonb_set(sch, '{required}', '["asked"]'::jsonb || (coalesce(sch->'required', '[]') - 'asked'));
  IF sch ? 'propertyOrdering' THEN sch := jsonb_set(sch, '{propertyOrdering}', '["asked"]'::jsonb || ((sch->'propertyOrdering') - 'asked')); END IF;
  x := jsonb_set(x, '{request,generationConfig,responseSchema}', sch);
  x := jsonb_set(x, '{request,generationConfig,maxOutputTokens}', '8000');
  RETURN x || jsonb_build_object('doc', nm);
END $$;


--
-- Name: ask_doc_row(jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_doc_row(dd jsonb, key text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(nullif(dd->'after'->key, 'null'::jsonb), dd->'before'->key) $$;


--
-- Name: ask_doc_there(jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_doc_there(st jsonb, f text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN coalesce((st->>'made')::boolean, false)
    THEN EXISTS (SELECT 1 FROM jsonb_each(coalesce(st->'rows', '{}')) r
                 WHERE (r.value->>'feature' = f OR (r.value->>'feature' = 'row' AND r.value->>'variant' = f)) AND coalesce((r.value->>'on')::boolean, true))
    ELSE coalesce((st->'rows'->f->>'on')::boolean, false) END $$;


--
-- Name: ask_done(text, bigint, jsonb, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_done(s text, aid bigint, body jsonb, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  a verse.realm_asks;
  hash text := CASE WHEN jsonb_typeof(body->'commit') = 'string' AND body->>'commit' ~ '^[0-9a-f]{40}$' THEN body->>'commit' END;
BEGIN
  IF NOT site_admin THEN RETURN '{"status":403,"error":"a site admin"}'; END IF;
  IF hash IS NULL THEN RETURN '{"status":400,"error":"the commit, 40 hex digits"}'; END IF;
  SELECT * INTO a FROM verse.realm_asks WHERE id = aid AND slug = s FOR UPDATE;
  IF a.id IS NULL THEN RETURN '{"status":404,"error":"no such ask"}'; END IF;
  IF a.kind = 'remove' OR a.state = 'removing' THEN
    DELETE FROM verse.realm_asks WHERE id = aid;
    RETURN jsonb_build_object('status', 200, 'ask', aid, 'state', 'gone');
  END IF;
  IF a.state = 'applied' THEN RETURN jsonb_build_object('status', 409, 'error', 'already applied'); END IF;
  UPDATE verse.realm_asks SET state = 'applied', commit_hash = hash, done_ms = verse.now_ms() WHERE id = aid;
  RETURN jsonb_build_object('status', 200, 'ask', aid, 'state', 'applied');
END $_$;


--
-- Name: ask_list(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_list(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg('ask ' || id || ' ' || CASE WHEN state = 'asking' THEN 'waiting' ELSE state END || ' ' || kind || ' ' || words, E'\n' ORDER BY id DESC) || E'\n', '')
  FROM (SELECT * FROM verse.realm_asks WHERE slug = s AND verse.edit_may(s, k, site_admin) ORDER BY id DESC LIMIT 40) x $$;


--
-- Name: ask_revert(text, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_revert(s text, did jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  n int := verse.ask_revert_0078(s, did);
BEGIN
  IF did ? 'palette' THEN
    UPDATE verse.made_realms SET palette = coalesce(did->'palette'->>0, palette) WHERE slug = s AND palette IS NOT DISTINCT FROM did->'palette'->>1;
  END IF;
  RETURN n;
END $$;


--
-- Name: ask_revert_0078(text, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_revert_0078(s text, did jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  cur jsonb := verse.ask_state(s);
  made boolean := coalesce((cur->>'made')::boolean, false);
  back jsonb := '{}';
  k text;
  was jsonb;
  left_as jsonb;
  n int := 0;
BEGIN
  FOR k IN SELECT jsonb_object_keys(coalesce(did->'after', '{}')) LOOP
    left_as := nullif(did->'after'->k, 'null'::jsonb);
    was := did->'before'->k;
    IF made AND (cur->'rows'->k) IS NOT DISTINCT FROM left_as THEN back := back || jsonb_build_object(k, was); END IF;
    IF NOT made AND cur->'rows' ? k AND (cur->'rows'->k->'on') IS NOT DISTINCT FROM (left_as->'on') THEN back := back || jsonb_build_object(k, was); END IF;
  END LOOP;
  n := (SELECT count(*) FROM jsonb_object_keys(back));
  IF made AND (n > 0 OR did ? 'ground' OR did ? 'time') THEN
    UPDATE verse.made_realms SET
      features = coalesce((SELECT jsonb_agg(f ORDER BY o) FROM jsonb_array_elements(features) WITH ORDINALITY AS x(f, o) WHERE NOT back ? verse.edit_key(f)), '[]')
              || coalesce((SELECT jsonb_agg(v - 'on') FROM jsonb_each(back) x(kk, v) WHERE jsonb_typeof(v) = 'object' AND (v->>'on')::boolean), '[]'),
      off = coalesce((SELECT jsonb_agg(f ORDER BY o) FROM jsonb_array_elements(off) WITH ORDINALITY AS x(f, o) WHERE NOT back ? verse.edit_key(f)), '[]')
         || coalesce((SELECT jsonb_agg(v - 'on') FROM jsonb_each(back) x(kk, v) WHERE jsonb_typeof(v) = 'object' AND NOT (v->>'on')::boolean), '[]'),
      ground = CASE WHEN did ? 'ground' AND ground IS NOT DISTINCT FROM did->'ground'->>1 THEN coalesce(did->'ground'->>0, ground) ELSE ground END,
      time = CASE WHEN did ? 'time' AND time IS NOT DISTINCT FROM did->'time'->>1 THEN coalesce(did->'time'->>0, time) ELSE time END,
      settings_ms = verse.now_ms()
    WHERE slug = s;
  ELSIF n > 0 THEN
    UPDATE verse.realm_edit SET
      switched = (switched - ARRAY(SELECT jsonb_object_keys(back)))
              || coalesce((SELECT jsonb_object_agg(kk, v->'raw') FROM jsonb_each(back) x(kk, v) WHERE jsonb_typeof(v->'raw') = 'boolean'), '{}'),
      ms = verse.now_ms()
    WHERE slug = s;
  END IF;
  RETURN n;
END $$;


--
-- Name: ask_row_delete(text, text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_row_delete(s text, key text, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.ask_row_delete_0110(s, key, k, site_admin)) $$;


--
-- Name: ask_row_delete_0110(text, text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_row_delete_0110(s text, key text, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  m verse.made_realms;
  label text;
  before jsonb;
  aid bigint;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s FOR UPDATE;
  IF m.slug IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(verse.edit_made_board(m)) f WHERE verse.edit_key(f) = key) THEN RETURN '{"status":404,"error":"no such row"}'; END IF;
    UPDATE verse.made_realms SET
      features = coalesce((SELECT jsonb_agg(f ORDER BY o) FROM jsonb_array_elements(features) WITH ORDINALITY AS x(f, o) WHERE verse.edit_key(f) <> key), '[]'),
      off = coalesce((SELECT jsonb_agg(f ORDER BY o) FROM jsonb_array_elements(off) WITH ORDINALITY AS x(f, o) WHERE verse.edit_key(f) <> key), '[]'),
      settings_ms = verse.now_ms()
    WHERE slug = s;
    -- the asks that changed it no longer can: their part goes, and an ask with nothing left goes too
    UPDATE verse.realm_asks SET did = jsonb_set(jsonb_set(did, '{before}', (did->'before') - key), '{after}', (did->'after') - key)
    WHERE slug = s AND did->'after' ? key;
    DELETE FROM verse.realm_asks WHERE slug = s AND state = 'applied' AND commit_hash IS NULL AND NOT verse.ask_changed(did);
    RETURN jsonb_build_object('status', 200, 'deleted', key);
  END IF;
  SELECT r->>'label' INTO label FROM verse.realm_rights h, jsonb_array_elements(h.rows) r WHERE h.slug = s AND r->>'id' = key;
  IF label IS NULL THEN RETURN '{"status":404,"error":"no such row"}'; END IF;
  SELECT id INTO aid FROM verse.realm_asks WHERE slug = s AND kind = 'remove' AND row_key = key LIMIT 1;
  IF aid IS NOT NULL THEN RETURN jsonb_build_object('status', 200, 'ask', aid, 'state', 'waiting'); END IF;
  before := verse.ask_state(s);
  INSERT INTO verse.realm_edit (slug, switched, ms, by_player) VALUES (s, jsonb_build_object(key, false), verse.now_ms(), (verse.builder_player(k)).id)
  ON CONFLICT (slug) DO UPDATE SET switched = verse.realm_edit.switched || jsonb_build_object(key, false), ms = excluded.ms, by_player = excluded.by_player;
  INSERT INTO verse.realm_asks (slug, ms, player, words, kind, row_key, state, did)
  VALUES (s, verse.now_ms(), (verse.builder_player(k)).id, left('Take out ' || label, 400), 'remove', key, 'waiting', verse.ask_diff(before, verse.ask_state(s)))
  RETURNING id INTO aid;
  RETURN jsonb_build_object('status', 200, 'ask', aid, 'state', 'waiting');
END $$;


--
-- Name: ask_state(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.ask_state(s text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  m verse.made_realms;
  e verse.realm_edit;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NOT NULL THEN
    RETURN jsonb_build_object('made', true, 'ground', m.ground, 'time', m.time, 'palette', m.palette,
      'rows', coalesce((SELECT jsonb_object_agg(verse.edit_key(f), f) FROM jsonb_array_elements(verse.edit_made_board(m)) f), '{}'));
  END IF;
  SELECT * INTO e FROM verse.realm_edit WHERE slug = s;
  RETURN jsonb_build_object('made', false,
    'rows', coalesce((SELECT jsonb_object_agg(b->>'id', jsonb_build_object('on', (b->>'on')::boolean, 'raw', e.switched->(b->>'id')))
                      FROM jsonb_array_elements(verse.edit_hand_board(s)) b), '{}'));
END $$;


--
-- Name: b64(bytea); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.b64(b bytea) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT translate(encode(b, 'base64'), E'\n', '') $$;


