--
-- Name: builder_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  r jsonb;
  t text;
  d jsonb;
  held jsonb;
  err text;
  status int := 200;
BEGIN
  BEGIN r := response::jsonb; EXCEPTION WHEN others THEN r := NULL; END;
  IF http = 200 AND r IS NOT NULL THEN
    SELECT string_agg(p->>'text', '') INTO t
    FROM jsonb_array_elements(coalesce(r->'candidates'->0->'content'->'parts', '[]')) p
    WHERE coalesce((p->>'thought')::boolean, false) = false AND p ? 'text';
    BEGIN d := t::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
    IF d IS NULL THEN status := 503; err := 'no answer';
    ELSE held := verse.builder_hold(d); IF held IS NULL THEN status := 502; err := 'not a board'; END IF;
    END IF;
  ELSE
    status := 503;
    err := CASE WHEN http = 429 THEN 'busy' WHEN http = 0 THEN 'model unreachable' ELSE 'model error ' || http END;
  END IF;
  IF held IS NOT NULL THEN held := held || verse.builder_setup(asked->'setup'); END IF;
  UPDATE verse.realm_plans SET board = held, error = err, model = builder_answer.model, ms_taken = taken WHERE id = (asked->>'id')::bigint;
  IF held IS NULL THEN RETURN jsonb_build_object('status', status, 'error', err); END IF;
  RETURN jsonb_build_object('status', 200, 'plan', (asked->>'id')::bigint, 'board', held, 'model', model,
                            'lines', verse.builder_lines((asked->>'id')::bigint, held));
END $$;


--
-- Name: builder_answer(jsonb, integer, text, text, integer, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_answer(asked jsonb, http integer, response text, model text, taken integer, request jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  pid bigint := (asked->>'id')::bigint;
  out jsonb := verse.builder_answer_0078(asked, http, response, model, taken, request);
  prev jsonb;
  nb jsonb;
  d jsonb;
BEGIN
  IF (out->>'status')::int <> 200 OR out ? 'retry' OR NOT out ? 'board' THEN RETURN out; END IF;
  SELECT board_in->'wanted' INTO prev FROM verse.realm_plans WHERE id = pid;
  -- every thing the planner named (not only the first six it checks the board against)
  BEGIN d := verse.builder_said(response)::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
  nb := (out->'board') || jsonb_build_object('wanted', verse.builder_wanted(verse.builder_wanted(prev, NULL) || coalesce(out->'board'->'wanted', '[]'),
                                                                            CASE WHEN jsonb_typeof(d) = 'object' THEN d->'asked' ELSE out->'asked' END));
  UPDATE verse.realm_plans SET board = nb WHERE id = pid;
  RETURN out || jsonb_build_object('board', nb, 'lines', verse.builder_lines(pid, nb));
END $$;


--
-- Name: builder_answer_0078(jsonb, integer, text, text, integer, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_answer_0078(asked jsonb, http integer, response text, model text, taken integer, request jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  again boolean := coalesce((asked->>'retry')::boolean, false);
  plan_id bigint := (asked->>'id')::bigint;
  first_board jsonb;
  first_wants jsonb;
  out jsonb;
  said text := verse.builder_said(response);
  d jsonb;
  wants jsonb;
  missing jsonb;
  nb jsonb;
  failed boolean := false;
BEGIN
  IF again THEN SELECT p.board, p.asked_for INTO first_board, first_wants FROM verse.realm_plans p WHERE p.id = plan_id; END IF;
  out := verse.builder_answer(asked - 'retry', http, response, model, taken);
  BEGIN d := said::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
  wants := verse.builder_wants(CASE WHEN jsonb_typeof(d) = 'object' THEN d->'asked' END);
  IF wants IS NULL OR (again AND wants = '[]') THEN wants := coalesce(first_wants, '[]'); END IF;
  IF (out->>'status')::int <> 200 THEN
    IF NOT again OR first_board IS NULL THEN RETURN out; END IF;
    nb := first_board;   -- the second try failed: the first board, already repaired
    failed := true;
  ELSE
    nb := out->'board';
    missing := verse.builder_missing(wants, nb);
    IF jsonb_array_length(missing) > 0 THEN
      nb := verse.builder_repair(nb, missing);
      IF NOT again AND request IS NOT NULL THEN
        UPDATE verse.realm_plans SET board = nb, asked_for = wants, retried = true, repaired = missing WHERE id = plan_id;
        RETURN jsonb_build_object('status', 200, 'retry', verse.builder_retry(request, said, missing));
      END IF;
    END IF;
  END IF;
  UPDATE verse.realm_plans SET board = nb, error = NULL, asked_for = wants, ms_taken = taken,
    repaired = CASE WHEN jsonb_array_length(coalesce(missing, '[]')) > 0 THEN missing WHEN again AND NOT failed THEN NULL ELSE repaired END
  WHERE id = plan_id;
  RETURN jsonb_build_object('status', 200, 'plan', plan_id, 'board', nb, 'model', model, 'asked', wants,
                            'lines', verse.builder_lines(plan_id, nb));
END $$;


--
-- Name: builder_ask(jsonb, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_ask(body jsonb, cap integer, k text) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.builder_fast(verse.builder_ask_0059(body, cap, k)) $$;


--
-- Name: builder_ask_0059(jsonb, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_ask_0059(body jsonb, cap integer, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  said text := CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'prompt', 600) ELSE '' END;
  rec verse.players := verse.builder_player(k);
  board jsonb := verse.builder_board_of(body, rec);
  setup jsonb := verse.builder_setup(CASE WHEN jsonb_typeof(body) = 'object' THEN body->'setup' END);
  row_id bigint;
  text_in text;
BEGIN
  IF said = '' THEN RETURN '{"status":400,"error":"say what world you want"}'; END IF;
  IF rec.id IS NOT NULL AND EXISTS (SELECT 1 FROM verse.realm_plans WHERE player = rec.id AND ms > verse.now_ms() - 2000) THEN
    RETURN '{"status":429,"error":"one at a time"}';
  END IF;
  IF (SELECT count(*) FROM verse.realm_plans WHERE ms > (extract(epoch FROM date_trunc('day', now())) * 1000)::bigint) >= cap THEN
    RETURN '{"status":503,"error":"the day''s plans are used up"}';
  END IF;
  INSERT INTO verse.realm_plans (ms, player, prompt, board_in) VALUES (verse.now_ms(), rec.id, said, board) RETURNING id INTO row_id;
  text_in := CASE WHEN board IS NULL THEN said
                  ELSE 'The current board: ' || (board - 'features' || jsonb_build_object('features',
                         (SELECT coalesce(jsonb_agg(f - 'label'), '[]') FROM jsonb_array_elements(board->'features') f)))::text
                       || E'\nThey now say: ' || said END;
  IF setup <> '{}' THEN text_in := 'Fixed in setup: ' || setup::text || E'\n' || text_in; END IF;
  RETURN jsonb_build_object('status', 200, 'id', row_id, 'setup', setup, 'request', jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text', verse.builder_prompt()))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(jsonb_build_object('text', text_in)))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json', 'responseSchema', verse.builder_schema(),
      'temperature', 0.4, 'maxOutputTokens', 4000, 'thinkingConfig', jsonb_build_object('thinkingLevel', 'LOW'))));
END $$;


--
-- Name: players; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.players (
    id text NOT NULL,
    key_sha256 text NOT NULL,
    account text,
    created_ms bigint NOT NULL,
    auto text,
    source text,
    name text
);


--
-- Name: builder_board_of(jsonb, verse.players); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_board_of(body jsonb, rec verse.players) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  b jsonb;
BEGIN
  IF jsonb_typeof(body) <> 'object' THEN RETURN NULL; END IF;
  IF jsonb_typeof(body->'plan') = 'number' AND jsonb_typeof(body->'on') = 'array' THEN
    SELECT p.board INTO b FROM verse.realm_plans p WHERE p.id = (body->>'plan')::bigint AND p.player = rec.id AND p.board IS NOT NULL;
    IF b IS NULL THEN RETURN NULL; END IF;
    RETURN b - 'features' || verse.builder_setup(body->'setup') || jsonb_build_object('features', coalesce((SELECT jsonb_agg(f || jsonb_build_object('on',
        CASE WHEN jsonb_typeof(body->'on'->((o - 1)::int)) = 'boolean' THEN (body->'on'->>((o - 1)::int))::boolean ELSE (f->>'on')::boolean END) ORDER BY o)
      FROM jsonb_array_elements(b->'features') WITH ORDINALITY AS t(f, o)), '[]'));
  END IF;
  b := verse.builder_hold(body->'board');
  RETURN CASE WHEN b IS NULL THEN NULL ELSE b || verse.builder_setup(body->'setup') END;
END $$;


