CREATE FUNCTION verse.builder_card_kept(s text, kb integer) RETURNS bigint
    LANGUAGE sql
    AS $$
  UPDATE verse.made_realms SET card_ms = verse.now_ms(), card_kb = kb WHERE slug = s RETURNING card_ms $$;


--
-- Name: builder_card_may(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_card_may(s text, k text, site_admin boolean) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s AND visibility = 'private') AND verse.builder_card_may_0099(s, k, site_admin) = 200 THEN 409
              ELSE verse.builder_card_may_0099(s, k, site_admin) END $$;


--
-- Name: builder_card_may_0099(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_card_may_0099(s text, k text, site_admin boolean) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN NOT verse.edit_made(s) THEN 404 WHEN verse.edit_may(s, k, site_admin) THEN 200 ELSE 403 END $$;


