CREATE TABLE verse.made_realms (
    slug text NOT NULL,
    world text NOT NULL,
    name text NOT NULL,
    style text NOT NULL,
    ground text NOT NULL,
    "time" text NOT NULL,
    features jsonb NOT NULL,
    tools jsonb NOT NULL,
    placed jsonb DEFAULT '[]'::jsonb NOT NULL,
    plan bigint,
    made_ms bigint NOT NULL,
    settings_ms bigint,
    page_ms bigint,
    page_note text,
    camera text DEFAULT 'third'::text NOT NULL,
    off jsonb DEFAULT '[]'::jsonb NOT NULL,
    description text,
    card_ms bigint,
    card_kb integer,
    edited_ms bigint,
    page_rev integer DEFAULT 0 NOT NULL,
    base text,
    forked_from text,
    published_ms bigint,
    palette text DEFAULT 'natural'::text NOT NULL,
    rev bigint DEFAULT 1 NOT NULL,
    moved jsonb DEFAULT '[]'::jsonb NOT NULL,
    forked_rev bigint,
    unlisted boolean DEFAULT false NOT NULL,
    published_rev bigint,
    published_sha256 text,
    undo jsonb DEFAULT '[]'::jsonb NOT NULL,
    visibility text DEFAULT 'private'::text NOT NULL,
    published_engine text,
    published_engine_sha256 text,
    shaped jsonb DEFAULT '[]'::jsonb NOT NULL,
    lore jsonb DEFAULT '{}'::jsonb NOT NULL,
    quests jsonb DEFAULT '{}'::jsonb NOT NULL,
    lore_since bigint,
