    CONSTRAINT made_realms_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'unlisted'::text, 'public'::text])))
);


--
-- Name: builder_card_path(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_card_path(m verse.made_realms) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT regexp_replace(verse.builder_card_path_0110(m), '^/realms/', '/worlds/') $$;


--
-- Name: builder_card_path_0110(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_card_path_0110(m verse.made_realms) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN m.card_ms IS NOT NULL THEN '/realms/' || m.slug || '/card.jpg?v=' || m.card_ms ELSE '/og/default.jpg' END $$;


--
-- Name: builder_card_want(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_card_want(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s AND visibility = 'private') THEN 'no'
              ELSE verse.builder_card_want_0099(s, k, site_admin) END $$;


--
-- Name: builder_card_want_0099(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_card_want_0099(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN m.card_ms IS NULL AND (verse.builder_owns(k, s) OR site_admin) THEN 'want'
              WHEN verse.builder_owns(k, s) AND coalesce(m.edited_ms, 0) > m.card_ms THEN 'want'
              ELSE 'no' END
  FROM verse.made_realms m WHERE m.slug = s $$;


