  SELECT verse.worlds_answer(verse.builder_decide_0110(s, pid, accept, k)) $$;


--
-- Name: builder_decide_0110(text, bigint, boolean, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_decide_0110(s text, pid bigint, accept boolean, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  p verse.realm_proposals;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s) THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF NOT verse.builder_owns(k, s) THEN RETURN '{"status":403,"error":"only its owner"}'; END IF;
  SELECT * INTO p FROM verse.realm_proposals WHERE id = pid AND slug = s FOR UPDATE;
  IF p.id IS NULL THEN RETURN '{"status":404,"error":"no such proposal"}'; END IF;
  IF p.state <> 'waiting' THEN RETURN jsonb_build_object('status', 409, 'error', 'already ' || p.state); END IF;
  UPDATE verse.realm_proposals SET state = CASE WHEN accept THEN 'accepted' ELSE 'declined' END, decided_ms = verse.now_ms() WHERE id = pid;
  IF accept THEN UPDATE verse.made_realms SET placed = placed || jsonb_build_array(p.change - 'kind') WHERE slug = s; END IF;
  RETURN jsonb_build_object('status', 200, 'state', CASE WHEN accept THEN 'accepted' ELSE 'declined' END);
END $$;


--
-- Name: builder_describe(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_describe(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.builder_describe_0110(s, body, k, site_admin)) $$;


--
-- Name: builder_describe_0110(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_describe_0110(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  line text := CASE WHEN jsonb_typeof(body) = 'object' AND jsonb_typeof(body->'description') = 'string' THEN verse.builder_one_line(body->'description', 200) END;
  m verse.made_realms;
BEGIN
  IF NOT verse.edit_made(s) THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF NOT verse.edit_may(s, k, site_admin) THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF line IS NULL THEN RETURN '{"status":400,"error":"a description"}'; END IF;
  UPDATE verse.made_realms SET description = nullif(line, '') WHERE slug = s RETURNING * INTO m;
  RETURN jsonb_build_object('status', 200, 'description', verse.builder_share_line(m));
END $$;


--
-- Name: builder_doc_ask(jsonb, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_doc_ask(d jsonb, cap integer, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  nm text := coalesce(nullif(verse.builder_line(d->'name', 80), ''), 'document');
  said text := 'the design document ' || nm;
  x jsonb;
  t text;
  parts jsonb;
BEGIN
  IF coalesce(d->>'text', '') = '' AND coalesce(d->>'pdf', '') = '' THEN RETURN '{"status":400,"error":"that document has no words in it"}'; END IF;
  x := verse.builder_ask(jsonb_build_object('prompt', said) || CASE WHEN jsonb_typeof(d->'setup') = 'object' THEN jsonb_build_object('setup', d->'setup') ELSE '{}' END, cap, k);
  IF (x->>'status')::int <> 200 OR NOT x ? 'request' THEN RETURN x; END IF;
  t := replace(x #>> '{request,contents,0,parts,0,text}', said,
         'They dropped their design document "' || nm || '": plan the realm it describes. In "asked", name every thing it asks for, '
         || 'in its order (at most 40), each with the feature that makes it or none.'
         || CASE WHEN coalesce(d->>'text', '') <> '' THEN E'\nThe document:\n' || left(d->>'text', 60000) ELSE '' END);
  parts := jsonb_build_array(jsonb_build_object('text', t));
  IF coalesce(d->>'pdf', '') <> '' THEN
    parts := parts || jsonb_build_array(jsonb_build_object('inlineData', jsonb_build_object('mimeType', 'application/pdf', 'data', d->>'pdf')));
  END IF;
  x := jsonb_set(x, '{request,contents,0,parts}', parts);
  RETURN jsonb_set(x, '{request,generationConfig,maxOutputTokens}', '8000');
END $$;


--
-- Name: builder_fast(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_fast(x jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(x->'request'->'generationConfig') = 'object'
              THEN jsonb_set(x, '{request,generationConfig,thinkingConfig}', '{"thinkingBudget": 0}')
              ELSE x END $$;


--
-- Name: builder_grounds(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_grounds() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT ARRAY['meadow', 'forest', 'desert', 'snow', 'stone', 'beach'] $$;


--
-- Name: builder_hold(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_hold(d jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT h || jsonb_build_object('features', coalesce((
    SELECT jsonb_agg(f ORDER BY o) FROM jsonb_array_elements(h->'features') WITH ORDINALITY AS t(f, o)
    WHERE c IS NULL OR NOT (
         (f->>'feature' = 'props' AND f->>'variant' = c AND c IN ('fountain', 'statue', 'well', 'campfire'))
      OR (f->>'feature' = 'building' AND f->>'variant' = 'tower' AND c = 'tower')
      OR (f->>'feature' = 'bigtree' AND c = 'tree')
      OR (f->>'feature' = 'water' AND coalesce(f->>'variant', 'pond') = 'pond' AND c = 'pond'))), '[]'))
  FROM (SELECT verse.builder_hold_0096(d) AS h) y,
       LATERAL (SELECT (SELECT f->>'variant' FROM jsonb_array_elements(y.h->'features') f WHERE f->>'feature' = 'centre' LIMIT 1) AS c) z
  WHERE h IS NOT NULL $$;


--
-- Name: builder_hold_0078(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_hold_0078(d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  nm text := CASE WHEN jsonb_typeof(d) = 'object' THEN verse.builder_line(d->'name', 30) ELSE '' END;
  f jsonb;
  h jsonb;
  kept jsonb := '[]';
  seen text[] := '{}';
  key text;
  counts jsonb := '{}';
BEGIN
  IF nm = '' THEN RETURN NULL; END IF;
  FOR f IN SELECT e FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'features') = 'array' THEN d->'features' ELSE '[]' END) e LIMIT 40 LOOP
    h := verse.builder_hold_feature(f);
    CONTINUE WHEN h IS NULL;
    key := h->>'feature' || ':' || coalesce(h->>'variant', h->>'tool', lower(h->>'name'), '');
    CONTINUE WHEN key = ANY (seen) AND h->>'feature' IN ('props', 'tool', 'character');
    CONTINUE WHEN coalesce((counts->>(h->>'feature'))::int, 0) >= (verse.builder_catalogue()->(h->>'feature')->>'most')::int;
    seen := seen || key;
    counts := counts || jsonb_build_object(h->>'feature', coalesce((counts->>(h->>'feature'))::int, 0) + 1);
    kept := kept || jsonb_build_array(h);
  END LOOP;
  kept := coalesce((SELECT jsonb_agg(e ORDER BY array_position(verse.builder_order(), e->>'feature'), o)
                    FROM jsonb_array_elements(kept) WITH ORDINALITY AS t(e, o)), '[]');
  RETURN jsonb_build_object('name', nm,
    'camera', verse.builder_pick(d->'camera', verse.builder_cameras()),
    'style', verse.builder_pick(d->'style', verse.builder_styles()),
    'ground', verse.builder_pick(d->'ground', verse.builder_grounds()),
    'time', verse.builder_pick(d->'time', verse.builder_times()),
    'features', kept);
END $$;


--
-- Name: builder_hold_0084(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_hold_0084(d jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT h || jsonb_build_object('palette', verse.builder_pick(d->'palette', verse.builder_palettes()),
                                 'wanted', verse.builder_wanted(d->'wanted', NULL))
  FROM (SELECT verse.builder_hold_0078(d) AS h) x WHERE h IS NOT NULL $$;


--
-- Name: builder_hold_0096(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_hold_0096(d jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT h || jsonb_build_object('features', coalesce((
    SELECT jsonb_agg(f ORDER BY o) FROM (
      SELECT f, o, row_number() OVER (PARTITION BY CASE WHEN f->>'feature' = 'building' THEN f->>'variant' ELSE o::text END ORDER BY o) AS k
      FROM jsonb_array_elements(h->'features') WITH ORDINALITY AS t(f, o)) x WHERE k = 1), '[]'))
  FROM (SELECT verse.builder_hold_0084(d) AS h) y WHERE h IS NOT NULL $$;


--
-- Name: builder_hold_feature(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_hold_feature(d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  h jsonb := verse.builder_hold_feature_0096(d);
  c jsonb := verse.builder_catalogue()->(h->>'feature');
  v jsonb;
BEGIN
  IF h IS NULL OR NOT (c ? 'kind') THEN RETURN h; END IF;
  v := CASE WHEN jsonb_typeof(d->'kind') = 'string' THEN d->'kind' ELSE d->'variant' END;
  h := h || jsonb_build_object('variant', verse.builder_pick(v, c->'kind'));
  RETURN h || jsonb_build_object('label', verse.builder_label(h));
END $$;


--
-- Name: builder_hold_feature_0096(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_hold_feature_0096(d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  name text := CASE WHEN jsonb_typeof(d) = 'object' AND jsonb_typeof(d->'feature') = 'string' THEN d->>'feature' END;
  c jsonb := verse.builder_catalogue()->name;
  out jsonb;
  n numeric;
BEGIN
  IF c IS NULL OR name IS NULL THEN RETURN NULL; END IF;
  out := jsonb_build_object('feature', name, 'on', CASE WHEN jsonb_typeof(d->'on') = 'boolean' THEN (d->>'on')::boolean ELSE true END);
  IF c ? 'size' THEN out := out || jsonb_build_object('size', verse.builder_pick(d->'size', c->'size')); END IF;
  IF c ? 'variant' THEN out := out || jsonb_build_object('variant', verse.builder_pick(d->'variant', c->'variant')); END IF;
  IF c ? 'colour' THEN out := out || jsonb_build_object('colour', verse.builder_pick(d->'colour', c->'colour')); END IF;
  IF c ? 'tool' THEN
    IF NOT (jsonb_typeof(d->'tool') = 'string' AND c->'tool' ? (d->>'tool')) THEN RETURN NULL; END IF;
    out := out || jsonb_build_object('tool', d->>'tool');
  END IF;
  IF c ? 'count' THEN
    n := CASE WHEN jsonb_typeof(d->'count') = 'number' THEN round((d->>'count')::numeric) END;
    out := out || jsonb_build_object('count', CASE WHEN n IS NULL OR n <= 0 THEN (c->'count'->>2)::int
                                                   ELSE greatest((c->'count'->>0)::int, least((c->'count'->>1)::int, n))::int END);
  END IF;
  IF name = 'character' THEN
    IF verse.builder_line(d->'name', 24) = '' THEN RETURN NULL; END IF;
    out := out || jsonb_build_object('name', verse.builder_line(d->'name', 24),
                                     'role', coalesce(nullif(verse.builder_line(d->'role', 40), ''), 'lives here'));
  END IF;
  RETURN out || jsonb_build_object('label', verse.builder_label(out));
END $$;


--
-- Name: builder_html(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_html(s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(replace(replace(replace(coalesce(s, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;') $$;


--
-- Name: builder_label(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN f->>'feature' = 'enclosure' THEN
      CASE f->>'variant' WHEN 'wood' THEN 'A wooden fence' WHEN 'palisade' THEN 'A palisade of logs' WHEN 'hedge' THEN 'A hedge' ELSE 'Stone walls' END
      || ' round a ' || CASE f->>'size' WHEN 'small' THEN 'small ' WHEN 'large' THEN 'large ' ELSE '' END
      || CASE f->>'variant' WHEN 'hedge' THEN 'garden' ELSE 'yard' END || ', a gate each end'
    WHEN f->>'feature' = 'centre' THEN
      CASE f->>'variant' WHEN 'statue' THEN 'A statue' WHEN 'well' THEN 'A well' WHEN 'campfire' THEN 'A campfire'
                         WHEN 'tower' THEN 'A stone tower' WHEN 'stones' THEN 'A ring of standing stones' WHEN 'tree' THEN 'A giant tree'
                         WHEN 'pond' THEN 'A round pond' ELSE 'A fountain' END || ' in the middle'
    WHEN f->>'feature' = 'layout' THEN
      CASE f->>'variant' WHEN 'garden' THEN 'A garden: beds and trees inside' WHEN 'clearing' THEN 'A clearing, the trees all round it'
                         WHEN 'ring' THEN 'Set in a ring round the middle' WHEN 'village' THEN 'Houses round a green, facing it'
                         ELSE 'A square paved in flagstones' END
    WHEN f->>'feature' = 'path' THEN CASE f->>'variant' WHEN 'earth' THEN 'An earth path' ELSE 'A flagstone path' END || ' through the middle'
    WHEN f->>'feature' = 'props' AND f->>'variant' = 'dock' THEN 'A wooden dock on the water'
    ELSE verse.builder_label_0096(f) END $$;


--
-- Name: builder_label_0064(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label_0064(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE f->>'feature'
    WHEN 'water' THEN initcap(f->>'size') || ' pond'
    WHEN 'trees' THEN (f->>'count') || ' ' || CASE f->>'variant' WHEN 'mixed' THEN 'trees and bushes' ELSE (f->>'variant') || ' trees' END
    WHEN 'rocks' THEN (f->>'count') || ' rocks'
    WHEN 'plants' THEN (f->>'count') || ' ferns'
    WHEN 'lanterns' THEN (f->>'count') || ' ' || (f->>'colour') || ' lanterns'
    WHEN 'flock' THEN 'A flock of ' || (f->>'count') || ' ' || (f->>'variant') || 's'
    WHEN 'props' THEN CASE f->>'variant' WHEN 'crates' THEN 'Crates' WHEN 'barrels' THEN 'Barrels' WHEN 'wagon' THEN 'A wagon'
                                         WHEN 'fence' THEN 'A fence' ELSE 'A camp: chest and anvil' END
    WHEN 'character' THEN (f->>'name') || ', ' || (f->>'role')
    WHEN 'tool' THEN CASE f->>'tool' WHEN 'build' THEN 'Visitors can build' WHEN 'fly' THEN 'Visitors can fly'
                                     WHEN 'jump' THEN 'Visitors can jump' WHEN 'map' THEN 'A map for visitors'
                                     WHEN 'talk' THEN 'Visitors can talk to characters' ELSE 'Voice: talk out loud to characters' END
  END $$;


--
-- Name: builder_label_0078(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label_0078(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' = 'house' THEN
    CASE WHEN coalesce((f->>'count')::int, 1) = 1 THEN 'A ' || (f->>'size') || ' ' || (f->>'colour') || ' house'
         ELSE (f->>'count') || ' ' || (f->>'size') || ' ' || (f->>'colour') || ' houses' END
  ELSE verse.builder_label_0064(f) END $$;


--
-- Name: builder_label_0082(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label_0082(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE f->>'feature'
    WHEN 'herd' THEN 'A herd of ' || (f->>'count') || ' ' || CASE f->>'variant' WHEN 'horse' THEN 'horses' ELSE f->>'variant' END
    WHEN 'dwellings' THEN CASE WHEN (f->>'count')::int = 1 THEN 'A ' || (f->>'variant') ELSE (f->>'count') || ' ' || (f->>'variant') || 's' END
    WHEN 'village' THEN 'A village of ' || (f->>'count') || ' people'
    ELSE verse.builder_label_0078(f) END $$;


--
-- Name: builder_label_0084(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label_0084(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE f->>'feature'
    WHEN 'bigtree' THEN CASE f->>'variant' WHEN 'pine' THEN 'A giant pine' WHEN 'dead' THEN 'A giant dead tree' ELSE 'A giant tree' END
    ELSE verse.builder_label_0082(f) END $$;


--
-- Name: builder_label_0091(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label_0091(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE f->>'feature'
    WHEN 'land' THEN CASE f->>'variant' WHEN 'hills' THEN 'Rolling hills' WHEN 'mountains' THEN 'Mountains round it'
                                        WHEN 'cliffs' THEN 'Cliffs round it' WHEN 'floating' THEN 'A floating island in the sky'
                                        WHEN 'island' THEN 'An island in the sea' ELSE 'A volcano' END
    WHEN 'building' THEN CASE f->>'variant' WHEN 'cabin' THEN 'A log cabin' WHEN 'barn' THEN 'A red barn' WHEN 'windmill' THEN 'A windmill'
                                            WHEN 'lighthouse' THEN 'A lighthouse' WHEN 'castle' THEN 'A castle' WHEN 'tower' THEN 'A stone tower'
                                            WHEN 'market' THEN 'A market' WHEN 'shop' THEN 'A shop' WHEN 'saloon' THEN 'A saloon'
                                            WHEN 'temple' THEN 'A temple' ELSE 'Ruins' END
    WHEN 'water' THEN CASE coalesce(f->>'variant', 'pond') WHEN 'river' THEN 'A river' WHEN 'frozen' THEN initcap(f->>'size') || ' frozen pond'
                                                         WHEN 'lava' THEN initcap(f->>'size') || ' pool of lava' ELSE initcap(f->>'size') || ' pond' END
    WHEN 'herd' THEN CASE WHEN (f->>'count')::int = 1 THEN 'A ' || CASE f->>'variant' WHEN 'horse' THEN 'horse' ELSE f->>'variant' END
                          ELSE 'A herd of ' || (f->>'count') || ' ' || verse.builder_many(f->>'variant') END
    WHEN 'flock' THEN CASE WHEN (f->>'count')::int = 1 THEN 'A ' || (f->>'variant')
                           WHEN f->>'variant' IN ('crow', 'bat', 'owl', 'parrot', 'gull') THEN 'A flock of ' || (f->>'count') || ' ' || verse.builder_many(f->>'variant')
                           WHEN f->>'variant' = 'fairy' THEN (f->>'count') || ' glowing fairies'
                           ELSE (f->>'count') || ' ' || verse.builder_many(f->>'variant') END
    WHEN 'trees' THEN CASE f->>'variant' WHEN 'palm' THEN (f->>'count') || ' palm trees' WHEN 'blossom' THEN (f->>'count') || ' blossom trees'
                                         ELSE verse.builder_label_0084(f) END
    WHEN 'plants' THEN (f->>'count') || ' ' || CASE coalesce(f->>'variant', 'fern') WHEN 'fern' THEN 'ferns' WHEN 'flower' THEN 'flowers'
                                                    WHEN 'mushroom' THEN 'mushrooms, glowing after dark' WHEN 'cactus' THEN 'cacti' ELSE 'glowing crystals' END
    WHEN 'props' THEN CASE f->>'variant' WHEN 'campfire' THEN 'A campfire' WHEN 'boat' THEN 'Boats' WHEN 'bridge' THEN 'A bridge'
                                         WHEN 'signpost' THEN 'A signpost' WHEN 'well' THEN 'A well' WHEN 'treasure' THEN 'Treasure: a chest and gold'
                                         WHEN 'graves' THEN 'Gravestones' WHEN 'tumbleweeds' THEN 'Tumbleweeds' WHEN 'statue' THEN 'A statue'
                                         ELSE verse.builder_label_0084(f) END
    ELSE verse.builder_label_0084(f) END $$;


--
-- Name: builder_label_0096(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_label_0096(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE
    WHEN f->>'feature' = 'mist' THEN 'Mist over the land'
    WHEN f->>'feature' = 'building' AND f->>'variant' = 'pagoda' THEN 'A pagoda'
    WHEN f->>'feature' = 'building' AND f->>'variant' = 'longhouse' THEN 'A longhouse'
    WHEN f->>'feature' = 'building' AND f->>'variant' = 'market' THEN 'A market of stalls'
    WHEN f->>'feature' = 'water' AND f->>'variant' = 'river' AND f->>'size' = 'small' THEN 'A stream'
    WHEN f->>'feature' = 'trees' AND f->>'variant' = 'autumn' THEN (f->>'count') || ' autumn trees, orange and red'
    WHEN f->>'feature' = 'trees' AND f->>'variant' = 'acacia' THEN (f->>'count') || ' acacia trees'
    WHEN f->>'feature' = 'props' AND f->>'variant' = 'fountain' THEN 'A fountain'
    WHEN f->>'feature' = 'props' AND f->>'variant' = 'wall' THEN 'A stone wall'
    WHEN f->>'feature' = 'props' AND f->>'variant' = 'wreck' THEN 'A shipwreck'
    WHEN f->>'feature' = 'props' AND f->>'variant' = 'wagon' THEN 'Wagons'
    WHEN f->>'feature' = 'house' AND f->>'size' = 'small' THEN regexp_replace(verse.builder_label_0091(f), 'houses?$',
                                                                CASE WHEN (f->>'count')::int > 1 THEN 'cottages' ELSE 'cottage' END)
    ELSE verse.builder_label_0091(f) END $_$;


--
-- Name: builder_line(jsonb, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_line(v jsonb, n integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(btrim(regexp_replace(CASE WHEN jsonb_typeof(v) = 'string' THEN v #>> '{}' ELSE '' END, '[[:cntrl:]|]+', ' ', 'g')), n) $$;


--
-- Name: builder_line_of(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_line_of(m verse.made_realms) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(verse.builder_line_of_0110(m), ' A realm built on the OpenAgents Metaverse.', ' A world built on the OpenAgents Metaverse.') $$;


--
-- Name: builder_line_of_0110(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_line_of_0110(m verse.made_realms) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  place text := CASE m.ground WHEN 'forest' THEN 'A forest' WHEN 'desert' THEN 'A desert' WHEN 'snow' THEN 'A snowfield'
                              WHEN 'stone' THEN 'A stony plain' WHEN 'beach' THEN 'A beach' ELSE 'A meadow' END
                || CASE m.time WHEN 'dawn' THEN ' at dawn' WHEN 'dusk' THEN ' at dusk' WHEN 'night' THEN ' at night' ELSE ' by day' END;
  things text[] := ARRAY(SELECT p FROM (SELECT verse.builder_phrase(f) p, o FROM jsonb_array_elements(m.features) WITH ORDINALITY x(f, o)) y
                         WHERE p IS NOT NULL ORDER BY o);
  people text[] := ARRAY(SELECT f->>'name' FROM jsonb_array_elements(m.features) WITH ORDINALITY x(f, o)
                         WHERE f->>'feature' = 'character' AND coalesce(f->>'name', '') <> '' ORDER BY o);
  out text;
  list text;
  who text;
BEGIN
  LOOP
    list := CASE coalesce(array_length(things, 1), 0) WHEN 0 THEN NULL WHEN 1 THEN things[1]
            ELSE array_to_string(things[1:array_length(things, 1) - 1], ', ') || ' and ' || things[array_length(things, 1)] END;
    who := CASE coalesce(array_length(people, 1), 0) WHEN 0 THEN NULL WHEN 1 THEN people[1] || ' lives'
           ELSE array_to_string(people[1:array_length(people, 1) - 1], ', ') || ' and ' || people[array_length(people, 1)] || ' live' END;
    out := place || coalesce(' with ' || list, '') || coalesce(', where ' || who, '') || '.';
    EXIT WHEN length(out) <= 160 OR (coalesce(array_length(things, 1), 0) <= 1 AND coalesce(array_length(people, 1), 0) <= 1);
    IF coalesce(array_length(things, 1), 0) > 1 THEN things := things[1:array_length(things, 1) - 1];
    ELSE people := people[1:array_length(people, 1) - 1]; END IF;
  END LOOP;
  out := left(out, 160);
  -- a short line says what it is too (a preview's line wants 50 characters or more)
  RETURN out || ' A realm built on the OpenAgents Metaverse.';
END $$;


--
-- Name: builder_lines(bigint, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_lines(plan bigint, b jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT 'plan ' || plan || E'\nname ' || (b->>'name') || E'\nstyle ' || (b->>'style') || E'\nground ' || (b->>'ground') || E'\ntime ' || (b->>'time')
      || E'\ncamera ' || coalesce(b->>'camera', 'third') || E'\npalette ' || coalesce(b->>'palette', 'natural') || E'\n'
      || coalesce((SELECT string_agg('f ' || (f->>'feature') || ' ' || CASE WHEN (f->>'on')::boolean THEN '1' ELSE '0' END || ' ' || (f->>'label'), E'\n' ORDER BY o)
                   FROM jsonb_array_elements(b->'features') WITH ORDINALITY AS t(f, o)) || E'\n', '')
      || coalesce((SELECT string_agg('want ' || (w #>> '{}'), E'\n' ORDER BY o)
                   FROM jsonb_array_elements(coalesce(b->'wanted', '[]')) WITH ORDINALITY AS t(w, o)) || E'\n', '') $$;


--
-- Name: builder_make(jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_make(body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT replace(verse.worlds_answer(verse.builder_make_0110(body, k, per_day))::text, '"/realms/', '"/worlds/')::jsonb $$;


--
-- Name: builder_make_0078(jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_make_0078(body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec verse.players := verse.builder_player(k);
  b jsonb := verse.builder_board_of(body, rec);
  feats jsonb;
  tools jsonb;
  s text;
  plan_id bigint := CASE WHEN jsonb_typeof(body->'plan') = 'number' THEN (body->>'plan')::bigint END;
BEGIN
  IF rec.id IS NULL THEN RETURN '{"status":401,"error":"no player"}'; END IF;
  IF b IS NULL THEN RETURN '{"status":400,"error":"no board"}'; END IF;
  IF (SELECT count(*) FROM verse.made_realms m JOIN verse.worlds w ON w.id = m.world
      WHERE w.owner_player = rec.id AND m.made_ms > verse.now_ms() - 86400000) >= per_day THEN
    RETURN '{"status":429,"error":"that''s today''s realms"}';
  END IF;
  feats := coalesce((SELECT jsonb_agg(f - 'on') FROM jsonb_array_elements(b->'features') f
                     WHERE (f->>'on')::boolean AND f->>'feature' <> 'tool'), '[]');
  tools := (SELECT jsonb_object_agg(t, EXISTS (SELECT 1 FROM jsonb_array_elements(b->'features') f
                                              WHERE f->>'feature' = 'tool' AND f->>'tool' = t AND (f->>'on')::boolean))
            FROM unnest(verse.builder_tools()) t);
  s := verse.builder_slug(b->>'name');
  INSERT INTO verse.worlds (id, owner_player, owner_account, created_ms) VALUES ('made-' || s, rec.id, rec.account, verse.now_ms());
  INSERT INTO verse.made_realms (slug, world, name, style, ground, time, camera, features, tools, plan, made_ms)
  VALUES (s, 'made-' || s, b->>'name', b->>'style', b->>'ground', b->>'time', verse.builder_pick(b->'camera', verse.builder_cameras()), feats, tools,
          (SELECT id FROM verse.realm_plans WHERE id = plan_id AND player = rec.id), verse.now_ms());
  RETURN jsonb_build_object('status', 200, 'slug', s, 'path', '/realms/' || s, 'name', b->>'name');
END $$;


--
-- Name: builder_make_0110(jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_make_0110(body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  out jsonb := verse.builder_make_0078(body, k, per_day);
  rec verse.players := verse.builder_player(k);
  b jsonb;
BEGIN
  IF (out->>'status')::int <> 200 THEN RETURN out; END IF;
  b := verse.builder_board_of(body, rec);
  UPDATE verse.made_realms SET palette = verse.builder_pick(b->'palette', verse.builder_palettes()) WHERE slug = out->>'slug';
  INSERT INTO verse.realm_asks (slug, ms, player, words, state)
  SELECT out->>'slug', verse.now_ms(), rec.id, w #>> '{}', 'waiting'
  FROM jsonb_array_elements(verse.builder_wanted(b->'wanted', NULL)) WITH ORDINALITY AS t(w, o) ORDER BY o;
  RETURN out;
END $$;


--
-- Name: builder_many(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_many(v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE v WHEN 'monkey' THEN 'monkeys' ELSE verse.builder_many_0091(v) END $$;


--
-- Name: builder_many_0091(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_many_0091(v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE v WHEN 'sheep' THEN 'sheep' WHEN 'bison' THEN 'bison' WHEN 'deer' THEN 'deer' WHEN 'wolf' THEN 'wolves'
                WHEN 'fox' THEN 'foxes' WHEN 'fairy' THEN 'fairies' WHEN 'firefly' THEN 'fireflies' WHEN 'butterfly' THEN 'butterflies'
                WHEN 'cactus' THEN 'cacti' WHEN 'gull' THEN 'seagulls' ELSE v || 's' END $$;


--
-- Name: builder_md(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_md(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.worlds_page(verse.builder_md_0110(s), 'https://openagents.com') $$;


--
-- Name: builder_md_0071(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_md_0071(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '# ' || m.name || E'\n\n' || verse.builder_share_line(m)
      || E'\n\nA realm on the OpenAgents Metaverse at https://openagents.com/realms/' || m.slug
      || ', made by a visitor from one prompt (https://openagents.com/realms/new). '
      || CASE m.camera WHEN 'first' THEN '3D, first person' WHEN 'top' THEN '3D, top-down' WHEN 'side' THEN '2D, side-on' ELSE '3D, third person' END
      || '. Style: ' || m.style || '. Ground: ' || m.ground
      || '. Time of day: ' || m.time || E'.\n\n## What is here\n\n'
      || coalesce((SELECT string_agg('- ' || (f->>'label'), E'\n' ORDER BY o) FROM jsonb_array_elements(m.features) WITH ORDINALITY AS x(f, o)), '- Nothing yet: open ground')
      || E'\n\n## What visitors may do\n\n- Walk'
      || coalesce(E'\n' || (SELECT string_agg('- ' || initcap(t), E'\n' ORDER BY o) FROM unnest(verse.builder_tools()) WITH ORDINALITY AS x(t, o)
                            WHERE coalesce((m.tools->>t)::boolean, false)), '')
      || E'\n\nThe owner decides what visitors get, and accepts or declines what others build here.\n'
  FROM verse.made_realms m WHERE m.slug = s $$;


--
-- Name: builder_md_0075(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_md_0075(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s AND base IS NOT NULL) THEN verse.fork_md(s) ELSE verse.builder_md_0071(s) END $$;


--
-- Name: builder_md_0110(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_md_0110(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.builder_md_0075(s)
      || CASE WHEN m.base IS NULL AND m.forked_from IS NOT NULL
              THEN E'\nForked from ' || verse.fork_name_of(m.forked_from) || ' (https://openagents.com/realms/' || m.forked_from || ') at revision ' || coalesce(m.forked_rev, 0) || E'.\n' ELSE '' END
  FROM verse.made_realms m WHERE m.slug = s $$;


--
-- Name: builder_missing(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_missing(wants jsonb, board jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_agg(w ORDER BY o), '[]') FROM (
    SELECT DISTINCT ON (w->>'feature') w, o FROM jsonb_array_elements(coalesce(wants, '[]')) WITH ORDINALITY AS t(w, o)
    WHERE w->>'feature' NOT IN ('none', 'tool')
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(board->'features', '[]')) f
                      WHERE f->>'feature' = w->>'feature' AND coalesce((f->>'on')::boolean, false))
    ORDER BY w->>'feature', o) x $$;


--
-- Name: builder_og_rows(integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_og_rows(n integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT replace(verse.builder_og_rows_0110(n), '|https://openagents.com/realms/', '|https://openagents.com/worlds/') $$;


--
-- Name: builder_og_rows_0110(integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_og_rows_0110(n integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg(
    '/realms/' || m.slug || '|made||' || verse.builder_line(to_jsonb(m.name), 120) || '|' || verse.builder_line(to_jsonb(verse.builder_share_line(m)), 240)
    || '|https://openagents.com/realms/' || m.slug || '|' || verse.builder_card_path(m) || '|' || verse.builder_line(to_jsonb(m.name), 120)
    || '|' || CASE WHEN m.card_ms IS NULL THEN 'default' ELSE 'made' END || '|1200|630|' || coalesce(m.card_kb, 0)
    || '|' || CASE WHEN m.card_ms IS NULL THEN 'no picture of its own yet (its owner''s next visit takes one)' ELSE '' END
    || '|' || CASE WHEN m.description IS NULL THEN 'line written from what is in it' ELSE '' END || '|', E'\n' ORDER BY m.made_ms DESC) || E'\n', '')
  FROM (SELECT * FROM verse.made_realms WHERE visibility = 'public' AND (base IS NULL OR published_ms IS NOT NULL)
        ORDER BY made_ms DESC LIMIT greatest(least(n, 200), 1)) m $$;


--
-- Name: builder_one_line(jsonb, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_one_line(v jsonb, n integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(btrim(regexp_replace(CASE WHEN jsonb_typeof(v) = 'string' THEN v #>> '{}' ELSE '' END, '[[:cntrl:][:space:]|]+', ' ', 'g')), n) $$;


--
-- Name: builder_order(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT o[1:p] || ARRAY['enclosure', 'centre', 'layout', 'path'] || o[p + 1:]
  FROM (SELECT verse.builder_order_0096() AS o) x, LATERAL (SELECT array_position(x.o, 'mist') AS p) y $$;


--
-- Name: builder_order_0064(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order_0064() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT ARRAY['water', 'trees', 'rocks', 'plants', 'lanterns', 'flock', 'props', 'character', 'tool'] $$;


--
-- Name: builder_order_0078(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order_0078() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT ARRAY['house'] || verse.builder_order_0064() $$;


--
-- Name: builder_order_0082(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order_0082() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT ARRAY['house', 'dwellings', 'village', 'herd'] || array_remove(verse.builder_order_0078(), 'house') $$;


--
-- Name: builder_order_0084(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order_0084() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT o[1:p] || ARRAY['bigtree'] || o[p + 1:] FROM (SELECT verse.builder_order_0082() AS o) x, LATERAL (SELECT array_position(x.o, 'trees') AS p) y $$;


--
-- Name: builder_order_0091(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order_0091() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT ARRAY['land', 'building'] || verse.builder_order_0084() $$;


--
-- Name: builder_order_0096(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_order_0096() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT o[1:1] || ARRAY['mist'] || o[2:] FROM (SELECT verse.builder_order_0091() AS o) x $$;


--
-- Name: builder_owns(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_owns(k text, s text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(verse.owns(verse.builder_player(k), NULL, 'made-' || s), false) $$;


--
-- Name: builder_page(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.worlds_page(verse.builder_page_0110(s, origin), origin) $$;


--
-- Name: builder_page_0071(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_0071(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>' || verse.builder_html(m.name) || ' · a realm on the Metaverse · OpenAgents</title>
<meta name="description" content="' || verse.builder_html(verse.builder_share_line(m)) || '">
<meta property="og:type" content="website">
<meta property="og:site_name" content="OpenAgents">
<meta property="og:title" content="' || verse.builder_html(m.name) || '">
<meta property="og:description" content="' || verse.builder_html(verse.builder_share_line(m)) || '">
<meta property="og:url" content="' || verse.builder_html(origin) || '/realms/' || m.slug || '">
<meta property="og:image" content="' || verse.builder_html(origin) || verse.builder_html(verse.builder_card_path(m)) || '">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="' || verse.builder_html(m.name) || ', a realm on the Metaverse">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="' || verse.builder_html(m.name) || '">
<meta name="twitter:description" content="' || verse.builder_html(verse.builder_share_line(m)) || '">
<meta name="twitter:image" content="' || verse.builder_html(origin) || verse.builder_html(verse.builder_card_path(m)) || '">
<meta name="theme-color" content="#000000">
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="alternate" type="text/markdown" href="/realms/' || m.slug || '/index.md">
<script>if ("gpu" in navigator) document.documentElement.classList.add("gpu")</script>
<style>
html,body{margin:0;height:100%;background:#000;color:#ededed}
body{overflow:hidden;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:14px;line-height:1.5}
canvas{position:fixed;inset:0;width:100%;height:100%;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
canvas[data-cursor=pointer]{cursor:pointer}
main{position:relative;max-width:640px;margin:0 auto;padding:24px 16px}
html:not(.gpu) body{overflow:auto}
a{color:#ededed}
.gpu main{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;padding:0}
</style>
</head>
<body>
<canvas id="coaxial" aria-hidden="true"></canvas>
<main>
<h1>' || verse.builder_html(m.name) || '</h1>
<p><a href="/realms/' || m.slug || '/index.md">' || verse.builder_html(m.name) || '</a></p>
</main>
<script type="module" data-made="' || m.slug || '" data-style-of="' || m.style || '">
const me = document.querySelector("script[data-made]"), slug = me.dataset.made;
const t = await (await fetch("/realms/built", { cache: "no-store" })).text();
const from = new DOMParser().parseFromString(t, "text/html").querySelector("script[data-app]");
const s = document.createElement("script");
for (const a of from.attributes) s.setAttribute(a.name, a.value);
s.dataset.realm = "made"; s.dataset.slot = "made-" + slug; s.dataset.style = me.dataset.styleOf;
s.dataset.text = slug; s.dataset.card = "/api/playtest/realms/" + slug + "/card";
document.body.append(s);
</script>
</body>
</html>
' FROM verse.made_realms m WHERE m.slug = s $$;


--
-- Name: builder_page_0075(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_0075(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s AND base IS NOT NULL) THEN verse.fork_page(s, origin) ELSE verse.builder_page_0071(s, origin) END $$;


--
-- Name: builder_page_0093(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_0093(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN m.base IS NOT NULL THEN p
              ELSE replace(replace(p,
                     E'<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n',
                     E'<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n' || CASE WHEN m.unlisted THEN E'<meta name="robots" content="noindex">\n' ELSE '' END),
                   E'</h1>\n',
                   E'</h1>\n' || CASE WHEN m.forked_from IS NOT NULL
                                      THEN '<p>Forked from <a href="/realms/' || m.forked_from || '">' || verse.builder_html(verse.fork_name_of(m.forked_from)) || '</a> at revision ' || coalesce(m.forked_rev, 0) || E'.</p>\n'
                                      ELSE '' END) END
  FROM verse.made_realms m, LATERAL (SELECT verse.builder_page_0075(s, origin) AS p) x WHERE m.slug = s $$;


--
-- Name: builder_page_0110(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_0110(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN m.base IS NOT NULL THEN p
              ELSE replace(replace(p,
                     '<script type="module" data-made="' || m.slug || '"',
                     '<script type="module" data-made="' || m.slug || '"'
                       || CASE WHEN m.published_engine IS NOT NULL
                               THEN ' data-engine="' || verse.builder_html(m.published_engine) || '" data-engine-sha256="' || m.published_engine_sha256 || '"'
                               ELSE '' END),
                   E'const t = await (await fetch("/realms/built", { cache: "no-store" })).text();\n'
                   || E'const from = new DOMParser().parseFromString(t, "text/html").querySelector("script[data-app]");\n'
                   || E'const s = document.createElement("script");\n'
                   || E'for (const a of from.attributes) s.setAttribute(a.name, a.value);\n',
                   E'const pin = me.dataset.engine, now = new URLSearchParams(location.search).get("engine") === "current";\n'
                   || E'let attrs;\n'
                   || E'if (pin && !now) attrs = pin.split("\\n").slice(1).filter(Boolean).map((l) => [l.slice(0, l.indexOf(" ")), l.slice(l.indexOf(" ") + 1)]);\n'
                   || E'else {\n'
                   || E'  const t = await (await fetch("/realms/built", { cache: "no-store" })).text();\n'
                   || E'  attrs = [...new DOMParser().parseFromString(t, "text/html").querySelector("script[data-app]").attributes].map((a) => [a.name, a.value]);\n'
                   || E'}\n'
                   || E'const s = document.createElement("script");\n'
                   || E'for (const [n, v] of attrs) s.setAttribute(n, v);\n') END
  FROM verse.made_realms m, LATERAL (SELECT verse.builder_page_0093(s, origin) AS p) x WHERE m.slug = s $$;


--
-- Name: builder_page_rev(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_rev() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 3 $$;


--
-- Name: builder_page_stale(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_stale() RETURNS text
    LANGUAGE sql
    AS $$
  UPDATE verse.made_realms SET page_rev = verse.builder_page_rev()
  WHERE slug = (SELECT slug FROM verse.made_realms WHERE page_rev < verse.builder_page_rev() ORDER BY made_ms DESC LIMIT 1 FOR UPDATE SKIP LOCKED)
  RETURNING slug $$;


--
-- Name: builder_page_written(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_page_written(s text) RETURNS boolean
    LANGUAGE sql
    AS $$
  UPDATE verse.made_realms SET page_rev = verse.builder_page_rev() WHERE slug = s RETURNING true $$;


--
-- Name: builder_paged(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_paged(s text, note text) RETURNS boolean
    LANGUAGE sql
    AS $$
  UPDATE verse.made_realms SET page_ms = CASE WHEN note IS NULL THEN verse.now_ms() END, page_note = note WHERE slug = s RETURNING true $$;


--
-- Name: builder_palettes(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_palettes() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT ARRAY['natural', 'pastel', 'vivid', 'muted'] $$;


--
-- Name: builder_phrase(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_phrase(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' IN ('enclosure', 'centre', 'layout', 'path') OR (f->>'feature' = 'props' AND f->>'variant' = 'dock')
              THEN lower(left(verse.builder_label(f), 1)) || substr(verse.builder_label(f), 2)
              ELSE verse.builder_phrase_0096(f) END $$;


--
-- Name: builder_phrase_0078(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_phrase_0078(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE f->>'feature'
    WHEN 'water' THEN 'a ' || coalesce(f->>'size', 'small') || ' pond'
    WHEN 'trees' THEN (f->>'count') || ' ' || CASE f->>'variant' WHEN 'mixed' THEN 'trees and bushes' ELSE coalesce(f->>'variant', 'round') || ' trees' END
    WHEN 'rocks' THEN (f->>'count') || ' rocks'
    WHEN 'plants' THEN (f->>'count') || ' ferns'
    WHEN 'lanterns' THEN (f->>'count') || ' ' || coalesce(f->>'colour', 'gold') || ' lanterns'
    WHEN 'flock' THEN 'a flock of ' || coalesce(f->>'variant', 'crow') || 's'
    WHEN 'props' THEN CASE f->>'variant' WHEN 'crates' THEN 'crates' WHEN 'barrels' THEN 'barrels' WHEN 'wagon' THEN 'a wagon'
                                         WHEN 'fence' THEN 'a fence' ELSE 'a camp' END
  END $$;


--
-- Name: builder_phrase_0082(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_phrase_0082(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' IN ('herd', 'dwellings', 'village') THEN lower(left(verse.builder_label(f), 1)) || substr(verse.builder_label(f), 2)
              ELSE verse.builder_phrase_0078(f) END $$;


--
-- Name: builder_phrase_0084(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_phrase_0084(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' = 'bigtree' THEN lower(left(verse.builder_label(f), 1)) || substr(verse.builder_label(f), 2)
              ELSE verse.builder_phrase_0082(f) END $$;


--
-- Name: builder_phrase_0091(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_phrase_0091(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' IN ('land', 'building')
                OR (f->>'feature' = 'water' AND f->>'variant' IN ('river', 'frozen', 'lava'))
                OR (f->>'feature' = 'herd' AND f->>'variant' NOT IN ('bison', 'deer', 'horse'))
                OR (f->>'feature' = 'flock' AND f->>'variant' NOT IN ('crow', 'bat', 'owl'))
                OR (f->>'feature' = 'trees' AND f->>'variant' IN ('palm', 'blossom'))
                OR (f->>'feature' = 'plants' AND f->>'variant' <> 'fern')
                OR (f->>'feature' = 'props' AND f->>'variant' NOT IN ('crates', 'barrels', 'wagon', 'fence', 'camp'))
              THEN lower(left(verse.builder_label(f), 1)) || substr(verse.builder_label(f), 2)
              ELSE verse.builder_phrase_0084(f) END $$;


--
-- Name: builder_phrase_0096(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_phrase_0096(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' = 'mist'
                OR (f->>'feature' = 'building' AND f->>'variant' IN ('pagoda', 'longhouse', 'market'))
                OR (f->>'feature' = 'water' AND f->>'variant' = 'river' AND f->>'size' = 'small')
                OR (f->>'feature' = 'trees' AND f->>'variant' IN ('autumn', 'acacia'))
                OR (f->>'feature' = 'herd' AND f->>'variant' IN ('elephant', 'giraffe', 'monkey', 'squirrel'))
                OR (f->>'feature' = 'props' AND f->>'variant' IN ('fountain', 'wall', 'wreck', 'wagon'))
              THEN lower(left(verse.builder_label(f), 1)) || substr(verse.builder_label(f), 2)
              ELSE verse.builder_phrase_0091(f) END $$;


--
-- Name: builder_pick(jsonb, text[]); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_pick(v jsonb, options text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'string' AND (v #>> '{}') = ANY (options) THEN v #>> '{}' ELSE options[1] END $$;


--
-- Name: builder_pick(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_pick(v jsonb, options jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'string' AND options ? (v #>> '{}') THEN v #>> '{}' ELSE options->>0 END $$;


--
-- Name: builder_pick_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_pick_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  r jsonb;
  t text;
  d jsonb;
  v text;
  field text := asked->>'field';
  words jsonb := verse.builder_questions()->field->'words';
BEGIN
  BEGIN r := response::jsonb; EXCEPTION WHEN others THEN r := NULL; END;
  IF http = 200 AND r IS NOT NULL THEN
    SELECT string_agg(p->>'text', '') INTO t
    FROM jsonb_array_elements(coalesce(r->'candidates'->0->'content'->'parts', '[]')) p
    WHERE coalesce((p->>'thought')::boolean, false) = false AND p ? 'text';
    BEGIN d := t::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
    v := CASE WHEN jsonb_typeof(d->'value') = 'string' AND words ? (d->>'value') THEN d->>'value' ELSE 'none' END;
  END IF;
  UPDATE verse.realm_plans SET board = CASE WHEN v IS NULL THEN NULL ELSE jsonb_build_object('pick', field, 'value', v) END,
         error = CASE WHEN v IS NULL THEN 'model error ' || http END, model = builder_pick_answer.model, ms_taken = taken
  WHERE id = (asked->>'id')::bigint;
  IF v IS NULL THEN RETURN jsonb_build_object('status', 503, 'error', CASE WHEN http = 429 THEN 'busy' ELSE 'no answer' END); END IF;
  RETURN jsonb_build_object('status', 200, 'field', field, 'value', v, 'lines', 'field ' || field || E'\nvalue ' || v || E'\n');
END $$;


--
-- Name: builder_pick_ask(jsonb, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_pick_ask(body jsonb, cap integer, k text) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.builder_fast(verse.builder_pick_ask_0059(body, cap, k)) $$;


--
-- Name: builder_pick_ask_0059(jsonb, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_pick_ask_0059(body jsonb, cap integer, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  field text := CASE WHEN jsonb_typeof(body) = 'object' AND jsonb_typeof(body->'field') = 'string' THEN body->>'field' END;
  q jsonb := verse.builder_questions()->field;
  said text := CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'words', 300) ELSE '' END;
  rec verse.players := verse.builder_player(k);
  row_id bigint;
BEGIN
  IF q IS NULL THEN RETURN '{"status":400,"error":"no such question"}'; END IF;
  IF said = '' THEN RETURN '{"status":400,"error":"say one of them"}'; END IF;
  IF rec.id IS NOT NULL AND EXISTS (SELECT 1 FROM verse.realm_plans WHERE player = rec.id AND ms > verse.now_ms() - 2000) THEN
    RETURN '{"status":429,"error":"one at a time"}';
  END IF;
  IF (SELECT count(*) FROM verse.realm_plans WHERE ms > (extract(epoch FROM date_trunc('day', now())) * 1000)::bigint) >= cap THEN
    RETURN '{"status":503,"error":"the day''s plans are used up"}';
  END IF;
  INSERT INTO verse.realm_plans (ms, player, prompt, board_in) VALUES (verse.now_ms(), rec.id, said, jsonb_build_object('pick', field)) RETURNING id INTO row_id;
  RETURN jsonb_build_object('status', 200, 'id', row_id, 'field', field, 'request', jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text',
      'A visitor is setting up a realm on the Verse, a small world in the browser. They were asked: ' || (q->>'asks')
      || ' Pick the option they mean from what they said. Answer "none" if they named none of them.'))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(jsonb_build_object('text', said)))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json',
      'responseSchema', jsonb_build_object('type', 'object', 'required', jsonb_build_array('value'), 'properties', jsonb_build_object(
        'value', jsonb_build_object('type', 'string', 'enum', (q->'words') || '["none"]'::jsonb))),
      'temperature', 0.0, 'maxOutputTokens', 200, 'thinkingConfig', jsonb_build_object('thinkingLevel', 'LOW'))));
END $$;


--
-- Name: builder_place(text, jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_place(s text, body jsonb, k text) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.builder_place_0110(s, body, k)) $$;


--
-- Name: builder_place_0110(text, jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_place_0110(s text, body jsonb, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  m verse.made_realms;
  rec verse.players := verse.builder_player(k);
  thing text := CASE WHEN jsonb_typeof(body->'thing') = 'string' AND (body->>'thing') = ANY (verse.builder_things()) THEN body->>'thing' END;
  x numeric := CASE WHEN jsonb_typeof(body->'x') = 'number' THEN (body->>'x')::numeric END;
  z numeric := CASE WHEN jsonb_typeof(body->'z') = 'number' THEN (body->>'z')::numeric END;
  yaw numeric := CASE WHEN jsonb_typeof(body->'yaw') = 'number' THEN (body->>'yaw')::numeric ELSE 0 END;
  change jsonb;
  pid bigint;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF rec.id IS NULL THEN RETURN '{"status":401,"error":"no player"}'; END IF;
  IF thing IS NULL OR x IS NULL OR z IS NULL OR abs(x) > 40 OR abs(z) > 40 THEN RETURN '{"status":400,"error":"not a thing here"}'; END IF;
  change := jsonb_build_object('kind', 'place', 'thing', thing, 'x', trim_scale(round(x, 2)), 'z', trim_scale(round(z, 2)), 'yaw', trim_scale(round(yaw, 3)));
  IF verse.builder_owns(k, s) THEN
    IF jsonb_array_length(m.placed) >= 200 THEN RETURN '{"status":409,"error":"the realm is full"}'; END IF;
    UPDATE verse.made_realms SET placed = placed || jsonb_build_array(change - 'kind') WHERE slug = s;
    RETURN '{"status":200,"placed":true}';
  END IF;
  IF NOT coalesce((m.tools->>'build')::boolean, false) THEN RETURN '{"status":403,"error":"the owner hasn''t let visitors build"}'; END IF;
  IF (SELECT count(*) FROM verse.realm_proposals WHERE slug = s AND state = 'waiting') >= 50 THEN RETURN '{"status":429,"error":"the owner has enough to look at"}'; END IF;
  INSERT INTO verse.realm_proposals (slug, ms, by_player, change) VALUES (s, verse.now_ms(), rec.id, change) RETURNING id INTO pid;
  RETURN jsonb_build_object('status', 200, 'proposed', pid);
END $$;


--
-- Name: builder_player(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_player(k text) RETURNS verse.players
    LANGUAGE sql STABLE
    AS $_$
  SELECT * FROM verse.players WHERE k ~ '^[A-Za-z0-9_-]{20,128}$' AND key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex') $_$;


--
-- Name: builder_prompt(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0096()
    || E'\nA place built round a middle is planned as one: a courtyard, cloister, walled garden or yard, farmyard, '
    || 'fort or stockade, town or village square, plaza, clearing, a circle of stones, or anything "in the middle", '
    || '"at the centre" or "round" something. Its walls or fence are feature enclosure (stone walls for stone, a wooden '
    || 'rail fence, a palisade of logs for a fort, or a hedge); the thing in its very middle is feature centre; how the rest '
    || 'stands round it is feature layout (a courtyard, cloister or paved square is square; a garden inside walls or a hedge '
    || 'is garden; a clearing is clearing with trees; a ring or circle of lanterns, stones or tents is ring; houses or '
    || 'cottages round a green are village); a path, track or cobbled way to it is feature path. A thing in the middle is '
    || 'the centre only, never also a prop, a building or a big tree. A courtyard of stone is enclosure stone, layout square '
    || 'and ground stone. Each of enclosure, centre, layout and path says which in its field kind: '
    || (SELECT string_agg(n || ' kind ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(verse.builder_catalogue()->n->'kind') k), '; ')
        FROM unnest(ARRAY['enclosure', 'centre', 'layout', 'path']) n) || '. A dock, jetty or pier is props dock, with water: a lake is a large pond. '
    || 'Missing is "" (an empty string) when nothing of the thing is missing: never the word empty, and never "none".' $$;


--
-- Name: builder_prompt_0061(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0061() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT 'You plan a realm for the Verse, a small world in the browser that a visitor is making for themselves. '
    || 'They said, out loud or typed, what world they want. Answer the realm as a short board they will check features on or off: '
    || 'a name for it (at most 30 characters, in their words where they gave one), its camera, its style, its ground and its time of day, '
    || 'and the features from this catalogue that make what they asked for. Use only the catalogue. '
    || 'The realm starts empty: add only features that fit what they said. Add a character only when they asked for people, '
    || 'characters or someone living there; give each a short name and a role of a few words. '
    || 'Add the visitor tools that fit (talk when there are characters; jump and map are usually wanted); put "on" false for '
    || 'a feature that is a good suggestion they did not ask for, true for what they asked for. '
    || 'If they gave the current board, change it as they now say and keep everything else, including what is on or off. '
    || 'If they fixed some answers in setup, use exactly those and choose only the rest. '
    || E'\nCameras: third (third person, behind you), first (first person, through your eyes), top (top-down, from high above), '
    || 'side (a 2D realm seen side-on: walk left and right and jump). Use side only for a 2D or side-scrolling world.'
    || E'\nStyles: lowpoly (facets and flat colours), painterly (soft, painted).'
    || E'\nGrounds: ' || array_to_string(verse.builder_grounds(), ', ') || '. Times: ' || array_to_string(verse.builder_times(), ', ') || '.'
    || E'\nThe features:\n'
    || string_agg('- ' || n || ': ' || (c->>'says')
         || CASE WHEN c ? 'variant' THEN '. variant: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c->'variant') k) ELSE '' END
         || CASE WHEN c ? 'colour' THEN '. colour: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c->'colour') k) ELSE '' END
         || CASE WHEN c ? 'size' THEN '. size: small, medium or large' ELSE '' END
         || CASE WHEN c ? 'tool' THEN '. tool: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c->'tool') k) ELSE '' END
         || CASE WHEN c ? 'count' THEN '. count ' || (c->'count'->>0) || ' to ' || (c->'count'->>1) ELSE '' END
         || CASE WHEN n = 'character' THEN '. name, role' ELSE '' END
         || '. At most ' || (c->>'most') || '.', E'\n' ORDER BY o)
  FROM unnest(verse.builder_order()) WITH ORDINALITY AS t(n, o), LATERAL (SELECT verse.builder_catalogue()->n AS c) x $$;


--
-- Name: builder_prompt_0064(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0064() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(verse.builder_prompt_0061(), E'\nStyles: lowpoly (facets and flat colours), painterly (soft, painted).',
    E'\nStyles: lowpoly (facets and flat colours), painterly (soft, painted), flat (bold flat shapes and few tones, like a picture book).') $$;


--
-- Name: builder_prompt_0078(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0078() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0064()
    || E'\nFirst, in "asked", name the main things they asked for, the one they asked for most first: each a few of their own words '
    || '(like "small red house" or "tall tree") and the feature from the catalogue that makes it, or none when nothing in it does. '
    || 'Every asked thing with a feature must be on the board, on true, with the fields that fit what they said (a red house is colour red). '
    || 'Then add what else fits.' $$;


--
-- Name: builder_prompt_0080(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0080() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0078()
    || E'\nPalettes: natural (true colours), pastel (soft, pale colours), vivid (bright, saturated), muted (greyed, quiet). '
    || 'Choose the one that fits the colours they asked for; natural when they named none. '
    || 'In "asked", list every thing they asked for, also each one no feature makes (feature none): none of them is ever left out. '
    || 'When they ask for a people or a culture, the village feature shows its people plainly and respectfully, as everyday people, never a caricature.' $$;


--
-- Name: builder_prompt_0082(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0082() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0080()
    || E'\nAn ask about its colours, ground, time of day, art style or camera is the setup: name it with feature setup, '
    || 'and set the palette, ground, time, style or camera it asks for.' $$;


--
-- Name: builder_prompt_0084(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0084() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0082()
    || E'\nIn "asked", name every thing they asked for, never only the main ones: each creature, person, building, plant, '
    || 'place, landform and terrain they named, in their own few words with what makes it what it is ("giant tree", '
    || '"floating island", "palm trees", "red barn", "frozen lake", "koi pond", "stone lanterns"). Give each the feature that '
    || 'draws it (or setup, or none); in drawn, what that feature will show for it, in the few words its board line has '
    || '("9 round trees", "a flock of 7 crows", "crates", "a medium pond"; nothing for none); '
    || 'and same: true only when what is drawn is the thing they said, with every word of it (its kind, its colour, its size, '
    || 'what it is made of); '
    || 'false when it only stands in for it (crows for owls, round trees for palm trees, a pond for a sea or a river, a house '
    || 'for a barn or a castle, a meadow for a floating island, fewer than they asked for). Put the stand-in on the board '
    || 'too when it fits. Every thing with same false or feature none stays on the board as still wanted, in those words, '
    || 'so an agent can build it later: name each exactly, once. Words about mood (friendly, cosy, quiet, spooky) are not things '
    || 'and change nothing of what is drawn. How many they asked for sets the count: a few is near the least, many, lots, '
    || 'everywhere or a forest of them is the most; when that is more than the most, the thing (with its words: "bison '
    || 'everywhere") is same false.' $$;


--
-- Name: builder_prompt_0091(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0091() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0084()
    || E'\nFor each asked thing, said is their words as they said them; thing is those words without the ones about mood '
    || 'or feeling (friendly, cosy, happy, spooky, creepy, peaceful, lonely, cheerful, magical, quiet: they change nothing '
    || 'that is drawn), so "friendly owls" is the thing "owls" and "a cosy cabin" is "cabin". Judge same on the thing alone. '
    || 'Use the catalogue fully: a cabin, barn, lighthouse or castle is a building of that kind, not a house; a river, a '
    || 'frozen pond or lava is that water; hills, mountains, a floating island or an island in the sea is the land; sheep, '
    || 'wolves or chickens are a herd of that kind; a dragon, fairies or fireflies are what flies. A whole place (a village, '
    || 'a farm, a town, a garden, a glade, a cove, a campsite, a valley) is feature place: made of the features that make it '
    || 'and the ground; it is same true when they are on the board, and then never a line still wanted. Judged on the thing alone: said "friendly owls", '
    || 'thing "owls", drawn "A flock of 7 owls": same true. When part of a thing is drawn and part is not, same is false and '
    || 'the thing is only the part not drawn: "a japanese village" drawn as a village is the thing "japanese buildings"; a '
    || 'castle is medieval already. A quality is part of the thing: glowing, sleeping, hidden, a colour. Set count to how '
    || 'many they said: "a dragon" is 1, "two wolves" 2; with no number say the feature''s default. Two kinds of animal are two '
    || 'herds. Same is true whenever a visitor would say the board draws it: "a snowy mountain cabin" with snow ground, '
    || 'mountains and a log cabin; "a frozen lake" as a large frozen pond; "sunset" as dusk; "a graveyard" as gravestones. '
    || 'A thing never stands whole as a line still wanted when part of it is drawn: the line is the part that is not '
    || '("a misty pine valley" with pines wants "mist"; "a haunted swamp" with dead trees and a pond wants "swamp"; '
    || '"a cyberpunk city street" wants "city street" and "cyberpunk look"), and nothing is wanted twice.' $$;


--
-- Name: builder_prompt_0096(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_prompt_0096() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_prompt_0091()
    || E'\nFor each asked thing, missing is the part of it the board does not draw as asked, in a few words, and empty '
    || 'when a visitor would say the board draws all of it: it is what stays on the board as still wanted. "a giant tree" '
    || 'as a giant tree, "glowing mushrooms" as mushrooms glowing after dark, "a wooden cabin" as a log cabin, "sunset" as '
    || 'dusk and "snowy mountains" as mountains with snow ground are missing nothing; "a koi pond" drawn as a pond is '
    || 'missing "koi"; owls stood in for by crows are missing "owls"; a thing no feature draws (feature none) is '
    || 'missing all of it. A whole place (feature place) is never wanted whole: "a pirate cove" with an island, '
    || 'treasure and parrots is missing nothing; "a haunted swamp" with dead trees and a pond is missing "swamp"; '
    || '"a fishing village" with a village, boats and the sea is missing nothing; "a cyberpunk city street" is missing '
    || '"cyberpunk city street". A cottage is a small house; a stream is a small river; stalls are a market; '
    || 'fog and mist are feature mist; autumn or orange leaves are autumn trees; a t-rex is not the dinosaurs drawn (they '
    || 'are long-necked, on four legs), so it is same false. A character''s name is a name a person has (Old Tam, Mira, '
    || 'Captain Brae), never their role again: a lighthouse keeper is named, and "keeps the lighthouse" is the role.' $$;


--
-- Name: builder_proposals(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_proposals(s text, k text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg('P ' || p.id || '|' || 'Visitor ' || right(coalesce(p.by_player, '----'), 4) || '|' || (p.change->>'thing') || '|'
         || (p.change->>'x') || '|' || (p.change->>'z') || '|' || (p.change->>'yaw') || '|'
         || (SELECT count(*) FROM jsonb_array_elements(m.placed) e WHERE e->>'thing' = p.change->>'thing') || '|'
         || ((SELECT count(*) FROM jsonb_array_elements(m.placed) e WHERE e->>'thing' = p.change->>'thing') + 1), E'\n' ORDER BY p.id DESC) || E'\n', '')
  FROM verse.realm_proposals p JOIN verse.made_realms m ON m.slug = p.slug
  WHERE p.slug = s AND p.state = 'waiting' AND verse.builder_owns(k, s) $$;


--
-- Name: builder_questions(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_questions() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_set(verse.builder_questions_0061(), '{style,asks}',
    to_jsonb('Which art style: low poly (facets, flat colours), painterly (soft, painted) or flat (bold flat shapes, like a picture book)?'::text)) $$;


--
-- Name: builder_questions_0061(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_questions_0061() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT jsonb_build_object(
  'dims',   jsonb_build_object('asks', 'Is the realm 2D (seen side-on) or 3D?', 'words', jsonb_build_array('3d', '2d')),
  'camera', jsonb_build_object('asks', 'Which camera: third person (behind you), first person (through your eyes) or top-down (from high above)?',
                               'words', jsonb_build_array('third', 'first', 'top')),
  'style',  jsonb_build_object('asks', 'Which art style: low poly (facets, flat colours) or painterly (soft, painted)?', 'words', to_jsonb(verse.builder_styles())),
  'ground', jsonb_build_object('asks', 'What is the ground: ' || array_to_string(verse.builder_grounds(), ', ') || '?', 'words', to_jsonb(verse.builder_grounds())),
  'time',   jsonb_build_object('asks', 'What time of day: ' || array_to_string(verse.builder_times(), ', ') || '?', 'words', to_jsonb(verse.builder_times()))) $$;


--
-- Name: builder_repair(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_repair(board jsonb, missing jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  m jsonb;
  feats jsonb := coalesce(board->'features', '[]');
  at int;
  held jsonb;
BEGIN
  FOR m IN SELECT e FROM jsonb_array_elements(coalesce(missing, '[]')) e LOOP
    SELECT o - 1 INTO at FROM jsonb_array_elements(feats) WITH ORDINALITY AS t(f, o) WHERE f->>'feature' = m->>'feature' ORDER BY o LIMIT 1;
    IF at IS NOT NULL THEN
      feats := jsonb_set(feats, ARRAY[at::text, 'on'], 'true');
    ELSE
      feats := feats || jsonb_build_array(jsonb_build_object('feature', m->>'feature', 'on', true)
                 || CASE WHEN m->>'feature' = 'character' THEN jsonb_build_object('name', left(m->>'thing', 24)) ELSE '{}' END);
    END IF;
  END LOOP;
  held := verse.builder_hold(board || jsonb_build_object('features', feats));
  RETURN coalesce(held, board);
END $$;


--
-- Name: builder_reserved(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_reserved() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
