    'name', jsonb_build_object('type', 'string'),
    'camera', jsonb_build_object('type', 'string', 'enum', to_jsonb(verse.builder_cameras())),
    'style', jsonb_build_object('type', 'string', 'enum', to_jsonb(verse.builder_styles())),
