      (SELECT jsonb_agg(DISTINCT k) FROM jsonb_each(verse.builder_catalogue()) e, jsonb_array_elements_text(coalesce(e.value->'colour', '[]')) k))
    || jsonb_build_object('propertyOrdering', '["asked"]'::jsonb || (s->'required'))
