--
-- Name: builder_settings(text, jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_settings(s text, body jsonb, k text) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.builder_settings_0110(s, body, k)) $$;


--
-- Name: builder_settings_0110(text, jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_settings_0110(s text, body jsonb, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  m verse.made_realms;
  t jsonb := CASE WHEN jsonb_typeof(body->'tools') = 'object' THEN body->'tools' ELSE '{}' END;
  next jsonb;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF NOT verse.builder_owns(k, s) THEN RETURN '{"status":403,"error":"only its owner"}'; END IF;
  next := (SELECT jsonb_object_agg(x, CASE WHEN jsonb_typeof(t->x) = 'boolean' THEN (t->>x)::boolean ELSE coalesce((m.tools->>x)::boolean, false) END)
           FROM unnest(verse.builder_tools()) x);
  UPDATE verse.made_realms SET tools = next, settings_ms = verse.now_ms() WHERE slug = s;
  RETURN jsonb_build_object('status', 200, 'tools', next);
END $$;


--
-- Name: builder_setup(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_setup(d jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_object_agg(k, d->>k), '{}') FROM unnest(ARRAY['camera', 'style', 'ground', 'time']) k
  WHERE jsonb_typeof(d) = 'object' AND jsonb_typeof(d->k) = 'string'
    AND (d->>k) = ANY (CASE k WHEN 'camera' THEN verse.builder_cameras() WHEN 'style' THEN verse.builder_styles()
                              WHEN 'ground' THEN verse.builder_grounds() ELSE verse.builder_times() END) $$;


--
-- Name: builder_share_line(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_share_line(m verse.made_realms) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(nullif(btrim(m.description), ''), CASE WHEN m.base IS NOT NULL THEN verse.fork_line(m) ELSE verse.builder_line_of(m) END) $$;


--
-- Name: builder_slug(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_slug(nm text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  base text := left(trim(BOTH '-' FROM regexp_replace(lower(nm), '[^a-z0-9]+', '-', 'g')), 40);
  s text;
  i int := 1;
BEGIN
  base := trim(BOTH '-' FROM base);
  IF base = '' OR base !~ '^[a-z0-9]' THEN base := 'realm'; END IF;
  s := base;
  WHILE s = ANY (verse.builder_reserved()) OR EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s) OR EXISTS (SELECT 1 FROM verse.worlds WHERE id = 'made-' || s) LOOP
    i := i + 1;
    s := left(base, 36) || '-' || i;
  END LOOP;
  RETURN s;
END $$;


--
-- Name: builder_slugs(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_slugs() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg(slug, E'\n' ORDER BY made_ms, slug) || E'\n', '') FROM verse.made_realms WHERE visibility <> 'private' $$;


--
-- Name: builder_spec(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_spec(s text, k text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.builder_spec_0078(s, k) || 'palette ' || m.palette || E'\n' FROM verse.made_realms m WHERE m.slug = s $$;


--
-- Name: builder_spec_0078(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_spec_0078(s text, k text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  m verse.made_realms;
  mine boolean := verse.builder_owns(k, s);
  out text;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NULL THEN RETURN NULL; END IF;
  out := 'realm ' || m.slug || E'\nname ' || m.name || E'\nstyle ' || m.style || E'\nground ' || m.ground || E'\ntime ' || m.time
      || E'\ncamera ' || m.camera || E'\nowner ' || CASE WHEN mine THEN '1' ELSE '0' END || E'\n';
  out := out || coalesce((SELECT string_agg('tool ' || t || ' ' || CASE WHEN coalesce((m.tools->>t)::boolean, false) THEN '1' ELSE '0' END, E'\n' ORDER BY o)
                          FROM unnest(verse.builder_tools()) WITH ORDINALITY AS x(t, o)) || E'\n', '');
  out := out || coalesce((SELECT string_agg(CASE f->>'feature'
      WHEN 'character' THEN 'character ' || (f->>'name') || '|' || (f->>'role')
      ELSE 'feature ' || (f->>'feature') || concat(' ' || (f->>'size'), ' ' || (f->>'variant'), ' ' || (f->>'colour'), ' ' || (f->>'count')) END, E'\n' ORDER BY o)
    FROM jsonb_array_elements(m.features) WITH ORDINALITY AS x(f, o)) || E'\n', '');
  out := out || coalesce((SELECT string_agg('placed ' || (p->>'thing') || ' ' || trim_scale(round((p->>'x')::numeric, 2)) || ' ' || trim_scale(round((p->>'z')::numeric, 2))
                                            || ' ' || trim_scale(round((p->>'yaw')::numeric, 3)), E'\n' ORDER BY o)
                          FROM jsonb_array_elements(m.placed) WITH ORDINALITY AS x(p, o)) || E'\n', '');
  IF mine THEN
    out := out || 'waiting ' || (SELECT count(*) FROM verse.realm_proposals WHERE slug = s AND state = 'waiting') || E'\n';
  END IF;
  RETURN out;
END $$;


