--
-- Name: builder_wanted(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_wanted(prev jsonb, asked jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT verse.builder_wanted_0091(prev, coalesce((
    SELECT jsonb_agg(CASE WHEN a->>'feature' IS DISTINCT FROM 'none' AND jsonb_typeof(a->'missing') = 'string'
                          THEN a || jsonb_build_object('thing', a->'missing', 'same', verse.builder_line(a->'missing', 60) = '')
                          ELSE a END ORDER BY o)
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(asked) = 'array' THEN asked ELSE '[]' END) WITH ORDINALITY y(a, o)), asked)) $$;


--
-- Name: builder_wanted_0091(jsonb, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_wanted_0091(prev jsonb, asked jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY o), '[]') FROM (
    SELECT t, o FROM (
      SELECT DISTINCT ON (lower(t)) t, o FROM (
        SELECT verse.builder_line(v, 60) t, o FROM jsonb_array_elements(CASE WHEN jsonb_typeof(prev) = 'array' THEN prev ELSE '[]' END) WITH ORDINALITY x(v, o)
        UNION ALL
        SELECT verse.builder_line(a->'thing', 60), 100 + o FROM jsonb_array_elements(CASE WHEN jsonb_typeof(asked) = 'array' THEN asked ELSE '[]' END) WITH ORDINALITY y(a, o)
        WHERE a->>'feature' = 'none' OR (jsonb_typeof(a->'same') = 'boolean' AND NOT (a->>'same')::boolean)) u
      WHERE t <> '' ORDER BY lower(t), o) d
    ORDER BY o LIMIT 24) e $$;


--
-- Name: builder_wants(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.builder_wants(v jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'array' THEN coalesce((
    SELECT jsonb_agg(jsonb_build_object('thing', verse.builder_line(e->'thing', 60),
                                        'feature', CASE WHEN e->>'feature' = ANY (verse.builder_order()) THEN e->>'feature' ELSE 'none' END) ORDER BY o)
    FROM jsonb_array_elements(v) WITH ORDINALITY AS t(e, o)
    WHERE o <= 6 AND jsonb_typeof(e) = 'object' AND verse.builder_line(e->'thing', 60) <> ''), '[]') END $$;


--
-- Name: capacity_put(date, text, bigint, integer, boolean, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.capacity_put(day_ date, env_ text, at_ms_ bigint, seated_ integer, holds_ boolean, body_ text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE n int;
BEGIN
  INSERT INTO verse.capacity_records AS c (day, env, at_ms, seated, holds, body) VALUES (day_, env_, at_ms_, seated_, holds_, body_)
  ON CONFLICT (day, env) DO UPDATE SET at_ms = EXCLUDED.at_ms, seated = EXCLUDED.seated, holds = EXCLUDED.holds, body = EXCLUDED.body
  WHERE c.at_ms <= EXCLUDED.at_ms;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n = 1;
END $$;


--
-- Name: capacity_record(date); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.capacity_record(day_ date) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT c.body FROM verse.capacity_records c
  WHERE c.env <> 'local' AND (day_ IS NULL OR c.day = day_)
  ORDER BY c.day DESC, (c.env = 'staging') DESC, c.at_ms DESC LIMIT 1 $$;


--
-- Name: character_outbox; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.character_outbox (
    seq bigint NOT NULL,
    event text NOT NULL,
    who text NOT NULL,
    level integer NOT NULL,
    xp bigint NOT NULL,
    at_ms bigint NOT NULL,
    CONSTRAINT character_outbox_at_ms_check CHECK ((at_ms > 0)),
    CONSTRAINT character_outbox_level_check CHECK (((level >= 1) AND (level <= 20))),
    CONSTRAINT character_outbox_xp_check CHECK ((xp >= 0))
);


--
-- Name: character_outbox_since(bigint, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.character_outbox_since(after bigint, n integer) RETURNS SETOF verse.character_outbox
    LANGUAGE sql STABLE
    AS $$ SELECT * FROM verse.character_outbox WHERE seq > after ORDER BY seq LIMIT least(greatest(n, 0), 500) $$;


--
-- Name: character_xp_of(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.character_xp_of(b jsonb) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE WHEN b->>'xp' ~ '^[0-9]{1,7}$' THEN (b->>'xp')::bigint ELSE 0 END $_$;


--
-- Name: chat_from_demo(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.chat_from_demo() RETURNS integer
    LANGUAGE sql
    AS $_$
  WITH e AS (
    SELECT f.path, f.space, substring(f.path FROM '/chat-([A-Za-z0-9_-]{1,64})\.json$') AS room, x.v
    FROM verse.demo_files f, jsonb_array_elements(CASE WHEN jsonb_typeof(f.doc) = 'array' THEN f.doc ELSE '[]' END) AS x(v)
    WHERE f.path ~ '/chat-[A-Za-z0-9_-]{1,64}\.json$'
  ), todo AS (
    SELECT e.*, row_number() OVER (PARTITION BY room ORDER BY (v->>'at')::double precision, path, (v->>'n')::int) AS k
    FROM e
    WHERE room IS NOT NULL AND jsonb_typeof(v->'n') = 'number' AND jsonb_typeof(v->'at') = 'number'
      AND btrim(coalesce(v->>'text', '')) <> ''
      AND NOT EXISTS (SELECT 1 FROM verse.room_chat c WHERE c.import_key = e.path || '#' || (v->>'n'))
  ), n AS (
    INSERT INTO verse.room_chat (room, n, player, name, text, at, sid, space, source, import_key)
    SELECT room, coalesce((SELECT max(c.n) FROM verse.room_chat c WHERE c.room = todo.room), 0) + k::int, NULL,
           left(coalesce(nullif(btrim(v->>'name'), ''), 'Guest'), 40), left(btrim(v->>'text'), 500), (v->>'at')::double precision,
           CASE WHEN v->>'sid' ~ '^[A-Za-z0-9_:-]{1,80}$' THEN v->>'sid' END, space, path, path || '#' || (v->>'n')
    FROM todo ORDER BY room, k
    ON CONFLICT DO NOTHING RETURNING 1)
  SELECT count(*)::int FROM n
$_$;


--
-- Name: chat_mask(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.chat_mask(t text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE w text;
BEGIN
  IF t IS NULL THEN RETURN t; END IF;
  FOREACH w IN ARRAY verse.blocked_words() LOOP
    t := regexp_replace(t, w, repeat('*', length(w)), 'gi');
  END LOOP;
  RETURN t;
END $$;


--
-- Name: checkpoints_follow(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.checkpoints_follow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  was text:=coalesce(OLD.account,OLD.id); now_ text:=coalesce(NEW.account,NEW.id);
  floor_ bigint; v verse.character_checkpoints_v2;
BEGIN
  IF was=now_ THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM verse.character_profiles_v2 WHERE who IN(was,now_)) THEN RETURN NEW; END IF;
  INSERT INTO verse.character_profiles_v2 VALUES(now_) ON CONFLICT DO NOTHING;
  INSERT INTO verse.room_owners(who,gen,at) SELECT x,1,verse.now_ms() FROM unnest(ARRAY[was,now_]) x ORDER BY x ON CONFLICT(who) DO NOTHING;
  PERFORM 1 FROM verse.room_owners WHERE who IN(was,now_) ORDER BY who FOR UPDATE;
  SELECT max(gen)+1 INTO floor_ FROM verse.room_owners WHERE who IN(was,now_);
  IF floor_>2147483647 THEN RAISE EXCEPTION 'character owner exhausted'; END IF;
  UPDATE verse.room_owners SET gen=floor_,at=verse.now_ms() WHERE who IN(was,now_);
  SELECT * INTO v FROM verse.character_checkpoints_v2 WHERE who IN(was,now_) ORDER BY accepted_at DESC,who LIMIT 1;
  IF v.who IS NULL THEN RETURN NEW; END IF;
  INSERT INTO verse.character_checkpoints_v2(who,owner,process,rev,body,accepted_at)
  VALUES(now_,v.owner,v.process,v.rev,v.body,v.accepted_at)
  ON CONFLICT(who) DO UPDATE SET owner=EXCLUDED.owner,process=EXCLUDED.process,rev=EXCLUDED.rev,body=EXCLUDED.body,accepted_at=EXCLUDED.accepted_at;
  RETURN NEW;
END $$;


--
-- Name: clean_text(jsonb, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.clean_text(v jsonb, cap integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(btrim(regexp_replace(coalesce(CASE WHEN jsonb_typeof(v) = 'string' THEN v #>> '{}' END, ''), '[\x00-\x1f\x7f]+', ' ', 'g')), cap)
$$;


--
-- Name: course_hoops(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.course_hoops(v jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'array' AND jsonb_array_length(v) BETWEEN 3 AND 12
               AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v) h
                                WHERE jsonb_typeof(h) <> 'array' OR jsonb_array_length(h) <> 4
                                   OR EXISTS (SELECT 1 FROM jsonb_array_elements(h) n
                                               WHERE jsonb_typeof(n) <> 'number' OR abs((n #>> '{}')::numeric) > 1000))
         THEN (SELECT jsonb_agg((SELECT jsonb_agg(round((n #>> '{}')::numeric, 2) ORDER BY o) FROM jsonb_array_elements(h) WITH ORDINALITY AS t(n, o)) ORDER BY ho)
                 FROM jsonb_array_elements(v) WITH ORDINALITY AS u(h, ho))
         END
$$;


--
-- Name: course_view(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.course_view(cid text, me text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('id', c.id, 'realm', c.realm, 'by', verse.player_name(c.owner), 'mine', me IS NOT NULL AND c.owner = me,
           'hoops', c.hoops,
           'times', coalesce((SELECT jsonb_agg(jsonb_build_object('name', verse.player_name(t.player), 'ms', t.ms, 'mine', me IS NOT NULL AND t.player = me)
                                               ORDER BY t.ms, t.at_ms)
                              FROM (SELECT * FROM verse.course_times x WHERE x.course = c.id ORDER BY x.ms, x.at_ms LIMIT 10) t), '[]'),
           'best', (SELECT t.ms FROM verse.course_times t WHERE t.course = c.id AND t.player = me))
  FROM verse.courses c WHERE c.id = cid
$$;


--
-- Name: crash_add(bigint, bigint, text, integer, text, text, text, boolean, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.crash_add(now_ms bigint, at_ms_ bigint, source_ text, shard_ integer, release_ text, build_ text, sig_ text, auto_ boolean, body_ text) RETURNS text
    LANGUAGE sql
    AS $$
  INSERT INTO verse.crash_buckets (bucket, source, sig, first_ms, last_ms)
  VALUES (md5(source_ || ' ' || sig_), source_, sig_, now_ms, now_ms)
  ON CONFLICT (bucket) DO NOTHING;
  WITH kept AS (
    INSERT INTO verse.crash_reports (bucket, kept_ms, at_ms, source, shard, release, build, auto, body)
    VALUES (md5(source_ || ' ' || sig_), now_ms, at_ms_, source_, shard_, coalesce(release_, ''), coalesce(build_, ''), auto_, body_)
    ON CONFLICT (md5(body)) DO NOTHING RETURNING bucket
  )
  UPDATE verse.crash_buckets k SET last_ms = now_ms, reports = k.reports + 1,
    live_ms = CASE WHEN auto_ THEN k.live_ms ELSE now_ms END
  FROM kept WHERE k.bucket = kept.bucket;
  DELETE FROM verse.crash_reports r WHERE r.bucket = md5(source_ || ' ' || sig_)
    AND r.id NOT IN (SELECT x.id FROM verse.crash_reports x WHERE x.bucket = md5(source_ || ' ' || sig_) ORDER BY x.id DESC LIMIT 20);
  DELETE FROM verse.crash_buckets k WHERE k.last_ms < now_ms - 90::bigint * 86400000;
  SELECT md5(source_ || ' ' || sig_);
$$;


--
-- Name: crash_facts(bigint, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.crash_facts(now_ms bigint, window_ms bigint) RETURNS TABLE(bucket text, source text, sig text, age_ms bigint, shard integer, release text, buckets integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT k.bucket, k.source, k.sig, greatest(now_ms - k.last_ms, 0), n.shard, coalesce(n.release, ''), 1
  FROM verse.crash_buckets k
  LEFT JOIN LATERAL (SELECT r.shard, r.release FROM verse.crash_reports r WHERE r.bucket = k.bucket ORDER BY r.id DESC LIMIT 1) n ON true
  WHERE k.source = 'room' AND k.last_ms > now_ms - window_ms
  UNION ALL
  SELECT '', s.source, coalesce((SELECT k.sig FROM verse.crash_buckets k WHERE k.source = s.source AND k.live_ms IS NOT NULL ORDER BY k.live_ms DESC LIMIT 1), ''),
         (SELECT CASE WHEN max(k.live_ms) IS NULL THEN -1 ELSE greatest(now_ms - max(k.live_ms), 0) END FROM verse.crash_buckets k WHERE k.source = s.source), NULL, '',
         (SELECT count(*) FROM verse.crash_buckets k WHERE k.source = s.source AND k.live_ms > now_ms - window_ms)::int
  FROM (VALUES ('page'), ('app')) s (source)
  ORDER BY 2 DESC, 1 $$;


--
-- Name: crash_list(bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.crash_list(now_ms bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.last_ms DESC, x.bucket), '[]'::jsonb) FROM (
    SELECT k.bucket, k.source, k.sig, k.first_ms, k.last_ms, k.reports, n.shard, n.release, n.build, n.body AS newest
    FROM verse.crash_buckets k
    LEFT JOIN LATERAL (SELECT r.shard, r.release, r.build, r.body FROM verse.crash_reports r WHERE r.bucket = k.bucket ORDER BY r.id DESC LIMIT 1) n ON true
    WHERE k.last_ms > now_ms - 30::bigint * 86400000
    ORDER BY k.last_ms DESC LIMIT 50) x $$;


--
-- Name: crash_page_take(integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.crash_page_take(most integer) RETURNS TABLE(o_ms bigint, o_page text, o_auto boolean, o_rel text, o_msg text, o_trap text, o_frames text)
    LANGUAGE sql
    AS $$
  INSERT INTO verse.crash_cursor (one, event_id) SELECT true, coalesce(max(e.id), 0) FROM analytics.events e
  ON CONFLICT (one) DO NOTHING;
  WITH c AS (
    SELECT k.event_id AS from_id, coalesce((SELECT max(e.id) FROM analytics.events e), k.event_id) AS upto FROM verse.crash_cursor k
  ), took AS (
    SELECT e.id, e.ms, e.page, e.auto, e.p FROM analytics.events e, c
    WHERE e.id > c.from_id AND e.id <= c.upto AND e.ev = 'crash' AND (e.p->>'f0' IS NOT NULL OR e.p->>'trap' IS NOT NULL)
    ORDER BY e.id LIMIT most
  ), moved AS (
    UPDATE verse.crash_cursor k SET event_id = CASE WHEN (SELECT count(*) FROM took) >= most THEN (SELECT max(t.id) FROM took t) ELSE (SELECT c.upto FROM c) END
    RETURNING 1
  )
  SELECT t.ms, t.page, t.auto IS NOT NULL AND t.auto <> 'team', coalesce(t.p->>'rel', ''), coalesce(t.p->>'msg', ''), coalesce(t.p->>'trap', ''),
         concat_ws(E'\n', t.p->>'f0', t.p->>'f1', t.p->>'f2', t.p->>'f3', t.p->>'f4', t.p->>'f5', t.p->>'f6', t.p->>'f7')
  FROM took t, (SELECT count(*) FROM moved) m ORDER BY t.id;
$$;


--
-- Name: edit_decide(text, bigint, boolean, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_decide(s text, pid bigint, accept boolean, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  out jsonb;
  r0 bigint;
BEGIN
  SELECT rev INTO r0 FROM verse.made_realms WHERE slug = s AND base IS NULL FOR UPDATE;
  PERFORM set_config('verse.card', pid::text, true);
  out := verse.edit_decide_0093(s, pid, accept, k, site_admin);
  PERFORM set_config('verse.card', '', true);
  IF r0 IS NOT NULL AND (out->>'status') = '200' AND NOT accept THEN
    UPDATE verse.made_realms SET redo = '[]', undo = (SELECT CASE WHEN jsonb_array_length(u) > 64 THEN u - 0 ELSE u END
                                         FROM (SELECT undo || jsonb_build_array(jsonb_build_object('to', r0, 'card', pid, 'ops', '[]'::jsonb)) AS u) x)
    WHERE slug = s;
  END IF;
  RETURN out;
END $$;


--
-- Name: edit_decide_0093(text, bigint, boolean, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_decide_0093(s text, pid bigint, accept boolean, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  p verse.realm_proposals;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  SELECT * INTO p FROM verse.realm_proposals WHERE id = pid AND slug = s FOR UPDATE;
  IF p.id IS NULL THEN RETURN '{"status":404,"error":"no such proposal"}'; END IF;
  IF p.state <> 'waiting' THEN RETURN jsonb_build_object('status', 409, 'error', 'already ' || p.state); END IF;
  UPDATE verse.realm_proposals SET state = CASE WHEN accept THEN 'accepted' ELSE 'declined' END, decided_ms = verse.now_ms() WHERE id = pid;
  IF accept THEN
    IF verse.edit_made(s) THEN
      UPDATE verse.made_realms SET placed = placed || jsonb_build_array(p.change - 'kind') WHERE slug = s;
    ELSE
      INSERT INTO verse.realm_edit (slug, placed, ms) VALUES (s, jsonb_build_array(p.change - 'kind'), verse.now_ms())
      ON CONFLICT (slug) DO UPDATE SET placed = verse.realm_edit.placed || jsonb_build_array(p.change - 'kind'), ms = excluded.ms;
    END IF;
  END IF;
  RETURN jsonb_build_object('status', 200, 'state', CASE WHEN accept THEN 'accepted' ELSE 'declined' END);
END $$;


--
-- Name: realm_rights; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.realm_rights (
    slug text NOT NULL,
    owner_account text NOT NULL,
    admins text[] DEFAULT '{}'::text[] NOT NULL,
    tools text[] DEFAULT '{}'::text[] NOT NULL,
    things text[] DEFAULT '{}'::text[] NOT NULL,
    rows jsonb DEFAULT '[]'::jsonb NOT NULL
);


--
-- Name: edit_hand(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_hand(s text) RETURNS verse.realm_rights
    LANGUAGE sql STABLE
    AS $$
  SELECT * FROM verse.realm_rights WHERE slug = s $$;


--
-- Name: edit_hand_board(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_hand_board(s text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(r || jsonb_build_object('on', coalesce((e.switched->>(r->>'id'))::boolean, true)) ORDER BY o), '[]')
  FROM verse.realm_rights h LEFT JOIN verse.realm_edit e ON e.slug = h.slug, jsonb_array_elements(h.rows) WITH ORDINALITY AS t(r, o)
  WHERE h.slug = s $$;


--
-- Name: edit_hand_prompt(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_hand_prompt(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT replace(replace(verse.edit_hand_prompt_0110(s), 'You edit a realm of the Verse, a 3D world in the browser, for its owner. The realm is built by hand; ', 'You edit a world of the Verse, a 3D scene in the browser, for its owner. The world is built by hand; '), 'this realm', 'this world') $$;


--
-- Name: edit_hand_prompt_0110(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_hand_prompt_0110(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT 'You edit a realm of the Verse, a 3D world in the browser, for its owner. The realm is built by hand; '
      || 'what can change is which of its features are on. They said, out loud or typed, how they want it. '
      || 'Answer every feature with on true or false: change only what they asked about and keep the rest as it is now. '
      || E'If what they asked for is not one of these features, keep everything as it is.\nThe features:\n'
      || string_agg('- ' || (r->>'id') || ': ' || (r->>'says'), E'\n' ORDER BY o)
  FROM verse.realm_rights h, jsonb_array_elements(h.rows) WITH ORDINALITY AS t(r, o) WHERE h.slug = s $$;


--
-- Name: edit_hand_schema(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_hand_schema(s text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('type', 'object', 'required', jsonb_build_array('features'), 'properties', jsonb_build_object(
    'features', jsonb_build_object('type', 'array', 'items', jsonb_build_object('type', 'object', 'required', jsonb_build_array('id', 'on'),
      'properties', jsonb_build_object(
        'id', jsonb_build_object('type', 'string', 'enum', (SELECT jsonb_agg(r->'id') FROM verse.realm_rights h, jsonb_array_elements(h.rows) r WHERE h.slug = s)),
        'on', jsonb_build_object('type', 'boolean')))))) $$;


--
-- Name: edit_key(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_key(f jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN f->>'feature' = 'row' THEN f->>'variant'
              ELSE (f->>'feature') || coalesce(':' || CASE WHEN f->>'feature' = 'character' THEN regexp_replace(lower(f->>'name'), '[^a-z0-9]+', '-', 'g')
                                                          WHEN f->>'feature' IN ('props', 'building', 'herd') THEN f->>'variant' END, '') END $$;


--
-- Name: edit_lore(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_lore(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  v_who text := verse.pane_text(body->'who', 40);
  t text := verse.pane_text(body->'text', 400);
  m verse.made_realms;
BEGIN
  IF NOT verse.made_lore_realm(s) THEN RETURN verse.edit_lore_0055(s, body, k, site_admin); END IF;
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR NOT verse.pane_key_ok(v_who) THEN RETURN '{"status":400,"error":"say whose lore"}'; END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s FOR UPDATE;
  IF t = '' THEN
    UPDATE verse.made_realms SET lore = lore - v_who WHERE slug = s;
    RETURN jsonb_build_object('status', 200, 'who', v_who, 'saved', false);
  END IF;
  IF NOT (m.lore ? v_who) AND (SELECT count(*) FROM jsonb_object_keys(m.lore)) >= 40 THEN
    RETURN '{"status":409,"error":"this realm has lore for 40 characters"}';
  END IF;
  UPDATE verse.made_realms SET lore = jsonb_set(lore, ARRAY[v_who], to_jsonb(t)) WHERE slug = s;
  RETURN jsonb_build_object('status', 200, 'who', v_who, 'saved', true);
END $$;


--
-- Name: edit_lore_0055(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_lore_0055(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.edit_lore_0110(s, body, k, site_admin)) $$;


--
-- Name: edit_lore_0110(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_lore_0110(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  v_who text := verse.pane_text(body->'who', 40);
  t text := verse.pane_text(body->'text', 400);
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR NOT verse.pane_key_ok(v_who) THEN RETURN '{"status":400,"error":"say whose lore"}'; END IF;
  IF t = '' THEN
    DELETE FROM verse.realm_lore l WHERE l.slug = s AND l.who = v_who;
    RETURN jsonb_build_object('status', 200, 'who', v_who, 'saved', false);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM verse.realm_lore l WHERE l.slug = s AND l.who = v_who)
     AND (SELECT count(*) FROM verse.realm_lore l WHERE l.slug = s) >= 40 THEN
    RETURN '{"status":409,"error":"this realm has lore for 40 characters"}';
  END IF;
  INSERT INTO verse.realm_lore (slug, who, text, ms, by_player) VALUES (s, v_who, t, verse.now_ms(), (verse.builder_player(k)).id)
  ON CONFLICT (slug, who) DO UPDATE SET text = excluded.text, ms = excluded.ms, by_player = excluded.by_player;
  RETURN jsonb_build_object('status', 200, 'who', v_who, 'saved', true);
END $$;


--
-- Name: edit_made(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_made(s text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s) $$;


--
-- Name: edit_made_board(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_made_board(m verse.made_realms) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_agg(e ORDER BY array_position(verse.builder_order(), e->>'feature'), o), '[]')
  FROM (SELECT f || '{"on": true}' AS e, o FROM jsonb_array_elements(m.features) WITH ORDINALITY AS a(f, o)
        UNION ALL SELECT f || '{"on": false}', 1000 + o FROM jsonb_array_elements(m.off) WITH ORDINALITY AS b(f, o)) x $$;


--
-- Name: edit_may(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_may(s text, k text, site_admin boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(verse.edit_role(s, k, site_admin) IN ('owner', 'admin'), false) $$;


--
-- Name: edit_panes(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_panes(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  m verse.made_realms;
  live jsonb;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s AND base IS NULL;
  IF m.slug IS NULL OR verse.edit_role(s, k, site_admin) IS NULL THEN RETURN verse.edit_panes_0055(s, k, site_admin); END IF;
  IF NOT verse.edit_may(s, k, site_admin) AND (m.lore_since IS NULL OR m.published_rev >= m.lore_since) THEN
    live := verse.realm_live_doc(m);
    IF live IS NOT NULL THEN RETURN verse.panes_of(live->'lore', live->'quests'); END IF;
  END IF;
  RETURN verse.panes_of(m.lore, m.quests);
END $$;


--
-- Name: edit_panes_0055(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_panes_0055(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF verse.edit_role(s, k, site_admin) IS NULL THEN RETURN NULL; END IF;
  RETURN coalesce((SELECT string_agg('lore ' || who || '|' || text, E'\n' ORDER BY who) || E'\n' FROM verse.realm_lore WHERE slug = s), '')
      || coalesce((SELECT string_agg('quest ' || giver || '|' || ask || '|' || coalesce(steps[1], '') || '|' || coalesce(steps[2], '') || '|'
                                     || coalesce(steps[3], '') || '|' || reward, E'\n' ORDER BY giver) || E'\n'
                   FROM verse.realm_quests WHERE slug = s), '');
END $$;


--
-- Name: edit_place(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_place(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.edit_place_0110(s, body, k, site_admin)) $$;


--
-- Name: edit_place_0110(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_place_0110(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  rec verse.players := verse.builder_player(k);
  h verse.realm_rights := verse.edit_hand(s);
  e verse.realm_edit;
  x numeric := CASE WHEN jsonb_typeof(body->'x') = 'number' THEN (body->>'x')::numeric END;
  z numeric := CASE WHEN jsonb_typeof(body->'z') = 'number' THEN (body->>'z')::numeric END;
  yaw numeric := CASE WHEN jsonb_typeof(body->'yaw') = 'number' THEN (body->>'yaw')::numeric ELSE 0 END;
  thing text;
  change jsonb;
  pid bigint;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF verse.edit_made(s) THEN
    IF role = 'admin' THEN   -- an admin places as its owner would
      thing := CASE WHEN jsonb_typeof(body->'thing') = 'string' AND (body->>'thing') = ANY (verse.builder_things()) THEN body->>'thing' END;
      IF thing IS NULL OR x IS NULL OR z IS NULL OR abs(x) > 40 OR abs(z) > 40 THEN RETURN '{"status":400,"error":"not a thing here"}'; END IF;
      UPDATE verse.made_realms SET placed = placed || jsonb_build_array(jsonb_build_object('thing', thing, 'x', trim_scale(round(x, 2)), 'z', trim_scale(round(z, 2)), 'yaw', trim_scale(round(yaw, 3))))
      WHERE slug = s AND jsonb_array_length(placed) < 200;
      RETURN '{"status":200,"placed":true}';
    END IF;
    RETURN verse.builder_place(s, body, k);
  END IF;
  IF rec.id IS NULL THEN RETURN '{"status":401,"error":"no player"}'; END IF;
  thing := CASE WHEN jsonb_typeof(body->'thing') = 'string' AND (body->>'thing') = ANY (h.things) THEN body->>'thing' END;
  IF thing IS NULL OR x IS NULL OR z IS NULL OR abs(x) > 400 OR abs(z) > 400 THEN RETURN '{"status":400,"error":"not a thing here"}'; END IF;
  change := jsonb_build_object('kind', 'place', 'thing', thing, 'x', trim_scale(round(x, 2)), 'z', trim_scale(round(z, 2)), 'yaw', trim_scale(round(yaw, 3)));
  SELECT * INTO e FROM verse.realm_edit WHERE slug = s;
  IF role IN ('owner', 'admin') THEN
    IF jsonb_array_length(coalesce(e.placed, '[]')) >= 200 THEN RETURN '{"status":409,"error":"the realm is full"}'; END IF;
    INSERT INTO verse.realm_edit (slug, placed, ms, by_player) VALUES (s, jsonb_build_array(change - 'kind'), verse.now_ms(), rec.id)
    ON CONFLICT (slug) DO UPDATE SET placed = verse.realm_edit.placed || jsonb_build_array(change - 'kind'), ms = excluded.ms, by_player = excluded.by_player;
    RETURN '{"status":200,"placed":true}';
  END IF;
  IF NOT ('build' = ANY (h.tools)) OR NOT coalesce((e.tools->>'build')::boolean, true) THEN
    RETURN '{"status":403,"error":"the owner hasn''t let visitors build"}';
  END IF;
  IF (SELECT count(*) FROM verse.realm_proposals WHERE slug = s AND state = 'waiting') >= 50 THEN RETURN '{"status":429,"error":"the owner has enough to look at"}'; END IF;
  INSERT INTO verse.realm_proposals (slug, ms, by_player, change) VALUES (s, verse.now_ms(), rec.id, change) RETURNING id INTO pid;
  RETURN jsonb_build_object('status', 200, 'proposed', pid);
END $$;


--
-- Name: edit_proposals(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_proposals(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(string_agg('P ' || p.id || '|' || 'Visitor ' || right(coalesce(p.by_player, '----'), 4) || '|' || (p.change->>'thing') || '|'
         || (p.change->>'x') || '|' || (p.change->>'z') || '|' || (p.change->>'yaw') || '|' || n.before || '|' || (n.before + 1), E'\n' ORDER BY p.id DESC) || E'\n', '')
  FROM verse.realm_proposals p,
       LATERAL (SELECT count(*) AS before FROM jsonb_array_elements(coalesce((SELECT placed FROM verse.made_realms WHERE slug = s),
                                                                              (SELECT placed FROM verse.realm_edit WHERE slug = s), '[]')) e
                WHERE e->>'thing' = p.change->>'thing') n
  WHERE p.slug = s AND p.state = 'waiting' AND verse.edit_may(s, k, site_admin) $$;


--
-- Name: edit_quest(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_quest(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  v_giver text := verse.pane_text(body->'giver', 40);
  v_ask text := verse.pane_text(body->'ask', 160);
  v_reward text := verse.pane_text(body->'reward', 100);
  v_steps jsonb;
  m verse.made_realms;
BEGIN
  IF NOT verse.made_lore_realm(s) THEN RETURN verse.edit_quest_0055(s, body, k, site_admin); END IF;
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR NOT verse.pane_key_ok(v_giver) THEN RETURN '{"status":400,"error":"say who gives it"}'; END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s FOR UPDATE;
  IF v_ask = '' THEN
    UPDATE verse.made_realms SET quests = quests - v_giver WHERE slug = s;
    RETURN jsonb_build_object('status', 200, 'giver', v_giver, 'saved', false);
  END IF;
  v_steps := coalesce((SELECT jsonb_agg(t ORDER BY i) FROM (
             SELECT verse.pane_text(x, 100) t, i FROM jsonb_array_elements(CASE WHEN jsonb_typeof(body->'steps') = 'array' THEN body->'steps' ELSE '[]' END)
             WITH ORDINALITY a(x, i) ORDER BY i LIMIT 3) z), '[]');
  IF NOT (m.quests ? v_giver) AND (SELECT count(*) FROM jsonb_object_keys(m.quests)) >= 40 THEN
    RETURN '{"status":409,"error":"this realm has 40 quests"}';
  END IF;
  UPDATE verse.made_realms SET quests = jsonb_set(quests, ARRAY[v_giver], jsonb_build_object('ask', v_ask, 'steps', v_steps, 'reward', v_reward)) WHERE slug = s;
  RETURN jsonb_build_object('status', 200, 'giver', v_giver, 'saved', true);
END $$;


--
-- Name: edit_quest_0055(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_quest_0055(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.edit_quest_0110(s, body, k, site_admin)) $$;


--
-- Name: edit_quest_0110(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_quest_0110(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  v_giver text := verse.pane_text(body->'giver', 40);
  v_ask text := verse.pane_text(body->'ask', 160);
  v_reward text := verse.pane_text(body->'reward', 100);
  v_steps text[];
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR NOT verse.pane_key_ok(v_giver) THEN RETURN '{"status":400,"error":"say who gives it"}'; END IF;
  IF v_ask = '' THEN
    DELETE FROM verse.realm_quests q WHERE q.slug = s AND q.giver = v_giver;
    RETURN jsonb_build_object('status', 200, 'giver', v_giver, 'saved', false);
  END IF;
  v_steps := coalesce((SELECT array_agg(t ORDER BY i) FROM (
             SELECT verse.pane_text(x, 100) t, i FROM jsonb_array_elements(CASE WHEN jsonb_typeof(body->'steps') = 'array' THEN body->'steps' ELSE '[]' END)
             WITH ORDINALITY a(x, i) ORDER BY i LIMIT 3) z), '{}');
  IF NOT EXISTS (SELECT 1 FROM verse.realm_quests q WHERE q.slug = s AND q.giver = v_giver)
     AND (SELECT count(*) FROM verse.realm_quests q WHERE q.slug = s) >= 40 THEN
    RETURN '{"status":409,"error":"this realm has 40 quests"}';
  END IF;
  INSERT INTO verse.realm_quests (slug, giver, ask, steps, reward, ms, by_player)
  VALUES (s, v_giver, v_ask, v_steps, v_reward, verse.now_ms(), (verse.builder_player(k)).id)
  ON CONFLICT (slug, giver) DO UPDATE SET ask = excluded.ask, steps = excluded.steps, reward = excluded.reward, ms = excluded.ms, by_player = excluded.by_player;
  RETURN jsonb_build_object('status', 200, 'giver', v_giver, 'saved', true);
END $$;


--
-- Name: edit_revise_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_revise_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  pid bigint := (asked->>'id')::bigint;
  s text := (SELECT slug FROM verse.realm_plans WHERE id = pid);
  r jsonb;
  t text;
  d jsonb;
  held jsonb;
  err text;
  status int := 200;
  changed int := 0;
  turn jsonb := '{}';
BEGIN
  BEGIN r := response::jsonb; EXCEPTION WHEN others THEN r := NULL; END;
  IF http = 200 AND r IS NOT NULL THEN
    SELECT string_agg(p->>'text', '') INTO t FROM jsonb_array_elements(coalesce(r->'candidates'->0->'content'->'parts', '[]')) p
    WHERE coalesce((p->>'thought')::boolean, false) = false AND p ? 'text';
    BEGIN d := t::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
    IF d IS NULL THEN status := 503; err := 'no answer'; END IF;
  ELSE
    status := 503;
    err := CASE WHEN http = 429 THEN 'busy' WHEN http = 0 THEN 'model unreachable' ELSE 'model error ' || http END;
  END IF;
  IF status = 200 AND verse.edit_made(s) THEN
    held := verse.builder_hold(jsonb_build_object('name', 'x') || d);
    IF held IS NULL THEN status := 502; err := 'not a board';
    ELSE
      UPDATE verse.made_realms m SET
        ground = held->>'ground', time = held->>'time',
        features = coalesce((SELECT jsonb_agg(f - 'on') FROM jsonb_array_elements(held->'features') f WHERE (f->>'on')::boolean AND f->>'feature' <> 'tool'), '[]'),
        off = coalesce((SELECT jsonb_agg(f - 'on') FROM jsonb_array_elements(held->'features') f WHERE NOT (f->>'on')::boolean AND f->>'feature' <> 'tool'), '[]'),
        settings_ms = verse.now_ms()
      WHERE m.slug = s;
      changed := jsonb_array_length(held->'features');
    END IF;
  ELSIF status = 200 THEN
    SELECT coalesce(jsonb_object_agg(f->>'id', (f->>'on')::boolean), '{}') INTO turn
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'features') = 'array' THEN d->'features' ELSE '[]' END) f, verse.realm_rights h, jsonb_array_elements(h.rows) rw
    WHERE h.slug = s AND rw->>'id' = f->>'id' AND jsonb_typeof(f->'on') = 'boolean';
    SELECT count(*) INTO changed FROM jsonb_each(turn) x JOIN jsonb_array_elements(verse.edit_hand_board(s)) b ON b->>'id' = x.key
    WHERE (b->>'on')::boolean <> (x.value #>> '{}')::boolean;
    INSERT INTO verse.realm_edit (slug, switched, ms) VALUES (s, turn, verse.now_ms())
    ON CONFLICT (slug) DO UPDATE SET switched = verse.realm_edit.switched || turn, ms = excluded.ms;
  END IF;
  UPDATE verse.realm_plans SET board = coalesce(held, CASE WHEN status = 200 THEN jsonb_build_object('switched', turn) END), error = err,
    model = edit_revise_answer.model, ms_taken = taken WHERE id = pid;
  IF status <> 200 THEN RETURN jsonb_build_object('status', status, 'error', err); END IF;
  RETURN jsonb_build_object('status', 200, 'plan', pid, 'changed', changed, 'lines', 'plan ' || pid || E'\n' || verse.edit_rows(s));
END $$;


--
-- Name: edit_revise_ask(text, jsonb, integer, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_revise_ask(s text, body jsonb, cap integer, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  x jsonb := verse.edit_revise_ask_0078(s, body, cap, k, site_admin);
  p text := (SELECT palette FROM verse.made_realms WHERE slug = s AND (verse.fork_of(s)).slug IS NULL);
  t text;
BEGIN
  IF p IS NULL OR (x->>'status')::int <> 200 THEN RETURN x; END IF;
  t := x #>> '{request,contents,0,parts,0,text}';
  RETURN jsonb_set(x, '{request,contents,0,parts,0,text}', to_jsonb(replace(t, 'The current board: {', 'The current board: {"palette": "' || p || '", ')));
END $$;


--
-- Name: edit_revise_ask_0059(text, jsonb, integer, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_revise_ask_0059(s text, body jsonb, cap integer, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  said text := CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'prompt', 600) ELSE '' END;
  rec verse.players := verse.builder_player(k);
  m verse.made_realms;
  board jsonb;
  row_id bigint;
  sys text;
  schema jsonb;
  text_in text;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF said = '' THEN RETURN '{"status":400,"error":"say how it should change"}'; END IF;
  IF EXISTS (SELECT 1 FROM verse.realm_plans WHERE slug = s AND ms > verse.now_ms() - 2000)
     OR (rec.id IS NOT NULL AND EXISTS (SELECT 1 FROM verse.realm_plans WHERE player = rec.id AND ms > verse.now_ms() - 2000)) THEN
    RETURN '{"status":429,"error":"one at a time"}';
  END IF;
  IF (SELECT count(*) FROM verse.realm_plans WHERE ms > (extract(epoch FROM date_trunc('day', now())) * 1000)::bigint) >= cap THEN
    RETURN '{"status":503,"error":"the day''s plans are used up"}';
  END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NOT NULL THEN
    board := jsonb_build_object('name', m.name, 'style', m.style, 'ground', m.ground, 'time', m.time,
                                'features', (SELECT coalesce(jsonb_agg(f - 'label'), '[]') FROM jsonb_array_elements(verse.edit_made_board(m)) f));
    sys := verse.builder_prompt();
    schema := verse.builder_schema();
  ELSE
    board := jsonb_build_object('features', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', r->>'id', 'on', (r->>'on')::boolean)), '[]')
                                             FROM jsonb_array_elements(verse.edit_hand_board(s)) r));
    sys := verse.edit_hand_prompt(s);
    schema := verse.edit_hand_schema(s);
  END IF;
  INSERT INTO verse.realm_plans (ms, player, prompt, board_in, slug) VALUES (verse.now_ms(), rec.id, said, board, s) RETURNING id INTO row_id;
  text_in := 'The current board: ' || board::text || E'\nThey now say: ' || said;
  RETURN jsonb_build_object('status', 200, 'id', row_id, 'request', jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text', sys))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(jsonb_build_object('text', text_in)))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json', 'responseSchema', schema,
      'temperature', 0.3, 'maxOutputTokens', 4000, 'thinkingConfig', jsonb_build_object('thinkingLevel', 'LOW'))));
END $$;


--
-- Name: edit_revise_ask_0073(text, jsonb, integer, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_revise_ask_0073(s text, body jsonb, cap integer, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.builder_fast(verse.edit_revise_ask_0059(s, body, cap, k, site_admin)) $$;


--
-- Name: edit_revise_ask_0078(text, jsonb, integer, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_revise_ask_0078(s text, body jsonb, cap integer, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  m verse.made_realms := verse.fork_of(s);
  role text := verse.edit_role(s, k, site_admin);
  said text := CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'prompt', 600) ELSE '' END;
  rec verse.players := verse.builder_player(k);
  board jsonb;
  row_id bigint;
  sys text;
  ids jsonb;
BEGIN
  IF m.slug IS NULL THEN RETURN verse.edit_revise_ask_0073(s, body, cap, k, site_admin); END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF said = '' THEN RETURN '{"status":400,"error":"say how it should change"}'; END IF;
  IF EXISTS (SELECT 1 FROM verse.realm_plans WHERE slug = s AND ms > verse.now_ms() - 2000)
     OR (rec.id IS NOT NULL AND EXISTS (SELECT 1 FROM verse.realm_plans WHERE player = rec.id AND ms > verse.now_ms() - 2000)) THEN
    RETURN '{"status":429,"error":"one at a time"}';
  END IF;
  IF (SELECT count(*) FROM verse.realm_plans WHERE ms > (extract(epoch FROM date_trunc('day', now())) * 1000)::bigint) >= cap THEN
    RETURN '{"status":503,"error":"the day''s plans are used up"}';
  END IF;
  board := jsonb_build_object('features', verse.fork_board(m));
  ids := (SELECT jsonb_agg(f->'variant') FROM jsonb_array_elements(verse.edit_made_board(m)) f WHERE f->>'feature' = 'row');
  sys := 'You edit a realm of the Verse, a 3D world in the browser, for its owner: their fork of ' || verse.fork_name_of(m.base)
      || ', whose rules and features they switch on and off. They said, out loud or typed, how they want it. '
      || 'Answer every feature with on true or false: change only what they asked about and keep the rest as it is now. '
      || E'If what they asked for is not one of these features, keep everything as it is.\nThe features:\n'
      || (SELECT string_agg('- ' || (f->>'variant') || ': ' || coalesce(f->>'says', f->>'label'), E'\n' ORDER BY o)
          FROM jsonb_array_elements(verse.edit_made_board(m)) WITH ORDINALITY AS t(f, o) WHERE f->>'feature' = 'row');
  INSERT INTO verse.realm_plans (ms, player, prompt, board_in, slug) VALUES (verse.now_ms(), rec.id, said, board, s) RETURNING id INTO row_id;
  RETURN verse.builder_fast(jsonb_build_object('status', 200, 'id', row_id, 'request', jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text', sys))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(jsonb_build_object('text',
      'The current board: ' || board::text || E'\nThey now say: ' || said)))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json', 'temperature', 0.3, 'maxOutputTokens', 4000,
      'responseSchema', jsonb_build_object('type', 'object', 'required', jsonb_build_array('features'), 'properties', jsonb_build_object(
        'features', jsonb_build_object('type', 'array', 'items', jsonb_build_object('type', 'object', 'required', jsonb_build_array('id', 'on'),
          'properties', jsonb_build_object('id', jsonb_build_object('type', 'string', 'enum', ids), 'on', jsonb_build_object('type', 'boolean'))))))))));
END $$;


--
-- Name: edit_role(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_role(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  rec verse.players := verse.builder_player(k);
  h verse.realm_rights := verse.edit_hand(s);
BEGIN
  IF verse.edit_made(s) THEN
    IF verse.builder_owns(k, s) THEN RETURN 'owner'; END IF;
    RETURN CASE WHEN site_admin THEN 'admin' ELSE 'visitor' END;
  END IF;
  IF h.slug IS NULL THEN RETURN NULL; END IF;
  IF rec.account IS NOT NULL AND rec.account = h.owner_account THEN RETURN 'owner'; END IF;
  IF site_admin OR (rec.account IS NOT NULL AND rec.account = ANY (h.admins)) THEN RETURN 'admin'; END IF;
  RETURN 'visitor';
END $$;


--
-- Name: edit_rows(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_rows(s text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  m verse.made_realms;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NOT NULL THEN
    RETURN coalesce((SELECT string_agg('row ' || verse.edit_key(f) || ' ' || CASE WHEN (f->>'on')::boolean THEN '1' ELSE '0' END || ' ' || (f->>'label'), E'\n' ORDER BY o)
                     FROM jsonb_array_elements(verse.edit_made_board(m)) WITH ORDINALITY AS t(f, o)) || E'\n', '');
  END IF;
  RETURN coalesce((SELECT string_agg('row ' || (r->>'id') || ' ' || CASE WHEN (r->>'on')::boolean THEN '1' ELSE '0' END || ' ' || (r->>'label'), E'\n' ORDER BY o)
                   FROM jsonb_array_elements(verse.edit_hand_board(s)) WITH ORDINALITY AS t(r, o)) || E'\n', '');
END $$;


--
-- Name: edit_settings(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_settings(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.edit_settings_0110(s, body, k, site_admin)) $$;


--
-- Name: edit_settings_0110(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_settings_0110(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  t jsonb := CASE WHEN jsonb_typeof(body->'tools') = 'object' THEN body->'tools' ELSE '{}' END;
  m verse.made_realms;
  h verse.realm_rights := verse.edit_hand(s);
  e verse.realm_edit;
  next jsonb;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NOT NULL THEN
    next := (SELECT jsonb_object_agg(x, CASE WHEN jsonb_typeof(t->x) = 'boolean' THEN (t->>x)::boolean ELSE coalesce((m.tools->>x)::boolean, false) END)
             FROM unnest(verse.builder_tools()) x);
    UPDATE verse.made_realms SET tools = next, settings_ms = verse.now_ms() WHERE slug = s;
    RETURN jsonb_build_object('status', 200, 'tools', next);
  END IF;
  SELECT * INTO e FROM verse.realm_edit WHERE slug = s;
  next := coalesce((SELECT jsonb_object_agg(x, CASE WHEN jsonb_typeof(t->x) = 'boolean' THEN (t->>x)::boolean ELSE coalesce((e.tools->>x)::boolean, true) END)
                    FROM unnest(h.tools) x), '{}');
  INSERT INTO verse.realm_edit (slug, tools, ms, by_player) VALUES (s, next, verse.now_ms(), (verse.builder_player(k)).id)
  ON CONFLICT (slug) DO UPDATE SET tools = excluded.tools, ms = excluded.ms, by_player = excluded.by_player;
  RETURN jsonb_build_object('status', 200, 'tools', next);
END $$;


--
-- Name: edit_spec(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN out IS NULL OR NOT verse.edit_may(s, k, site_admin) THEN out
              ELSE out || coalesce((SELECT 'redo ' || jsonb_array_length(redo) || E'\n' FROM verse.made_realms WHERE slug = s AND base IS NULL), '') END
  FROM (SELECT verse.edit_spec_0109(s, k, site_admin) AS out) x $$;


--
-- Name: edit_spec_0092(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec_0092(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  may boolean := role IN ('owner', 'admin');
  h verse.realm_rights;
  e verse.realm_edit;
  out text;
BEGIN
  IF role IS NULL THEN RETURN NULL; END IF;
  IF verse.edit_made(s) THEN
    out := verse.builder_spec(s, k);
    IF may AND role = 'admin' THEN
      out := replace(out, E'\nowner 0\n', E'\nowner 1\n')
          || 'waiting ' || (SELECT count(*) FROM verse.realm_proposals WHERE slug = s AND state = 'waiting') || E'\n';
    END IF;
    RETURN out || 'role ' || role || E'\n' || verse.edit_rows(s);
  END IF;
  h := verse.edit_hand(s);
  SELECT * INTO e FROM verse.realm_edit WHERE slug = s;
  out := 'realm ' || s || E'\nrole ' || role || E'\nowner ' || CASE WHEN may THEN '1' ELSE '0' END || E'\n';
  out := out || coalesce((SELECT string_agg('tool ' || t || ' ' || CASE WHEN coalesce((e.tools->>t)::boolean, true) THEN '1' ELSE '0' END, E'\n' ORDER BY o)
                          FROM unnest(h.tools) WITH ORDINALITY AS x(t, o)) || E'\n', '');
  out := out || coalesce((SELECT string_agg('thing ' || t, E'\n' ORDER BY o) FROM unnest(h.things) WITH ORDINALITY AS x(t, o)) || E'\n', '');
  out := out || verse.edit_rows(s);
  out := out || coalesce((SELECT string_agg('placed ' || (p->>'thing') || ' ' || (p->>'x') || ' ' || (p->>'z') || ' ' || (p->>'yaw'), E'\n' ORDER BY o)
                          FROM jsonb_array_elements(coalesce(e.placed, '[]')) WITH ORDINALITY AS x(p, o)) || E'\n', '');
  IF may THEN
    out := out || 'waiting ' || (SELECT count(*) FROM verse.realm_proposals WHERE slug = s AND state = 'waiting') || E'\n';
  END IF;
  RETURN out;
END $$;


--
-- Name: edit_spec_0093(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec_0093(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  out text := verse.edit_spec_0092(s, k, site_admin);
  m verse.made_realms;
BEGIN
  IF out IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s;
  IF m.slug IS NULL THEN RETURN out; END IF;
  RETURN out || 'rev ' || m.rev || E'\npublished ' || coalesce(m.published_rev, 0) || E'\nlisted ' || CASE WHEN m.unlisted THEN '0' ELSE '1' END || E'\n'
      || CASE WHEN m.forked_from IS NOT NULL AND m.base IS NULL
              THEN 'from ' || m.forked_from || ' ' || coalesce(m.forked_rev, 0) || '|' || verse.builder_one_line(to_jsonb(verse.fork_name_of(m.forked_from)), 60) || E'\n' ELSE '' END
      || coalesce((SELECT string_agg('moved ' || (v->>'entity') || ' ' || to_char((v->>'x')::numeric, 'FM990.00') || ' ' || to_char((v->>'z')::numeric, 'FM990.00'), E'\n' ORDER BY o)
                   FROM jsonb_array_elements(m.moved) WITH ORDINALITY AS t(v, o)) || E'\n', '');
END $$;


--
-- Name: edit_spec_0094(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec_0094(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  m verse.made_realms;
  live jsonb;
BEGIN
  SELECT * INTO m FROM verse.made_realms WHERE slug = s AND base IS NULL;
  IF m.slug IS NULL THEN RETURN verse.edit_spec_0093(s, k, site_admin); END IF;
  IF NOT verse.edit_may(s, k, site_admin) THEN
    live := verse.realm_live_doc(m);
    RETURN CASE WHEN live IS NOT NULL THEN verse.realm_live_spec(m, live) ELSE verse.edit_spec_0093(s, k, site_admin) END;
  END IF;
  RETURN verse.edit_spec_0093(s, k, site_admin) || 'undo ' || jsonb_array_length(m.undo) || E'\n';
END $$;


--
-- Name: edit_spec_0099(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec_0099(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN out IS NULL THEN NULL
              ELSE out || coalesce((SELECT 'visibility ' || m.visibility || E'\n' FROM verse.made_realms m WHERE m.slug = s), '') END
  FROM (SELECT verse.edit_spec_0094(s, k, site_admin) AS out) x $$;


--
-- Name: edit_spec_0107(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec_0107(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN out IS NULL THEN NULL
              ELSE out || coalesce((SELECT 'engine ' || m.published_engine_sha256 || E'\n' FROM verse.made_realms m
                                    WHERE m.slug = s AND m.base IS NULL AND m.published_engine_sha256 IS NOT NULL), '') END
  FROM (SELECT verse.edit_spec_0099(s, k, site_admin) AS out) x $$;


--
-- Name: edit_spec_0109(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_spec_0109(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN out IS NULL OR NOT EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s AND base IS NULL) THEN out
              ELSE out || coalesce((SELECT string_agg('shaped ' || (v->>'entity') || ' ' || (v->>'yaw') || ' ' || (v->>'scale') || ' '
                                                      || CASE WHEN (v->>'gone')::boolean THEN '1' ELSE '0' END, E'\n' ORDER BY o) || E'\n'
                                    FROM jsonb_array_elements(coalesce(verse.realm_doc_of(s, k, site_admin)->'doc'->'shaped', '[]')) WITH ORDINALITY AS t(v, o)), '')
                       || E'shapes 1\n' END
  FROM (SELECT verse.edit_spec_0107(s, k, site_admin) AS out) x $$;


--
-- Name: edit_switch(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_switch(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.edit_switch_0110(s, body, k, site_admin)) $$;


--
-- Name: edit_switch_0110(text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.edit_switch_0110(s text, body jsonb, k text, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  role text := verse.edit_role(s, k, site_admin);
  key text := CASE WHEN jsonb_typeof(body->'row') = 'string' THEN body->>'row' END;
  turn boolean := CASE WHEN jsonb_typeof(body->'on') = 'boolean' THEN (body->>'on')::boolean END;
  m verse.made_realms;
  f jsonb;
BEGIN
  IF role IS NULL THEN RETURN '{"status":404,"error":"no such realm"}'; END IF;
  IF role NOT IN ('owner', 'admin') THEN RETURN '{"status":403,"error":"only its owner and admins"}'; END IF;
  IF key IS NULL OR turn IS NULL THEN RETURN '{"status":400,"error":"a row and on"}'; END IF;
  SELECT * INTO m FROM verse.made_realms WHERE slug = s FOR UPDATE;
  IF m.slug IS NOT NULL THEN
    SELECT e INTO f FROM jsonb_array_elements(verse.edit_made_board(m)) e WHERE verse.edit_key(e) = key LIMIT 1;
    IF f IS NULL THEN RETURN '{"status":404,"error":"no such row"}'; END IF;
    UPDATE verse.made_realms SET
      features = coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(features) x WHERE verse.edit_key(x) <> key), '[]')
                 || CASE WHEN turn THEN jsonb_build_array(f - 'on') ELSE '[]' END,
      off = coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(off) x WHERE verse.edit_key(x) <> key), '[]')
            || CASE WHEN turn THEN '[]' ELSE jsonb_build_array(f - 'on') END,
      settings_ms = verse.now_ms()
    WHERE slug = s;
    RETURN jsonb_build_object('status', 200, 'row', key, 'on', turn);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM verse.realm_rights h, jsonb_array_elements(h.rows) r WHERE h.slug = s AND r->>'id' = key) THEN
    RETURN '{"status":404,"error":"no such row"}';
  END IF;
  INSERT INTO verse.realm_edit (slug, switched, ms, by_player) VALUES (s, jsonb_build_object(key, turn), verse.now_ms(), (verse.builder_player(k)).id)
  ON CONFLICT (slug) DO UPDATE SET switched = verse.realm_edit.switched || jsonb_build_object(key, turn), ms = excluded.ms, by_player = excluded.by_player;
  RETURN jsonb_build_object('status', 200, 'row', key, 'on', turn);
END $$;


--
-- Name: engine_manifest(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.engine_manifest(t text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  open text := '<script type="module" src="';
  rest text := t;
  at int;
  e int;
  tag text;
  found text;
  a text[];
  v text;
  names text[] := '{}';
  out text := E'aethyr-engine 1\n';
  has_src boolean := false;
  has_wasm boolean := false;
  has_wgsl boolean := false;
BEGIN
  IF t IS NULL THEN RETURN NULL; END IF;
  LOOP   -- every script that opens like the engine's; exactly one of them is myrealm's
    at := strpos(rest, open);
    EXIT WHEN at = 0;
    e := strpos(substr(rest, at), '>');
    IF e = 0 THEN RETURN NULL; END IF;
    tag := substr(rest, at, e - 1);
    IF strpos(tag, ' data-app="myrealm"') > 0 THEN
      IF found IS NOT NULL THEN RETURN NULL; END IF;
      found := substr(tag, 8);
    END IF;
    rest := substr(rest, at + 1);
  END LOOP;
  IF found IS NULL OR found !~ E'^([ \n\t\r]*[^ \n\t\r=]+="[^"]*")*[ \n\t\r]*$' THEN RETURN NULL; END IF;
  FOR a IN SELECT regexp_matches(found, E'([^ \n\t\r=]+)="([^"]*)"', 'g') LOOP
    IF a[1] !~ '^[a-z][a-z-]{0,31}$' OR a[1] = ANY (names) OR cardinality(names) >= 24 THEN RETURN NULL; END IF;
    names := names || a[1];
    v := btrim(regexp_replace(a[2], E'[ \n\t\r]+', ' ', 'g'), ' ');
    IF NOT verse.engine_value_ok(v) THEN RETURN NULL; END IF;
    IF a[1] = 'src' THEN has_src := v ~ '^/coaxial/host\.[0-9a-f]{12}\.js$'; END IF;
    IF a[1] = 'data-app' AND v <> 'myrealm' THEN RETURN NULL; END IF;
    IF a[1] = 'data-wasm' THEN has_wasm := verse.engine_path_ok(v); END IF;
    IF a[1] = 'data-wgsl' THEN has_wgsl := verse.engine_path_ok(v); END IF;
    out := out || a[1] || ' ' || v || E'\n';
  END LOOP;
  IF NOT (has_src AND has_wasm AND has_wgsl) OR octet_length(out) > 4096 THEN RETURN NULL; END IF;
  RETURN out;
END $_$;


--
-- Name: engine_path_ok(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.engine_path_ok(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT coalesce(length(p) BETWEEN 2 AND 200 AND p ~ '^/[a-z0-9._/-]+$' AND p !~ '//' AND right(p, 1) <> '/'
         AND p !~ '/\.\.?(/|$)' AND p ~ '/([^/]+\.[0-9a-f]{12}\.[^/]+|[0-9a-f]{64})(/|$)', false) $_$;


--
-- Name: engine_value_ok(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.engine_value_ok(v text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT v IS NOT NULL AND v <> '' AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(v, ' ')) x(w) WHERE NOT verse.engine_word_ok(w)) $$;


--
-- Name: engine_word_ok(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.engine_word_ok(w text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE WHEN w IS NULL OR w = '' THEN false
              WHEN strpos(w, '/') = 0 THEN w ~ '^[A-Za-z0-9._:=-]+$'
              ELSE (strpos(w, '/') = 1 OR left(w, strpos(w, '/') - 1) ~ '^[a-z0-9_:=-]*[:=]$')
                   AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(substr(w, strpos(w, '/')), '|')) x(p) WHERE NOT verse.engine_path_ok(p)) END $_$;


--
-- Name: feedback(text[], jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.feedback(parts text[], body jsonb, auto text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  a jsonb := body->'a';
  skip boolean := coalesce(body->'skip' = 'true'::jsonb, false);
  n int; total int;
  now_s double precision := extract(epoch FROM clock_timestamp());
BEGIN
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN RETURN verse.r(400, '{"error":"expected an object"}'); END IF;
  IF parts = ARRAY['survey'] THEN   -- the whole form at once (before the demo's revision 7)
    INSERT INTO analytics.surveys (id, at, answers, auto, space) VALUES (verse.hex(16), now_s, body, nullif(auto, ''), 'web');
    RETURN verse.r(200, '{}');
  END IF;
  IF parts <> ARRAY['survey', 'answer'] THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
  IF coalesce(body->>'rid', '') !~ '^[0-9a-f]{16}$' OR jsonb_typeof(body->'rid') <> 'string' THEN
    RETURN verse.r(400, '{"error":"expected a respondent id"}');
  END IF;
  IF coalesce(body->>'q', '') !~ '^[A-Za-z][A-Za-z0-9_]{0,23}$' OR jsonb_typeof(body->'q') <> 'string' THEN
    RETURN verse.r(400, '{"error":"expected a question id"}');
  END IF;
  IF skip THEN a := NULL;
  ELSIF jsonb_typeof(a) = 'string' THEN a := to_jsonb(left(btrim(a #>> '{}'), 1000));
  ELSIF jsonb_typeof(a) = 'array' THEN
    a := coalesce((SELECT jsonb_agg(to_jsonb(left(v #>> '{}', 80)) ORDER BY o) FROM jsonb_array_elements(a) WITH ORDINALITY x(v, o)
                   WHERE o <= 16 AND jsonb_typeof(v) = 'string'), '[]');
  ELSIF a IS NOT NULL AND jsonb_typeof(a) <> 'null' THEN RETURN verse.r(400, '{"error":"an answer is text or a list of choices"}');
  ELSE a := NULL;
  END IF;
  IF a IN ('""'::jsonb, '[]'::jsonb) OR a IS NULL THEN a := NULL; skip := true; END IF;
  n := CASE WHEN jsonb_typeof(body->'n') = 'number' AND (body->>'n') ~ '^[0-9]+$' AND (body->>'n')::int BETWEEN 1 AND 99 THEN (body->>'n')::int END;
  total := CASE WHEN jsonb_typeof(body->'of') = 'number' AND (body->>'of') ~ '^[0-9]+$' AND (body->>'of')::int BETWEEN 1 AND 99 THEN (body->>'of')::int END;
  INSERT INTO analytics.survey_answers (id, at, rid, q, a, skip, n, "of", player, sid, "user", joined_as, auto, space)
  VALUES (verse.hex(16), now_s, body->>'rid', body->>'q', a, skip, n, total, left(coalesce(body->>'player', ''), 32),
          left(coalesce(body->>'sid', ''), 80), left(coalesce(body->>'user', ''), 64), left(coalesce(body->>'joinedAs', ''), 120),
          nullif(auto, ''), 'web');
  RETURN verse.r(200, '{"saved":true}');
END $_$;


--
-- Name: flag_clear(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.flag_clear(name_ text) RETURNS integer
    LANGUAGE sql
    AS $$
  WITH d AS (DELETE FROM verse.flags WHERE name = name_ RETURNING 1) SELECT count(*)::int FROM d $$;


--
-- Name: flag_put(text, bigint, bigint, text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.flag_put(name_ text, value_ bigint, until_ms_ bigint, why_ text, by_ text) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO verse.flags (name, value, until_ms, why, set_ms, set_by) VALUES (name_, value_, until_ms_, why_, verse.now_ms(), by_)
  ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value, until_ms = EXCLUDED.until_ms, why = EXCLUDED.why, set_ms = EXCLUDED.set_ms, set_by = EXCLUDED.set_by $$;


--
-- Name: fork_bases; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.fork_bases (
    slug text NOT NULL,
    title text NOT NULL,
    style text NOT NULL,
    ground text DEFAULT 'forest'::text NOT NULL,
    rules jsonb DEFAULT '[]'::jsonb NOT NULL
);


--
-- Name: fork_base_of(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_base_of(s text) RETURNS verse.fork_bases
    LANGUAGE sql STABLE
    AS $$
  SELECT b.* FROM verse.fork_bases b WHERE b.slug = coalesce((SELECT base FROM verse.made_realms WHERE slug = s AND base IS NOT NULL), s) $$;


--
-- Name: fork_board(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_board(m verse.made_realms) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', f->>'variant', 'on', (f->>'on')::boolean)), '[]')
  FROM jsonb_array_elements(verse.edit_made_board(m)) f WHERE f->>'feature' = 'row' $$;


--
-- Name: fork_info(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_info(s text, k text, site_admin boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  b verse.fork_bases := verse.fork_base_of(s);
  m verse.made_realms := verse.fork_of(s);
  on_ text[];
BEGIN
  IF b.slug IS NULL THEN RETURN NULL; END IF;
  on_ := CASE WHEN m.slug IS NOT NULL THEN verse.fork_rules_on(m) ELSE '{}' END;
  RETURN 'base ' || b.slug || E'\ntitle ' || b.title || E'\nfork ' || CASE WHEN m.slug IS NULL THEN '0' ELSE '1' END || E'\n'
      || CASE WHEN m.slug IS NULL THEN '' ELSE 'from ' || m.forked_from || '|' || verse.fork_name_of(m.forked_from) || E'\n' END
      || 'maker ' || verse.fork_maker(b.slug) || E'\nname ' || coalesce(m.name, b.title) || E'\n'
      || 'owner ' || CASE WHEN m.slug IS NOT NULL AND verse.edit_may(s, k, site_admin) THEN '1' ELSE '0' END || E'\n'
      || 'published ' || CASE WHEN m.published_ms IS NOT NULL THEN '1' ELSE '0' END || E'\n'
      || coalesce((SELECT string_agg('rule ' || (r->>'id') || ' ' || CASE WHEN (r->>'id') = ANY (on_) THEN '1' ELSE '0' END || ' ' || (r->>'label'), E'\n' ORDER BY o)
                   FROM jsonb_array_elements(b.rules) WITH ORDINALITY AS t(r, o)) || E'\n', '');
END $$;


--
-- Name: fork_line(verse.made_realms); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_line(m verse.made_realms) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT 'A fork of ' || verse.fork_name_of(m.forked_from) || ' on the OpenAgents Metaverse'
      || CASE WHEN m.forked_from <> m.base THEN ' (from ' || b.title || ' by ' || verse.fork_maker(m.base) || ')' ELSE ' by ' || verse.fork_maker(m.base) END
      || coalesce(': ' || lower(nullif((SELECT string_agg(r->>'label', ', ' ORDER BY o) FROM jsonb_array_elements(b.rules) WITH ORDINALITY AS t(r, o)
                                  WHERE (r->>'id') = ANY (verse.fork_rules_on(m))), '')) || '.', ', with the same rules.')
  FROM verse.fork_bases b WHERE b.slug = m.base $$;


--
-- Name: fork_make(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_make(s text, body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT replace(verse.worlds_answer(verse.fork_make_0110(s, body, k, per_day))::text, '"/realms/', '"/worlds/')::jsonb $$;


--
-- Name: fork_make_0075(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_make_0075(s text, body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec verse.players := verse.builder_player(k);
  b verse.fork_bases := verse.fork_base_of(s);
  src verse.made_realms := verse.fork_of(s);
  asked jsonb := CASE WHEN jsonb_typeof(body) = 'object' AND jsonb_typeof(body->'rules') = 'array' THEN body->'rules' ELSE '[]' END;
  rules text[];
  bad text;
  nm text;
  rows jsonb;
  slug_ text;
BEGIN
  IF b.slug IS NULL THEN RETURN '{"status":404,"error":"this realm can''t be forked"}'; END IF;
  IF rec.id IS NULL THEN RETURN '{"status":401,"error":"no player"}'; END IF;
  IF jsonb_array_length(asked) > 16 THEN RETURN '{"status":400,"error":"too many rules"}'; END IF;
  SELECT y.x INTO bad FROM jsonb_array_elements(asked) a(v), LATERAL (SELECT CASE WHEN jsonb_typeof(a.v) = 'string' THEN a.v #>> '{}' ELSE '?' END x) y
  WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(b.rules) r(v) WHERE r.v->>'id' = y.x) LIMIT 1;
  IF bad IS NOT NULL THEN RETURN jsonb_build_object('status', 400, 'error', 'not a rule here: ' || left(regexp_replace(bad, '[^a-z0-9-]', '', 'g'), 24)); END IF;
  rules := ARRAY(SELECT DISTINCT a.v #>> '{}' FROM jsonb_array_elements(asked) a(v));
  IF jsonb_typeof(body->'name') = 'string' THEN
    nm := btrim(regexp_replace(verse.builder_one_line(body->'name', 40), '[<>&"]', '', 'g'));
    IF (body->>'name') <> '' AND nm = '' THEN RETURN '{"status":400,"error":"a name of plain words"}'; END IF;
  END IF;
  IF (SELECT count(*) FROM verse.made_realms m JOIN verse.worlds w ON w.id = m.world
      WHERE w.owner_player = rec.id AND m.made_ms > verse.now_ms() - 86400000) >= per_day THEN
    RETURN '{"status":429,"error":"that''s today''s realms"}';
  END IF;
  nm := coalesce(nullif(nm, ''), left(verse.fork_name_of(s), 34) || ' Fork');
  -- the board: the base's rows as they are now (or the fork's), then its rules, on as chosen
  IF src.slug IS NOT NULL THEN
    rows := coalesce((SELECT jsonb_agg(f || jsonb_build_object('on', true)) FROM jsonb_array_elements(src.features) f WHERE NOT coalesce((f->>'rule')::boolean, false)), '[]')
         || coalesce((SELECT jsonb_agg(f || jsonb_build_object('on', false)) FROM jsonb_array_elements(src.off) f WHERE NOT coalesce((f->>'rule')::boolean, false)), '[]');
  ELSE
    rows := coalesce((SELECT jsonb_agg(jsonb_build_object('feature', 'row', 'variant', r->>'id', 'label', r->>'label', 'says', r->>'says', 'rule', false,
                                                          'on', coalesce((e.switched->>(r->>'id'))::boolean, true)) ORDER BY o)
                      FROM verse.realm_rights h LEFT JOIN verse.realm_edit e ON e.slug = h.slug, jsonb_array_elements(h.rows) WITH ORDINALITY AS t(r, o)
                      WHERE h.slug = b.slug), '[]');
  END IF;
  rows := rows || coalesce((SELECT jsonb_agg(jsonb_build_object('feature', 'row', 'variant', r->>'id', 'label', r->>'label', 'says', r->>'says', 'rule', true,
                                                                'on', (r->>'id') = ANY (rules)) ORDER BY o)
                            FROM jsonb_array_elements(b.rules) WITH ORDINALITY AS t(r, o)), '[]');
  slug_ := verse.builder_slug(nm);
  INSERT INTO verse.worlds (id, owner_player, owner_account, created_ms) VALUES ('made-' || slug_, rec.id, rec.account, verse.now_ms());
  INSERT INTO verse.made_realms (slug, world, name, style, ground, time, camera, features, off, tools, made_ms, base, forked_from)
  VALUES (slug_, 'made-' || slug_, nm, b.style, b.ground, CASE WHEN 'night' = ANY (rules) THEN 'night' ELSE 'day' END, 'third',
          coalesce((SELECT jsonb_agg(f - 'on') FROM jsonb_array_elements(rows) f WHERE (f->>'on')::boolean), '[]'),
          coalesce((SELECT jsonb_agg(f - 'on') FROM jsonb_array_elements(rows) f WHERE NOT (f->>'on')::boolean), '[]'),
          coalesce(src.tools, (SELECT jsonb_object_agg(t, t = 'map') FROM unnest(verse.builder_tools()) t)), verse.now_ms(), b.slug, s);
  -- the city as it is published now (Everglade's edits, or the fork's), the fork's own from here on
  INSERT INTO verse.published (world, doc, version, published_by, published_at)
  SELECT 'made-' || slug_, p.doc, 1, 'fork of ' || s, extract(epoch FROM clock_timestamp())
  FROM verse.published p WHERE p.world = CASE WHEN src.slug IS NOT NULL THEN 'made-' || s ELSE b.slug END;
  RETURN jsonb_build_object('status', 200, 'slug', slug_, 'path', '/realms/' || slug_, 'name', nm, 'base', b.slug, 'from', s,
                            'rules', to_jsonb(verse.fork_rules_on(verse.fork_of(slug_))));
END $$;


--
-- Name: fork_make_0110(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_make_0110(s text, body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = s AND base IS NULL) THEN verse.made_fork(s, body, k, per_day)
              ELSE verse.fork_make_0075(s, body, k, per_day) END $$;


--
-- Name: fork_maker(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_maker(base text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT name FROM makers.realms WHERE realm = base), 'OpenAgents') $$;


--
-- Name: fork_md(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_md(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.worlds_page(verse.fork_md_0110(s), 'https://openagents.com') $$;


--
-- Name: fork_md_0110(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_md_0110(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '# ' || m.name || E'\n\n' || verse.builder_share_line(m)
      || E'\n\nA fork of ' || verse.fork_name_of(m.forked_from) || ' (https://openagents.com/realms/' || m.forked_from || ')'
      || CASE WHEN m.forked_from <> m.base THEN ', itself a fork of ' || b.title || ' (https://openagents.com/realms/' || b.slug || ')' ELSE '' END
      || ', made by ' || verse.fork_maker(b.slug) || ', at https://openagents.com/realms/' || m.slug
      || '. It plays ' || b.title || E' with its own rules; the original never changes.\n\n## Its rules\n\n'
      || coalesce((SELECT string_agg('- ' || (r->>'label'), E'\n' ORDER BY o) FROM jsonb_array_elements(b.rules) WITH ORDINALITY AS t(r, o)
                   WHERE (r->>'id') = ANY (verse.fork_rules_on(m))), '- The same rules as ' || b.title)
      || E'\n\nIts owner switches its rules and the rest of its board with EDIT, by a tap or by voice. Anyone can fork it again with FORK.\n'
  FROM verse.made_realms m JOIN verse.fork_bases b ON b.slug = m.base WHERE m.slug = s $$;


--
-- Name: fork_name_of(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_name_of(s text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT name FROM verse.made_realms WHERE slug = s), (SELECT title FROM verse.fork_bases WHERE slug = s), s) $$;


--
-- Name: fork_of(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_of(s text) RETURNS verse.made_realms
    LANGUAGE sql STABLE
    AS $$
  SELECT * FROM verse.made_realms WHERE slug = s AND base IS NOT NULL $$;


--
-- Name: fork_page(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_page(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.worlds_page(verse.fork_page_0110(s, origin), origin) $$;


--
-- Name: fork_page_0110(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.fork_page_0110(s text, origin text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT '<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>' || verse.builder_html(m.name) || ' · a fork of ' || verse.builder_html(b.title) || ' · OpenAgents</title>
' || CASE WHEN m.published_ms IS NULL THEN '<meta name="robots" content="noindex">
' ELSE '' END || '<meta name="description" content="' || verse.builder_html(verse.builder_share_line(m)) || '">
<meta property="og:type" content="website">
<meta property="og:site_name" content="OpenAgents">
<meta property="og:title" content="' || verse.builder_html(m.name) || '">
<meta property="og:description" content="' || verse.builder_html(verse.builder_share_line(m)) || '">
<meta property="og:url" content="' || verse.builder_html(origin) || '/realms/' || m.slug || '">
