--
-- Name: item_outbox; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.item_outbox (
    seq bigint NOT NULL,
    op text NOT NULL,
    who text NOT NULL,
    item bigint NOT NULL,
    to_who text,
    kind integer,
    at_ms bigint NOT NULL
);


--
-- Name: item_outbox_since(bigint, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.item_outbox_since(after bigint, n integer) RETURNS SETOF verse.item_outbox
    LANGUAGE sql STABLE
    AS $$ SELECT * FROM verse.item_outbox WHERE seq > after ORDER BY seq LIMIT least(greatest(n, 0), 500) $$;


--
-- Name: item_reconcile(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.item_reconcile() RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE e verse.item_outbox; ok boolean;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS item_r (id bigint PRIMARY KEY, kind int, owner text, escrow_to text) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS inv_r (who text PRIMARY KEY, version bigint) ON COMMIT DROP;
  DELETE FROM item_r; DELETE FROM inv_r;
  FOR e IN SELECT * FROM verse.item_outbox ORDER BY seq LOOP
    INSERT INTO inv_r VALUES (e.who, 0) ON CONFLICT DO NOTHING;
    IF e.to_who IS NOT NULL THEN INSERT INTO inv_r VALUES (e.to_who, 0) ON CONFLICT DO NOTHING; END IF;
    IF e.op = 'grant' THEN INSERT INTO item_r VALUES (e.item, coalesce(e.kind, 0), e.who, NULL); UPDATE inv_r SET version = version + 1 WHERE who = e.who;
    ELSIF e.op = 'transfer' THEN UPDATE item_r SET owner = e.to_who WHERE id = e.item; UPDATE inv_r SET version = version + 1 WHERE who IN (e.who, e.to_who);
    ELSIF e.op = 'escrow' THEN UPDATE item_r SET escrow_to = e.to_who WHERE id = e.item; UPDATE inv_r SET version = version + 1 WHERE who = e.who;
    ELSIF e.op = 'settle' THEN UPDATE item_r SET owner = e.to_who, escrow_to = NULL WHERE id = e.item; UPDATE inv_r SET version = version + 1 WHERE who IN (e.who, e.to_who);
    ELSIF e.op = 'consume' THEN DELETE FROM item_r WHERE id = e.item; UPDATE inv_r SET version = version + 1 WHERE who = e.who;
    ELSIF e.op = 'claim' THEN UPDATE inv_r SET version = version + 1 WHERE who = e.who;
    ELSE UPDATE item_r SET escrow_to = NULL WHERE id = e.item; UPDATE inv_r SET version = version + 1 WHERE who = e.who;
    END IF;
  END LOOP;
  SELECT NOT EXISTS (SELECT id, kind, owner, escrow_to FROM verse.items EXCEPT SELECT * FROM item_r)
     AND NOT EXISTS (SELECT * FROM item_r EXCEPT SELECT id, kind, owner, escrow_to FROM verse.items)
     AND NOT EXISTS (SELECT who, version FROM verse.inventories WHERE version > 0 EXCEPT SELECT * FROM inv_r)
     AND NOT EXISTS (SELECT * FROM inv_r EXCEPT SELECT who, version FROM verse.inventories) INTO ok;
  RETURN ok;
END $$;


--
-- Name: item_who(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.item_who(p text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(account, id) FROM verse.players WHERE id = p $$;


--
-- Name: link(text, verse.players, text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.link(k text, rec verse.players, acct text, auto text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF rec.id IS NOT NULL AND (rec.account IS NULL OR rec.account = acct) THEN
    UPDATE verse.players SET account = acct WHERE id = rec.id;
    RETURN jsonb_build_object('key', k, 'id', rec.id, 'account', acct);
  END IF;
  RETURN verse.mint(acct, auto);
END $$;


--
-- Name: made_fork(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.made_fork(s text, body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT replace(verse.worlds_answer(verse.made_fork_0110(s, body, k, per_day))::text, '"/realms/', '"/worlds/')::jsonb $$;


--
-- Name: made_fork_0093(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.made_fork_0093(s text, body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec verse.players := verse.builder_player(k);
  src verse.made_realms;
  nm text;
  slug_ text;
  m verse.made_realms;
BEGIN
  SELECT * INTO src FROM verse.made_realms WHERE slug = s AND base IS NULL;
  IF src.slug IS NULL THEN RETURN '{"status":404,"error":"this realm can''t be forked"}'; END IF;
  IF rec.id IS NULL THEN RETURN '{"status":401,"error":"no player"}'; END IF;
  IF jsonb_typeof(body->'name') = 'string' THEN
    nm := btrim(regexp_replace(verse.builder_one_line(body->'name', 40), '[<>&"]', '', 'g'));
    IF (body->>'name') <> '' AND nm = '' THEN RETURN '{"status":400,"error":"a name of plain words"}'; END IF;
  END IF;
  IF (SELECT count(*) FROM verse.made_realms x JOIN verse.worlds w ON w.id = x.world
      WHERE w.owner_player = rec.id AND x.made_ms > verse.now_ms() - 86400000) >= per_day THEN
    RETURN '{"status":429,"error":"that''s today''s realms"}';
  END IF;
  nm := coalesce(nullif(nm, ''), left(src.name, 34) || ' Fork');
  slug_ := verse.builder_slug(nm);
  INSERT INTO verse.worlds (id, owner_player, owner_account, created_ms) VALUES ('made-' || slug_, rec.id, rec.account, verse.now_ms());
  INSERT INTO verse.made_realms (slug, world, name, style, ground, time, camera, palette, features, off, tools, placed, moved, made_ms, forked_from, forked_rev)
  VALUES (slug_, 'made-' || slug_, nm, src.style, src.ground, src.time, src.camera, src.palette, src.features, src.off, src.tools, src.placed, src.moved,
          verse.now_ms(), src.slug, src.rev)
  RETURNING * INTO m;
  PERFORM verse.realm_keep_rev(src, 'fork', k);   -- the parent's revision it was forked at, kept
  PERFORM verse.realm_keep_rev(m, 'made', k);
  RETURN jsonb_build_object('status', 200, 'slug', slug_, 'path', '/realms/' || slug_, 'name', nm, 'from', src.slug, 'rev', src.rev);
END $$;


--
-- Name: made_fork_0110(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.made_fork_0110(s text, body jsonb, k text, per_day integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec verse.players := verse.builder_player(k);
  src verse.made_realms;
  live jsonb;
  nm text;
  slug_ text;
  m verse.made_realms;
BEGIN
  SELECT * INTO src FROM verse.made_realms WHERE slug = s AND base IS NULL;
  IF src.slug IS NULL OR verse.builder_owns(k, s) THEN RETURN verse.made_fork_0093(s, body, k, per_day); END IF;
  live := verse.realm_live_doc(src);
  IF live IS NULL THEN RETURN verse.made_fork_0093(s, body, k, per_day); END IF;
  src := verse.realm_as_doc(src, live);
  IF rec.id IS NULL THEN RETURN '{"status":401,"error":"no player"}'; END IF;
  IF jsonb_typeof(body->'name') = 'string' THEN
    nm := btrim(regexp_replace(verse.builder_one_line(body->'name', 40), '[<>&"]', '', 'g'));
    IF (body->>'name') <> '' AND nm = '' THEN RETURN '{"status":400,"error":"a name of plain words"}'; END IF;
  END IF;
  IF (SELECT count(*) FROM verse.made_realms x JOIN verse.worlds w ON w.id = x.world
      WHERE w.owner_player = rec.id AND x.made_ms > verse.now_ms() - 86400000) >= per_day THEN
    RETURN '{"status":429,"error":"that''s today''s realms"}';
  END IF;
  nm := coalesce(nullif(nm, ''), left(src.name, 34) || ' Fork');
  slug_ := verse.builder_slug(nm);
  INSERT INTO verse.worlds (id, owner_player, owner_account, created_ms) VALUES ('made-' || slug_, rec.id, rec.account, verse.now_ms());
  INSERT INTO verse.made_realms (slug, world, name, style, ground, time, camera, palette, features, off, tools, placed, moved, made_ms, forked_from, forked_rev)
  VALUES (slug_, 'made-' || slug_, nm, src.style, src.ground, src.time, src.camera, src.palette, src.features, src.off, src.tools, src.placed, src.moved,
          verse.now_ms(), src.slug, src.rev)
  RETURNING * INTO m;
  PERFORM verse.realm_keep_rev(m, 'made', k);
  RETURN jsonb_build_object('status', 200, 'slug', slug_, 'path', '/realms/' || slug_, 'name', nm, 'from', src.slug, 'rev', src.rev);
END $$;


