--
-- Name: reply_title(verse.replies); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.reply_title(r verse.replies) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT '“' || CASE WHEN length(r.words) > 90 THEN rtrim(left(r.words, 89)) || '…' ELSE r.words END || '”' $$;


--
-- Name: reply_words(jsonb, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.reply_words(v jsonb, n integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'string' AND length(btrim(regexp_replace(v #>> '{}', '[[:cntrl:][:space:]|]+', ' ', 'g'))) BETWEEN 1 AND n
              THEN btrim(regexp_replace(v #>> '{}', '[[:cntrl:][:space:]|]+', ' ', 'g')) END $$;


--
-- Name: room(text, text, text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room(method text, kind text, r text, body jsonb, k text, after integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
#variable_conflict use_column
DECLARE
  rec verse.players;
  who text;
  now_ms bigint := verse.now_ms();
  fresh bigint := verse.now_ms() - verse.room_present_ms();
  here int;
  was verse.room_here;
  said text;
  n_ int;
  since int;
  top int;
BEGIN
  IF r !~ '^[A-Za-z0-9_-]{1,64}$' THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO rec FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  END IF;
  IF kind = 'chat' AND method = 'GET' THEN
    RETURN verse.r(200, jsonb_build_object('messages', verse.room_lines(r, greatest(after, 0), rec.id),
      'last', coalesce((SELECT max(n) FROM verse.room_chat WHERE room = r), 0)));
  END IF;
  IF method <> 'POST' THEN RETURN verse.r(405, '{"error":"POST"}'); END IF;
  IF rec.id IS NULL THEN
    RETURN verse.r(403, '{"error":"send a player key (POST /api/playtest/player) to join a room"}');
  END IF;
  who := verse.player_name(rec.id);

  IF kind = 'chat' THEN
    said := verse.clean_text(body->'text', 500);
    IF said = '' THEN RETURN verse.r(400, '{"error":"say something"}'); END IF;
    SELECT count(*) INTO since FROM verse.room_chat
    WHERE player = rec.id AND at > extract(epoch FROM clock_timestamp()) - 10;
    IF since >= 5 THEN RETURN verse.r(429, '{"error":"a little slower"}'); END IF;
    PERFORM pg_advisory_xact_lock(7731013, hashtext(r));
    SELECT coalesce(max(n), 0) + 1 INTO n_ FROM verse.room_chat WHERE room = r;
    INSERT INTO verse.room_chat (room, n, player, name, text, at, sid)
    VALUES (r, n_, rec.id, who, said, extract(epoch FROM clock_timestamp()),
            CASE WHEN body->>'sid' ~ '^[A-Za-z0-9_:-]{1,80}$' THEN body->>'sid' END);
    RETURN verse.r(200, jsonb_build_object('n', n_));
  END IF;

  IF kind = 'presence' THEN
    SELECT * INTO was FROM verse.room_here WHERE room = r AND player = rec.id;
    IF was.player IS NULL OR was.seen_ms < fresh THEN
      SELECT count(*) INTO here FROM verse.room_here WHERE room = r AND seen_ms >= fresh AND player <> rec.id;
      IF here >= verse.room_max() THEN RETURN verse.r(429, '{"error":"the room is full"}'); END IF;
    END IF;
    INSERT INTO verse.room_here AS h (room, player, name, x, y, z, yaw, since_ms, seen_ms)
    VALUES (r, rec.id, who, verse.room_num(body->'x', 10000), verse.room_num(body->'y', 10000), verse.room_num(body->'z', 10000),
            verse.room_num(body->'yaw', 1000), now_ms, now_ms)
    ON CONFLICT (room, player) DO UPDATE SET name = EXCLUDED.name, x = EXCLUDED.x, y = EXCLUDED.y, z = EXCLUDED.z, yaw = EXCLUDED.yaw,
      seen_ms = EXCLUDED.seen_ms, since_ms = CASE WHEN h.seen_ms < fresh THEN EXCLUDED.since_ms ELSE h.since_ms END;
    INSERT INTO verse.players_met AS m (a, b, room, first_ms, last_ms)
    SELECT least(rec.id, h.player), greatest(rec.id, h.player), r, now_ms, now_ms
    FROM verse.room_here h WHERE h.room = r AND h.seen_ms >= fresh AND h.player <> rec.id
    ON CONFLICT (a, b) DO UPDATE SET room = EXCLUDED.room, last_ms = EXCLUDED.last_ms WHERE m.last_ms < EXCLUDED.last_ms - 60000;
    top := coalesce((SELECT max(n) FROM verse.room_chat WHERE room = r), 0);
    RETURN verse.r(200, jsonb_build_object(
      'you', jsonb_build_object('id', rec.id, 'name', who),
      'others', coalesce((SELECT jsonb_agg(jsonb_build_object('id', h.player, 'name', h.name, 'x', h.x, 'y', h.y, 'z', h.z, 'yaw', h.yaw)
                                           ORDER BY h.since_ms, h.player)
                          FROM verse.room_here h WHERE h.room = r AND h.seen_ms >= fresh AND h.player <> rec.id), '[]'),
      'messages', CASE WHEN jsonb_typeof(body->'after') = 'number' THEN verse.room_lines(r, greatest((body->>'after')::numeric::int, 0), rec.id) ELSE '[]' END,
      'removed', coalesce((SELECT jsonb_agg(c.n ORDER BY c.n) FROM verse.room_chat c WHERE c.room = r AND c.n > top - 50 AND c.removed_ms IS NOT NULL), '[]'),
      'last', top));
  END IF;
  RETURN verse.r(404, '{"error":"unknown"}');
END $_$;


--
-- Name: room(text, text, text, jsonb, text, integer, text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room(method text, kind text, r text, body jsonb, k text, after integer, mark text, ua text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  out jsonb;
  who verse.players;
  auto_ text;
  pair_ text := verse.room_pair(mark);
  seen jsonb;
BEGIN
  IF k ~ '^[A-Za-z0-9_-]{20,128}$' THEN
    SELECT * INTO who FROM verse.players WHERE key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
  END IF;
  auto_ := left(coalesce(nullif(regexp_replace(coalesce(mark, ''), '[^A-Za-z0-9_.:-]', '', 'g'), ''), verse.headless_agent(ua), who.auto), 64);
  IF kind = 'presence' AND method = 'GET' THEN
    IF r !~ '^[A-Za-z0-9_-]{1,64}$' THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
    seen := verse.room_seen(r, who.id, pair_);
    RETURN verse.r(200, jsonb_build_object('others', seen, 'count', jsonb_array_length(seen)));
  END IF;
  out := verse.room(method, kind, r, body, k, after);
  IF (out->>'status')::int <> 200 OR who.id IS NULL THEN RETURN out; END IF;
  IF kind = 'presence' AND method = 'POST' THEN
    UPDATE verse.room_here SET auto = auto_ WHERE room = r AND player = who.id AND auto IS DISTINCT FROM auto_;
    seen := (SELECT coalesce(jsonb_agg(o ORDER BY i), '[]') FROM jsonb_array_elements(verse.room_seen(r, who.id, pair_)) WITH ORDINALITY e(o, i) WHERE o->>'id' <> who.id);
    RETURN jsonb_set(out, '{body,others}', seen);
  END IF;
  IF kind = 'chat' AND method = 'POST' AND jsonb_typeof(out->'body'->'n') = 'number' AND auto_ IS NOT NULL THEN
    UPDATE verse.room_chat SET auto = auto_ WHERE room = r AND n = (out->'body'->>'n')::int AND player = who.id;
  END IF;
  RETURN out;
END $_$;


--
-- Name: room(text, text, text, jsonb, text, integer, text, text, boolean, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room(method text, kind text, r text, body jsonb, k text, after integer, mark text, ua text, seat boolean, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  out jsonb;
  me text := verse.player_of(k);
  pair_ text := verse.room_pair(mark);
  until_ bigint;
  read_after int;
BEGIN
  IF kind = 'chat' AND method = 'POST' AND me IS NOT NULL THEN
    SELECT until_ms INTO until_ FROM verse.room_kicks WHERE player = me AND until_ms > verse.now_ms();
    IF until_ IS NOT NULL THEN RETURN verse.r(403, jsonb_build_object('error', 'kicked', 'until', until_)); END IF;
    IF jsonb_typeof(body) = 'object' AND jsonb_typeof(body->'text') = 'string' THEN
      body := jsonb_set(body, '{text}', to_jsonb(verse.chat_mask(body->>'text')));
    END IF;
  END IF;
  out := verse.room_0110(method, kind, r, body, k, after, mark, ua, seat, site_admin);
  IF pair_ IS NULL OR (out->>'status')::int <> 200 OR jsonb_typeof(out->'body'->'messages') <> 'array' THEN RETURN out; END IF;
  IF kind = 'chat' AND method = 'GET' THEN read_after := greatest(after, 0);
  ELSIF kind = 'presence' AND method = 'POST' AND jsonb_typeof(body->'after') = 'number' THEN read_after := greatest((body->>'after')::numeric::int, 0);
  ELSE RETURN out; END IF;
  RETURN jsonb_set(out, '{body,messages}', verse.room_lines_paired(r, read_after, me, pair_));
END $$;


--
-- Name: room_0110(text, text, text, jsonb, text, integer, text, text, boolean, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_0110(method text, kind text, r text, body jsonb, k text, after integer, mark text, ua text, seat boolean, site_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  out jsonb;
  me text;
  agent_ boolean;
BEGIN
  IF verse.room_hidden(r, k, site_admin) THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
  IF NOT coalesce(seat, false) THEN
    out := verse.room(method, kind, r, body, k, after, mark, ua);
    IF kind = 'presence' AND method = 'POST' AND (out->>'status')::int = 200 THEN
      me := out->'body'->'you'->>'id';
      agent_ := verse.seat_player(me);
      UPDATE verse.room_here SET agent = agent_ WHERE room = r AND player = me AND agent IS DISTINCT FROM agent_;
      IF agent_ THEN out := jsonb_set(out, '{body,you,agent}', 'true'::jsonb); END IF;
    END IF;
    RETURN out;
  END IF;
  IF kind <> 'presence' OR method <> 'POST' THEN RETURN verse.r(405, '{"error":"a seat posts its presence"}'); END IF;
  IF jsonb_typeof(body) = 'object' AND body->'gone' = 'true'::jsonb THEN
    SELECT id INTO me FROM verse.players WHERE k ~ '^[A-Za-z0-9_-]{20,128}$' AND key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex');
    IF me IS NULL THEN RETURN verse.r(403, '{"error":"no player"}'); END IF;
    DELETE FROM verse.room_here WHERE room = r AND player = me;
    RETURN verse.r(200, '{"gone": true}');
  END IF;
  out := verse.room(method, kind, r, body, k, after, 'seat', ua);
  IF (out->>'status')::int <> 200 THEN RETURN out; END IF;
  UPDATE verse.room_here SET agent = true,
    seat_page = CASE WHEN jsonb_typeof(body) = 'object' AND body->>'page' ~ '^p-[a-z0-9]{1,40}$' THEN body->>'page' END
  WHERE room = r AND player = out->'body'->'you'->>'id';
  RETURN jsonb_set(out, '{body,you,agent}', 'true'::jsonb);
END $_$;


--
-- Name: room_admit_count(text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_admit_count(reason text, n bigint) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO verse.room_admission AS a (reason, n) SELECT reason, n WHERE n > 0
  ON CONFLICT (reason) DO UPDATE SET n = a.n + EXCLUDED.n $$;


--
-- Name: room_any_fits(text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_any_fits(bld text, now bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM verse.room_shards s WHERE verse.room_fits(s.shard, bld, now)) $$;


--
-- Name: room_class_once(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_class_once(p_pid text, p_class text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  w text;
  kept text;
BEGIN
  IF p_class IS NULL OR p_class !~ '^srd-[a-z]{3,12}$' THEN RETURN NULL; END IF;
  SELECT coalesce(account, id) INTO w FROM verse.players WHERE id = p_pid;
  IF w IS NULL THEN RETURN NULL; END IF;
  INSERT INTO verse.room_vitals AS x (who, character_class, at) VALUES (w, p_class, verse.now_ms())
  ON CONFLICT (who) DO UPDATE SET character_class = coalesce(x.character_class, EXCLUDED.character_class)
  RETURNING x.character_class INTO kept;
  RETURN kept;
END $_$;


--
-- Name: room_down(integer, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_down(k integer, now bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM verse.room_shards s
                 WHERE s.shard = k AND s.endpoint IS NOT NULL
                   AND coalesce(s.seen_at, 0) <= now - 15000 AND coalesce(s.seen_at, 0) > now - 120000) $$;


--
-- Name: room_draining(integer, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_draining(k integer, now bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM verse.room_shards s
                 WHERE s.shard = k AND s.draining IS NOT NULL AND s.draining = s.gen AND coalesce(s.at, 0) > now - 60000) $$;


--
-- Name: room_endpoint(integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_endpoint(k integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT s.endpoint FROM verse.room_shards s
  WHERE s.shard = k AND s.endpoint IS NOT NULL AND coalesce(s.seen_at, 0) > verse.room_now() - 15000 $$;


--
-- Name: room_event_dials(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_event_dials(j jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH n AS (SELECT
    CASE WHEN jsonb_typeof(j->'on') = 'boolean' THEN (j->>'on')::boolean ELSE false END AS on_,
    CASE WHEN jsonb_typeof(j->'every') = 'number' THEN (j->>'every')::numeric::int ELSE 0 END AS every,
    CASE WHEN jsonb_typeof(j->'waves') = 'number' THEN (j->>'waves')::numeric::int ELSE 3 END AS waves,
    CASE WHEN jsonb_typeof(j->'size') = 'number' THEN (j->>'size')::numeric::int ELSE 12 END AS size,
    CASE WHEN jsonb_typeof(j->'cultists') = 'number' THEN (j->>'cultists')::numeric::int ELSE 6 END AS cult,
    CASE WHEN jsonb_typeof(j->'fanatics') = 'number' THEN (j->>'fanatics')::numeric::int ELSE 1 END AS fan,
    CASE WHEN jsonb_typeof(j->'warlocks') = 'number' THEN (j->>'warlocks')::numeric::int ELSE 3 END AS wl,
    CASE WHEN jsonb_typeof(j->'warlock_level') = 'number' THEN (j->>'warlock_level')::numeric::int ELSE 3 END AS wlmax,
    CASE WHEN jsonb_typeof(j->'gates') = 'number' THEN (j->>'gates')::numeric::int ELSE 31 END AS gates,
    CASE WHEN jsonb_typeof(j->'leader') = 'boolean' THEN (j->>'leader')::boolean ELSE true END AS arch,
    CASE WHEN jsonb_typeof(j->'aggression') = 'number' THEN (j->>'aggression')::numeric::int ELSE 2 END AS aggr,
    CASE WHEN jsonb_typeof(j->'town_damage') = 'boolean' THEN (j->>'town_damage')::boolean ELSE true END AS harm,
    CASE WHEN jsonb_typeof(j->'reward') = 'number' THEN (j->>'reward')::numeric::int ELSE 100 END AS reward,
    CASE WHEN jsonb_typeof(j->'minutes') = 'number' THEN (j->>'minutes')::numeric::int ELSE 15 END AS minutes,
    CASE WHEN jsonb_typeof(j->'levels') = 'boolean' THEN (j->>'levels')::boolean ELSE false END AS levels,
    CASE WHEN jsonb_typeof(j->'level_cap') = 'number' THEN (j->>'level_cap')::numeric::int ELSE 2 END AS cap)
  SELECT jsonb_build_object('on', on_, 'every', CASE WHEN every <= 0 THEN 0 ELSE least(greatest(every, 15), 240) END,
    'waves', least(greatest(waves, 1), 8), 'size', least(greatest(size, 4), 24),
    'cultists', least(greatest(cult, 0), 10), 'fanatics', least(greatest(fan, 0), 10), 'warlocks', least(greatest(wl, 0), 10),
    'warlock_level', least(greatest(wlmax, 1), 3), 'gates', least(greatest(gates, 1), 31),
    'leader', arch, 'aggression', least(greatest(aggr, 0), 3), 'town_damage', harm,
    'reward', least(greatest(reward, 50), 300), 'minutes', least(greatest(minutes, 5), 30), 'levels', levels,
    'level_cap', least(greatest(cap, 1), 3)) FROM n $$;


--
-- Name: room_fits(integer, text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_fits(k integer, bld text, now bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT NOT verse.room_draining(k, now) AND NOT verse.room_down(k, now) AND (coalesce(bld, '') = '' OR NOT EXISTS (
    SELECT 1 FROM verse.room_shards s WHERE s.shard = k AND s.build IS NOT NULL AND s.build_at > now - 60000 AND s.build <> bld)) $$;


--
-- Name: room_hidden(text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_hidden(r text, k text, site_admin boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
  SELECT r ~ '^made-[a-z0-9-]{1,59}$' AND verse.realm_hidden(substr(r, 6), k, site_admin)
$_$;


--
-- Name: room_invite(text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_invite(asked text, by_pid text, seats integer, OUT until_ms bigint, OUT why text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  now bigint := verse.room_now();
  i verse.room_instances;
  tag text := 'i-' || by_pid;
  rl text;
BEGIN
  -- the instance's realm (kept for as long as the instance is) names the locks; then it is read again
  SELECT x.realm INTO rl FROM verse.room_instances x WHERE x.code = asked;
  PERFORM verse.room_lock(ARRAY[verse.room_lock_key(asked), hashtext(rl)]);
  IF rl IS NOT NULL THEN PERFORM verse.room_sweep_realm(rl, now); END IF;
  SELECT * INTO i FROM verse.room_instances x WHERE x.code = asked;
  IF NOT FOUND OR NOT (by_pid = ANY (i.pids) OR EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = asked AND h.pid = by_pid)) THEN
    why := 'not in it'; RETURN;
  END IF;
  DELETE FROM verse.room_holds h WHERE h.pid = tag AND h.code <> asked;
  IF NOT EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = asked AND h.pid = tag) AND verse.room_taken(i, now) >= seats THEN
    why := 'full'; RETURN;
  END IF;
  until_ms := now + verse.room_invite_ms();
  INSERT INTO verse.room_holds (code, pid, until_ms) VALUES (asked, tag, until_ms)
  ON CONFLICT ON CONSTRAINT room_holds_pkey DO UPDATE SET until_ms = EXCLUDED.until_ms;
END $$;


--
-- Name: room_invite_ms(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_invite_ms() RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 120000::bigint $$;


--
-- Name: room_chat; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.room_chat (
    id bigint NOT NULL,
    room text NOT NULL,
    n integer NOT NULL,
    player text,
    name text NOT NULL,
    text text NOT NULL,
    at double precision NOT NULL,
    sid text,
    space text DEFAULT 'web'::text NOT NULL,
    source text,
    import_key text,
    removed_ms bigint,
    removed_by text,
    auto text
);


--
-- Name: room_line(verse.room_chat, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_line(c verse.room_chat, me text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('n', c.n, 'name', c.name, 'text', c.text, 'at', c.at, 'mine', me IS NOT NULL AND c.player = me, 'from', c.player)
$$;


--
-- Name: room_lines(text, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_lines(r text, after integer, me text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(verse.room_line(c, me) ORDER BY c.n), '[]')
  FROM (SELECT * FROM verse.room_chat x WHERE x.room = r AND x.n > after AND x.removed_ms IS NULL
          AND (x.auto IS NULL OR (me IS NOT NULL AND x.player = me))
          AND NOT EXISTS (SELECT 1 FROM verse.player_blocks b WHERE b.player = me AND b.blocked = x.player)
        ORDER BY x.n DESC LIMIT 50) c
$$;


--
-- Name: room_lines_paired(text, integer, text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_lines_paired(r text, after integer, me text, pair text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(verse.room_line(c, me) ORDER BY c.n), '[]')
  FROM (SELECT * FROM verse.room_chat x WHERE x.room = r AND x.n > after AND x.removed_ms IS NULL
          AND (x.auto IS NULL OR (me IS NOT NULL AND x.player = me) OR (pair IS NOT NULL AND x.auto = pair))
          AND NOT EXISTS (SELECT 1 FROM verse.player_blocks b WHERE b.player = me AND b.blocked = x.player)
        ORDER BY x.n DESC LIMIT 50) c
$$;


--
-- Name: room_list(text, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_list(realm text, seats integer, pid text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH clk AS (SELECT verse.room_now() AS t),
  live AS (SELECT i.*, verse.room_taken(i, clk.t) AS taken,
                  EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = i.code AND h.pid = 'i-' || room_list.pid AND h.until_ms > clk.t) AS invited
           FROM verse.room_instances i, clk
           WHERE i.realm = room_list.realm AND verse.room_live(i, clk.t)),
  pub AS (SELECT * FROM live WHERE n IS NOT NULL),
  j AS (SELECT coalesce((SELECT min(n) FROM pub WHERE taken < seats),
                        (SELECT min(g) FROM generate_series(1, 999) g WHERE NOT EXISTS (SELECT 1 FROM pub WHERE pub.n = g))) AS n),
  rooms AS (SELECT coalesce(string_agg(format('{"code":%s,"players":%s,"shard":%s}', to_json(code), taken, shard), ',' ORDER BY n), '') AS a FROM pub),
  w AS (SELECT (SELECT code FROM live WHERE pid = ANY (live.pids) AND (taken < seats OR invited) ORDER BY n NULLS LAST LIMIT 1) AS code,
               (SELECT code FROM live WHERE pid = ANY (live.pids) AND taken >= seats AND NOT invited ORDER BY n NULLS LAST LIMIT 1) AS full)
  SELECT format('{"realm":%s,"game":"everglade","seats":%s,"join":%s,"rooms":[%s]%s%s}', to_json(realm), seats,
                to_json(coalesce(w.code, realm || '-' || j.n)), rooms.a,
                CASE WHEN w.code IS NULL THEN '' ELSE ',"with":' || to_json(w.code)::text END,
                CASE WHEN w.code IS NULL AND w.full IS NOT NULL THEN ',"with_full":' || to_json(w.full)::text ELSE '' END)
  FROM j, rooms, w $$;


--
-- Name: room_instances; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.room_instances (
    code text NOT NULL,
    realm text NOT NULL,
    n integer,
    shard integer NOT NULL,
    players integer DEFAULT 0 NOT NULL,
    pids text[] DEFAULT '{}'::text[] NOT NULL,
    made_at bigint NOT NULL,
    at bigint
);


--
-- Name: room_live(verse.room_instances, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_live(i verse.room_instances, now bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(i.at, 0) > now - 15000 OR i.made_at > now - 25000
      OR EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = i.code AND h.until_ms > now) $$;


--
-- Name: room_lock(integer[]); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_lock(keys integer[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE k int;
BEGIN
  FOR k IN SELECT DISTINCT u FROM unnest(keys) u WHERE u IS NOT NULL ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(7731028, k);
  END LOOP;
END $$;


--
-- Name: room_lock_key(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_lock_key(code text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT hashtext(coalesce(substring(code FROM '^(.*)-[1-9][0-9]{0,2}$'), code)) $_$;


--
-- Name: room_max(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_max() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 16 $$;


--
-- Name: room_minutes_add(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_minutes_add() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  m bigint := (extract(epoch FROM NEW.at) * 1000)::bigint / 60000 * 60000;
  p int := coalesce(verse.room_stat(NEW.body, 'players'), 0)::int;
  t bigint := round(verse.room_stat(NEW.body, 'tick p99 ms') * 1000)::bigint;
  u bigint := verse.room_stat(NEW.body, 'checkpoint unsaved age ms most')::bigint;
BEGIN
  INSERT INTO verse.room_minutes AS r (shard, minute, reports, players, tick_p99_us, unsaved_ms) VALUES (NEW.shard, m, 1, p, t, u)
  ON CONFLICT (shard, minute) DO UPDATE SET reports = r.reports + 1, players = greatest(r.players, EXCLUDED.players),
    tick_p99_us = greatest(r.tick_p99_us, EXCLUDED.tick_p99_us), unsaved_ms = greatest(r.unsaved_ms, EXCLUDED.unsaved_ms);
  RETURN NULL;
END $$;


--
-- Name: room_now(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_now() RETURNS bigint
    LANGUAGE sql
    AS $$
  SELECT (extract(epoch FROM clock_timestamp()) * 1000)::bigint $$;


--
-- Name: room_num(jsonb, real); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_num(v jsonb, lim real) RETURNS real
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'number' AND abs((v #>> '{}')::double precision) <= lim THEN (v #>> '{}')::real ELSE 0 END
$$;


--
-- Name: room_owner_next(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_owner_next(p_pid text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
  who_ text;
  g bigint;
  floor_ bigint := verse.region_gen_floor();
BEGIN
  SELECT coalesce(account, id) INTO who_ FROM verse.players WHERE id = p_pid;
  IF who_ IS NULL THEN RETURN NULL; END IF;
  INSERT INTO verse.room_owners AS o (who, gen, at) VALUES (who_, floor_ + 1, verse.now_ms())
  ON CONFLICT (who) DO UPDATE SET gen = greatest(o.gen, floor_) + 1, at = EXCLUDED.at WHERE greatest(o.gen, floor_) < 2147483647
  RETURNING o.gen INTO g;
  RETURN g;
END $$;


--
-- Name: room_owner_next(text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_owner_next(p_pid text, p_shard integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
  g bigint := verse.room_owner_next(p_pid);
BEGIN
  IF g IS NOT NULL THEN
    UPDATE verse.room_owners o SET shard = p_shard FROM verse.players p
     WHERE p.id = p_pid AND o.who = coalesce(p.account, p.id);
  END IF;
  RETURN g;
END $$;


--
-- Name: room_owner_shard_ok(text, bigint, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_owner_shard_ok(p_pid text, p_gen bigint, p_shard integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT o.shard IS NULL OR o.shard = p_shard OR p_gen IS NULL OR p_gen < o.gen
                     FROM verse.room_owners o JOIN verse.players p ON o.who = coalesce(p.account, p.id)
                    WHERE p.id = p_pid), true)
$$;


--
-- Name: room_pair(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_pair(mark text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE WHEN m ~ '^pair-[A-Za-z0-9_.:-]{1,59}$' THEN m END
  FROM (SELECT regexp_replace(coalesce(mark, ''), '[^A-Za-z0-9_.:-]', '', 'g') AS m) x
$_$;


--
-- Name: room_pick(text, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_pick(realm text, asked text, pid text, seats integer, OUT code text, OUT shard integer, OUT was_full boolean) RETURNS record
    LANGUAGE sql
    AS $$ SELECT * FROM verse.room_pick(realm, asked, pid, seats, '', '') $$;


--
-- Name: room_pick(text, text, text, integer, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_pick(realm text, asked text, pid text, seats integer, via text, OUT code text, OUT shard integer, OUT was_full boolean) RETURNS record
    LANGUAGE sql
    AS $$ SELECT * FROM verse.room_pick(realm, asked, pid, seats, via, '') $$;


--
-- Name: room_pick(text, text, text, integer, text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_pick(realm text, asked text, pid text, seats integer, via text, build text, OUT code text, OUT shard integer, OUT was_full boolean) RETURNS record
    LANGUAGE plpgsql
    AS $_$
DECLARE
  now bigint := verse.room_now();
  i verse.room_instances;
  k int;
  bld text := build;
BEGIN
  was_full := false;
  -- this realm's lock, and the asked instance's when its name belongs to another (in key order)
  PERFORM verse.room_lock(ARRAY[hashtext(realm), verse.room_lock_key(asked)]);
  PERFORM verse.room_sweep_realm(realm, now);
  IF NOT verse.room_any_fits(bld, now) THEN bld := ''; END IF;
  IF asked <> realm THEN
    SELECT * INTO i FROM verse.room_instances x WHERE x.code = asked;
    IF FOUND AND NOT verse.room_fits(i.shard, bld, now) THEN
      -- the asked instance runs another build: placed as a pick of the realm
      NULL;
    ELSIF FOUND AND (pid = ANY (i.pids) OR EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = i.code AND h.pid = room_pick.pid)) THEN
      code := i.code; shard := i.shard;
    ELSIF FOUND AND coalesce(via, '') <> '' AND via <> pid
          AND EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = i.code AND h.pid = 'i-' || via AND h.until_ms > now) THEN
      DELETE FROM verse.room_holds h WHERE h.code = i.code AND h.pid = 'i-' || via;
      code := i.code; shard := i.shard;
    ELSIF FOUND AND verse.room_taken(i, now) < seats THEN
      code := i.code; shard := i.shard;
    ELSIF FOUND THEN
      was_full := true;
    ELSE
      PERFORM pg_advisory_xact_lock(7731029, 0);   -- a new instance: the shards' counts, one placement at a time
      k := verse.room_place(now, bld);
      IF k IS NULL THEN RETURN; END IF;
      INSERT INTO verse.room_instances (code, realm, n, shard, made_at)
      VALUES (asked, realm, CASE WHEN asked ~ ('^' || realm || '-[1-9][0-9]{0,2}$') THEN substr(asked, length(realm) + 2)::int END, k, now);
      code := asked; shard := k;
    END IF;
  END IF;
  IF code IS NULL THEN
    -- a reconnect keeps its instance, when it fits
    SELECT x.code, x.shard INTO code, shard FROM verse.room_instances x
    WHERE x.realm = room_pick.realm AND x.n IS NOT NULL AND verse.room_fits(x.shard, bld, now)
      AND (pid = ANY (x.pids) OR EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = x.code AND h.pid = room_pick.pid AND h.until_ms > now))
    ORDER BY x.n LIMIT 1;
  END IF;
  IF code IS NULL THEN
    SELECT x.code, x.shard INTO code, shard FROM verse.room_instances x
    WHERE x.realm = room_pick.realm AND x.n IS NOT NULL AND verse.room_taken(x, now) < seats AND verse.room_fits(x.shard, bld, now)
    ORDER BY x.n LIMIT 1;
  END IF;
  IF code IS NULL THEN
    PERFORM pg_advisory_xact_lock(7731029, 0);
    k := verse.room_place(now, bld);
    IF k IS NULL THEN RETURN; END IF;
    SELECT min(g) INTO code FROM generate_series(1, 999) g
    WHERE NOT EXISTS (SELECT 1 FROM verse.room_instances x WHERE x.realm = room_pick.realm AND x.n = g)
      AND NOT EXISTS (SELECT 1 FROM verse.room_instances x WHERE x.code = room_pick.realm || '-' || g);
    IF code IS NULL THEN RETURN; END IF;
    INSERT INTO verse.room_instances (code, realm, n, shard, made_at) VALUES (realm || '-' || code, realm, code::int, k, now);
    code := realm || '-' || code; shard := k;
  END IF;
  INSERT INTO verse.room_holds (code, pid, until_ms) VALUES (code, pid, now + 20000)
  ON CONFLICT ON CONSTRAINT room_holds_pkey DO UPDATE SET until_ms = EXCLUDED.until_ms;
END $_$;


--
-- Name: room_place(bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_place(now bigint) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT s.shard FROM verse.room_shards s
  WHERE s.rooms_cap > (SELECT count(*) FROM verse.room_instances i WHERE i.shard = s.shard)
    AND (s.free IS NULL OR coalesce(s.at, 0) <= now - 15000
         OR s.free > (SELECT count(*) FROM verse.room_instances i WHERE i.shard = s.shard AND i.at IS NULL))
  ORDER BY s.shard LIMIT 1 $$;


--
-- Name: room_place(bigint, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_place(now bigint, bld text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT s.shard FROM verse.room_shards s
  WHERE s.rooms_cap > (SELECT count(*) FROM verse.room_instances i WHERE i.shard = s.shard)
    AND (s.free IS NULL OR coalesce(s.at, 0) <= now - 15000
         OR s.free > (SELECT count(*) FROM verse.room_instances i WHERE i.shard = s.shard AND i.at IS NULL))
    AND verse.room_fits(s.shard, bld, now)
  ORDER BY s.shard LIMIT 1 $$;


--
-- Name: room_present_ms(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_present_ms() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 6000 $$;


--
-- Name: room_remove(text, jsonb, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_remove(r text, body jsonb, by_ text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  n_ int;
BEGIN
  IF r !~ '^[A-Za-z0-9_-]{1,64}$' THEN RETURN verse.r(404, '{"error":"unknown"}'); END IF;
  IF jsonb_typeof(body->'n') IS DISTINCT FROM 'number' THEN RETURN verse.r(400, '{"error":"which line: {n}"}'); END IF;
  n_ := (body->>'n')::numeric::int;
  UPDATE verse.room_chat SET removed_ms = verse.now_ms(), removed_by = by_ WHERE room = r AND n = n_ AND removed_ms IS NULL;
  IF NOT FOUND AND NOT EXISTS (SELECT 1 FROM verse.room_chat WHERE room = r AND n = n_) THEN
    RETURN verse.r(404, '{"error":"no such line"}');
  END IF;
  RETURN verse.r(200, jsonb_build_object('removed', n_));
END $_$;


--
-- Name: room_report(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_report(body text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
  now bigint := verse.room_now();
  lines text[] := string_to_array(rtrim(body, E'\n'), E'\n');
  f text[]; at bigint; sh int; fr int; named text[] := '{}'; ln text; m int := 0;
  g bigint; d boolean := false; first int := 3; newest bigint;
BEGIN
  IF array_length(lines, 1) IS NULL OR array_length(lines, 1) < 2 THEN RETURN -1; END IF;
  IF lines[1] !~ '^t [0-9]{1,15}$' OR lines[2] !~ '^s [1-9][0-9]? [0-9]{1,3}$' THEN RETURN -1; END IF;
  at := split_part(lines[1], ' ', 2)::bigint;
  IF at < now - 120000 OR at > now + 120000 THEN RETURN -1; END IF;
  sh := split_part(lines[2], ' ', 2)::int; fr := split_part(lines[2], ' ', 3)::int;
  IF array_length(lines, 1) >= 3 AND lines[3] ~ '^g ' THEN
    IF lines[3] !~ '^g [0-9]{1,15}( d)?$' THEN RETURN -1; END IF;
    g := split_part(lines[3], ' ', 2)::bigint; d := lines[3] ~ ' d$'; first := 4;
  END IF;
  -- this shard's reports one at a time; then every realm the report can change (the rooms it names
  -- and the ones the directory has on this shard), in key order; then the shards' counts
  PERFORM pg_advisory_xact_lock(7731030, sh);
  PERFORM verse.room_lock(
    (SELECT coalesce(array_agg(verse.room_lock_key(split_part(l, ' ', 2))), '{}') FROM unnest(coalesce(lines[first:], '{}')) l WHERE l ~ '^r [a-z0-9-]{1,24} ')
    || (SELECT coalesce(array_agg(hashtext(i.realm)) || array_agg(verse.room_lock_key(i.code)), '{}') FROM verse.room_instances i WHERE i.shard = sh));
  PERFORM pg_advisory_xact_lock(7731029, 0);
  -- holds long over whose room is gone (a realm's own are swept by its picks)
  DELETE FROM verse.room_holds h WHERE h.until_ms <= now - 60000 AND NOT EXISTS (SELECT 1 FROM verse.room_instances x WHERE x.code = h.code);
  IF g IS NOT NULL THEN
    SELECT s.gen INTO newest FROM verse.room_shards s WHERE s.shard = sh;
    IF newest IS NOT NULL AND g < newest THEN RETURN -2; END IF;   -- a replaced process: refused whole
  END IF;
  INSERT INTO verse.room_shards (shard, rooms_cap, free, at, gen, draining) VALUES (sh, 0, fr, at, g, CASE WHEN d THEN g END)
  ON CONFLICT (shard) DO UPDATE SET free = EXCLUDED.free, at = EXCLUDED.at,
    gen = coalesce(EXCLUDED.gen, verse.room_shards.gen),
    draining = CASE WHEN EXCLUDED.gen IS NULL THEN verse.room_shards.draining ELSE EXCLUDED.draining END
  WHERE verse.room_shards.at IS NULL OR verse.room_shards.at <= EXCLUDED.at OR EXCLUDED.gen > verse.room_shards.gen;
  FOREACH ln IN ARRAY coalesce(lines[first:], '{}') LOOP
    IF ln !~ '^r [a-z0-9-]{1,24} [0-9]{1,3}( [a-z0-9-]{1,40})*$' THEN RETURN -1; END IF;
    f := string_to_array(ln, ' ');
    named := named || f[2];
    INSERT INTO verse.room_instances AS x (code, realm, n, shard, players, pids, made_at, at)
    VALUES (f[2], coalesce(substring(f[2] FROM '^(.*)-[1-9][0-9]{0,2}$'), f[2]),
            substring(f[2] FROM '-([1-9][0-9]{0,2})$')::int, sh, f[3]::int, coalesce(f[4:], '{}'), now, at)
    ON CONFLICT (code) DO UPDATE SET shard = EXCLUDED.shard, players = EXCLUDED.players, pids = EXCLUDED.pids, at = EXCLUDED.at
    WHERE x.at IS NULL OR x.at <= EXCLUDED.at;
    DELETE FROM verse.room_holds h WHERE h.code = f[2] AND h.pid = ANY (f[4:]);
    m := m + 1;
  END LOOP;
  DELETE FROM verse.room_instances i WHERE i.shard = sh AND NOT (i.code = ANY (named))
    AND (i.at IS NOT NULL OR i.made_at <= now - 25000)
    AND NOT EXISTS (SELECT 1 FROM verse.room_holds h WHERE h.code = i.code AND h.until_ms > now);
  RETURN m;
END $_$;


--
-- Name: room_seat_ms(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_seat_ms() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 40000 $$;


--
-- Name: room_seated(text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_seated(who text, rate_n bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE now bigint := verse.room_now(); since bigint;
BEGIN
  DELETE FROM verse.room_waiting w WHERE w.pid = who RETURNING w.since_ms INTO since;
  IF since IS NOT NULL THEN
    INSERT INTO verse.room_wait_last (one, wait_ms, at) VALUES (1, now - since, now)
    ON CONFLICT (one) DO UPDATE SET wait_ms = EXCLUDED.wait_ms, at = EXCLUDED.at;
    PERFORM verse.room_admit_count('seated after a wait', 1);
  END IF;
  PERFORM verse.room_admit_count('rate', rate_n);
END $$;


--
-- Name: room_seen(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_seen(r text, me text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', h.player, 'name', h.name, 'x', h.x, 'y', h.y, 'z', h.z, 'yaw', h.yaw)
                            ORDER BY h.since_ms, h.player), '[]')
  FROM verse.room_here h
  WHERE h.room = r AND h.seen_ms >= verse.now_ms() - verse.room_present_ms()
    AND (h.auto IS NULL OR (me IS NOT NULL AND h.player = me))
$$;


--
-- Name: room_seen(text, text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_seen(r text, me text, pair text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', h.player, 'name', h.name, 'x', h.x, 'y', h.y, 'z', h.z, 'yaw', h.yaw)
                            || CASE WHEN l.look IS NOT NULL THEN jsonb_build_object('look', l.look) ELSE '{}'::jsonb END
                            || CASE WHEN h.agent THEN '{"agent": true}'::jsonb ELSE '{}'::jsonb END
                            ORDER BY h.since_ms, h.player), '[]')
  FROM verse.room_here h
  LEFT JOIN makers.wearing w ON w.player = h.player
  LEFT JOIN makers.listings l ON l.id = w.listing AND l.state = 'approved'
  WHERE h.room = r
    AND h.seen_ms >= verse.now_ms() - CASE WHEN h.agent THEN verse.room_seat_ms() ELSE verse.room_present_ms() END
    AND (h.agent OR h.auto IS NULL OR (me IS NOT NULL AND h.player = me) OR (pair IS NOT NULL AND h.auto = pair))
    AND NOT (h.agent AND me IS NOT NULL AND h.seat_page IS NOT DISTINCT FROM me)
$$;


--
-- Name: room_shard_list(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_shard_list() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH clk AS (SELECT verse.room_now() AS t)
  SELECT json_build_object('shards', coalesce(json_agg(json_build_object(
    'shard', s.shard, 'state', verse.room_state(s.shard, clk.t),
    'endpoint', CASE WHEN coalesce(s.seen_at, 0) > clk.t - 120000 THEN s.endpoint END,
    'players', s.players, 'tick_us', s.tick_us,
    'seen_ms_ago', CASE WHEN s.seen_at IS NULL THEN NULL ELSE clk.t - s.seen_at END,
    'instances', (SELECT count(*) FROM verse.room_instances i WHERE i.shard = s.shard)) ORDER BY s.shard), '[]'::json))::text
  FROM verse.room_shards s, clk $$;


--
-- Name: room_shard_seen(integer, text, integer, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_shard_seen(k integer, ep text, p integer, t integer) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE verse.room_shards SET endpoint = ep, players = p, tick_us = t, seen_at = verse.room_now() WHERE shard = k $$;


--
-- Name: room_stat(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_stat(b text, name text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(substring(b FROM '\n' || name || '=(-?[0-9]{1,15}(\.[0-9]{1,6})?)\n'), '')::numeric $$;


--
-- Name: room_state(integer, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_state(k integer, now bigint) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN verse.room_down(k, now) THEN 'down' WHEN verse.room_draining(k, now) THEN 'draining' ELSE 'live' END $$;


--
-- Name: room_stats_add(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_stats_add(b text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  t bigint := nullif(substring(b FROM '^t ([0-9]{1,15})\n'), '')::bigint;
  s int := nullif(substring(b FROM '\nshard=([0-9]{1,2})\n'), '')::int;
  m text[] := regexp_match(b, '\nbuild engine=([0-9]{1,9}) rules=([0-9]{1,9}) content=([0-9]{1,9}) wire=([0-9]{1,6})-([0-9]{1,6}) schema=([0-9]{1,6})\n');
BEGIN
  IF t IS NULL OR s IS NULL OR s < 1 OR s > 99 OR abs(t - (extract(epoch FROM now()) * 1000)::bigint) > 120000 THEN RETURN NULL; END IF;
  INSERT INTO verse.room_stats (shard, body) VALUES (s, b);
  DELETE FROM verse.room_stats WHERE at < now() - interval '1 day';
  IF m IS NOT NULL THEN
    INSERT INTO verse.room_shards (shard, rooms_cap, build, wire, schema, build_at)
    VALUES (s, 0, m[1] || '.' || m[2] || '.' || m[3], m[4] || '-' || m[5], m[6]::int, t)
    ON CONFLICT (shard) DO UPDATE SET build = EXCLUDED.build, wire = EXCLUDED.wire, schema = EXCLUDED.schema, build_at = EXCLUDED.build_at
    WHERE verse.room_shards.build_at IS NULL OR verse.room_shards.build_at <= EXCLUDED.build_at;
  END IF;
  RETURN s;
END $$;


--
-- Name: room_sweep(bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_sweep(now bigint) RETURNS void
    LANGUAGE sql
    AS $$
  DELETE FROM verse.room_holds WHERE until_ms <= now;
  DELETE FROM verse.room_instances i WHERE NOT verse.room_live(i, now);
$$;


--
-- Name: room_sweep_realm(text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_sweep_realm(realm_ text, now bigint) RETURNS void
    LANGUAGE sql
    AS $$
  DELETE FROM verse.room_holds h WHERE h.until_ms <= now
    AND h.code IN (SELECT x.code FROM verse.room_instances x WHERE x.realm = realm_);
  DELETE FROM verse.room_instances i WHERE i.realm = realm_ AND NOT verse.room_live(i, now);
$$;


--
-- Name: room_taken(verse.room_instances, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_taken(i verse.room_instances, now bigint) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT i.players + (SELECT count(*)::int FROM verse.room_holds h
                      WHERE h.code = i.code AND h.until_ms > now AND NOT (h.pid = ANY (i.pids))) $$;


--
-- Name: room_vital_apply(integer, bigint, text, integer, integer, integer, integer, bigint, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_vital_apply(p_shard integer, p_gen bigint, p_pid text, p_hp integer, p_max integer, p_xp integer, p_wanted integer, p_rev bigint, p_at bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  who_ text;
  kept bigint;
BEGIN
  SELECT coalesce(account, id) INTO who_ FROM verse.players WHERE id = p_pid;
  IF who_ IS NULL THEN RETURN 'u'; END IF;
  INSERT INTO verse.room_vital_ops AS o (shard, gen, pid, rev, at, applied)
  VALUES (p_shard, p_gen, p_pid, p_rev, verse.now_ms(), 1)
  ON CONFLICT (shard, gen, pid) DO UPDATE SET rev = EXCLUDED.rev, at = EXCLUDED.at, applied = o.applied + 1
    WHERE o.rev < EXCLUDED.rev
  RETURNING o.rev INTO kept;
  IF kept IS NULL THEN
    SELECT o.rev INTO kept FROM verse.room_vital_ops o WHERE o.shard = p_shard AND o.gen = p_gen AND o.pid = p_pid;
    IF kept = p_rev THEN
      UPDATE verse.room_vital_ops SET dups = dups + 1 WHERE shard = p_shard AND gen = p_gen AND pid = p_pid;
      RETURN 'd';
    END IF;
    RETURN 's';
  END IF;
  INSERT INTO verse.room_vitals AS rv (who, hp, hp_max, hp_at, at, xp, wanted, wanted_at, wanted_by)
  VALUES (who_, p_hp, p_max, p_at, p_at, p_xp, p_wanted, p_at, p_shard || '.' || p_gen)
  ON CONFLICT (who) DO UPDATE SET
    hp = CASE WHEN rv.hp_at IS NULL OR rv.hp_at <= EXCLUDED.hp_at THEN EXCLUDED.hp ELSE rv.hp END,
    hp_max = CASE WHEN rv.hp_at IS NULL OR rv.hp_at <= EXCLUDED.hp_at THEN EXCLUDED.hp_max ELSE rv.hp_max END,
    hp_at = greatest(rv.hp_at, EXCLUDED.hp_at),
    at = greatest(rv.at, EXCLUDED.at),
    xp = greatest(coalesce(rv.xp, 0), EXCLUDED.xp),
    wanted = CASE WHEN rv.wanted_by IS NULL OR rv.wanted_at IS NULL OR rv.wanted_at <= EXCLUDED.wanted_at THEN EXCLUDED.wanted ELSE rv.wanted END,
    wanted_by = CASE WHEN rv.wanted_by IS NULL OR rv.wanted_at IS NULL OR rv.wanted_at <= EXCLUDED.wanted_at THEN EXCLUDED.wanted_by ELSE rv.wanted_by END,
    wanted_at = CASE WHEN rv.wanted_by IS NULL OR rv.wanted_at IS NULL OR rv.wanted_at <= EXCLUDED.wanted_at THEN EXCLUDED.wanted_at ELSE rv.wanted_at END;
  RETURN 'a';
END $$;


--
-- Name: room_vital_apply(integer, bigint, text, integer, integer, integer, integer, bigint, bigint, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_vital_apply(p_shard integer, p_gen bigint, p_pid text, p_hp integer, p_max integer, p_xp integer, p_wanted integer, p_rev bigint, p_at bigint, p_owner bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE w text; g bigint;
BEGIN
  SELECT coalesce(account,id) INTO w FROM verse.players WHERE id=p_pid FOR SHARE;
  SELECT gen INTO g FROM verse.room_owners WHERE who=w FOR UPDATE;
  IF EXISTS (SELECT 1 FROM verse.character_profiles_v2 WHERE who=w)
     AND (p_owner IS NULL OR p_owner<>g) THEN RETURN 'f'; END IF;
  RETURN verse.room_vital_apply_before_checkpoints(p_shard,p_gen,p_pid,p_hp,p_max,p_xp,p_wanted,p_rev,p_at,p_owner);
END $$;


--
-- Name: room_vital_apply_before_checkpoints(integer, bigint, text, integer, integer, integer, integer, bigint, bigint, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_vital_apply_before_checkpoints(p_shard integer, p_gen bigint, p_pid text, p_hp integer, p_max integer, p_xp integer, p_wanted integer, p_rev bigint, p_at bigint, p_owner bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  newest bigint;
  res text;
BEGIN
  IF p_owner IS NOT NULL THEN
    SELECT o.gen INTO newest FROM verse.room_owners o JOIN verse.players p ON o.who = coalesce(p.account, p.id) WHERE p.id = p_pid;
    IF newest IS NOT NULL AND p_owner < newest THEN RETURN 'f'; END IF;
  END IF;
  res := verse.room_vital_apply(p_shard, p_gen, p_pid, p_hp, p_max, p_xp, p_wanted, p_rev, p_at);
  IF res = 'a' THEN
    UPDATE verse.room_vitals rv SET build = s.build || '/' || s.schema
    FROM verse.room_shards s, verse.players p
    WHERE s.shard = p_shard AND s.build IS NOT NULL AND p.id = p_pid AND rv.who = coalesce(p.account, p.id);
  END IF;
  RETURN res;
END $$;


--
-- Name: room_vital_legacy(text, integer, integer, integer, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_vital_legacy(p_pid text, p_hp integer, p_max integer, p_xp integer, p_at bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE w text; kept int;
BEGIN
  SELECT coalesce(account,id) INTO w FROM verse.players WHERE id=p_pid FOR SHARE;
  IF w IS NULL THEN RETURN 0; END IF;
  PERFORM 1 FROM verse.room_owners WHERE who=w FOR UPDATE;
  IF EXISTS(SELECT 1 FROM verse.character_profiles_v2 WHERE who=w) THEN RETURN 0; END IF;
  INSERT INTO verse.room_vitals(who,hp,hp_max,hp_at,at,xp)
  VALUES(w,p_hp,p_max,p_at,p_at,nullif(greatest(p_xp,-1),-1))
  ON CONFLICT(who) DO UPDATE SET
    hp=CASE WHEN verse.room_vitals.hp_at IS NULL OR verse.room_vitals.hp_at<=EXCLUDED.hp_at THEN EXCLUDED.hp ELSE verse.room_vitals.hp END,
    hp_max=CASE WHEN verse.room_vitals.hp_at IS NULL OR verse.room_vitals.hp_at<=EXCLUDED.hp_at THEN EXCLUDED.hp_max ELSE verse.room_vitals.hp_max END,
    hp_at=greatest(verse.room_vitals.hp_at,EXCLUDED.hp_at),at=greatest(verse.room_vitals.at,EXCLUDED.at),xp=greatest(verse.room_vitals.xp,EXCLUDED.xp)
  WHERE verse.room_vitals.hp_at IS NULL OR verse.room_vitals.hp_at<=EXCLUDED.hp_at OR EXCLUDED.xp>coalesce(verse.room_vitals.xp,-1);
  GET DIAGNOSTICS kept=ROW_COUNT;RETURN kept;
END $$;


--
-- Name: room_wait(text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.room_wait(who text, rate_n bigint, OUT waiting integer, OUT last_wait_ms bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE now bigint := verse.room_now();
BEGIN
  DELETE FROM verse.room_waiting w WHERE w.last_ms < now - 60000;
  INSERT INTO verse.room_waiting AS w (pid, since_ms, last_ms) VALUES (who, now, now)
  ON CONFLICT (pid) DO UPDATE SET last_ms = EXCLUDED.last_ms;
  SELECT count(*)::int INTO waiting FROM verse.room_waiting;
  SELECT l.wait_ms INTO last_wait_ms FROM verse.room_wait_last l WHERE l.at > now - 3600000;
  PERFORM verse.room_admit_count('full', 1);
  PERFORM verse.room_admit_count('rate', rate_n);
END $$;


--
-- Name: seat_close(bigint, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_close(id_ bigint, acct text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE s verse.seats := verse.seat_mine(id_, acct);
BEGIN
  IF s.id IS NULL THEN RETURN 404; END IF;
  PERFORM verse.seat_shut(s, 'closed');
  RETURN 200;
END $$;


--
-- Name: seat_facts(text, text, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_facts(acct text, k text, slug_ text, site_admin boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'others', (SELECT count(*) FROM verse.seats WHERE closed_ms IS NULL AND account <> acct),
    'seen', EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = slug_) AND NOT verse.realm_hidden(slug_, k, site_admin))
$$;


--
-- Name: seat_idle(bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_idle(id_ bigint) RETURNS void
    LANGUAGE sql
    AS $$
  SELECT verse.seat_shut(s, 'idle') FROM verse.seats s WHERE s.id = id_ AND s.closed_ms IS NULL $$;


--
-- Name: seat_keep(bigint, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_keep(id_ bigint, acct text) RETURNS integer
    LANGUAGE sql
    AS $$
  WITH k AS (UPDATE verse.seats SET kept_ms = verse.now_ms() WHERE id = id_ AND account = acct AND closed_ms IS NULL RETURNING 1)
  SELECT CASE WHEN EXISTS (SELECT 1 FROM k) THEN 200 ELSE 404 END $$;


--
-- Name: seats; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.seats (
    id bigint NOT NULL,
    account text NOT NULL,
    signer text NOT NULL,
    slug text NOT NULL,
    player text NOT NULL,
    admin boolean DEFAULT false NOT NULL,
    hosted boolean DEFAULT false NOT NULL,
    opened_ms bigint NOT NULL,
    kept_ms bigint NOT NULL,
    closed_ms bigint,
    closed_why text
);


--
-- Name: seat_mine(bigint, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_mine(id_ bigint, acct text) RETURNS verse.seats
    LANGUAGE sql STABLE
    AS $$
  SELECT * FROM verse.seats WHERE id = id_ AND account = acct AND closed_ms IS NULL $$;


--
-- Name: seat_open(text, text, text, boolean, boolean, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_open(acct text, signer_ text, slug_ text, admin_ boolean, hosted_ boolean, until_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  s verse.seats;
  p jsonb;
  id_ bigint;
BEGIN
  FOR s IN SELECT * FROM verse.seats WHERE closed_ms IS NULL AND account = acct LOOP
    PERFORM verse.seat_shut(s, 'replaced');
  END LOOP;
  p := verse.mint(acct, 'realm-seat');
  INSERT INTO verse.seats (account, signer, slug, player, admin, hosted, opened_ms, kept_ms)
  VALUES (acct, signer_, slug_, p->>'id', admin_, hosted_, verse.now_ms(), verse.now_ms()) RETURNING id INTO id_;
  RETURN jsonb_build_object('id', id_, 'slug', slug_, 'hosted', hosted_, 'player', jsonb_build_object('id', p->>'id', 'key', p->>'key'), 'until', until_ms);
END $$;


--
-- Name: seat_player(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_player(pid text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT pid IS NOT NULL AND EXISTS (SELECT 1 FROM verse.seats WHERE player = pid AND closed_ms IS NULL) $$;


--
-- Name: seat_shut(verse.seats, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seat_shut(s verse.seats, why text) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE verse.seats SET closed_ms = verse.now_ms(), closed_why = why WHERE id = s.id AND closed_ms IS NULL;
  UPDATE verse.players SET key_sha256 = 'closed-seat:' || s.id WHERE id = s.player;
$$;


--
-- Name: seats_kept(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seats_kept() RETURNS TABLE(id bigint, kept_ms bigint, now_ms bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT id, kept_ms, verse.now_ms() FROM verse.seats WHERE closed_ms IS NULL ORDER BY id $$;


--
-- Name: seats_mine(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.seats_mine(acct text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', id, 'slug', slug, 'hosted', hosted, 'opened_ms', opened_ms, 'kept_ms', kept_ms) ORDER BY id DESC), '[]')
  FROM verse.seats WHERE account = acct AND closed_ms IS NULL $$;


--
-- Name: service_levels(bigint, integer, bigint, bigint, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.service_levels(now_ms bigint, days integer, tick_us bigint, join_ms bigint, ckpt_ms bigint) RETURNS TABLE(which integer, good bigint, total bigint, worst bigint, daily jsonb)
    LANGUAGE sql STABLE
    AS $$
  WITH m AS (
    SELECT to_char(to_timestamp(minute / 1000.0) AT TIME ZONE 'America/Chicago', 'YYYY-MM-DD') AS day, tick_p99_us, unsaved_ms
    FROM verse.room_minutes WHERE minute >= now_ms - days::bigint * 86400000 AND players > 0
  ), j AS (
    SELECT to_char(to_timestamp(e.ms / 1000.0) AT TIME ZONE 'America/Chicago', 'YYYY-MM-DD') AS day,
           (e.ms - greatest(e.ms - (e.p->>'ms')::float8,
              coalesce((SELECT max(s.ms) FROM analytics.events s WHERE s.sid = e.sid AND s.ev IN ('create-done', 'portal-shown')
                        AND s.ms <= e.ms AND s.ms >= e.ms - 3600000), 0)))::bigint AS wait
    FROM analytics.events e
    WHERE e.ev = 'room-join' AND e.ms >= now_ms - days::bigint * 86400000 AND e.auto IS DISTINCT FROM 'team'
      AND jsonb_typeof(e.p->'ms') = 'number' AND (e.p->>'ms')::float8 >= 0
  ), v AS (
    SELECT 0 AS which, day, tick_p99_us AS value, tick_p99_us <= tick_us AS ok FROM m WHERE tick_p99_us IS NOT NULL
    UNION ALL SELECT 1, day, wait, wait <= join_ms FROM j
    UNION ALL SELECT 2, day, unsaved_ms, unsaved_ms <= ckpt_ms FROM m WHERE unsaved_ms IS NOT NULL
  ), d AS (
    SELECT which, day, count(*) FILTER (WHERE ok) AS good, count(*) AS total FROM v GROUP BY 1, 2
  )
  SELECT w.which, coalesce((SELECT sum(d.good) FROM d WHERE d.which = w.which), 0)::bigint,
         coalesce((SELECT sum(d.total) FROM d WHERE d.which = w.which), 0)::bigint,
         (SELECT max(v.value) FROM v WHERE v.which = w.which)::bigint,
         coalesce((SELECT jsonb_agg(jsonb_build_array(d.day, d.good, d.total) ORDER BY d.day) FROM d WHERE d.which = w.which), '[]'::jsonb)
  FROM (VALUES (0), (1), (2)) w(which) ORDER BY w.which $$;


--
-- Name: service_mail(jsonb, text, text, text, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.service_mail(sync jsonb, to_addr text, env text, origin text, now_ms bigint) RETURNS SETOF jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('to', to_addr,
    'subject', '[' || env || '] ' || CASE WHEN t.what = 'opened' THEN '' ELSE 'resolved: ' END || (a->>'title'),
    'text', CASE WHEN t.what = 'opened' THEN 'Opened ' ELSE 'Resolved ' END
            || to_char(to_timestamp(CASE WHEN t.what = 'opened' THEN (a->>'opened_ms')::bigint ELSE now_ms END / 1000.0) AT TIME ZONE 'America/Chicago', 'YYYY-MM-DD HH24:MI')
            || ' Chicago time, on ' || env || E'.\n\n' || (a->>'title')
            || CASE WHEN t.what = 'opened' AND a->>'todo' <> '' THEN E'\n\nDo: ' || (a->>'todo') ELSE '' END
            || E'\n\nNow: ' || origin || E'/api/playtest/service-health\nRunbook: https://github.com/OpenAgentsInc/openagents/blob/main/docs/deployment/service-levels.md\n',
    'idempotency_key', 'service-alert-' || env || '-' || (a->>'id') || '-' || t.what)
  FROM (SELECT 'opened' AS what, jsonb_array_elements(coalesce(sync->'opened', '[]'::jsonb)) AS a
        UNION ALL SELECT 'resolved', jsonb_array_elements(coalesce(sync->'resolved', '[]'::jsonb))) t $$;


--
-- Name: service_shard_facts(bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.service_shard_facts(now_ms bigint, slow_us bigint, w_slow bigint, w_fail bigint, w_fenced bigint) RETURNS TABLE(shard integer, addressed boolean, draining boolean, silent_ms bigint, slow integer, failures integer, fenced integer, unsaved_ms bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH r AS (
    SELECT s.shard, (extract(epoch FROM s.at) * 1000)::bigint AS at_ms,
           verse.room_stat(s.body, 'process generation') AS gen,
           round(verse.room_stat(s.body, 'tick p95 ms') * 1000) AS p95_us,
           verse.room_stat(s.body, 'checkpoint failures') AS fails,
           verse.room_stat(s.body, 'checkpoint stale owner refusals') AS fences,
           verse.room_stat(s.body, 'checkpoint unsaved age ms most') AS unsaved
    FROM verse.room_stats s
    WHERE s.at >= to_timestamp((now_ms - greatest(w_slow, w_fail, w_fenced) - 60000) / 1000.0)
  ), d AS (
    SELECT r.*, lag(gen) OVER w AS gen0, lag(fails) OVER w AS fails0, lag(fences) OVER w AS fences0
    FROM r WINDOW w AS (PARTITION BY r.shard ORDER BY r.at_ms)
  ), x AS (
    SELECT d.shard, d.at_ms, d.p95_us, d.unsaved,
           CASE WHEN d.gen0 IS NULL THEN 0 WHEN d.gen0 = d.gen THEN greatest(coalesce(d.fails - d.fails0, 0), 0) ELSE coalesce(d.fails, 0) END AS dfail,
           CASE WHEN d.gen0 IS NULL THEN 0 WHEN d.gen0 = d.gen THEN greatest(coalesce(d.fences - d.fences0, 0), 0) ELSE coalesce(d.fences, 0) END AS dfence
    FROM d
  )
  SELECT k.shard, k.endpoint IS NOT NULL, coalesce(k.draining IS NOT NULL AND k.draining = k.gen, false),
         now_ms - greatest(coalesce(k.at, 0), coalesce(k.seen_at, 0)),
         (SELECT count(*) FROM x WHERE x.shard = k.shard AND x.at_ms > now_ms - w_slow AND x.p95_us > slow_us)::int,
         coalesce((SELECT sum(x.dfail) FROM x WHERE x.shard = k.shard AND x.at_ms > now_ms - w_fail), 0)::int,
         coalesce((SELECT sum(x.dfence) FROM x WHERE x.shard = k.shard AND x.at_ms > now_ms - w_fenced), 0)::int,
         coalesce((SELECT max(x.unsaved) FROM x WHERE x.shard = k.shard AND x.at_ms > now_ms - w_slow), 0)::bigint
  FROM verse.room_shards k ORDER BY k.shard $$;


--
-- Name: service_sync(bigint, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.service_sync(now_ms bigint, alerts jsonb) RETURNS jsonb
    LANGUAGE sql
    AS $$
  WITH want AS (
    SELECT DISTINCT ON (a->>'key') a->>'key' AS key, coalesce(a->>'title', a->>'key') AS title, coalesce(a->>'do', '') AS todo
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(alerts) = 'array' THEN alerts ELSE '[]'::jsonb END) a
    WHERE jsonb_typeof(a) = 'object' AND a->>'key' IS NOT NULL
  ), opened AS (
    INSERT INTO verse.service_alerts (key, title, todo, opened_ms) SELECT w.key, w.title, w.todo, now_ms FROM want w
    ON CONFLICT (key) WHERE resolved_ms IS NULL DO NOTHING
    RETURNING id, key, title, todo, opened_ms
  ), resolved AS (
    UPDATE verse.service_alerts a SET resolved_ms = now_ms
    WHERE a.resolved_ms IS NULL AND NOT EXISTS (SELECT 1 FROM want w WHERE w.key = a.key)
    RETURNING a.id, a.key, a.title, a.todo, a.opened_ms
  ), aged AS (
    DELETE FROM verse.room_minutes WHERE minute < now_ms - 400::bigint * 86400000 RETURNING 1
  ), forgotten AS (
    DELETE FROM verse.service_alerts WHERE resolved_ms < now_ms - 400::bigint * 86400000 RETURNING 1
  )
  SELECT jsonb_build_object(
    'opened', coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.key) FROM opened o), '[]'::jsonb),
    'resolved', coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.key) FROM resolved r), '[]'::jsonb),
    'open', (SELECT count(*) FROM verse.service_alerts WHERE resolved_ms IS NULL) + (SELECT count(*) FROM opened) - (SELECT count(*) FROM resolved)) $$;


--
-- Name: social(text, text, jsonb, text, boolean); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.social(method text, what text, body jsonb, k text, admin boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  me text := verse.player_of(k);
  now_ms bigint := verse.now_ms();
  them text;
  said text;
  sent int;
  id_ bigint;
BEGIN
  IF me IS NULL THEN RETURN verse.r(403, '{"error":"send a player key (POST /api/playtest/player)"}'); END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;

  IF what = 'inbox' AND method = 'GET' THEN
    RETURN verse.r(200, jsonb_build_object(
      'you', jsonb_build_object('id', me, 'name', verse.player_name(me)),
      'admin', admin,
      'unread', (SELECT count(*) FROM verse.inbox i WHERE i.to_player = me AND i.read_ms IS NULL
                   AND NOT EXISTS (SELECT 1 FROM verse.player_blocks b WHERE b.player = me AND b.blocked = i.from_player)),
      'messages', coalesce((SELECT jsonb_agg(jsonb_build_object('id', x.id, 'from', x.from_player, 'name', verse.player_name(x.from_player),
                                                                'to', x.to_player, 'to_name', verse.player_name(x.to_player), 'text', x.text,
                                                                'at', x.at_ms, 'mine', x.from_player = me, 'read', x.read_ms IS NOT NULL) ORDER BY x.id)
                            FROM (SELECT * FROM verse.inbox i WHERE (i.to_player = me OR i.from_player = me)
                                    AND NOT EXISTS (SELECT 1 FROM verse.player_blocks b WHERE b.player = me AND b.blocked IN (i.from_player, i.to_player))
                                  ORDER BY i.id DESC LIMIT 40) x), '[]'),
      'met', coalesce((SELECT jsonb_agg(jsonb_build_object('id', y.other, 'name', verse.player_name(y.other),
                                                           'blocked', EXISTS (SELECT 1 FROM verse.player_blocks b WHERE b.player = me AND b.blocked = y.other))
                                        ORDER BY y.last_ms DESC)
                       FROM (SELECT CASE WHEN m.a = me THEN m.b ELSE m.a END AS other, m.last_ms FROM verse.players_met m
                             WHERE m.a = me OR m.b = me ORDER BY m.last_ms DESC LIMIT 30) y), '[]'),
      'blocked', verse.blocked_by(me)));
  END IF;
  IF method <> 'POST' THEN RETURN verse.r(405, '{"error":"POST"}'); END IF;

  IF what = 'inbox' THEN
    them := CASE WHEN jsonb_typeof(body->'to') = 'string' THEN body->>'to' END;
    IF them IS NULL OR them !~ '^[A-Za-z0-9_-]{1,64}$' OR NOT EXISTS (SELECT 1 FROM verse.players WHERE id = them) THEN
      RETURN verse.r(404, '{"error":"no such player"}');
    END IF;
    IF them = me THEN RETURN verse.r(400, '{"error":"that is you"}'); END IF;
    IF NOT verse.have_met(me, them) THEN RETURN verse.r(403, '{"error":"you can write to players you have met"}'); END IF;
    said := verse.clean_text(body->'text', 500);
    IF said = '' THEN RETURN verse.r(400, '{"error":"write something"}'); END IF;
    SELECT count(*) INTO sent FROM verse.inbox WHERE from_player = me AND at_ms > now_ms - 60000;
    IF sent >= 5 THEN RETURN verse.r(429, '{"error":"a little slower"}'); END IF;
    SELECT count(*) INTO sent FROM verse.inbox WHERE from_player = me AND at_ms > now_ms - 86400000;
    IF sent >= 100 THEN RETURN verse.r(429, '{"error":"that is enough for today"}'); END IF;
    INSERT INTO verse.inbox (to_player, from_player, text, at_ms) VALUES (them, me, said, now_ms) RETURNING id INTO id_;
    RETURN verse.r(200, jsonb_build_object('id', id_));
  END IF;

  IF what = 'inbox/read' THEN
    IF jsonb_typeof(body->'upto') IS DISTINCT FROM 'number' THEN RETURN verse.r(400, '{"error":"up to which: {upto}"}'); END IF;
    UPDATE verse.inbox SET read_ms = now_ms WHERE to_player = me AND read_ms IS NULL AND id <= (body->>'upto')::numeric::bigint
      AND (jsonb_typeof(body->'from') IS DISTINCT FROM 'string' OR from_player = body->>'from');
    RETURN verse.r(200, jsonb_build_object('unread', (SELECT count(*) FROM verse.inbox WHERE to_player = me AND read_ms IS NULL)));
  END IF;

  IF what = 'block' THEN
    them := CASE WHEN jsonb_typeof(body->'player') = 'string' THEN body->>'player' END;
    IF them IS NULL OR them = me OR NOT EXISTS (SELECT 1 FROM verse.players WHERE id = them) THEN
      RETURN verse.r(404, '{"error":"no such player"}');
    END IF;
    IF body->'on' = 'false'::jsonb THEN
      DELETE FROM verse.player_blocks WHERE player = me AND blocked = them;
    ELSE
      INSERT INTO verse.player_blocks (player, blocked, at_ms) VALUES (me, them, now_ms) ON CONFLICT DO NOTHING;
    END IF;
    RETURN verse.r(200, jsonb_build_object('blocked', verse.blocked_by(me)));
  END IF;
  RETURN verse.r(404, '{"error":"unknown"}');
END $_$;


--
-- Name: visibility_of(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.visibility_of(v jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'string' AND (v #>> '{}') IN ('private', 'unlisted', 'public') THEN v #>> '{}' END $$;


--
-- Name: vitals_follow(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.vitals_follow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  was text := coalesce(OLD.account, OLD.id);
  now_ text := coalesce(NEW.account, NEW.id);
  v verse.room_vitals;
BEGIN
  IF was = now_ THEN RETURN NEW; END IF;
  SELECT * INTO v FROM verse.room_vitals WHERE who = was;
  IF v.who IS NULL THEN RETURN NEW; END IF;
  INSERT INTO verse.room_vitals AS x (who, hp, hp_max, hp_at, wanted, wanted_at, look, class, at, xp, character_class)
  VALUES (now_, v.hp, v.hp_max, v.hp_at, v.wanted, v.wanted_at, v.look, v.class, v.at, v.xp, v.character_class)
  ON CONFLICT (who) DO UPDATE SET
    xp = greatest(x.xp, EXCLUDED.xp),
    hp = CASE WHEN x.hp_at IS NULL OR x.hp_at < EXCLUDED.hp_at THEN EXCLUDED.hp ELSE x.hp END,
    hp_max = CASE WHEN x.hp_at IS NULL OR x.hp_at < EXCLUDED.hp_at THEN EXCLUDED.hp_max ELSE x.hp_max END,
    hp_at = greatest(x.hp_at, EXCLUDED.hp_at),
    look = coalesce(x.look, EXCLUDED.look), class = coalesce(x.class, EXCLUDED.class),
    character_class = coalesce(x.character_class, EXCLUDED.character_class),
    at = greatest(x.at, EXCLUDED.at);
  RETURN NEW;
END $$;


--
-- Name: voice_edit_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  r jsonb;
  t text;
  d jsonb;
  held jsonb;
  err text;
  status int := 200;
  realm text := (SELECT v.realm FROM verse.voice_edits v WHERE v.id = (asked->>'id')::bigint);
BEGIN
  BEGIN r := response::jsonb; EXCEPTION WHEN others THEN r := NULL; END;
  IF http = 200 AND r IS NOT NULL THEN
    SELECT string_agg(p->>'text', '') INTO t
    FROM jsonb_array_elements(coalesce(r->'candidates'->0->'content'->'parts', '[]')) p
    WHERE coalesce((p->>'thought')::boolean, false) = false AND p ? 'text';
    BEGIN d := t::jsonb; EXCEPTION WHEN others THEN d := NULL; END;
    IF d IS NULL THEN status := 503; err := 'no answer';
    ELSIF jsonb_typeof(d) = 'object' AND d->>'edit' = 'none' THEN
      IF verse.voice_edit_reply(d) <> '' THEN held := jsonb_build_object('edit', 'chat', 'reply', verse.voice_edit_reply(d));
      ELSE status := 422; err := 'none fit';
      END IF;
    ELSE held := verse.voice_edit_hold(realm, d); IF held IS NULL THEN status := 502; err := 'not an edit'; END IF;
    END IF;
  ELSE
    status := 503;
    err := CASE WHEN http = 429 THEN 'busy' WHEN http = 0 THEN 'model unreachable' ELSE 'model error ' || http END;
  END IF;
  UPDATE verse.voice_edits SET edit = held, error = err, model = voice_edit_answer.model, ms_taken = taken WHERE id = (asked->>'id')::bigint;
  IF held IS NULL THEN RETURN jsonb_build_object('status', status, 'error', err); END IF;
  RETURN jsonb_build_object('status', 200) || held || jsonb_build_object('model', model);
END $$;


--
-- Name: voice_edit_ask(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_ask(realm text, body jsonb, pubkey text, cap integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT verse.worlds_answer(verse.voice_edit_ask_0110(realm, body, pubkey, cap)) $$;


--
-- Name: voice_edit_ask_0110(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_ask_0110(realm text, body jsonb, pubkey text, cap integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  sentence text := CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'sentence', 300) ELSE '' END;
  row_id bigint;
BEGIN
  IF NOT verse.voice_realm(realm) THEN RETURN '{"status":400,"error":"this realm takes no voice edits"}'; END IF;
  IF sentence = '' THEN RETURN '{"status":400,"error":"say what to change"}'; END IF;
  IF EXISTS (SELECT 1 FROM verse.voice_edits v WHERE v.pubkey = voice_edit_ask_0110.pubkey AND v.ms > verse.now_ms() - 30000 AND v.ms_taken IS NULL) THEN
    RETURN '{"status":429,"error":"one edit at a time"}';
  END IF;
  IF (SELECT count(*) FROM verse.voice_edits WHERE ms > (extract(epoch FROM date_trunc('day', now())) * 1000)::bigint) >= cap THEN
    RETURN '{"status":503,"error":"the day''s voice edits are used up"}';
  END IF;
  INSERT INTO verse.voice_edits (ms, realm, pubkey, sentence) VALUES (verse.now_ms(), realm, pubkey, sentence) RETURNING id INTO row_id;
  RETURN jsonb_build_object('status', 200, 'id', row_id, 'request', jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text',
      verse.voice_edit_prompt(realm) || E'\n' || verse.voice_edit_now()))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(jsonb_build_object('text', sentence)))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json', 'responseSchema', verse.voice_edit_schema(realm),
      'temperature', 0, 'maxOutputTokens', 800, 'thinkingConfig', jsonb_build_object('thinkingBudget', 0))));
END $$;


--
-- Name: voice_edit_catalogue(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_catalogue(realm text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN m = 'everglade' THEN jsonb_set(c, '{who}', (c->'who') || '["Warden Hale", "Lark", "Mistress Wren", "Dunstan", "Tamsin", "Old Haddon"]'::jsonb)
              ELSE c END
  FROM (SELECT m, verse.voice_edit_catalogue_0051(m) AS c
        FROM (SELECT CASE WHEN b IN ('everglade-5e', 'everglade-classic') THEN 'everglade' ELSE b END AS m
              FROM (SELECT coalesce((SELECT base FROM verse.made_realms WHERE slug = realm AND base IS NOT NULL), realm) AS b) x) y) z $$;


--
-- Name: voice_edit_catalogue_0051(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_catalogue_0051(realm text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT CASE realm
  WHEN 'everglade' THEN '{
    "items": ["crate", "barrel", "bench", "fence", "stall", "pumpkin", "sack", "apple crate", "carrots", "pot", "bucket", "lantern", "cart", "vase", "table", "chair", "stool", "anvil", "cauldron", "training dummy", "weapon rack", "banner", "coins", "sign", "bush", "flowers", "rock", "rock pile", "hay pile", "stone wall", "crops", "house", "shed", "tower"],
    "sizes": ["0.8x0.9x0.9", "0.7x0.7x0.9", "2.8x0.5x0.5", "2.1x0.1x0.8", "2.9x1.5x2.6 (a market stall)", "0.6x0.6x0.5", "0.7x0.5x0.8", "0.7x0.4x0.2", "0.4x0.4x0.6", "0.5x0.5x0.2", "0.4x0.4x0.3", "0.4x0.4x2.4 (on a post)", "3.0x1.1x2.6", "0.7x0.7x0.5", "2.8x1.1x0.8", "0.6x0.5x1.1", "0.5x0.5x0.6", "1.1x0.4x0.6", "1.0x0.9x0.8", "0.8x0.6x1.9", "1.4x1.0x1.1", "1.6x0.2x2.4", "0.4x0.3x0.1", "1.2x0.2x1.8", "1.6x1.6x1.2", "a patch 6 m across", "1.8x1.8x0.8", "2.5x2.5x1.2", "2.0x2.0x1.2", "4.0x0.6x1.2", "rows, 4x4 m", "6x5x6 (a cottage: any building they ask for)", "3x3x3", "4x4x10"],
    "kinds": ["person", "cat", "building"],
    "onto": ["stall", "table", "crate", "barrel", "bench", "cart", "stool"],
    "colours": ["purple", "blue", "red", "pink", "yellow", "white", "orange"],
    "arrange": ["front", "row", "ring", "scatter", "fill"],
    "directions": ["here", "forward", "back", "left", "right", "away", "closer"],
    "buildings": ["inn", "general store", "smithy", "alchemist", "fighters'' hall", "rangers'' lodge", "mages'' tower", "temple", "observatory", "stables", "house"],
    "who": ["Bram", "Tilda", "Pip", "Oswin", "Pebble", "Marta", "Soot", "Hollis", "Fern", "Ada", "Quill", "Garrick", "Isolde", "Rook", "Sable", "Elowen", "Wisp", "Brother Anselm", "Vega", "Moss", "Old Tam", "Corin"],
    "edits": {
      "place": {"says": "put things down: count how many (1 to 40; a plural with no number is 3), arrange how (front: a row in front of the speaker, the usual; row; ring: all around, around me, in a circle; scatter: spread about; fill: cover the open ground in front, \"fill the field with\"), onto one of the things with a top when they said ON it, colour when they said one, size when they said big (1.5), huge (2.5), small (0.6) or tiny (0.4)",
                "examples": ["put two barrels here => place, item barrel, count 2", "add a bench => place, item bench, count 1",
                             "put pumpkins on the stall => place, item pumpkin, count 3, onto stall", "put six pumpkins on the stall => place, item pumpkin, count 6, onto stall",
                             "put a building in front of me => place, item house (any building is a house, never a stall)",
                             "place 12 benches all around => place, item bench, count 12, arrange ring", "place four big crates in front => place, item crate, count 4, size 1.5",
                             "fill the field with purple flowers => place, item flowers, colour purple, arrange fill", "a row of fences => place, item fence, count 4, arrange row",
                             "scatter some rocks about => place, item rock, count 3, arrange scatter",
                             "place a dragon => place, item something, name dragon (a dragon is not in the list: never put another thing instead)"]},
      "remove": {"says": "take away placed things, or the city''s people, cats or buildings, near the speaker or named: one (the nearest, \"that\", \"this crate\"), or many with all true (\"these\", \"those\", \"the crates\", plurals, \"all the\", \"clear this\")",
                 "examples": ["remove that => remove", "remove these crates => remove, item crate, all true", "get rid of those benches => remove, item bench, all true",
                              "remove all the barrels here => remove, item barrel, all true", "clear this => remove, all true", "take this crate away => remove, item crate",
                              "remove Marta => remove, item person, who Marta", "remove these cats => remove, item cat, all true", "get rid of that guard => remove, item person",
                              "delete this temple building => remove, item building, building temple", "remove the inn => remove, item building, building inn",
                              "remove that house => remove, item house", "remove Bob => remove, item person, name Bob (no one in the city is called Bob)"]},
      "move": {"says": "move placed things near the speaker (one, or many with all true) in a direction: here (to in front of the speaker, when no direction is said), forward, back, left, right, away, closer; metres when they said how far",
               "examples": ["move these crates => move, item crate, all true, direction here", "movies crates (misheard: move these crates) => move, item crate, all true, direction here",
                            "move it left two metres => move, direction left, metres 2", "push that barrel back => move, item barrel, direction back",
                            "bring the benches closer => move, item bench, all true, direction closer"]},
      "resize": {"says": "make placed things near the speaker bigger or smaller: size is the factor (bigger 1.5, smaller 0.67, twice as big 2, half 0.5)",
                 "examples": ["this barrel is bigger => resize, item barrel, size 1.5 (they want it bigger)", "make these benches smaller => resize, item bench, all true, size 0.67",
                              "make that twice as big => resize, size 2", "the stall should be half the size => resize, item stall, size 0.5"]},
      "rotate": {"says": "turn placed things near the speaker: turn in degrees, positive to the speaker''s right (turn it around: 180; a turn with no amount: 90)",
                 "examples": ["turn it around => rotate, turn 180", "turn that bench to the left => rotate, item bench, turn -90", "rotate these fences a bit right => rotate, item fence, all true, turn 30"]},
      "restore": {"says": "bring back a building of the city that was hidden, or a person or cat that was removed",
                  "examples": ["bring back the temple => restore, building temple", "bring Marta back => restore, who Marta"]},
      "list": {"says": "they ask what they can put down or what can be made",
               "examples": ["what else can I put down? => list", "what can you make? => list", "what can I place? => list"]},
      "undo": {"says": "take back the last change", "examples": ["undo that => undo", "put it back the way it was => undo"]}
    }
  }'::jsonb END $$;


--
-- Name: voice_edit_generic(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_generic() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(replace(verse.voice_edit_generic_0110()::text, ' realm''s ', ' world''s '), 'the realm changed', 'the world changed')::jsonb $$;


--
-- Name: voice_edit_generic_0110(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_generic_0110() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT '{
  "switch": {"says": "turn one of the realm''s switches on or off: row is its id, on is true to turn it on, false to turn it off, disable, stop or get rid of it",
             "examples": ["turn off the guards => switch, row guards, on false", "stop the guards chasing me => switch, row guards, on false",
                          "make me invincible => switch, row invincible, on true", "I want to be able to die again => switch, row invincible, on false",
                          "no more ducks => switch, row floats, on false", "keep it daytime => switch, row daycycle, on false"]},
  "show": {"says": "open or close the editing screen: panel edit (the edit panel, the board, the list of features, edit mode), settings (the realm''s settings, tools visitors get), ideas (visitors'' ideas, proposals, cards), close (close it, done editing)",
           "examples": ["open the edit panel => show, panel edit", "edit mode => show, panel edit", "show me the settings => show, panel settings",
                        "what have visitors suggested => show, panel ideas", "close that => show, panel close", "I''m done editing => show, panel close"]},
  "look": {"says": "they ask about something they see on their screen right now: what it is, why it looks like that, where something is, what is wrong with the picture; the screen is looked at next",
           "examples": ["there''s some weird dark strip along the sky, what is this? => look", "what am I looking at? => look",
                        "what''s that building over there? => look", "why is the water black? => look", "can you see that glitch? => look"]},
  "ask": {"says": "they want the realm changed in a way none of its switches does: something added, taken away, moved or made different; their words go on the realm''s list of changes",
          "examples": ["add a dragon by the lake => ask", "put a castle on the hill => ask", "make the trees taller => ask", "can we have more lanterns => ask",
                       "take the bridge away => ask (when no switch is the bridge)"]}
}'::jsonb $$;


--
-- Name: voice_edit_hold(text, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_hold(realm text, d jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  verb text := CASE WHEN jsonb_typeof(d) = 'object' AND jsonb_typeof(d->'edit') = 'string' THEN d->>'edit' END;
BEGIN
  IF verse.voice_edit_catalogue(realm) IS NOT NULL THEN RETURN verse.voice_edit_hold_0105(realm, d); END IF;
  IF verb IS NULL OR NOT verb = ANY (verse.voice_edit_verbs(realm)) THEN RETURN NULL; END IF;
  IF verb IN ('look', 'ask') THEN RETURN jsonb_build_object('edit', verb); END IF;
  IF verb = 'switch' THEN
    IF NOT verse.voice_edit_rows(realm) @> jsonb_build_array(jsonb_build_object('id', coalesce(d->>'row', ''))) THEN RETURN NULL; END IF;
    RETURN jsonb_build_object('edit', 'switch', 'row', d->>'row', 'on', jsonb_typeof(d->'on') = 'boolean' AND (d->>'on')::boolean);
  END IF;
  IF NOT verse.voice_edit_panels() ? coalesce(d->>'panel', '') THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('edit', 'show', 'panel', d->>'panel');
END $$;


--
-- Name: voice_edit_hold_0105(text, jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_hold_0105(realm text, d jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  c jsonb := verse.voice_edit_catalogue(realm);
  verb text := CASE WHEN jsonb_typeof(d) = 'object' AND jsonb_typeof(d->'edit') = 'string' THEN d->>'edit' END;
  said text := CASE WHEN jsonb_typeof(d->'name') = 'string' THEN left(btrim(d->>'name'), 60) ELSE '' END;
  item text := CASE WHEN jsonb_typeof(d->'item') = 'string' THEN d->>'item' END;
  placed bool;
  out jsonb;
  x numeric;
BEGIN
  IF c IS NULL OR verb IS NULL OR NOT verb = ANY (verse.voice_edit_order()) THEN RETURN NULL; END IF;
  placed := coalesce(c->'items' ? item, false);
  out := jsonb_build_object('edit', verb);
  IF verb IN ('list', 'undo', 'look') THEN RETURN out; END IF;
  IF verb = 'switch' THEN   -- one of the realm's own rows, by its id
    IF NOT verse.voice_edit_rows(realm) @> jsonb_build_array(jsonb_build_object('id', coalesce(d->>'row', ''))) THEN RETURN NULL; END IF;
    RETURN out || jsonb_build_object('row', d->>'row', 'on', jsonb_typeof(d->'on') = 'boolean' AND (d->>'on')::boolean);
  END IF;
  IF verb = 'show' THEN     -- one of the editing screen's panes, or close
    IF NOT verse.voice_edit_panels() ? coalesce(d->>'panel', '') THEN RETURN NULL; END IF;
    RETURN out || jsonb_build_object('panel', d->>'panel');
  END IF;

  IF verb = 'place' THEN
    IF NOT placed THEN   -- never another thing instead: what they named is missing, or it's no edit
      RETURN CASE WHEN said <> '' THEN jsonb_build_object('edit', 'missing', 'name', said) END;
    END IF;
    x := CASE WHEN jsonb_typeof(d->'count') = 'number' THEN round((d->>'count')::numeric) END;
    out := out || jsonb_build_object('item', item, 'count', CASE WHEN x IS NULL OR x < 1 THEN 1 ELSE least(x, 40)::int END);
    IF c->'arrange' ? coalesce(d->>'arrange', '') AND d->>'arrange' <> 'front' THEN out := out || jsonb_build_object('arrange', d->>'arrange'); END IF;
    IF c->'onto' ? coalesce(d->>'onto', '') THEN out := out || jsonb_build_object('onto', d->>'onto'); END IF;
    IF c->'colours' ? coalesce(d->>'colour', '') THEN out := out || jsonb_build_object('colour', d->>'colour'); END IF;
    x := CASE WHEN jsonb_typeof(d->'size') = 'number' THEN round((d->>'size')::numeric, 2) END;
    IF x > 0 AND x <> 1 THEN out := out || jsonb_build_object('size', trim_scale(greatest(0.25, least(4, x)))); END IF;
    RETURN out;
  END IF;

  IF verb = 'restore' THEN
    IF c->'buildings' ? coalesce(d->>'building', '') THEN out := out || jsonb_build_object('building', d->>'building');
    ELSIF c->'who' ? coalesce(d->>'who', '') THEN out := out || jsonb_build_object('who', d->>'who');
    ELSIF said <> '' THEN RETURN jsonb_build_object('edit', 'missing', 'name', said);
    END IF;
    RETURN out;
  END IF;

  -- remove, move, resize, rotate: what (a placed kind; remove also the city's people, cats and buildings), and how many
  IF placed OR (verb = 'remove' AND c->'kinds' ? coalesce(item, '')) THEN out := out || jsonb_build_object('item', item); END IF;
  IF jsonb_typeof(d->'all') = 'boolean' AND (d->>'all')::boolean THEN out := out || '{"all": true}'::jsonb; END IF;
  IF verb = 'remove' THEN
    -- a name only for one person: not with a placed thing's kind, nor with many
    IF c->'who' ? coalesce(d->>'who', '') AND NOT out ? 'all' AND coalesce(out->>'item', 'person') IN ('person', 'cat') THEN
      out := out || jsonb_build_object('who', d->>'who');
    END IF;
    -- a building of the city only as the building it is
    IF c->'buildings' ? coalesce(d->>'building', '') AND coalesce(out->>'item', 'building') = 'building' AND NOT out ? 'who' THEN
      out := out || jsonb_build_object('item', 'building', 'building', d->>'building');
    END IF;
  END IF;
  -- they named someone or something not here, and nothing that is
  IF said <> '' AND NOT placed AND NOT out ? 'who' AND NOT out ? 'building' THEN
    RETURN jsonb_build_object('edit', 'missing', 'name', said);
  END IF;
  IF verb = 'move' THEN
    out := out || jsonb_build_object('direction', CASE WHEN c->'directions' ? coalesce(d->>'direction', '') THEN d->>'direction' ELSE 'here' END);
    x := CASE WHEN jsonb_typeof(d->'metres') = 'number' THEN round((d->>'metres')::numeric, 1) END;
    IF x > 0 THEN out := out || jsonb_build_object('metres', trim_scale(greatest(0.5, least(30, x)))); END IF;
  ELSIF verb = 'resize' THEN
    x := CASE WHEN jsonb_typeof(d->'size') = 'number' THEN round((d->>'size')::numeric, 2) END;
    out := out || jsonb_build_object('size', CASE WHEN x IS NULL OR x <= 0 OR x = 1 THEN 1.5 ELSE trim_scale(greatest(0.25, least(4, x))) END);
  ELSIF verb = 'rotate' THEN
    x := CASE WHEN jsonb_typeof(d->'turn') = 'number' THEN round((d->>'turn')::numeric) END;
    out := out || jsonb_build_object('turn', CASE WHEN x IS NULL OR x = 0 THEN 90 ELSE greatest(-360, least(360, x))::int END);
  END IF;
  RETURN out;
END $$;


--
-- Name: voice_edit_now(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_now() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT 'It is now ' || to_char(now() AT TIME ZONE 'America/Chicago', 'FMDay, FMMonth FMDD, YYYY, FMHH12:MI AM') || ' in Chicago (Central time).' $$;


--
-- Name: voice_edit_order(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_order() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT ARRAY['place', 'remove', 'move', 'resize', 'rotate', 'restore', 'list', 'undo', 'switch', 'show', 'look'] $$;


--
-- Name: voice_edit_panels(); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_panels() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT '["edit", "settings", "ideas", "close"]'::jsonb $$;


--
-- Name: voice_edit_prompt(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_prompt(realm text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT replace(replace(replace(replace(verse.voice_edit_prompt_0110(realm),
    ' is a realm in the Verse (a small 3D world) and they stand in it. ', ' is a world in the Verse (a small 3D scene) and they stand in it. '),
    'what is in this realm comes from the ', 'what is in this world comes from the '),
    E'\nThe realm''s switches', E'\nThe world''s switches'),
    'what''s in this realm? => none', 'what''s in this world? => none') $$;


--
-- Name: voice_edit_prompt_0105(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_prompt_0105(realm text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH c AS (SELECT verse.voice_edit_catalogue(realm) AS c)
  SELECT 'You turn what an admin said out loud into one edit of ' || initcap(realm) || ', a realm in the Verse (a small 3D world). '
    || 'They stand in the realm and speak one sentence to change it. Choose the one edit below that does what they asked, '
    || 'and fill its fields from what they said; every field the edit does not use gets its "not said" value. '
    || 'Speech recognition may mishear a word; pick what they most likely meant. When the sentence is unclear, still pick the edit it most likely means. '
    || 'Answer edit "none" only when it is not an edit at all (a question, small talk, thanks); a question about what they see on screen is look. '
    || 'Never answer a thing they did not ask for: when what they named is not in these lists, the item is something and name is what they said. '
    || 'reply is "" for every edit. For none, reply answers them the way a friendly builder standing beside them would, out loud: '
    || 'one to three short plain sentences, no lists or markdown. Answer the question itself when you can (what is in this realm and what you '
    || 'can do come from the lists below; the current time is given); when you cannot know, say so briefly. '
    || E'\nThe things that can be put down (width x depth x height in metres at size 1):\n'
    || (SELECT string_agg(i || ' ' || (c.c->'sizes'->>(o - 1)::int), '; ' ORDER BY o) FROM jsonb_array_elements_text(c.c->'items') WITH ORDINALITY AS t(i, o))
    || E'\nThings with a top that others can go onto: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c.c->'onto') k)
    || E'\nColours: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c.c->'colours') k)
    || E'\nThe city''s buildings: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c.c->'buildings') k)
    || E'\nThe city''s people and cats: ' || (SELECT string_agg(k, ', ') FROM jsonb_array_elements_text(c.c->'who') k)
    || E'\nThe realm''s switches (its features, each on or off for everyone):\n'
    || coalesce((SELECT string_agg('- ' || (r->>'id') || ': ' || coalesce(r->>'label', '') || ' (' || coalesce(r->>'says', '') || ')', E'\n')
                 FROM jsonb_array_elements(verse.voice_edit_rows(realm)) r), '(none)')
    || E'\nThe edits:\n'
    || (SELECT string_agg('- ' || n || ': ' || (e->>'says')
         || E'\n  for example: ' || (SELECT string_agg(k, '; ') FROM jsonb_array_elements_text(e->'examples') k), E'\n' ORDER BY o)
        FROM unnest(verse.voice_edit_order()) WITH ORDINALITY AS t(n, o),
             LATERAL (SELECT coalesce(c.c->'edits'->n, verse.voice_edit_generic()->n) AS e) x WHERE e IS NOT NULL)
    || E'\n- none: not an edit; reply answers them. for example: what time is it => none, reply with the time; '
    || 'is this working? => none, reply yes, I can hear you; hello => none, reply with a greeting and what they can ask for; '
    || 'who lives here? => none, reply naming a few of the city''s people'
  FROM c WHERE c.c IS NOT NULL $$;


--
-- Name: voice_edit_prompt_0110(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_prompt_0110(realm text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN verse.voice_edit_catalogue(realm) IS NOT NULL THEN verse.voice_edit_prompt_0105(realm) ELSE
    'You turn what the owner of ' || verse.voice_realm_name(realm) || ' said out loud or typed into one action. '
    || verse.voice_realm_name(realm) || ' is a realm in the Verse (a small 3D world) and they stand in it. '
    || 'Choose the one action below that does what they asked, and fill its fields from what they said; every field the action does not use gets its "not said" value. '
    || 'Speech recognition may mishear a word; pick what they most likely meant. When the sentence is unclear, still pick the action it most likely means. '
    || 'Answer edit "none" only when it is not an action at all (a question, small talk, thanks); a question about what they see on screen is look. '
    || 'reply is "" for every action but none. For none, reply answers them the way a friendly builder standing beside them would, out loud: '
    || 'one to three short plain sentences, no lists or markdown. Answer the question itself when you can (what is in this realm comes from the '
    || 'list below; the current time is given); when you cannot know, say so briefly.'
    || E'\nThe realm''s switches (its features, each on or off for everyone):\n'
    || coalesce((SELECT string_agg('- ' || (r->>'id') || ': ' || coalesce(r->>'label', '') || CASE WHEN coalesce(r->>'says', '') NOT IN ('', r->>'label') THEN ' (' || (r->>'says') || ')' ELSE '' END, E'\n')
                 FROM jsonb_array_elements(verse.voice_edit_rows(realm)) r), '(none)')
    || E'\nThe actions:\n'
    || (SELECT string_agg('- ' || n || ': ' || (verse.voice_edit_generic()->n->>'says')
         || E'\n  for example: ' || (SELECT string_agg(k, '; ') FROM jsonb_array_elements_text(verse.voice_edit_generic()->n->'examples') k), E'\n' ORDER BY o)
        FROM unnest(verse.voice_edit_verbs(realm)) WITH ORDINALITY AS t(n, o))
    || E'\n- none: not an action; reply answers them. for example: what time is it => none, reply with the time; '
    || 'is this working? => none, reply yes, I can hear you; hello => none, reply with a greeting and what they can ask for; '
    || 'what''s in this realm? => none, reply naming a few of its features'
  END $$;


--
-- Name: voice_edit_reply(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_reply(d jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(d->'reply') = 'string'
    THEN left(btrim(regexp_replace(translate(d->>'reply', E'"\\', E'''/'), '\s+', ' ', 'g')), 300) ELSE '' END $$;


--
-- Name: voice_edit_rows(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_rows(realm text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = realm) THEN
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id', verse.edit_key(f), 'label', f->>'label', 'says', f->>'label') ORDER BY o), '[]'::jsonb)
     FROM verse.made_realms m, jsonb_array_elements(verse.edit_made_board(m)) WITH ORDINALITY AS t(f, o)
     WHERE m.slug = realm AND jsonb_typeof(f->'label') = 'string' AND verse.edit_key(f) IS NOT NULL)
  ELSE coalesce((SELECT jsonb_agg(r) FROM verse.realm_rights x, jsonb_array_elements(x.rows) r
                 WHERE x.slug = realm AND jsonb_typeof(r->'id') = 'string'), '[]'::jsonb) END $$;


--
-- Name: voice_edit_schema(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_schema(realm text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN verse.voice_edit_catalogue(realm) IS NOT NULL THEN verse.voice_edit_schema_0105(realm) ELSE
    jsonb_build_object('type', 'object',
      'required', '["edit", "row", "on", "panel", "reply"]'::jsonb,
      'propertyOrdering', '["edit", "row", "on", "panel", "reply"]'::jsonb,
      'properties', jsonb_build_object(
        'edit', jsonb_build_object('type', 'string', 'enum', to_jsonb(verse.voice_edit_verbs(realm) || ARRAY['none'])),
        'row', jsonb_build_object('type', 'string', 'description', 'for switch: the switch they mean; unnamed otherwise',
                                  'enum', '["unnamed"]'::jsonb || coalesce((SELECT jsonb_agg(r->'id') FROM jsonb_array_elements(verse.voice_edit_rows(realm)) r), '[]'::jsonb)),
        'on', jsonb_build_object('type', 'boolean', 'description', 'for switch: true to turn it on, false to turn it off; else false'),
        'panel', jsonb_build_object('type', 'string', 'description', 'for show: the pane to open, or close; unsaid otherwise',
                                    'enum', '["unsaid"]'::jsonb || verse.voice_edit_panels()),
        'reply', jsonb_build_object('type', 'string', 'description', 'for none: what to say back to them, one to three short spoken sentences; for an action: ""')))
  END $$;


--
-- Name: voice_edit_schema_0105(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_schema_0105(realm text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  WITH c AS (SELECT verse.voice_edit_catalogue(realm) AS c)
  SELECT jsonb_build_object('type', 'object',
    'required', '["edit", "item", "name", "count", "arrange", "onto", "colour", "size", "direction", "metres", "turn", "all", "who", "building", "row", "on", "panel", "reply"]'::jsonb,
    'propertyOrdering', '["edit", "item", "name", "count", "arrange", "onto", "colour", "size", "direction", "metres", "turn", "all", "who", "building", "row", "on", "panel", "reply"]'::jsonb,
    'properties', jsonb_build_object(
    'edit', jsonb_build_object('type', 'string', 'enum', to_jsonb(verse.voice_edit_order() || ARRAY['none'])),
    'item', jsonb_build_object('type', 'string', 'description', 'the kind of thing they named (a person, cat or building of the city by its kind); something when they named no kind ("that", "it", "this") or a thing not in the list',
                               'enum', (c.c->'items') || (c.c->'kinds') || '["something"]'::jsonb),
    'name', jsonb_build_object('type', 'string', 'description', 'only when they named a thing, a person or a building that is NOT in the lists: what they said, as said ("dragon", "Bob"); else ""'),
    'count', jsonb_build_object('type', 'integer', 'description', 'for place: how many (1 to 40; "two" is 2, "a" is 1, a plural with no number is 3); else 1'),
    'arrange', jsonb_build_object('type', 'string', 'description', 'for place: front (the usual), row, ring (all around, around me, in a circle), scatter (spread about), fill (fill the field with)',
                                  'enum', c.c->'arrange'),
    'onto', jsonb_build_object('type', 'string', 'description', 'for place: the thing they said to put it ON; ground when they did not say on',
                               'enum', '["ground"]'::jsonb || (c.c->'onto')),
    'colour', jsonb_build_object('type', 'string', 'description', 'for place: the colour they said; unsaid when none', 'enum', (c.c->'colours') || '["unsaid"]'::jsonb),
    'size', jsonb_build_object('type', 'number', 'description', 'for place: big 1.5, huge 2.5, small 0.6, tiny 0.4, else 1; for resize: the factor (bigger 1.5, smaller 0.67, twice 2, half 0.5)'),
    'direction', jsonb_build_object('type', 'string', 'description', 'for move: which way; here (to in front of the speaker) when not said', 'enum', c.c->'directions'),
    'metres', jsonb_build_object('type', 'number', 'description', 'for move: how far, when they said; else 0'),
    'turn', jsonb_build_object('type', 'number', 'description', 'for rotate: degrees, positive to the right, around is 180; else 0'),
    'all', jsonb_build_object('type', 'boolean', 'description', 'for remove, move, resize, rotate: true when they mean more than one (these, those, a plural, all, clear), else false'),
    'who', jsonb_build_object('type', 'string', 'description', 'for remove or restore: the person or cat of the city they said by name; nobody when they said no such name',
                              'enum', '["nobody"]'::jsonb || (c.c->'who')),
    'building', jsonb_build_object('type', 'string', 'description', 'for remove or restore: the city''s building they named; unnamed when none',
                                   'enum', '["unnamed"]'::jsonb || (c.c->'buildings')),
    'row', jsonb_build_object('type', 'string', 'description', 'for switch: the switch they mean; unnamed otherwise',
                              'enum', '["unnamed"]'::jsonb || coalesce((SELECT jsonb_agg(r->'id') FROM jsonb_array_elements(verse.voice_edit_rows(realm)) r), '[]'::jsonb)),
    'on', jsonb_build_object('type', 'boolean', 'description', 'for switch: true to turn it on, false to turn it off; else false'),
    'panel', jsonb_build_object('type', 'string', 'description', 'for show: the pane to open, or close; unsaid otherwise',
                                'enum', '["unsaid"]'::jsonb || verse.voice_edit_panels()),
    'reply', jsonb_build_object('type', 'string', 'description', 'for none: what to say back to them, one to three short spoken sentences; for an edit: ""')))
  FROM c WHERE c.c IS NOT NULL $$;


--
-- Name: voice_edit_verbs(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_edit_verbs(realm text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN verse.voice_edit_catalogue(realm) IS NOT NULL THEN verse.voice_edit_order()
    ELSE CASE WHEN jsonb_array_length(verse.voice_edit_rows(realm)) > 0 THEN ARRAY['switch'] ELSE '{}'::text[] END || ARRAY['show', 'look', 'ask'] END $$;


--
-- Name: voice_look_answer(jsonb, integer, text, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_look_answer(asked jsonb, http integer, response text, model text, taken integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  r jsonb;
  t text;
  reply text;
  err text;
  status int := 200;
BEGIN
  BEGIN r := response::jsonb; EXCEPTION WHEN others THEN r := NULL; END;
  IF http = 200 AND r IS NOT NULL THEN
    SELECT string_agg(p->>'text', '') INTO t
    FROM jsonb_array_elements(coalesce(r->'candidates'->0->'content'->'parts', '[]')) p
    WHERE coalesce((p->>'thought')::boolean, false) = false AND p ? 'text';
    reply := verse.voice_edit_reply(jsonb_build_object('reply', coalesce(t, '')));
    IF reply = '' THEN status := 503; err := 'no answer'; END IF;
  ELSE
    status := 503;
    err := CASE WHEN http = 429 THEN 'busy' WHEN http = 0 THEN 'model unreachable' ELSE 'model error ' || http END;
  END IF;
  UPDATE verse.voice_edits SET edit = CASE WHEN err IS NULL THEN jsonb_build_object('edit', 'look', 'reply', reply) END,
    error = err, model = voice_look_answer.model, ms_taken = taken WHERE id = (asked->>'id')::bigint;
  IF err IS NOT NULL THEN RETURN jsonb_build_object('status', status, 'error', err); END IF;
  RETURN jsonb_build_object('status', 200, 'edit', 'chat', 'reply', reply, 'model', model);
END $$;


--
-- Name: voice_look_ask(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_look_ask(realm text, body jsonb, pubkey text, cap integer) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT replace(verse.worlds_answer(verse.voice_look_ask_0110(realm, body, pubkey, cap))::text, ', a realm in the Verse: a small 3D world drawn live', ', a world in the Verse: a small 3D scene drawn live')::jsonb $$;


--
-- Name: voice_look_ask_0110(text, jsonb, text, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_look_ask_0110(realm text, body jsonb, pubkey text, cap integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  question text := CASE WHEN jsonb_typeof(body) = 'object' THEN verse.npc_text(body->'question', 300) ELSE '' END;
  image text := CASE WHEN jsonb_typeof(body->'image') = 'string' THEN body->>'image' ELSE '' END;
  row_id bigint;
BEGIN
  IF NOT verse.voice_realm(realm) THEN RETURN '{"status":400,"error":"this realm takes no voice"}'; END IF;
  IF question = '' THEN RETURN '{"status":400,"error":"ask what to look at"}'; END IF;
  IF image = '' THEN RETURN '{"status":400,"error":"no picture"}'; END IF;
  IF length(image) > 700000 THEN RETURN '{"status":413,"error":"the picture is too large"}'; END IF;
  IF image !~ '^[A-Za-z0-9+/]+=*$' THEN RETURN '{"status":400,"error":"not a picture"}'; END IF;
  IF EXISTS (SELECT 1 FROM verse.voice_edits v WHERE v.pubkey = voice_look_ask_0110.pubkey AND v.ms > verse.now_ms() - 30000 AND v.ms_taken IS NULL) THEN
    RETURN '{"status":429,"error":"one at a time"}';
  END IF;
  IF (SELECT count(*) FROM verse.voice_edits WHERE ms > (extract(epoch FROM date_trunc('day', now())) * 1000)::bigint) >= cap THEN
    RETURN '{"status":503,"error":"the day''s voice edits are used up"}';
  END IF;
  INSERT INTO verse.voice_edits (ms, realm, pubkey, sentence) VALUES (verse.now_ms(), realm, pubkey, 'look: ' || question) RETURNING id INTO row_id;
  RETURN jsonb_build_object('status', 200, 'id', row_id, 'request', jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text',
      'The picture is the screen of someone in ' || verse.voice_realm_name(realm) || ', a realm in the Verse: a small 3D world drawn live in their browser, '
      || 'which they own and are building. Answer their question about what is on the screen the way a friendly builder looking over their '
      || 'shoulder would, out loud: one to three short plain sentences, no lists or markdown. Say what the thing most likely is (part of the '
      || 'scene, the sky, the water, the interface, or a drawing fault such as a gap, a seam, a band or a missing texture) and, when it looks '
      || 'like a fault, say so plainly. When you cannot tell, say what you can see and that you are not sure.'))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(
      jsonb_build_object('inlineData', jsonb_build_object('mimeType', 'image/jpeg', 'data', image)),
      jsonb_build_object('text', question)))),
    'generationConfig', jsonb_build_object('temperature', 0.2, 'maxOutputTokens', 400,
      'thinkingConfig', jsonb_build_object('thinkingBudget', 0))));
END $_$;


--
-- Name: voice_realm(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_realm(realm text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.voice_edit_catalogue(realm) IS NOT NULL OR EXISTS (SELECT 1 FROM verse.realm_rights WHERE slug = realm)
      OR EXISTS (SELECT 1 FROM verse.made_realms WHERE slug = realm) $$;


--
-- Name: voice_realm_name(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.voice_realm_name(realm text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce((SELECT name FROM verse.made_realms WHERE slug = realm), initcap(replace(realm, '-', ' '))) $$;


--
-- Name: world_outbox; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.world_outbox (
    seq bigint NOT NULL,
    event text NOT NULL,
    world text NOT NULL,
    lane text NOT NULL,
    rev bigint NOT NULL,
    body text NOT NULL,
    at_ms bigint NOT NULL,
    CONSTRAINT world_outbox_at_ms_check CHECK ((at_ms > 0)),
    CONSTRAINT world_outbox_lane_check CHECK ((lane = ANY (ARRAY['dev'::text, 'live'::text]))),
    CONSTRAINT world_outbox_rev_check CHECK ((rev >= 1))
);


--
-- Name: world_outbox_since(text, text, bigint, integer); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.world_outbox_since(w text, l text, after bigint, n integer) RETURNS SETOF verse.world_outbox
    LANGUAGE sql STABLE
    AS $$ SELECT * FROM verse.world_outbox WHERE world = w AND lane = l AND rev > after ORDER BY rev LIMIT least(greatest(n, 0), 500) $$;


--
-- Name: worlds_answer(jsonb); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.worlds_answer(r jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(r) = 'object' AND r ? 'error' THEN verse.worlds_text(r::text)::jsonb ELSE r END $$;


--
-- Name: worlds_page(text, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.worlds_page(p text, origin text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(replace(replace(p, origin || '/realms/', origin || '/worlds/'), '"/realms/', '"/worlds/'),
                 'https://openagents.com/realms/', 'https://openagents.com/worlds/') $$;


--
-- Name: worlds_requalify(regprocedure, text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.worlds_requalify(f regprocedure, old text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  EXECUTE replace(pg_get_functiondef(f), old || '.', (SELECT proname FROM pg_proc WHERE oid = f) || '.');
END $$;


--
-- Name: worlds_text(text); Type: FUNCTION; Schema: verse; Owner: -
--

CREATE FUNCTION verse.worlds_text(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(t, '"not a realm"', '"not a world"'), '"this claim link isn''t for this realm"', '"this claim link isn''t for this world"'), '"nobody has claimed this realm yet"', '"nobody has claimed this world yet"'), '"nobody has claimed this realm"', '"nobody has claimed this world"'), '"no such realm"', '"no such world"'), '"the realm is full"', '"the world is full"'), '"this realm has lore for 40 characters"', '"this world has lore for 40 characters"'), '"this realm has 40 quests"', '"this world has 40 quests"'), '"that''s today''s realms"', '"that''s today''s worlds"'), '"only approved creators and admins change who sees a realm"', '"only approved creators and admins change who sees a world"'), '"that realm has no revisions"', '"that world has no revisions"'), '"this realm takes no voice edits"', '"this world takes no voice edits"'), '"this realm takes no voice"', '"this world takes no voice"'), '"this realm can''t be forked"', '"this world can''t be forked"') $$;


--
-- Name: agent_done(text, integer, text, integer); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.agent_done(pet_ text, http integer, answer text, took integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE body jsonb; txt text; d jsonb; why text; p villa.pets;
BEGIN
  IF http = 200 THEN
    BEGIN
      body := answer::jsonb;
      SELECT string_agg(x->>'text', '' ORDER BY i) INTO txt
      FROM jsonb_array_elements(body#>'{candidates,0,content,parts}') WITH ORDINALITY AS z(x, i)
      WHERE coalesce((x->>'thought')::bool, false) = false AND x ? 'text';
      d := txt::jsonb;
    EXCEPTION WHEN others THEN d := NULL;
    END;
    why := CASE WHEN jsonb_typeof(d) = 'object' THEN NULL ELSE 'we could not read the answer: try again' END;
  ELSE
    why := 'we could not reach the agent: try again';
  END IF;
  UPDATE villa.pets SET agent = CASE WHEN why IS NULL THEN 'ready' ELSE 'failed' END, agent_note = coalesce(why, ''),
    avatar = CASE WHEN why IS NULL THEN villa.avatar_fix(d) ELSE avatar END,
    species = CASE WHEN why IS NULL AND d->>'species' IN ('dog', 'cat', 'rabbit', 'fox', 'other') THEN d->>'species' ELSE species END,
    choices = CASE WHEN why IS NULL AND jsonb_typeof(d->'choices') = 'array' THEN
      (SELECT coalesce(jsonb_agg(jsonb_build_object('part', villa.clean(c->'part', 20), 'why', villa.clean(c->'why', 200))), '[]')
       FROM (SELECT c FROM jsonb_array_elements(d->'choices') c LIMIT 16) z) ELSE choices END,
    updated_ms = verse.now_ms()
  WHERE id = pet_ RETURNING * INTO p;
  RETURN villa.r(CASE WHEN why IS NULL THEN 200 ELSE 502 END, villa.owned(p));
END $$;


--
-- Name: agent_prompt(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.agent_prompt() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT 'You make a pet''s avatar for a gentle memorial garden. From what its owner wrote and the photos and video they shared, '
    || 'set the avatar''s build relative to a typical dog of medium size (1 is usual): size 0.4-1.8 (a chihuahua 0.45, a labrador 1.1, '
    || 'a great dane 1.6), legs 0.5-1.6, body 0.6-1.6 (a dachshund 1.5), girth 0.6-1.6, head 0.7-1.5, snout 0.4-1.6 (a pug 0.45, a '
    || 'greyhound 1.5), ears 0-1 (0 pricked up, 1 hanging down), ear_size 0.5-1.8, tail 0-1.8 (0 none), fluff 0.5-2 (the tail''s thickness). '
    || 'Coat and marks are linear RGB from 0 to 1; pattern is the marks'' layout. In choices, name each part you set and say in a short '
    || 'warm sentence what you saw that made you choose it, for its owner to read. Never guess a breed you cannot see; keep usual values then.' $$;


--
-- Name: pets; Type: TABLE; Schema: villa; Owner: -
--

CREATE TABLE villa.pets (
    id text NOT NULL,
    slug text NOT NULL,
    player text NOT NULL,
    name text DEFAULT ''::text NOT NULL,
    species text DEFAULT 'dog'::text NOT NULL,
    born text DEFAULT ''::text NOT NULL,
    died text DEFAULT ''::text NOT NULL,
    line text DEFAULT ''::text NOT NULL,
    story text DEFAULT ''::text NOT NULL,
    traits text DEFAULT ''::text NOT NULL,
    achievements text DEFAULT ''::text NOT NULL,
    avatar jsonb DEFAULT '{}'::jsonb NOT NULL,
    choices jsonb DEFAULT '[]'::jsonb NOT NULL,
    agent text DEFAULT 'none'::text NOT NULL,
    agent_note text DEFAULT ''::text NOT NULL,
    agent_ms bigint,
    plot integer,
    status text DEFAULT 'draft'::text NOT NULL,
    created_ms bigint NOT NULL,
    updated_ms bigint NOT NULL,
    emotes jsonb DEFAULT '[]'::jsonb NOT NULL,
    emote_ms bigint DEFAULT 0 NOT NULL,
    CONSTRAINT pets_agent_check CHECK ((agent = ANY (ARRAY['none'::text, 'reading'::text, 'ready'::text, 'failed'::text]))),
    CONSTRAINT pets_plot_check CHECK (((plot >= 0) AND (plot <= 63))),
    CONSTRAINT pets_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'placed'::text, 'removed'::text, 'held'::text])))
);


--
-- Name: agent_request(villa.pets, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.agent_request(p villa.pets, bucket text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text', villa.agent_prompt()))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts',
      jsonb_build_array(jsonb_build_object('text', 'Name: ' || p.name || E'\nSpecies: ' || p.species || E'\nAbout them: ' || p.story
        || E'\nTraits: ' || p.traits))
      || coalesce((SELECT jsonb_agg(jsonb_build_object('fileData', jsonb_build_object('mimeType', f.content_type,
                     'fileUri', 'gs://' || bucket || '/' || f.object)) ORDER BY f.created_ms)
                   FROM (SELECT * FROM villa.files WHERE pet = p.id AND status = 'kept' ORDER BY created_ms LIMIT 8) f), '[]'))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json', 'responseSchema', villa.agent_schema(),
      'temperature', 0.2, 'maxOutputTokens', 4096)) $$;


--
-- Name: agent_schema(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.agent_schema() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT '{"type":"object","properties":{
    "species":{"type":"string","enum":["dog","cat","rabbit","fox","other"]},
    "size":{"type":"number"},"legs":{"type":"number"},"body":{"type":"number"},"girth":{"type":"number"},"head":{"type":"number"},
    "snout":{"type":"number"},"ears":{"type":"number"},"ear_size":{"type":"number"},"tail":{"type":"number"},"fluff":{"type":"number"},
    "pattern":{"type":"string","enum":["plain","patches","points","stripes","socks"]},
    "coat":{"type":"array","items":{"type":"number"}},"marks":{"type":"array","items":{"type":"number"}},
    "choices":{"type":"array","items":{"type":"object","properties":{"part":{"type":"string"},"why":{"type":"string"}},"required":["part","why"]}}},
    "required":["species","size","legs","body","girth","head","snout","ears","ear_size","tail","fluff","pattern","coat","marks","choices"]}'::jsonb $$;


--
-- Name: api(text, text[], jsonb, text, text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.api(method text, parts text[], body jsonb, k text, prefix text, bucket text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
#variable_conflict use_column
DECLARE
  me verse.players := villa.player(k);
  p villa.pets;
  f villa.files;
  n int;
  name_ text; ext_ text; kind_ text; bytes_ bigint; said text;
  free int;
  head0 text := parts[1];
  objs jsonb;
BEGIN
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;

  -- Anyone: the garden's tombstones, and a memorial by its link.
  IF head0 = 'garden' AND method = 'GET' AND cardinality(parts) = 1 THEN
    RETURN villa.r(200, jsonb_build_object('pets', coalesce((SELECT jsonb_agg(jsonb_build_object('slug', slug, 'name', name, 'born', born,
      'died', died, 'line', line, 'plot', plot, 'avatar', avatar, 'mine', me.id IS NOT NULL AND player = me.id) ORDER BY plot)
      FROM villa.pets WHERE status = 'placed'), '[]')));
  END IF;
  IF head0 = 'memorial' AND cardinality(parts) BETWEEN 2 AND 3 THEN
    SELECT * INTO p FROM villa.pets WHERE slug = parts[2] AND status = 'placed';
    IF p.id IS NULL THEN RETURN villa.err(404, 'no memorial here'); END IF;
    IF cardinality(parts) = 2 AND method = 'GET' THEN
      RETURN villa.r(200, villa.public(p) || jsonb_build_object('mine', me.id IS NOT NULL AND p.player = me.id,
        'notes', villa.notes_of(p.id, me.id IS NOT NULL AND p.player = me.id)));
    END IF;
    IF parts[3] = 'notes' AND method = 'POST' THEN
      IF me.id IS NULL THEN RETURN villa.err(403, 'send a player key to leave a note'); END IF;
      said := villa.clean(body->'text', 600);
      IF said = '' THEN RETURN villa.err(400, 'write something first'); END IF;
      IF villa.linky(said) THEN RETURN villa.err(400, 'notes can''t carry links'); END IF;
      SELECT count(*) INTO n FROM villa.notes WHERE player = me.id AND created_ms > verse.now_ms() - 60000;
      IF n >= 3 THEN RETURN villa.err(429, 'a little slower'); END IF;
      INSERT INTO villa.notes (pet, player, name, text, created_ms) VALUES (p.id, me.id, villa.player_name(me), said, verse.now_ms());
      RETURN villa.r(200, jsonb_build_object('notes', villa.notes_of(p.id, p.player = me.id)));
    END IF;
    RETURN villa.err(404, 'unknown');
  END IF;

  IF head0 <> 'pets' THEN RETURN villa.err(404, 'unknown'); END IF;
  IF me.id IS NULL THEN RETURN villa.err(403, 'send a player key (POST /api/playtest/player)'); END IF;

  IF cardinality(parts) = 1 THEN
    IF method = 'GET' THEN
      RETURN villa.r(200, jsonb_build_object('pets', coalesce((SELECT jsonb_agg(villa.owned(x) ORDER BY x.created_ms)
        FROM villa.pets x WHERE x.player = me.id AND x.status <> 'removed'), '[]')));
    END IF;
    SELECT count(*) INTO n FROM villa.pets WHERE player = me.id AND status <> 'removed';
    IF n >= 6 THEN RETURN villa.err(409, 'six pets is the most for now'); END IF;
    INSERT INTO villa.pets (id, slug, player, name, species, created_ms, updated_ms, avatar)
    VALUES ('q-' || drops.hex16(), villa.new_slug(), me.id, villa.clean(body->'name', 40),
            CASE WHEN body->>'species' IN ('dog', 'cat', 'rabbit', 'fox', 'other') THEN body->>'species' ELSE 'dog' END,
            verse.now_ms(), verse.now_ms(), villa.avatar_fix('{}'))
    RETURNING * INTO p;
    RETURN villa.r(200, villa.owned(p));
  END IF;

  SELECT * INTO p FROM villa.pets WHERE id = parts[2] AND player = me.id AND status <> 'removed' FOR UPDATE;
  IF p.id IS NULL THEN RETURN villa.err(404, 'not found'); END IF;

  IF cardinality(parts) = 2 THEN
    IF method = 'GET' THEN RETURN villa.r(200, villa.owned(p) || jsonb_build_object('notes', villa.notes_of(p.id, true))); END IF;
    -- an edit: any of the text fields
    UPDATE villa.pets SET
      name = CASE WHEN body ? 'name' THEN villa.clean(body->'name', 40) ELSE name END,
      species = CASE WHEN body->>'species' IN ('dog', 'cat', 'rabbit', 'fox', 'other') THEN body->>'species' ELSE species END,
      born = CASE WHEN body ? 'born' THEN villa.clean(body->'born', 24) ELSE born END,
      died = CASE WHEN body ? 'died' THEN villa.clean(body->'died', 24) ELSE died END,
      line = CASE WHEN body ? 'line' THEN villa.clean(body->'line', 120) ELSE line END,
      story = CASE WHEN body ? 'story' THEN villa.clean(body->'story', 4000) ELSE story END,
      traits = CASE WHEN body ? 'traits' THEN villa.clean(body->'traits', 600) ELSE traits END,
      achievements = CASE WHEN body ? 'achievements' THEN villa.clean(body->'achievements', 600) ELSE achievements END,
      avatar = CASE WHEN jsonb_typeof(body->'avatar') = 'object' THEN villa.avatar_fix(avatar || body->'avatar') ELSE avatar END,
      updated_ms = verse.now_ms()
    WHERE id = p.id RETURNING * INTO p;
    RETURN villa.r(200, villa.owned(p));
  END IF;
  IF method <> 'POST' THEN RETURN villa.err(405, 'POST'); END IF;

  IF parts[3] = 'files' AND cardinality(parts) = 3 THEN
    SELECT count(*) INTO n FROM villa.files WHERE pet = p.id AND status IN ('waiting', 'uploading', 'kept');
    IF n >= 12 THEN RETURN villa.err(409, 'twelve files is the most for one pet'); END IF;
    name_ := villa.clean(body->'name', 120);
    ext_ := drops.ext(name_); kind_ := villa.kind(ext_);
    IF kind_ IS NULL THEN RETURN villa.err(415, 'photos (jpg, png, webp, gif, heic) or short videos (mp4, mov, webm) only'); END IF;
    bytes_ := CASE WHEN jsonb_typeof(body->'bytes') = 'number' THEN (body->>'bytes')::numeric::bigint ELSE 0 END;
    IF bytes_ <= 0 THEN RETURN villa.err(400, 'it is empty'); END IF;
    IF bytes_ > (CASE kind_ WHEN 'image' THEN 16777216 ELSE 67108864 END) THEN
      RETURN villa.err(413, CASE kind_ WHEN 'image' THEN 'a photo can be at most 16 MB' ELSE 'a video can be at most 64 MB' END);
    END IF;
    INSERT INTO villa.files (id, pet, name, ext, kind, bytes, content_type, object, created_ms)
    VALUES ('g-' || drops.hex16(), p.id, name_, ext_, kind_, bytes_, villa.type(ext_), '', verse.now_ms()) RETURNING * INTO f;
    UPDATE villa.files SET object = prefix || '/villa/' || p.id || '/' || f.id || '.' || ext_, status = 'uploading'
    WHERE id = f.id RETURNING * INTO f;
    RETURN villa.r(200, jsonb_build_object('file', f.id)) || jsonb_build_object('open', jsonb_build_object('object', f.object,
      'type', f.content_type, 'bytes', f.bytes, 'file', f.id));
  END IF;
  IF parts[3] = 'files' AND cardinality(parts) = 5 THEN
    SELECT * INTO f FROM villa.files WHERE id = parts[4] AND pet = p.id AND status <> 'deleted';
    IF f.id IS NULL THEN RETURN villa.err(404, 'not found'); END IF;
    IF parts[5] = 'done' THEN
      RETURN villa.r(200, '{}') || jsonb_build_object('scan', jsonb_build_object('object', f.object, 'file', f.id));
    END IF;
    IF parts[5] = 'delete' THEN
      UPDATE villa.files SET status = 'deleted' WHERE id = f.id;
      RETURN villa.r(200, villa.owned(p)) || jsonb_build_object('delete', jsonb_build_array(f.object));
    END IF;
    RETURN villa.err(404, 'unknown');
  END IF;
  IF parts[3] = 'agent' THEN
    IF p.agent = 'reading' AND p.agent_ms > verse.now_ms() - 180000 THEN RETURN villa.err(409, 'already reading'); END IF;
    IF p.story = '' AND p.traits = '' AND NOT EXISTS (SELECT 1 FROM villa.files WHERE pet = p.id AND status = 'kept') THEN
      RETURN villa.err(409, 'tell us about them, or add a photo, first');
    END IF;
    UPDATE villa.pets SET agent = 'reading', agent_note = '', agent_ms = verse.now_ms() WHERE id = p.id;
    RETURN villa.r(200, '{}') || jsonb_build_object('request', villa.agent_request(p, bucket), 'pet', p.id);
  END IF;
  IF parts[3] = 'place' THEN   -- PLAY: the tombstone takes a plot
    IF p.name = '' THEN RETURN villa.err(409, 'give them a name first'); END IF;
    IF p.plot IS NULL THEN
      PERFORM pg_advisory_xact_lock(7731029);
      -- the plots in the garden's order, skipping the four old stones (villa.coax OLD_STONES)
      SELECT g INTO free FROM generate_series(0, 63) g
      WHERE g NOT IN (0, 7, 59, 60) AND NOT EXISTS (SELECT 1 FROM villa.pets WHERE plot = g)
      ORDER BY (CASE WHEN jsonb_typeof(body->'near') = 'number' THEN abs(g - (body->>'near')::int) ELSE 0 END), g LIMIT 1;
      IF free IS NULL THEN RETURN villa.err(409, 'the garden is full for now'); END IF;
    ELSE free := p.plot;
    END IF;
    UPDATE villa.pets SET plot = free, status = 'placed', updated_ms = verse.now_ms() WHERE id = p.id RETURNING * INTO p;
    RETURN villa.r(200, villa.owned(p));
  END IF;
  IF parts[3] = 'remove' THEN   -- the pet, its tombstone and its files, gone
    SELECT coalesce(jsonb_agg(object), '[]') INTO objs FROM villa.files WHERE pet = p.id AND status IN ('uploading', 'kept');
    UPDATE villa.files SET status = 'deleted' WHERE pet = p.id;
    UPDATE villa.pets SET status = 'removed', plot = NULL, story = '', traits = '', achievements = '', updated_ms = verse.now_ms() WHERE id = p.id;
    DELETE FROM villa.notes WHERE pet = p.id;
    RETURN villa.r(200, '{"removed":true}') || jsonb_build_object('delete', objs);
  END IF;
  IF parts[3] = 'notes' AND cardinality(parts) = 5 AND parts[5] IN ('hide', 'show') AND parts[4] ~ '^[0-9]{1,18}$' THEN
    UPDATE villa.notes SET hidden = parts[5] = 'hide' WHERE id = parts[4]::bigint AND pet = p.id;
    RETURN villa.r(200, jsonb_build_object('notes', villa.notes_of(p.id, true)));
  END IF;
  RETURN villa.err(404, 'unknown');
END $_$;


--
-- Name: avatar_fix(jsonb); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.avatar_fix(a jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE out jsonb := '{}'; k text; lo real; hi real; d real; v real; c jsonb;
BEGIN
  IF jsonb_typeof(a) <> 'object' THEN a := '{}'; END IF;
  FOR k, lo, hi, d IN SELECT * FROM (VALUES ('size', 0.4, 1.8, 1), ('legs', 0.5, 1.6, 1), ('body', 0.6, 1.6, 1), ('girth', 0.6, 1.6, 1),
      ('head', 0.7, 1.5, 1), ('snout', 0.4, 1.6, 1), ('ears', 0, 1, 0), ('ear_size', 0.5, 1.8, 1), ('tail', 0, 1.8, 1), ('fluff', 0.5, 2, 1),
      ('chest', 0, 1, 0)) t LOOP
    v := CASE WHEN jsonb_typeof(a->k) = 'number' THEN (a->>k)::real ELSE d END;
    out := out || jsonb_build_object(k, round(greatest(lo, least(hi, v))::numeric, 3));
  END LOOP;
  out := out || jsonb_build_object('pattern', CASE WHEN a->>'pattern' IN ('plain', 'patches', 'points', 'stripes', 'socks',
      'spots', 'saddle', 'mask', 'blaze') THEN a->>'pattern' ELSE 'plain' END);
  out := out || jsonb_build_object('tail_shape', CASE WHEN a->>'tail_shape' IN ('straight', 'plume', 'curl') THEN a->>'tail_shape' ELSE 'straight' END);
  out := out || jsonb_build_object('collar', CASE WHEN a->>'collar' IN ('none', 'red', 'blue', 'green', 'purple', 'black', 'white') THEN a->>'collar' ELSE 'none' END);
  out := out || jsonb_build_object('tag', coalesce(jsonb_typeof(a->'tag') = 'boolean' AND (a->>'tag')::boolean, false));
  FOREACH k IN ARRAY ARRAY['coat', 'marks'] LOOP
    c := a->k;
    IF jsonb_typeof(c) = 'array' AND jsonb_array_length(c) = 3 AND (SELECT bool_and(jsonb_typeof(x) = 'number') FROM jsonb_array_elements(c) x) THEN
      out := out || jsonb_build_object(k, (SELECT jsonb_agg(round(greatest(0, least(1, (x #>> '{}')::real))::numeric, 3)) FROM jsonb_array_elements(c) x));
    ELSE
      out := out || jsonb_build_object(k, CASE k WHEN 'coat' THEN '[0.55, 0.36, 0.2]'::jsonb ELSE '[0.92, 0.88, 0.82]'::jsonb END);
    END IF;
  END LOOP;
  out := out || jsonb_build_object('skills', coalesce((SELECT jsonb_agg(DISTINCT x #>> '{}') FROM jsonb_array_elements(
    CASE WHEN jsonb_typeof(a->'skills') = 'array' THEN a->'skills' ELSE '["fetch", "obedience", "digging"]' END) x
    WHERE x #>> '{}' IN ('fetch', 'obedience', 'digging')), '[]'));
  RETURN out;
END $$;


--
-- Name: chat_room(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.chat_room() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 'hecates-cemetery' $$;


--
-- Name: clean(jsonb, integer); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.clean(v jsonb, n integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(btrim(regexp_replace(CASE WHEN jsonb_typeof(v) = 'string' THEN v #>> '{}' ELSE '' END,
                                   '[\x00-\x09\x0b-\x1f\x7f]+', ' ', 'g')), n) $$;


--
-- Name: emote_api(text, text[], jsonb, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.emote_api(method text, parts text[], body jsonb, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE me verse.players := villa.player(k); p villa.pets; said text; nm text; t text; lb text;
BEGIN
  IF method <> 'POST' THEN RETURN villa.err(405, 'POST'); END IF;
  IF me.id IS NULL THEN RETURN villa.err(403, 'send a player key (POST /api/playtest/player)'); END IF;
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;
  SELECT * INTO p FROM villa.pets WHERE id = parts[2] AND player = me.id AND status <> 'removed' FOR UPDATE;
  IF p.id IS NULL THEN RETURN villa.err(404, 'no such pet'); END IF;
  IF cardinality(parts) = 3 THEN
    said := villa.clean(body->'said', 300);
    IF said = '' THEN RETURN villa.err(400, 'tell us what they used to do'); END IF;
    IF p.emote_ms > verse.now_ms() - 4000 THEN RETURN villa.err(429, 'a little slower'); END IF;
    UPDATE villa.pets SET emote_ms = verse.now_ms() WHERE id = p.id;
    RETURN villa.r(200, '{}') || jsonb_build_object('pet', p.id, 'done', 'emote',
      'request', villa.emote_request(p, said, villa.clean(body->'error', 300), left(coalesce(body->>'last', ''), 3000)));
  END IF;
  IF cardinality(parts) = 4 AND parts[4] = 'keep' THEN
    nm := body->>'name'; t := body->>'text'; lb := upper(villa.clean(body->'label', 16));
    IF nm IS NULL OR nm !~ '^[a-z0-9_]{1,24}$' OR t IS NULL OR length(t) > 3000 OR lb = '' THEN RETURN villa.err(400, 'that motion isn''t whole'); END IF;
    UPDATE villa.pets SET emotes = (
      SELECT coalesce(jsonb_agg(e ORDER BY o), '[]') FROM (
        SELECT e, o FROM jsonb_array_elements(p.emotes) WITH ORDINALITY AS z(e, o) WHERE e->>'name' <> nm
        UNION ALL SELECT jsonb_build_object('name', nm, 'label', lb, 'text', t, 'said', villa.clean(body->'said', 300)), 1000
      ) w WHERE o > (SELECT greatest(0, jsonb_array_length(p.emotes) - 7)) OR o = 1000), updated_ms = verse.now_ms()
    WHERE id = p.id RETURNING * INTO p;
    RETURN villa.r(200, villa.owned(p));
  END IF;
  IF cardinality(parts) = 5 AND parts[5] = 'delete' THEN
    UPDATE villa.pets SET emotes = coalesce((SELECT jsonb_agg(e ORDER BY o) FROM jsonb_array_elements(p.emotes) WITH ORDINALITY AS z(e, o)
      WHERE e->>'name' <> parts[4]), '[]'), updated_ms = verse.now_ms() WHERE id = p.id RETURNING * INTO p;
    RETURN villa.r(200, villa.owned(p));
  END IF;
  RETURN villa.err(404, 'unknown');
END $_$;


--
-- Name: emote_done(text, integer, text, integer); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.emote_done(pet_ text, http integer, answer text, took integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE txt text; d jsonb;
BEGIN
  IF http <> 200 THEN RETURN villa.err(502, 'we could not reach the agent: try again'); END IF;
  BEGIN
    SELECT string_agg(x->>'text', '' ORDER BY i) INTO txt
    FROM jsonb_array_elements(answer::jsonb#>'{candidates,0,content,parts}') WITH ORDINALITY AS z(x, i)
    WHERE coalesce((x->>'thought')::bool, false) = false AND x ? 'text';
    d := txt::jsonb;
  EXCEPTION WHEN others THEN d := NULL;
  END;
  IF jsonb_typeof(d) <> 'object' OR jsonb_typeof(d->'text') <> 'string' THEN RETURN villa.err(502, 'we could not read the answer: try again'); END IF;
  RETURN villa.r(200, jsonb_build_object('motion', jsonb_build_object(
    'name', left(regexp_replace(lower(coalesce(d->>'name', 'move')), '[^a-z0-9_]', '_', 'g'), 24),
    'label', upper(left(villa.clean(d->'label', 16), 16)),
    'text', left(regexp_replace(d->>'text', '[\x00-\x09\x0b-\x1f]', ' ', 'g'), 3000))));
END $$;


--
-- Name: emote_prompt(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.emote_prompt() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT 'You write one short animation ("motion") for a pet''s avatar in a gentle memorial garden, from what its owner says it '
    || 'used to do. Answer name (a-z, 0-9, _ only, at most 24, a word for the move), label (one or two words in capitals for its '
    || E'button) and text: the motion, statements separated by "; ". The format:\n'
    || E'motion NAME; rig animal; seconds S (0.1 to 30); once | loop | hold (after the last key: fade out, repeat, keep the pose); '
    || E'fade F (0 to 2); still (only if the pet stops walking to do it); then keys: at T (seconds from the start, each later than '
    || E'the last); under each key, JOINT PITCH YAW ROLL in degrees, and lift X Y Z in metres for the whole body.\n'
    || E'Joints and their ranges (pitch, yaw, roll): pelvis -180..180 for each; spine and chest -40..40, -40..40, -30..30; neck -70..80, -80..80, -40..40; '
    || E'head -60..60, -60..60, -45..45; left_ear and right_ear -70..70, -60..60, -70..70; tail, tail_2, tail_3 -80..100, -80..80, -40..40; '
    || E'front_left_shoulder and front_right_shoulder -130..80, -25..25, -40..40; front_*_elbow -10..150, -10..10, -10..10; '
    || E'front_*_wrist -40..130, -10..10, -10..10; front_*_paw and hind_*_paw -80..80, -20..20, -20..20; '
    || E'hind_left_hip and hind_right_hip -110..80, -25..25, -40..40; hind_*_knee -30..130, -10..10, -10..10; '
    || E'hind_*_hock -130..40, -10..10, -10..10. Never turn nose, ear tips, tail_tip, toes or eyes. Turning the whole body round is pelvis 0 YAW 0, '
    || E'YAW from -180 to 180 and never past it: a full spin is a key with pelvis 0 -180 0 and a later one with pelvis 0 180 0; '
    || E'to go round again, add a key 0.001 seconds after the 180 one with pelvis 0 -180 0 and turn on from there. Keep it under 6 seconds, gentle and true to what was said. Examples:\n'
    || E'motion sit; rig animal; seconds 1.2; hold; still; fade 0.5; at 1.2; pelvis -32 0 0; lift 0 -0.1 0; front_left_shoulder 32 0 0; front_right_shoulder 32 0 0; hind_left_hip -75 0 0; hind_right_hip -75 0 0; hind_left_knee 125 0 0; hind_right_knee 125 0 0; hind_left_hock -110 0 0; hind_right_hock -110 0 0; neck -5 0 0; head 15 0 0; tail 60 0 0\n'
    || E'motion wag; rig animal; seconds 0.5; loop; fade 0.3; at 0; tail -60 45 0; tail_2 0 25 0; pelvis 0 4 0; at 0.25; tail -60 -45 0; tail_2 0 -25 0; pelvis 0 -4 0\n'
    || E'motion play_bow; rig animal; seconds 2.4; once; still; fade 0.35; at 0.5; pelvis 22 0 0; lift 0 -0.02 0; front_left_shoulder -85 0 0; front_right_shoulder -85 0 0; front_left_elbow 15 0 0; front_right_elbow 15 0 0; neck -40 0 0; head -10 0 0; tail -70 40 0; at 1.1; tail -70 -40 0; at 2.4; pelvis 0 0 0; lift 0 0 0; tail -50 0 0\n'
    || 'If you are told your last motion was refused and why, write it again fixing exactly that.' $$;


--
-- Name: emote_request(villa.pets, text, text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.emote_request(p villa.pets, said text, err text, last text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'systemInstruction', jsonb_build_object('parts', jsonb_build_array(jsonb_build_object('text', villa.emote_prompt()))),
    'contents', jsonb_build_array(jsonb_build_object('role', 'user', 'parts', jsonb_build_array(jsonb_build_object('text',
      'The pet: ' || p.name || ', a ' || p.species || E'.\nWhat they used to do: ' || said
      || CASE WHEN err <> '' THEN E'\nYour last motion was refused: ' || err || E'\nIt was: ' || last ELSE '' END)))),
    'generationConfig', jsonb_build_object('responseMimeType', 'application/json',
      'responseSchema', '{"type":"object","properties":{"name":{"type":"string"},"label":{"type":"string"},"text":{"type":"string"}},"required":["name","label","text"]}'::jsonb,
      'temperature', 0.4, 'maxOutputTokens', 8192,
      'thinkingConfig', jsonb_build_object('thinkingLevel', 'LOW'))) $$;


--
-- Name: err(integer, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.err(status integer, why text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT villa.r(status, jsonb_build_object('error', why)) $$;


--
-- Name: field_cap(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.field_cap(f text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE f WHEN 'name' THEN 40 WHEN 'species' THEN 20 WHEN 'born' THEN 24 WHEN 'died' THEN 24 WHEN 'line' THEN 120
    WHEN 'story' THEN 4000 WHEN 'traits' THEN 600 WHEN 'achievements' THEN 600 END $$;


--
-- Name: held_text(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.held_text() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 'This line is waiting to be looked at' $$;


--
-- Name: keep_held(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.keep_held() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status = 'held' AND NEW.status <> 'removed' AND coalesce(current_setting('villa.restoring', true), '') <> 'on' THEN
    NEW.status := 'held';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: kind(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.kind(ext text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN ext IN ('jpg', 'jpeg', 'png', 'webp', 'gif', 'heic') THEN 'image'
              WHEN ext IN ('mp4', 'mov', 'webm') THEN 'video' END $$;


--
-- Name: linky(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.linky(t text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT t ~* '(https?://|www\.|[a-z0-9-]+\.(com|net|org|io|ru|xyz|top|link|ly|gg|me)\b)' $$;


--
-- Name: media_api(text, text[], text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.media_api(method text, parts text[], k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE me verse.players := villa.player(k); p villa.pets; f villa.files; n int;
BEGIN
  IF parts[1] = 'memorial' AND cardinality(parts) = 4 AND parts[3] = 'media' THEN
    IF method <> 'GET' THEN RETURN villa.err(405, 'GET'); END IF;
    SELECT f2.* INTO f FROM villa.files f2 JOIN villa.pets p2 ON p2.id = f2.pet
    WHERE p2.slug = parts[2] AND p2.status = 'placed' AND parts[4] ~ '^[0-9a-f]{16}$' AND f2.id = 'g-' || parts[4]
      AND f2.status = 'kept' AND f2.shown AND NOT f2.held;
    IF f.id IS NULL THEN RETURN villa.err(404, 'not here'); END IF;
    RETURN villa.r(200, '{}') || jsonb_build_object('stream', jsonb_build_object('object', f.object, 'type', f.content_type, 'bytes', f.bytes));
  END IF;
  IF parts[1] = 'pets' AND cardinality(parts) = 5 AND parts[3] = 'files' AND parts[5] IN ('show', 'unshow') THEN
    IF method <> 'POST' THEN RETURN villa.err(405, 'POST'); END IF;
    IF me.id IS NULL THEN RETURN villa.err(403, 'send a player key (POST /api/playtest/player)'); END IF;
    SELECT * INTO p FROM villa.pets WHERE id = parts[2] AND player = me.id AND status <> 'removed';
    IF p.id IS NULL THEN RETURN villa.err(404, 'not found'); END IF;
    UPDATE villa.files SET shown = parts[5] = 'show' WHERE id = parts[4] AND pet = p.id AND status = 'kept';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n = 0 THEN RETURN villa.err(404, 'that file isn''t kept'); END IF;
    RETURN villa.r(200, villa.owned(p));
  END IF;
  RETURN villa.err(404, 'unknown');
END $_$;


--
-- Name: media_of(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.media_of(pet_ text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', substr(f.id, 3), 'kind', f.kind) ORDER BY f.created_ms), '[]')
  FROM (SELECT * FROM villa.files WHERE pet = pet_ AND status = 'kept' AND shown AND NOT held ORDER BY created_ms LIMIT 6) f $$;


--
-- Name: new_slug(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.new_slug() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE s text;
BEGIN
  LOOP
    s := left(replace(gen_random_uuid()::text, '-', ''), 8);
    IF NOT EXISTS (SELECT 1 FROM villa.pets WHERE slug = s) THEN RETURN s; END IF;
  END LOOP;
END $$;


--
-- Name: notes_of(text, boolean); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.notes_of(pet_ text, owner boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('n', n.id, 'name', n.name, 'text', n.text, 'hidden', n.hidden) ORDER BY n.created_ms), '[]')
  FROM villa.notes n WHERE n.pet = pet_ AND NOT n.held AND (owner OR NOT n.hidden) $$;


--
-- Name: owned(villa.pets); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.owned(p villa.pets) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT villa.public(p) || jsonb_build_object('id', p.id, 'status', p.status, 'choices', p.choices, 'agent', p.agent,
    'agent_note', p.agent_note, 'emotes', p.emotes,
    'files', coalesce((SELECT jsonb_agg(jsonb_build_object('id', f.id, 'name', f.name, 'kind', f.kind, 'bytes', f.bytes,
                         'status', f.status, 'note', f.note, 'shown', f.shown, 'held', f.held) ORDER BY f.created_ms)
                       FROM villa.files f WHERE f.pet = p.id AND f.status <> 'deleted'), '[]')) $$;


--
-- Name: player(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.player(k text) RETURNS verse.players
    LANGUAGE sql STABLE
    AS $_$
  SELECT * FROM verse.players WHERE k ~ '^[A-Za-z0-9_-]{20,128}$' AND key_sha256 = encode(sha256(convert_to(k, 'UTF8')), 'hex') $_$;


--
-- Name: player_name(verse.players); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.player_name(p verse.players) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT verse.player_name(p.id) $$;


--
-- Name: public(villa.pets); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.public(p villa.pets) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('slug', p.slug, 'name', p.name, 'species', p.species, 'born', p.born, 'died', p.died, 'line', p.line,
    'story', p.story, 'traits', p.traits, 'achievements', p.achievements, 'avatar', p.avatar, 'plot', p.plot,
    'media', villa.media_of(p.id)) $$;


--
-- Name: r(integer, jsonb); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.r(status integer, body jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT jsonb_build_object('status', status, 'body', body) $$;


--
-- Name: removed_text(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.removed_text() RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 'This line was removed' $$;


--
-- Name: report_hide(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_hide(kind_ text, ref_ text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF kind_ <> 'player' THEN RETURN villa.report_hide_0034(kind_, ref_); END IF;
  IF ref_ !~ '^[0-9a-f]{16}$' OR NOT EXISTS (SELECT 1 FROM verse.players WHERE id = 'p-' || ref_) THEN RETURN false; END IF;
  INSERT INTO verse.room_kicks (player, by_who, until_ms, at_ms) VALUES ('p-' || ref_, 'report', verse.now_ms() + 86400000, verse.now_ms())
  ON CONFLICT (player) DO UPDATE SET by_who = 'report', until_ms = EXCLUDED.until_ms, at_ms = EXCLUDED.at_ms;
  INSERT INTO verse.mod_log (at_ms, by_who, verb, whom, who, minutes, until_ms, reason, source, outcome, team)
  SELECT verse.now_ms(), 'report', 'kick', p.id, coalesce(p.account, p.id), 0, verse.now_ms() + 86400000, 'a report hidden', 'report', 'ok',
         EXISTS (SELECT 1 FROM analytics.team t WHERE t.kind = 'player' AND t.value = p.id)
  FROM verse.players p WHERE p.id = 'p-' || ref_;
  RETURN true;
END $_$;


--
-- Name: report_hide_0034(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_hide_0034(kind_ text, ref_ text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
DECLARE n int;
BEGIN
  IF kind_ = 'memorial' THEN
    UPDATE villa.pets SET status = 'held', updated_ms = verse.now_ms() WHERE slug = ref_ AND status IN ('placed', 'held');
  ELSIF kind_ = 'note' THEN
    UPDATE villa.notes SET held = true WHERE ref_ ~ '^[0-9]{1,18}$' AND id = ref_::bigint;
  ELSIF kind_ = 'chat' THEN
    UPDATE verse.room_chat SET text = villa.removed_text() WHERE room = villa.chat_room() AND ref_ ~ '^[0-9]{1,9}$' AND room_chat.n = ref_::int;
  ELSIF kind_ = 'file' THEN
    UPDATE villa.files SET held = true WHERE ref_ ~ '^[0-9a-f]{16}$' AND id = 'g-' || ref_ AND status <> 'deleted';
  ELSE RETURN false;
  END IF;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n > 0;
END $_$;


--
-- Name: report_keep(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_keep(kind_ text, ref_ text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF kind_ = 'note' THEN UPDATE villa.notes SET hidden = false WHERE ref_ ~ '^[0-9]{1,18}$' AND id = ref_::bigint AND NOT held; END IF;
  IF kind_ = 'chat' THEN
    UPDATE verse.room_chat c SET text = substr(r.shown, length(c.name) + 3)
    FROM (SELECT shown FROM villa.reports WHERE kind = 'chat' AND ref = ref_ ORDER BY at_ms LIMIT 1) r
    WHERE c.room = villa.chat_room() AND ref_ ~ '^[0-9]{1,9}$' AND c.n = ref_::int AND c.text = villa.held_text();
  END IF;
END $_$;


--
-- Name: report_kinds(); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_kinds() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT ARRAY['memorial', 'note', 'chat', 'file', 'player'] $$;


--
-- Name: report_last(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_last(kind_ text, ref_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT status FROM villa.reports WHERE kind = kind_ AND ref = ref_ AND status <> 'open' ORDER BY decided_ms DESC, id DESC LIMIT 1 $$;


--
-- Name: report_restore(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_restore(kind_ text, ref_ text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
DECLARE n int;
BEGIN
  IF kind_ <> 'player' THEN RETURN villa.report_restore_0034(kind_, ref_); END IF;
  DELETE FROM verse.room_kicks WHERE ref_ ~ '^[0-9a-f]{16}$' AND player = 'p-' || ref_;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    INSERT INTO verse.mod_log (at_ms, by_who, verb, whom, who, minutes, until_ms, reason, source, outcome, team)
    SELECT verse.now_ms(), 'report', 'unkick', p.id, coalesce(p.account, p.id), 0, 0, 'a report restored', 'report', 'ok',
           EXISTS (SELECT 1 FROM analytics.team t WHERE t.kind = 'player' AND t.value = p.id)
    FROM verse.players p WHERE p.id = 'p-' || ref_;
  END IF;
  RETURN n > 0;
END $_$;


--
-- Name: report_restore_0034(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_restore_0034(kind_ text, ref_ text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
DECLARE n int;
BEGIN
  IF kind_ = 'memorial' THEN
    PERFORM set_config('villa.restoring', 'on', true);
    UPDATE villa.pets SET status = 'placed', updated_ms = verse.now_ms() WHERE slug = ref_ AND status = 'held';
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM set_config('villa.restoring', '', true);
  ELSIF kind_ = 'note' THEN
    UPDATE villa.notes SET held = false, hidden = false WHERE ref_ ~ '^[0-9]{1,18}$' AND id = ref_::bigint;
    GET DIAGNOSTICS n = ROW_COUNT;
  ELSIF kind_ = 'chat' THEN
    UPDATE verse.room_chat c SET text = substr(r.shown, length(c.name) + 3)
    FROM (SELECT shown FROM villa.reports WHERE kind = 'chat' AND ref = ref_ ORDER BY at_ms LIMIT 1) r
    WHERE c.room = villa.chat_room() AND ref_ ~ '^[0-9]{1,9}$' AND c.n = ref_::int AND c.text IN (villa.removed_text(), villa.held_text());
    GET DIAGNOSTICS n = ROW_COUNT;
  ELSIF kind_ = 'file' THEN
    UPDATE villa.files SET held = false WHERE ref_ ~ '^[0-9a-f]{16}$' AND id = 'g-' || ref_ AND status = 'kept';
    GET DIAGNOSTICS n = ROW_COUNT;
  ELSE RETURN false;
  END IF;
  RETURN n > 0;
END $_$;


--
-- Name: report_shown(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_shown(kind_ text, ref_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT CASE WHEN kind_ = 'player' THEN coalesce((
      SELECT 'An Everglade player, p-' || ref_ || coalesce(' (' || nullif(a.name, '') || ')', '')
      FROM verse.players p LEFT JOIN verse.accounts a ON a.id = p.account WHERE ref_ ~ '^[0-9a-f]{16}$' AND p.id = 'p-' || ref_), '')
    ELSE villa.report_shown_0034(kind_, ref_) END $_$;


--
-- Name: report_shown_0034(text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.report_shown_0034(kind_ text, ref_ text) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT coalesce(CASE kind_
    WHEN 'memorial' THEN (SELECT left(concat_ws(' · ', name, line, story, traits, achievements), 2000) FROM villa.pets WHERE slug = ref_ AND status = 'placed')
    WHEN 'note' THEN (SELECT name || ': ' || text FROM villa.notes WHERE ref_ ~ '^[0-9]{1,18}$' AND id = ref_::bigint)
    WHEN 'chat' THEN (SELECT name || ': ' || text FROM verse.room_chat WHERE room = villa.chat_room() AND ref_ ~ '^[0-9]{1,9}$' AND n = ref_::int)
    WHEN 'file' THEN (SELECT 'A ' || CASE f.kind WHEN 'video' THEN 'video' ELSE 'photo' END || ' on ' || p.name || '''s memorial (/api/villa/memorial/'
                             || p.slug || '/media/' || ref_ || '): ' || f.name
                      FROM villa.files f JOIN villa.pets p ON p.id = f.pet
                      WHERE ref_ ~ '^[0-9a-f]{16}$' AND f.id = 'g-' || ref_ AND f.status = 'kept' AND f.shown AND NOT f.held AND p.status = 'placed')
  END, '') $_$;


--
-- Name: reports_api(text, text[], jsonb, text, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.reports_api(method text, parts text[], body jsonb, k text, admin text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE me verse.players := villa.player(k); kind_ text; ref_ text; shown_ text; cnt int; by_ int; act text; open_ bool;
BEGIN
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;
  -- a visitor reports
  IF parts[1] = 'report' AND cardinality(parts) = 1 THEN
    IF method <> 'POST' THEN RETURN villa.err(405, 'POST'); END IF;
    IF me.id IS NULL THEN RETURN villa.err(403, 'send a player key (POST /api/playtest/player)'); END IF;
    kind_ := body->>'kind'; ref_ := body->>'ref';
    IF kind_ IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(villa.report_kinds()) x WHERE x = kind_) OR ref_ IS NULL OR ref_ !~ '^[A-Za-z0-9]{1,18}$' THEN
      RETURN villa.err(400, 'what is it?');
    END IF;
    shown_ := villa.report_shown(kind_, ref_);
    IF shown_ = '' THEN RETURN villa.err(404, 'it isn''t there any more'); END IF;
    SELECT count(*) INTO cnt FROM villa.reports WHERE player = me.id AND at_ms > verse.now_ms() - 3600000;
    IF cnt >= 20 THEN RETURN villa.err(429, 'a little slower'); END IF;
    INSERT INTO villa.reports (kind, ref, player, why, shown, at_ms) VALUES (kind_, ref_, me.id, villa.clean(body->'why', 300), shown_, verse.now_ms())
    ON CONFLICT (kind, ref, player) WHERE status = 'open' DO NOTHING;
    SELECT count(*) INTO by_ FROM villa.reports WHERE kind = kind_ AND ref = ref_ AND status = 'open';
    IF by_ >= 3 AND kind_ = 'note' THEN UPDATE villa.notes SET hidden = true WHERE id = ref_::bigint; END IF;
    IF by_ >= 3 AND kind_ = 'chat' THEN UPDATE verse.room_chat SET text = villa.held_text() WHERE room = villa.chat_room() AND room_chat.n = ref_::int AND text <> villa.removed_text(); END IF;
    RETURN villa.r(200, '{"reported":true}');
  END IF;
  -- an admin
  IF parts[1] <> 'reports' THEN RETURN villa.err(404, 'unknown'); END IF;
  IF admin IS NULL OR admin = '' THEN RETURN villa.err(401, 'admins only'); END IF;
  IF cardinality(parts) = 1 AND method = 'GET' THEN
    RETURN villa.r(200, jsonb_build_object(
      'open', coalesce((
        SELECT jsonb_agg(jsonb_build_object('kind', r.kind, 'ref', r.ref, 'reports', r.c, 'first_ms', r.first_ms,
                 'shown', r.shown, 'why', r.whys) ORDER BY r.c DESC, r.first_ms)
        FROM (SELECT kind, ref, count(*) AS c, min(at_ms) AS first_ms, (array_agg(shown ORDER BY at_ms))[1] AS shown,
                     coalesce(jsonb_agg(why) FILTER (WHERE why <> ''), '[]') AS whys
              FROM villa.reports WHERE status = 'open' GROUP BY kind, ref) r), '[]'),
      -- the last forty decisions, newest first; restore: it was hidden, is still hidden, and nobody has reported it since
      'decided', coalesce((
        SELECT jsonb_agg(jsonb_build_object('kind', d.kind, 'ref', d.ref, 'decision', CASE d.status WHEN 'removed' THEN 'hidden' ELSE d.status END,
                 'reports', d.c, 'decided_ms', d.decided_ms, 'by', d.decided_by, 'shown', d.shown,
                 'restore', d.status = 'removed' AND villa.report_last(d.kind, d.ref) = 'removed'
                            AND NOT EXISTS (SELECT 1 FROM villa.reports o WHERE o.kind = d.kind AND o.ref = d.ref AND o.status = 'open'))
                 ORDER BY d.decided_ms DESC)
        FROM (SELECT kind, ref, status, decided_ms, min(decided_by) AS decided_by, count(*) AS c, (array_agg(shown ORDER BY at_ms))[1] AS shown
              FROM villa.reports WHERE status <> 'open' GROUP BY kind, ref, status, decided_ms ORDER BY decided_ms DESC LIMIT 40) d), '[]')));
  END IF;
  IF cardinality(parts) = 4 AND method = 'POST' AND parts[4] IN ('hide', 'remove', 'keep', 'restore') THEN
    kind_ := parts[2]; ref_ := parts[3]; act := CASE parts[4] WHEN 'remove' THEN 'hide' ELSE parts[4] END;
    open_ := EXISTS (SELECT 1 FROM villa.reports WHERE kind = kind_ AND ref = ref_ AND status = 'open');
    IF act = 'restore' THEN
      IF open_ OR villa.report_last(kind_, ref_) IS DISTINCT FROM 'removed' THEN RETURN villa.err(404, 'nothing hidden to restore'); END IF;
      IF NOT villa.report_restore(kind_, ref_) THEN RETURN villa.err(410, 'its owner has deleted it'); END IF;
      UPDATE villa.reports SET status = 'restored', decided_by = admin, decided_ms = verse.now_ms()
      WHERE id = (SELECT id FROM villa.reports WHERE kind = kind_ AND ref = ref_ AND status = 'removed' ORDER BY decided_ms DESC, id DESC LIMIT 1);
      RETURN villa.r(200, jsonb_build_object('decided', 'restore'));
    END IF;
    IF NOT open_ THEN RETURN villa.err(404, 'nothing open'); END IF;
    IF act = 'hide' THEN PERFORM villa.report_hide(kind_, ref_); ELSE PERFORM villa.report_keep(kind_, ref_); END IF;
    UPDATE villa.reports SET status = CASE act WHEN 'hide' THEN 'removed' ELSE 'kept' END, decided_by = admin, decided_ms = verse.now_ms()
    WHERE kind = kind_ AND ref = ref_ AND status = 'open';
    RETURN villa.r(200, jsonb_build_object('decided', act));
  END IF;
  RETURN villa.err(404, 'unknown');
END $_$;


--
-- Name: reports_rows(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.reports_rows(admin text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE q jsonb; t text; x jsonb;
BEGIN
  q := villa.reports_api('GET', ARRAY['reports'], '{}', NULL, admin)->'body';
  IF q ? 'error' THEN RETURN NULL; END IF;
  t := '#OPEN REPORTS|aw|KIND|WHICH|REPORTS|FIRST|WHAT IT SAYS|WHY' || chr(10);
  FOR x IN SELECT * FROM jsonb_array_elements(q->'open') LOOP
    t := t || concat_ws('|', x->>'kind', x->>'ref', x->>'reports',
      to_char(to_timestamp((x->>'first_ms')::bigint / 1000.0) AT TIME ZONE 'America/Chicago', 'MM-DD HH24:MI'),
      villa.row_value(x->>'shown'), villa.row_value((SELECT string_agg(w, '; ') FROM jsonb_array_elements_text(x->'why') w))) || chr(10);
  END LOOP;
  t := t || '#DECIDED|rw|KIND|WHICH|DECISION|WHEN|BY|WHAT IT SAID|RESTORE' || chr(10);
  FOR x IN SELECT * FROM jsonb_array_elements(q->'decided') LOOP
    t := t || concat_ws('|', x->>'kind', x->>'ref', upper(x->>'decision'),
      to_char(to_timestamp((x->>'decided_ms')::bigint / 1000.0) AT TIME ZONE 'America/Chicago', 'MM-DD HH24:MI'),
      left(coalesce(x->>'by', ''), 8), villa.row_value(x->>'shown'), CASE WHEN (x->>'restore')::bool THEN 'yes' ELSE '' END) || chr(10);
  END LOOP;
  RETURN t;
END $$;


--
-- Name: row_value(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.row_value(s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(regexp_replace(coalesce(s, ''), '[|\r\n\t]+', ' ', 'g'), 400) $$;


--
-- Name: scanned(text, bigint, bytea); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.scanned(file_ text, size bigint, head bytea) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE f villa.files; why text; p villa.pets;
BEGIN
  SELECT * INTO f FROM villa.files WHERE id = file_ FOR UPDATE;
  IF f.id IS NULL OR f.status = 'deleted' THEN RETURN villa.err(404, 'not found'); END IF;
  why := CASE WHEN size < 0 THEN 'it did not arrive' WHEN size <> f.bytes THEN 'it arrived cut short' ELSE villa.sniff(f.ext, head) END;
  UPDATE villa.files SET status = CASE WHEN why IS NULL THEN 'kept' ELSE 'refused' END, note = coalesce(why, '') WHERE id = f.id;
  SELECT * INTO p FROM villa.pets WHERE id = f.pet;
  RETURN villa.r(200, villa.owned(p)) || CASE WHEN why IS NOT NULL AND size >= 0 THEN jsonb_build_object('delete', jsonb_build_array(f.object)) ELSE '{}' END;
END $$;


--
-- Name: sniff(text, bytea); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.sniff(ext text, head bytea) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN ext = 'webm' THEN CASE WHEN drops.at(head, 0, '1a45dfa3') THEN NULL ELSE 'it is not a WebM video' END
              ELSE drops.sniff(ext, head) END $$;


--
-- Name: type(text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.type(ext text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE ext WHEN 'webm' THEN 'video/webm' ELSE drops.content_type(ext) END $$;


--
-- Name: vases; Type: TABLE; Schema: villa; Owner: -
--

CREATE TABLE villa.vases (
    id bigint NOT NULL,
    player text NOT NULL,
    x real NOT NULL,
    z real NOT NULL,
    yaw real DEFAULT 0 NOT NULL,
    flowers jsonb NOT NULL,
    plot integer,
    placed_ms bigint NOT NULL
);


--
-- Name: vase_json(villa.vases, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.vase_json(v villa.vases, me text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('n', v.id, 'x', v.x, 'z', v.z, 'yaw', v.yaw, 'flowers', v.flowers, 'plot', v.plot,
    'age', greatest(0, (verse.now_ms() - v.placed_ms) / 1000), 'mine', me IS NOT NULL AND v.player = me) $$;


--
-- Name: vases_api(text, text[], jsonb, text); Type: FUNCTION; Schema: villa; Owner: -
--

CREATE FUNCTION villa.vases_api(method text, parts text[], body jsonb, k text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE me verse.players := villa.player(k); n int; fl jsonb; v villa.vases;
BEGIN
  IF jsonb_typeof(body) IS DISTINCT FROM 'object' THEN body := '{}'; END IF;
  IF cardinality(parts) = 1 AND method = 'GET' THEN
    RETURN villa.r(200, jsonb_build_object('vases', coalesce((SELECT jsonb_agg(villa.vase_json(w, me.id) ORDER BY w.placed_ms)
      FROM villa.vases w WHERE w.id IN (SELECT id FROM villa.vases ORDER BY placed_ms DESC LIMIT 80)), '[]')));
  END IF;
  IF method <> 'POST' THEN RETURN villa.err(405, 'POST'); END IF;
  IF me.id IS NULL THEN RETURN villa.err(403, 'send a player key (POST /api/playtest/player)'); END IF;
  IF cardinality(parts) = 1 THEN
    SELECT count(*) INTO n FROM villa.vases WHERE player = me.id;
    IF n >= 3 THEN RETURN villa.err(409, 'three vases is the most: clean one up first'); END IF;
    IF EXISTS (SELECT 1 FROM villa.vases WHERE player = me.id AND placed_ms > verse.now_ms() - 60000) THEN RETURN villa.err(429, 'a little slower'); END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('kind', (f->>'kind')::int, 'slot', (f->>'slot')::int)), '[]') INTO fl
    FROM (SELECT f FROM jsonb_array_elements(CASE WHEN jsonb_typeof(body->'flowers') = 'array' THEN body->'flowers' ELSE '[]' END) f
          WHERE jsonb_typeof(f->'kind') = 'number' AND (f->>'kind')::numeric BETWEEN 0 AND 2
            AND jsonb_typeof(f->'slot') = 'number' AND (f->>'slot')::numeric BETWEEN 0 AND 6 LIMIT 7) z;
    IF jsonb_array_length(fl) = 0 THEN RETURN villa.err(400, 'put a flower in it first'); END IF;
    INSERT INTO villa.vases (player, x, z, yaw, flowers, plot, placed_ms)
    VALUES (me.id, verse.room_num(body->'x', 200), verse.room_num(body->'z', 200), verse.room_num(body->'yaw', 10), fl,
            CASE WHEN jsonb_typeof(body->'plot') = 'number' AND (body->>'plot')::numeric BETWEEN 0 AND 63 THEN (body->>'plot')::int END,
            verse.now_ms()) RETURNING * INTO v;
    RETURN villa.r(200, villa.vase_json(v, me.id));
  END IF;
  IF cardinality(parts) = 3 AND parts[3] = 'clean' AND parts[2] ~ '^[0-9]{1,18}$' THEN
    DELETE FROM villa.vases WHERE id = parts[2]::bigint AND player = me.id;
    RETURN villa.r(200, '{"cleaned":true}');
  END IF;
  RETURN villa.err(404, 'unknown');
END $_$;


--
-- Name: answer_text(jsonb); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.answer_text(b jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT string_agg(p->>'text', '') FROM jsonb_array_elements(coalesce(b #> '{candidates,0,content,parts}', '[]'::jsonb)) p
  WHERE NOT coalesce((p->>'thought')::boolean, false) $$;


--
-- Name: clean(text); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.clean(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(regexp_replace(coalesce(t, ''), '[|,\r\n]', ' ', 'g'), 200) $$;


--
-- Name: lines(text); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.lines(answer text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE j jsonb; a jsonb; out text; asset text;
BEGIN
  BEGIN j := answer::jsonb; EXCEPTION WHEN others THEN RETURN NULL; END;
  IF jsonb_typeof(j) <> 'object' OR jsonb_typeof(j->'actions') IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;
  out := 'S ' || worldbuilder.say(j->>'say') || E'\n';
  FOR a IN SELECT e FROM jsonb_array_elements(j->'actions') e LIMIT 24 LOOP
    IF jsonb_typeof(a) <> 'object' THEN CONTINUE; END IF;
    asset := worldbuilder.clean(a->>'asset');
    IF coalesce(a->>'op', '') IN ('paint', 'raise', 'lower', 'smooth', 'flatten') AND coalesce(a->>'layer', '') <> '' THEN
      asset := worldbuilder.clean(a->>'layer');
    END IF;
    out := out || 'A ' || worldbuilder.clean(a->>'op') || '|' || asset || '|' || worldbuilder.num(a, 'count')
      || '|' || worldbuilder.clean(a->>'targets') || '|' || worldbuilder.list(a, 'names') || '|' || worldbuilder.clean(a->>'anchor')
      || '|' || worldbuilder.list(a, 'anchor_names') || '|' || worldbuilder.clean(a->>'side') || '|' || worldbuilder.num(a, 'distance')
      || '|' || worldbuilder.num(a, 'spread') || '|' || worldbuilder.num(a, 'size') || '|' || worldbuilder.num(a, 'factor')
      || '|' || worldbuilder.num(a, 'degrees') || E'\n';
  END LOOP;
  RETURN out;
END $$;


--
-- Name: list(jsonb, text); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.list(j jsonb, k text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(j->k) = 'array'
    THEN coalesce((SELECT string_agg(worldbuilder.clean(e), ',') FROM (SELECT jsonb_array_elements_text(j->k) e LIMIT 64) x), '')
    ELSE '' END $$;


--
-- Name: num(jsonb, text); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.num(j jsonb, k text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(j->k) = 'number' THEN (j->>k) ELSE '' END $$;


--
-- Name: say(text); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.say(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT left(regexp_replace(coalesce(t, ''), '[\r\n|]', ' ', 'g'), 200) $$;


--
-- Name: today(); Type: FUNCTION; Schema: worldbuilder; Owner: -
--

CREATE FUNCTION worldbuilder.today() RETURNS date
    LANGUAGE sql STABLE
    AS $$
  SELECT (now() AT TIME ZONE 'America/Chicago')::date $$;


