    CONSTRAINT accounts_frozen_why_check CHECK ((frozen_why = ANY (ARRAY['freeze'::text, 'delete'::text]))),
    CONSTRAINT accounts_id_check CHECK ((id ~ '^acct_[a-z2-7]{26}$'::text)),
    CONSTRAINT accounts_kind_check CHECK ((kind = ANY (ARRAY['person'::text, 'agent'::text, 'service'::text]))),
    CONSTRAINT deleting_is_frozen CHECK (((delete_asked_at IS NULL) OR (frozen_at IS NOT NULL))),
    CONSTRAINT frozen_has_why CHECK (((frozen_at IS NULL) = (frozen_why IS NULL))),
    CONSTRAINT purge_waits_30_days CHECK (((purge_at IS NULL) OR ((delete_asked_at IS NOT NULL) AND (purge_at >= (delete_asked_at + '30 days'::interval)))))
);


