    by_pubkey text NOT NULL,
    by_name text NOT NULL,
    status text NOT NULL,
    undo_of bigint,
    undone_by bigint,
    stop boolean DEFAULT false NOT NULL,
    asked_ms bigint NOT NULL,
    woken_ms bigint DEFAULT 0 NOT NULL,
    started_ms bigint,
    ended_ms bigint,
    version_before integer,
    version_after integer,
    commit_sha text,
    files jsonb DEFAULT '[]'::jsonb NOT NULL,
    cost_usd numeric(10,4) DEFAULT 0 NOT NULL,
    working text DEFAULT ''::text NOT NULL,
    answer text DEFAULT ''::text NOT NULL,
    error text DEFAULT ''::text NOT NULL,
    credential text DEFAULT ''::text NOT NULL,
    CONSTRAINT turns_credential_check CHECK ((credential = ANY (ARRAY[''::text, 'own'::text, 'openagents'::text]))),
    CONSTRAINT turns_kind_check CHECK ((kind = ANY (ARRAY['ask'::text, 'undo'::text]))),
    CONSTRAINT turns_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'done'::text, 'failed'::text, 'stopped'::text, 'refused'::text])))
);


