--
-- Name: character_checkpoints_v1; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.character_checkpoints_v1 (
    who text NOT NULL,
    owner bigint NOT NULL,
    process bigint NOT NULL,
    rev bigint NOT NULL,
    body jsonb NOT NULL,
    accepted_at bigint NOT NULL,
    CONSTRAINT character_checkpoints_v1_accepted_at_check CHECK ((accepted_at > 0)),
    CONSTRAINT character_checkpoints_v1_body_check CHECK (((jsonb_typeof(body) = 'object'::text) AND ((body ->> 'v'::text) = '1'::text))),
    CONSTRAINT character_checkpoints_v1_owner_check CHECK (((owner >= 1) AND (owner <= 2147483647))),
    CONSTRAINT character_checkpoints_v1_process_check CHECK (((process >= 1) AND (process <= '9007199254740991'::bigint))),
    CONSTRAINT character_checkpoints_v1_rev_check CHECK (((rev >= 1) AND (rev <= '9007199254740991'::bigint)))
);


--
-- Name: character_checkpoints_v2; Type: TABLE; Schema: verse; Owner: -
--

CREATE TABLE verse.character_checkpoints_v2 (
    who text NOT NULL,
    owner bigint NOT NULL,
    process bigint NOT NULL,
    rev bigint NOT NULL,
    body jsonb NOT NULL,
    accepted_at bigint NOT NULL,
    CONSTRAINT character_checkpoints_v2_accepted_at_check CHECK ((accepted_at > 0)),
    CONSTRAINT character_checkpoints_v2_body_profile CHECK (((jsonb_typeof(body) = 'object'::text) AND (jsonb_typeof((body -> 'state'::text)) = 'array'::text) AND (jsonb_array_length((body -> 'state'::text)) = 27) AND ((((body ->> 'v'::text) = '2'::text) AND (NOT (body ? 'rest'::text))) OR (((body ->> 'v'::text) = '3'::text) AND (jsonb_typeof((body -> 'rest'::text)) = 'array'::text) AND (jsonb_array_length((body -> 'rest'::text)) = 19))))),
    CONSTRAINT character_checkpoints_v2_owner_check CHECK (((owner >= 1) AND (owner <= 2147483647))),
    CONSTRAINT character_checkpoints_v2_process_check CHECK (((process >= 1) AND (process <= '9007199254740991'::bigint))),
    CONSTRAINT character_checkpoints_v2_rev_check CHECK (((rev >= 1) AND (rev <= '9007199254740991'::bigint)))
);


